        if self.res[p] >= 1:
            moves += ["shore B%d" % b for b in range(len(self.bys))] + ["share P%d" % q for q in range(self.n) if q != p]
        if self.res[p] >= 2:
            moves += ["rebuild B%d" % b for b in range(len(self.bys))]
