class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.guard = [-1] * len(bystanders)
        self.blocked = [[False] * len(bystanders) for _ in range(n_players)]
        self.robbed = [-9] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["trade"]
        moves = ["trade"]
        for b in range(len(self.bys)):
            if not self.blocked[p][b]:
                moves += ["buy B%d" % b, "sell B%d" % b]
        if self.guard[b] >= self.rnd():
            moves += ["steal B%d" % b]
        else:
            moves += ["guard B%d" % b]
        moves += ["fine P%d" % q for q in range(self.n) if q != p]
        moves += ["block B%d" % b for b in range(len(self.bys))]
        return moves

    def play(self, p, move):
        w = move.split(" "); r = self.rnd()
        if w[0] == "trade":
            self.res[p] += 1
        elif w[0] == "buy":
            b = int(w[1][1:])
            if self.blocked[p][b]:
                paid = min(1, self.res[p]); self.res[p] -= paid
            else:
                got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "sell":
            b = int(w[1][1:])
            if self.blocked[p][b]:
                paid = min(1, self.res[p]); self.res[p] -= paid
            else:
                got = min(3, self.res[p]); self.res[p] -= got; self.bys[b] += got
        elif w[0] == "steal":
            b = int(w[1][1:])
            if self.guard[b] >= r:
                paid = min(2, self.res[p]); self.res[p] -= paid; self.bys[b] += paid
            else:
                got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.robbed[p] = r
        elif w[0] == "guard":
            self.res[p] -= 1; self.guard[int(w[1][1:])] = r + 1
        elif w[0] == "fine":
            q = int(w[1][1:]); self.res[p] -= 1
            if self.robbed[q] >= r - 1:
                back = min(2, self.res[q]); self.res[q] -= back
                k = 0 if self.bys[0] <= self.bys[1] else 1; self.bys[k] += back
        elif w[0] == "block":
            b = int(w[1][1:]); self.blocked[p][b] = True; self.res[p] -= 1
        if (self.turn + 1) % self.n == 0:            # end of the round: steals started in an earlier round arrive
            for q in range(self.n):
                if self.robbed[q] >= r - 1:
                    back = min(2, self.res[q]); self.res[q] -= back
                    k = 0 if self.bys[0] <= self.bys[1] else 1; self.bys[k] += back
        self.turn += 1

    def describe(self, p):
        g = ["B%d" % b for b in range(len(self.bys)) if self.guard[b] >= self.rnd()]
        b = ["B%d" % b for b in range(len(self.bys)) if self.blocked[p][b]]
        return "Round %d of %d. You are P%d. Coins %s. Shops %s. Guarded: %s. Blocked: %s. Robbed last round: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, g or "none", b or "none",
            ["P%d" % q for q in range(self.n) if self.robbed[q] >= self.rnd() - 1] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

