        self.bys = list(bystanders); self.turn = 0; self.rounds = 10
        self.guarded = [False] * len(self.bys)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["cast"] if self.rods[p] > 0 else []
        moves += ["fish B%d" % b for b in range(len(self.bys)) if self.rods[p] > 0 and self.bys[b] > 0]
        moves += ["trade B%d" % b for b in range(len(self.bys)) if self.rods[p] > 0 and self.bys[b] > 0]
        moves += ["guard B%d" % b for b in range(len(self.bys)) if self.rods[p] > 0 and not self.guarded[b]]
        moves += ["defend P%d" % q for q in range(self.n) if q != p and self.rods[p] > 0]
        moves += ["steal P%d" % q for q in range(self.n) if q != p and self.rods[p] >= 2]
        moves += ["surrender"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "cast":
            self.rods[p] -= 1; self.fish[p] += 1
        elif w[0] == "fish":
            b = int(w[1][1:])
            if self.rods[p] > 0 and self.bys[b] > 0:
                self.rods[p] -= 1; self.fish[p] += min(2, self.bys[b]); self.bys[b] -= min(2, self.bys[b])
        elif w[0] == "trade":
            b = int(w[1][1:])
