        elif w[0] == "steal":
            q = int(w[1][1:])
            if self.rods[p] >= 2:
                self.rods[p] -= 2; self.fish[p] += 1; self.fish[q] -= 1
        elif w[0] == "surrender":
            self.fish[p] = 0
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Rods %s. Fish %s. Bystanders %s. Guarded: %s." % (
