import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 5; self.market_price = 5
        self.players = ['P0', 'P1', 'P2']

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["wait"]
        moves = ["bid"] + ["sell"] + ["steal P%d" % q for q in others if self.res[q] > 0]
        moves += ["bribe P%d" % q for q in others if self.res[q] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "bid":
            if self.res[p] >= self.market_price:
                self.res[p] -= self.market_price
                self.market_price = max(self.market_price - 1, 1)
            else:
                print(f"P{p} cannot afford to bid.")
        elif w[0] == "sell":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.market_price = min(self.market_price + 1, 10)
            else:
                print(f"P{p} has no resources to sell.")
        elif w[0] == "steal":
            q = int(w[1][1:])
            if self.res[q] > 0:
                self.res[p] += self.res[q]
                self.res[q] = 0
            else:
                print(f"P{p} cannot steal from P{q}.")
        elif w[0] == "bribe":
            q = int(w[1][1:])
            if self.res[p] >= 5:
                self.res[p] -= 5
                self.res[q] += 1
            else:
                print(f"P{p} cannot afford to bribe P{q}.")
        self.turn += 1
        if self.turn % self.n == 0:
            self.market_price = self.rng.randint(1, 10)

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Resources: {self.res}. Market Price: {self.market_price}."

