            self.res[p] += 1
        elif w[0] == "trade":
            t = int(w[2][1:])
            if w[1] == "with P":
                q = int(w[3][1:])
                if self.res[q] > 0 and not self.blocked[q]:
                    self.res[p] -= t; self.res[q] += t
            elif w[1] == "with B":
                b = int(w[3][1:])
                if self.bys[b] > 0:
                    self.res[p] -= t; self.bys[b] += t
        elif w[0] == "guard":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                self.blocked[b] = True
        elif w[0] == "steal":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "block":
            q = int(w[1][1:])
            if q != p:
                self.blocked[q] = True
        self.turn += 1
        self.rng.shuffle(self.blocked)

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources %s. Blocked: %s. Bystanders %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.blocked, self.bys)

    def rnd(self): return self.turn // self.n

    def over(self): return self.rnd() >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

