import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["patrol"]
        if self.barred[p] < self.rnd():
            moves += ["rob B1"] if self.bys[0] > 0 else []
            moves += ["rob B2"] if self.bys[1] > 0 else []
        if self.res[p] >= 1:
            moves += ["report B1"] if self.guilty(0) else []
            moves += ["report B2"] if self.guilty(1) else []
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "patrol":
            self.res[p] += 1
        elif w[0] == "rob":
            b = int(w[1][1:])
            if b == 1 and self.bys[0] > 0:
                got = min(5, self.bys[0])
                self.bys[0] -= got
                self.res[p] += got
                self.owed[p][0] += got
            elif b == 2 and self.bys[1] > 0:
                got = min(5, self.bys[1])
                self.bys[1] -= got
                self.res[p] += got
                self.owed[p][1] += got
            else:
                print("Invalid move: cannot rob an empty bystander.")
        elif w[0] == "report":
            q = int(w[1][1:])
            guilty = self.guilty(q)
            if self.res[p] >= 1:
                if guilty:
                    self.res[p] -= 1
                else:
                    self.res[p] -= 1
            if self.rnd() == 0:
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources %s. Bystanders %s. Guilty (took from a bystander, not yet reported): %s. Barred from rob: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["B%d" % q for q in range(2) if self.guilty(q)] or "none",
            ["B%d" % q for q in range(2) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

