import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.pool = 20
        self.bys = list(bystanders); self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = ["harvest"]
        if self.resources[p] < 5:
            moves.append("rest")
        if self.resources[p] > 0:
            moves.append("share P0")
            moves.append("share P1")
            moves.append("share P2")
        if self.resources[p] > 0 and others:
            moves.append("rob P0")
        if self.resources[p] > 0 and others:
            moves.append("rob P1")
        if self.resources[p] > 0 and others:
            moves.append("rob P2")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            got = self.rng.randint(1, 5)
            self.resources[p] += got
            self.pool -= got
        elif w[0] == "rest":
            self.resources[p] += 1
        elif w[0] == "share":
            target = int(w[1][1:])
            got = min(5, self.resources[p])
            self.resources[p] -= got
            self.resources[target] += got
        elif w[0] == "rob":
            target = int(w[1][1:])
            got = min(5, self.resources[target])
            self.resources[target] -= got
            self.resources[p] += got
        self.turn += 1

    def describe(self, p):
        return "Turn %d. You are P%d. Resources: %s. Pool: %d. Shares: %d." % (
            self.turn, p, self.resources, self.pool, sum([self.resources[i] for i in range(3) if i != p]))

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.resources)
    def final_bystanders(self): return list(self.bys)

