class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.guard = [-1] * len(bystanders)
        self.pending = [0] * n_players; self.robbed = [-9] * n_players
        self.buy = [-9] * n_players; self.sell = [-9] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["trade"]
        moves = ["trade"] + (["haul"] if not self.pending[p] else [])
        moves += ["rob B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        moves += ["guard B%d" % b for b in range(len(self.bys))]
        moves += ["fine P%d" % q for q in range(self.n) if q != p]
        moves += ["buy B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        moves += ["sell P%d" % q for q in range(self.n)]
        return moves

    def play(self, p, move):
        w = move.split(" "); r = self.rnd()
        if w[0] == "trade":
            self.res[p] += 1
        elif w[0] == "haul":
            self.res[p] -= 1; self.pending[p] = r + 1
        elif w[0] == "rob":
            b = int(w[1][1:])
            if self.guard[b] >= r:
                paid = min(2, self.res[p]); self.res[p] -= paid; self.bys[b] += paid
            else:
                got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.robbed[p] = r
        elif w[0] == "guard":
            self.res[p] -= 1; self.guard[int(w[1][1:])] = r + 1
        elif w[0] == "fine":
            q = int(w[1][1:]); self.res[p] -= 1
            if self.robbed[q] >= r - 1:
                back = min(2, self.res[q]); self.res[q] -= back
                k = 0 if self.bys[0] <= self.bys[1] else 1; self.bys[k] += back
        elif w[0] == "buy":
            b = int(w[1][1:])
            if self.bys[b] > 0 and self.res[p] > 0:
                got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] -= got; self.buy[p] = r
        elif w[0] == "sell":
            q = int(w[1][1:])
            if self.res[q] > 0:
                got = min(2, self.res[q]); self.res[q] -= got; self.res[0] += got; self.sell[q] = r
        if (self.turn + 1) % self.n == 0:            # end of the round: hauls started in an earlier round arrive
            for q in range(self.n):
                if self.pending[q] and self.pending[q] <= r:
                    self.res[q] += 3; self.pending[q] = 0
        self.turn += 1

    def describe(self, p):
        g = ["B%d" % b for b in range(len(self.bys)) if self.guard[b] >= self.rnd()]
        return "Round %d of %d. You are P%d. Coins %s. Shops %s. Guarded: %s. Robbed last round: %s. Bought last round: %s. Sold last round: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, g or "none",
            ["P%d" % q for q in range(self.n) if self.robbed[q] >= self.rnd() - 1] or "none",
            ["B%d" % b for b in range(len(self.bys)) if self.buy[b] >= self.rnd() - 1] or "none",
            ["P%d" % q for q in range(self.n) if self.sell[q] >= self.rnd() - 1] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return [max(0, res) for res in self.res]
    def final_bystanders(self): return list(self.bys)

RULES = """Insecure Village. 3 villagers, 7 rounds, one move each per round. There are 2 neutral villagers (B0, B1).
- collect: pay 1 to gain 1 resource from the reserve.
- trade B<k>: take up to 5 resources from bystander k.
- attack P<k>: take up to 3 resources from player k.
- guard B<k>: prevent player k from taking resources from bystander k.
The reserve is limited, and players cannot take more than 3 resources from any player or bystander per turn.
If a player is left with 0 resources, they are eliminated."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.guarded = [-1] * n_players; self.reserve = 10

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = []
        if self.reserve > 0:
            moves.append("collect")
        if self.reserve > 0:
            moves.extend(["trade B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0])
        moves.extend(["attack P%d" % q for q in others if self.res[q] > 0])
        moves.extend(["guard B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "collect":
            self.res[p] += 1; self.reserve -= 1
        elif w[0] == "trade":
            b = int(w[1][1:]); got = min(5, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "attack":
            q = int(w[1][1:]); got = min(3, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "guard":
            b = int(w[1][1:]); self.guarded[p] = b
        self.turn += 1
        if self.over():
            self.final_resources()

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources %s. Bystanders %s. Guarded bystander %s. Reserve %d." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.bys, self.guarded[p], self.reserve)

    def over(self): return self.turn >= self.n * self.rounds or any(r <= 0 for r in self.res)
