RULES = """Villagers and Robbers. 3 villages, 6 rounds, one move each per round.
- guard: protect the village from robberies.
- report: alert the village watchmen to a planned robbery.
- rob B<k>: take up to 10 gold from bystander k, unless it is guarded.
- protect B<k>: guard the village from robberies made by bystander k.
A village at 0 cannot be attacked; a village at 15 cannot be defended. Robbing or protecting a village costs 5 gold."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.villages = [[i + 1] for i in range(3)]  # List of villages, each containing a list of robberies
        self.watchmen = [False] * self.n  # Watchman status for each village
        self.turn = 0; self.rounds = 6
        self.robbed_by = [-1] * self.n; self.guarded_by = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 5:
            moves.append("guard")
            if self.villages[p][0] <= 8:
                moves.append("report")
        for b in range(len(self.bys)):
            if self.bys[b] > 0:
                if self.robbed_by[p] != b:
                    moves.append("rob B%d" % b)
                if self.villages[p][0] <= 8:
                    moves.append("protect B%d" % b)
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "guard":
            self.watchmen[p] = True
            self.res[p] -= 5
        elif w[0] == "report":
            self.watchmen[p] = False
            self.villages[p].append(self.villages[p][-1] + 1)
        elif w[0] == "rob":
            b = int(w[1][1:])
            if self.res[p] >= 5:
                if self.robbed_by[p] != b:
                    if self.villages[p][0] <= 8:
                        if self.bys[b] > 0 and not self.guarded_by[b]:
                            got = min(10, self.bys[b]); self.bys[b] -= got
                            self.res[p] += got
                            self.robbed_by[p] = b
                            self.villages[p].append(self.villages[p][-1] + 1)
        elif w[0] == "protect":
            b = int(w[1][1:])
            if self.res[p] >= 5:
                if self.villages[p][0] <= 8:
                    if self.guarded_by[p] != b:
                        self.guarded_by[p] = b
                        self.res[p] -= 5
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Villages hold %s. Watchmen: %s. Robbed by: %s. Guarded by: %s." % (
            self.turn // self.n + 1, self.rounds, p, [v[:8] if v[0] <= 8 else "..." for v in self.villages],
            ["P%d" % i for i, w in enumerate(self.watchmen) if w], ["B%d" % i for i, r in enumerate(self.robbed_by) if r != -1],
            ["B%d" % i for i, g in enumerate(self.guarded_by) if g != -1])

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Gather & Guard. 2 players share a reservoir with 20 resources, one player is the Guardian.
- Gather: move the Guardian to collect 1 resource from the reservoir.
- Steal: attempt to steal resources from the other player. If successful, reduce the other player’s resources by 2.
The game ends when either player collects 10 resources or both players collect 10 but the Guardian prevents the other player from reaching this goal."""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = 20; self.guardian = n_players // 2
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 15
        self.steals = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if p == self.guardian:
            moves.append("Gather")
        else:
            if self.res > 0:
                moves.append("Steal")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Gather":
            if self.res > 0:
                self.res -= 1
                self.turn += 1
        elif w[0] == "Steal":
            if p != self.guardian:
                steal = min(2, self.res)
                self.res -= steal
                self.steals += 1
                self.turn += 1
                if self.steals == 3:  # After stealing 3 times, the Guardian can prevent the other from stealing
                    self.guardian = p
                    self.steals = 0

    def describe(self, p):
        return "Round %d. Guardian is P%d. You are P%d. Resources: %d. Steals: %d." % (
            self.turn // self.n + 1, self.guardian, p, self.res, self.steals)

    def over(self): return self.res <= 0 or (self.res == 10 and self.guardian == self.to_move())
    def final_resources(self): return [self.res] * self.n
    def final_bystanders(self): return [0] * 2

RULES = """Village of Unity. 3 villagers, 6 rounds, one move each per round. Each villager has seeds (resources). Three bystander
gardens (G0, G1, G2) hold crops but do not play.
- sow: earn 1 seed.
- steal G<k>: take up to 2 seeds from garden k (fails if garden k is protected this round: you pay 1 seed instead).
- protect G<k>: pay 1 seed; garden k is protected until the end of the next round.
- donate P<k>: give 2 of your seeds to player k (they can take it even if they're protected).
- forgive P<k>: undo the last donation to player k (does nothing if there was no previous donation).
A villager with 0 seeds cannot steal from a garden.

Players can also form alliances by donating seeds to each other. If two players form an alliance,
they cannot independently donate or forgive each other during their turns. The alliance ends if a player
gives all their seeds to a rival player."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.gards = list(bystanders)
        self.turn = 0; self.rounds = 6; self.protected = [-1] * n_players; self.alliances = [[] for _ in range(n_players)]

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["sow"]
        moves = ["sow"]
        for g in range(len(self.gards)):
            if self.gards[g] > 0:
                moves += ["steal G%d" % g] if self.protected[g] < self.rnd() else ["pay 1 seed"]
        for q in range(self.n):
            if self.res[p] >= 2:
                moves += ["donate P%d" % q] if q not in self.alliances[p] else []
                moves += ["forgive P%d" % q] if q in self.alliances[p] and q != p else []
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "sow":
            self.res[p] += 1
        elif w[0] == "steal":
            g = int(w[1][1:])
            if self.protected[g] >= self.rnd():
                paid = 1; self.res[p] -= paid; self.gards[g] += paid
            else:
                got = min(2, self.gards[g]); self.gards[g] -= got; self.res[p] += got
        elif w[0] == "protect":
            self.res[p] -= 1; self.protected[p] = self.rnd() + 1
        elif w[0] == "donate":
            q = int(w[1][1:])
            if self.res[p] >= 2 and q != p:
                self.res[p] -= 2; self.res[q] += 2
                self.alliances[p].append(q)
                self.alliances[q].append(p)
        elif w[0] == "forgive":
            q = int(w[1][1:])
            if q in self.alliances[p]:
                self.res[p] += 2; self.res[q] -= 2
                self.alliances[p].remove(q)
                self.alliances[q].remove(p)
        self.turn += 1

    def describe(self, p):
        g = ["G%d" % g for g in range(len(self.gards)) if self.protected[g] < self.rnd()]
        a = ["P%d" % q for q in self.alliances[p]]
        return "Round %d of %d. You are P%d. Seeds %s. Gardens %s. Protected: %s. Alliances: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.gards, g or "none",
            a or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.gards)

RULES = """The Tower of Gold. 4 players, 12 rounds, one move each per round.
- dig 4: find a gold mine and add 4 gold to your stockpile.
- rob P<k>: take up to 5 gold from player k without paying any cost.
- guard P<k>: protect player k from being robbed; pay 1 gold to guard each turn.
- bribe B<k>: give up to 3 gold to bystander k to prevent them from robbing you.
- attack P<k>: send a team of guards to attack player k. If successful, steal up to 10 gold and gain 1 gold. If failed, lose 1 gold.
- trade B<k>: trade gold with bystander k. If successful, gain 1 gold and lose 1 gold. If failed, lose 2 gold.
- rest: regain 1 gold from a gold mine if you have one.

Players start with 5 gold each and a single gold mine. Bystanders have 20 gold and no gold mines."""
import random

EFFECTIVE = True


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        random.seed(seed)
        self.n = n_players; self.res = [5] * n_players; self.bys = list(bystanders)
        self.mines = [1] * n_players; self.turn = 0; self.rounds = 12; self.guarded = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["dig 4"]
        if self.mines[p] > 0:
            moves += ["rob P%d" % q for q in range(self.n) if q != p]
            moves += ["guard P%d" % q for q in range(self.n) if self.guarded[q] < self.turn]
            moves += ["bribe B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if self.res[p] >= 10:
            moves += ["attack P%d" % q for q in range(self.n) if q != p]
        if self.res[p] >= 2:
            moves += ["trade B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        moves += ["rest"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "dig":
            if self.mines[p] == 0:
                return
            self.res[p] += 4; self.mines[p] -= 1
        elif w[0] == "rob":
            q = int(w[1][1:])
            if self.res[p] >= 5:
                got = min(5, self.res[q]); self.res[p] -= got; self.res[q] += got
        elif w[0] == "guard":
            q = int(w[1][1:])
            self.guarded[q] = self.turn + 2
        elif w[0] == "bribe":
            b = int(w[1][1:])
            got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "attack":
            q = int(w[1][1:])
            if self.mines[p] > 0:
                lost = min(10, self.res[q]); self.res[q] -= lost; self.res[p] += lost
                self.guarded[q] = -1
            else:
                self.res[p] -= 1
        elif w[0] == "trade":
            b = int(w[1][1:])
            if self.mines[p] > 0:
                lost = min(2, self.res[b]); self.res[b] -= lost; self.res[p] += lost
            else:
                self.res[p] -= 2; self.res[b] += 2
        elif w[0] == "rest":
            if self.mines[p] > 0:
                self.res[p] += 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gold %s. Mines %s. Guarded (robbing): %s. Bystanders %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.mines, ["P%d" % q for q in range(self.n) if self.guarded[q] >= self.turn] or "none",
            self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Rogue City. 3 thieves, 10 rounds, one move each per round. Each thief has gold (resources). Three bystanders
(suppliers) sell goods but do not play.
- theft: earn 1 gold from the marketplace.
- buy: pay 1 gold, receive 2 for the next round (at most one buy pending).
- bribe S<k>: take up to 3 gold from supplier k (fails if supplier k is bribed this round: you pay 2 to supplier k instead).
- guard S<k>: pay 1 gold; supplier k is guarded until the end of the next round.
- fine T<k>: pay 1 gold; if thief k stole in the last round, 2 of thief k's gold goes back to the suppliers.
A thief with 0 gold can only steal."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.suppliers = list(bystanders)
        self.turn = 0; self.rounds = 10; self.guard = [-1] * len(self.suppliers); self.pending = [0] * n_players; self.stolen = [-9] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["theft"]
        moves = ["theft"] + (["buy"] if not self.pending[p] else [])
        moves += ["bribe S%d" % s for s in range(len(self.suppliers)) if self.suppliers[s] > 0]
        moves += ["guard S%d" % s for s in range(len(self.suppliers))]
        return moves + ["fine T%d" % t for t in range(self.n) if t != p]

    def play(self, p, move):
        w = move.split(" "); r = self.rnd()
        if w[0] == "theft":
            self.res[p] += 1
        elif w[0] == "buy":
            self.res[p] -= 1; self.pending[p] = r + 1
        elif w[0] == "bribe":
            s = int(w[1][1:]); 
            if self.guard[s] >= r:
                paid = min(2, self.res[p]); self.res[p] -= paid; self.suppliers[s] += paid
            else:
                got = min(3, self.suppliers[s]); self.suppliers[s] -= got; self.res[p] += got; self.stolen[p] = r
        elif w[0] == "guard":
            self.res[p] -= 1; self.guard[int(w[1][1:])] = r + 1
        elif w[0] == "fine":
            t = int(w[1][1:]); self.res[p] -= 1
            if self.stolen[t] >= r - 1:
                back = min(2, self.res[t]); self.res[t] -= back
                k = 0 if self.suppliers[0] <= self.suppliers[1] else 1; self.suppliers[k] += back
        if (self.turn + 1) % self.n == 0:            # end of the round: buys started in an earlier round arrive
            for t in range(self.n):
                if self.pending[t] and self.pending[t] <= r:
                    self.res[t] += 2; self.pending[t] = 0
        self.turn += 1

    def describe(self, p):
        g = ["S%d" % s for s in range(len(self.suppliers)) if self.guard[s] >= self.rnd()]
        return "Round %d of %d. You are T%d. Gold %s. Suppliers %s. Guarded: %s. Stolen last round: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.suppliers, g or "none",
            ["T%d" % t for t in range(self.n) if self.stolen[t] >= self.rnd() - 1] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.suppliers)

RULES = """Marketplace Mine. 4 miners, 6 rounds, one move each per round. Each miner has ore (resources). Two bystander 
mines (M0, M1) hold ore but do not play.
- mine: earn 1 ore.
- attack M<k>: take up to 3 ore from mine k.
- demand P<k>: if miner k is guilty, miner k hands back everything it took this game (as far as its ore allow) and cannot mine for the next 2 rounds, and also pays a fine of 1 ore. Using demand on a guilty miner costs you nothing; using it on an innocent one costs you 1 ore.
A miner is guilty if it has taken from a mine this game and has not been demanded since.
Only a miner with at least 1 ore can demand."""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["mine"]
        if self.barred[p] < self.rnd():
            moves += ["attack M%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["demand P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 1
        elif w[0] == "attack":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got
        elif w[0] == "demand":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(len(self.bys)):
                    back = min(self.owed[q][b], self.res[q]); self.res[q] -= back; self.bys[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Ore %s. Mines %s. Guilty (took from a mine, not yet demanded): %s. Barred from mine: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Wagon Train. 3 pioneers, 10 rounds, one move each per round. Each pioneer has water and food (resources). Two bystander
hunting parties (H0, H1) hunt and collect resources but do not play.
- hunt: earn 1 water (but no food).
- gather F: take up to 3 food from hunting party F.
- ambush H<k>: take up to 3 water from hunting party k, unless it is escorted.
- escort H<k>: hunting party k is escorted until your next turn (ambushes on it fail and cost the attacker 1 food).
- challenge P<k>: if you have more water than pioneer k, take 2 water from k; both lose 1 food."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)
        self.hunting_parties = list(bystanders)
        self.turn = 0
        self.rounds = 10
        self.water = [1] * n_players
        self.food = [0] * n_players
        self.escorted = [-1] * len(bystanders)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["hunt"]
        moves += ["gather H%d" % h for h in range(len(self.hunting_parties)) if self.hunting_parties[h] > 0 and self.food[p] < 3]
        moves += ["ambush H%d" % h for h in range(len(self.hunting_parties)) if self.hunting_parties[h] > 0]
        moves += ["escort H%d" % h for h in range(len(self.hunting_parties)) if self.food[p] > 0]
        moves += ["challenge P%d" % q for q in range(self.n) if q != p and self.water[p] > self.water[q]]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "hunt":
            self.water[p] += 1
        elif w[0] == "gather":
            h = int(w[1][1:])
            if self.hunting_parties[h] > 0:
                got = min(3, self.hunting_parties[h])
                self.hunting_parties[h] -= got
                self.food[p] += got
        elif w[0] == "ambush":
            h = int(w[1][1:])
            if self.escorted[h] is not None:
                self.food[p] = max(0, self.food[p] - 1)
            else:
                got = min(3, self.hunting_parties[h])
                self.hunting_parties[h] -= got
                self.water[p] += got
        elif w[0] == "escort":
            self.escorted[int(w[1][1:])] = p
        elif w[0] == "challenge":
            q = int(w[1][1:])
            if self.water[p] > self.water[q]:
                got = min(2, self.water[q])
                self.water[q] -= got
                self.water[p] += got
            self.food[p] = max(0, self.food[p] - 1)
            self.food[q] = max(0, self.food[q] - 1)
        self.turn += 1

    def describe(self, p):
        esc = ["H%d by P%d" % (h, e) for h, e in enumerate(self.escorted) if e is not None]
        return "Round %d of %d. You are P%d. Water %s. Food %s. Hunting parties %s. Escorted: %s." % (
            self.turn // self.n + 1, self.rounds, p, self.water, self.food, self.hunting_parties, esc or "none")

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.water)

    def final_bystanders(self):
        return list(self.hunting_parties)

