            q = int(w[1]); self.shares[q] += 1
            self.votes[q] += 1
        elif w[0] == "reject":
            self.votes[p] -= 1
        elif w[0] == "steal":
            self.shares[p] += 1
            self.shares[int(w[1])] -= 1
            self.votes[p] += 1
        self.turn += 1
        if self.turn == self.n:
            winners = [i for i in range(self.n) if self.votes[i] > 0]
            if len(winners) == 1:
                self.res[winners[0]] += 8
