import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 4

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = ["gather"]
        moves += ["donate B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        moves += ["plunder P%d" % q for q in others if self.res[q] > 0]
        if self.res[p] > 0:
            moves.append("defend")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            got = min(2, self.res[p]); self.res[p] += got
        elif w[0] == "donate":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] += got; self.res[p] -= got
        elif w[0] == "plunder":
            q = int(w[1][1:]); got = min(2, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "defend":
            self.res[p] -= 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources %s. Bystanders %s." % (
            self.turn // self.rounds + 1, self.rounds, p, self.res, self.bys)

    def over(self):
        # Check if any player has no resources left
        if all(res <= 0 for res in self.res):
            return True
        # Check if all rounds have been played
        return self.turn >= self.n * self.rounds

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

