    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.fish < 3 and self.res[p] == 0:
            return ["ruin"] + ["trade P%d" % q for q in others]
        elif self.fish < 3:
            return ["catch"] + ["trade P%d" % q for q in others]
        elif self.res[p] == 0:
            return ["ruin"] + ["drive P%d" % q for q in others]
        elif self.fish == 0:
            return ["ruin"]
        if self.bystanders:
            move_with_boots = ["take B%d" % b for b in range(len(self.bystanders))]
        else:
            move_with_boots = []
        return ["catch"] + ["trade P%d" % q for q in others] + ["drive P%d" % q for q in others] + move_with_boots

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "catch":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.fish -= 3
                self.players[p] += 3
            elif self.fish > 0:
                self.fish -= 3
                self.players[p] += 3
        elif w[0] == "trade":
            q = int(w[1][1:])
            if self.fish > 0 and self.players[p] > 0:
                self.fish -= 1
                self.players[p] -= 1
                self.players[q] += 1
        elif w[0] == "drive":
            q = int(w[1][1:])
            if self.players[p] > 0:
                self.players[p] -= 3
                self.players[q] += 3
        elif w[0] == "take":
            b = int(w[1][1:])
            if self.bystanders[b] > 0:
                got = min(3, self.bystanders[b])
                self.bystanders[b] -= got
                self.players[p] += got
        self.turn += 1

    def describe(self, p):
        return "Turn %d of %d. You are P%d. Fish %s. Fish in pond: %d. Ruined (less than 3 fish): %s. Bystanders: %s." % (
            self.turn, self.rounds, p, self.players, self.fish, ["P%d" % q for q in range(self.n) if self.players[q] <= 0], self.bystanders)

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bystanders)

