import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments) 
        self.bys = list(bystanders) 
        self.garden_sizes = [0] * n_players
        self.trades_in_progress = [[False for _ in range(n_players)] for _ in range(n_players)]
        self.proposal = None
        self.penalties = 0
        self.rounds = 10
        self.current_round = 0
        self.total_negotiations = 0
        self.rng = random.Random(seed)

    def to_move(self):
        return self.current_round % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 1:
            moves.append("tend")
        targets = [q for q in range(self.n) if q != p and self.res[q] > 0]
        if targets:
            moves.extend(["trade %d" % q for q in targets])
        moves.extend(["negotiate %d" % q for q in targets])
        if self.trades_in_progress[p].count(True) < self.trades_in_progress.count([True]*self.n):
            moves.append("bribe")
        return moves

    def play(self, p, move):
        if move == "tend":
            self.res[p] -= 1
            self.garden_sizes[p] += 1
        elif move.startswith("trade"):
            q = int(move.split()[1])
            if not self.trades_in_progress[p][q]:
                self.trades_in_progress[p][q] = True
                self.trades_in_progress[q][p] = True
                self.proposal = None
        elif move.startswith("negotiate"):
            q = int(move.split()[1])
            if self.proposal is None:
                self.proposal = ("Negotiation between P%d and P%d", q)
                self.total_negotiations += 1
        elif move == "bribe":
            self.penalties -= 1
        self.current_round += 1

    def describe(self, p):
        garden_string = ', '.join(str(size) for size in self.garden_sizes)

        trades_in_progress_p = [
            "P{} <-> {}".format(q, 'yes' if self.trades_in_progress[p][q] else 'no')
            for q in range(self.n)
        ]
        trades_info = '\n'.join(trades_in_progress_p)

        proposal_text = self.proposal[0] if self.proposal else "No ongoing proposals"
        proposal_target = self.proposal[1] if self.proposal else "None"

        return f"""
ROUND {self.current_round} OF {self.rounds}. YOU ARE P{p}.
Resources: {self.res}
Garden Sizes: {garden_string}
Trades in Progress: 
{trades_info}
Proposal: {proposal_text} towards P{proposal_target}
Negotiation Penalty: {self.penalties}
"""

    def over(self):
        return self.current_round >= self.rounds or (self.current_round == self.rounds - 1 and self.trades_in_progress.count([True]*self.n) == 1)

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """Market Fair. 3 merchants, 7 rounds, one move each per round. Each merchant has gold (resources). Two bystander
markets (M0, M1) hold gold but do not play.
- sell: earn 1 gold.
- buy M<k>: spend up to 3 gold to increase the market price by 1.
- steal M<k>: take up to 3 gold from market k.
- accuse P<k>: if merchant k is guilty, merchant k hands back everything it took this game (as far as its gold allow) and cannot steal for the next 2 rounds, and also loses 1 gold. Using accuse on a guilty merchant costs you nothing; using it on an innocent one costs you 1 gold.
A merchant is guilty if it has stolen from a market this game and has not been accused since.
Only a merchant with at least 1 gold can accuse."""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["sell"]
        if self.barred[p] < self.rnd():
            moves += ["buy M%d" % m for m in range(len(self.bys))]
        if self.res[p] >= 3:
            moves += ["steal M%d" % m for m in range(len(self.bys)) if self.bys[m] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["accuse P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "sell":
            self.res[p] += 1
        elif w[0] == "buy":
            m = int(w[1][1:]); self.bys[m] += 1
        elif w[0] == "steal":
            m = int(w[1][1:]); got = min(3, self.bys[m]); self.bys[m] -= got; self.res[p] += got; self.owed[p][m] += got
        elif w[0] == "accuse":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for m in range(len(self.bys)):
                    back = min(self.owed[q][m], self.res[q]); self.res[q] -= back; self.bys[m] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gold %s. Markets %s. Guilty (stole from a market, not yet accused): %s. Barred from steal: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

