import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [0] * n_players; self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10; self.reports = [[0] * n_players for _ in range(n_players)]
        self.banned = [False] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["steal from B%d" % b for b in range(len(self.bys))]
        if not self.banned[p]:
            moves += ["bribe P%d" % q for q in range(self.n) if q != p]
        moves += ["hide"]
        if sum(self.reports[p]) > 0:
            moves += ["report P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "steal":
            b = int(w[2][1:])
            if self.bys[b] > 0:
                stolen = min(4, self.bys[b])
                self.bys[b] -= stolen
                self.res[p] += stolen
        elif w[0] == "bribe":
            q = int(w[1][1:])
            if self.res[p] >= 2:
                self.res[p] -= 2
                self.reports[q][p] += 1
        elif w[0] == "report":
            q = int(w[1][1:])
            if self.reports[q][p] > 0:
                self.res[q] = 0
                self.reports[q][p] = 0
                self.banned[q] = True
        elif w[0] == "hide":
            pass
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are T%d. Gold %s. Bystanders hold %s. Reports against you: %s. Banned: %s." % (
