            moves += ["steal T%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if p not in self.enemies and p not in self.allies:
            moves += ["bribe P%d" % q for q in range(self.n) if q != p]
        if p not in self.enemies and self.res[p] >= 1:
            moves += ["accuse P%d" % q for q in range(self.n) if q != p]
        return moves

