        self.pending = [0] * n_players; self.stolen = [-9] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["harvest"]
        if self.res[p] > 0:
            moves.append("trade")
        if self.res[p] == 0:
            moves += ["steal G%d" % g for g in range(len(self.bys)) if self.bys[g] > 0]
        moves += ["guard G%d" % g for g in range(len(self.bys))]
        if self.res[p] >= 3:
            moves += ["bribe P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" "); r = self.rnd()
        if w[0] == "harvest":
            self.res[p] += 1
        elif w[0] == "trade":
            self.res[p] -= 1; self.res[p] += 2
        elif w[0] == "steal":
            g = int(w[1][1:])
            if self.guard[g] >= r:
                paid = min(2, self.res[p]); self.res[p] -= paid; self.bys[g] += paid
            else:
                got = min(4, self.bys[g]); self.bys[g] -= got; self.res[p] += got; self.stolen[p] = r
        elif w[0] == "guard":
            self.res[p] -= 1; self.guard[int(w[1][1:])] = r + 1
        elif w[0] == "bribe":
            q = int(w[1][1:]); self.res[p] -= 3
            if self.stolen[q] >= r - 1:
                back = min(2, self.res[q]); self.res[q] -= back
                k = 0 if self.bys[0] <= self.bys[1] else 1; self.bys[k] += back
        if (self.turn + 1) % self.n == 0:            # end of the round: trades made in an earlier round complete
            for q in range(self.n):
                if self.pending[q] and self.pending[q] <= r:
                    self.res[q] += 2; self.pending[q] = 0
        self.turn += 1

    def describe(self, p):
        g = ["G%d" % g for g in range(len(self.bys)) if self.guard[g] >= self.rnd()]
        return "Round %d of %d. You are P%d. Wheat %s. Granaries %s. Guarded: %s. Stole last round: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, g or "none",
            ["P%d" % q for q in range(self.n) if self.stolen[q] >= self.rnd() - 1] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

