        self.pasture = 10; self.guarded = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["plant C"] * (self.res[p] >= 1 and self.res[p] >= 1)
        moves += ["harvest"]
        if not self.guarded:
            moves += ["steal from P0"]
        moves += ["guard P0"] if self.res[p] >= 1 else []
        moves += ["trade P%d" % q for q in range(self.n) if q != p and self.res[p] > 0 and self.res[q] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "plant":
            self.res[p] -= 1; self.res[p] -= 1; self.res[p] += 1
        elif w[0] == "harvest":
            self.res[p] += self.res[p]
            self.res[p] = min(self.res[p], 9)  # Max 9 crops in barn
