        elif w[0] == "trade":
            q = int(w[1][1:])
            x = min(self.res[p], self.res[q])
            self.res[p] -= x; self.res[q] -= x; self.res[p] += x; self.res[q] += x
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Crops %s. Barn %s. Pasture %d. Guarded: %s. Trading partner options: %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.res[p], self.pasture, self.guarded, 
            ", ".join(["P%d" % q for q in range(self.n) if q != p and self.res[q] > 0]))

