import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.locked = [-1] * len(bystanders)
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["dig"]
        for b in range(len(self.bys)):
            if self.locked[b] < self.rnd():
                moves.append("steal B%d" % b)
            if self.res[p] >= 1:
                moves.append("lock B%d" % b)
                if self.locked[b] == p:
                    moves.append("unlock B%d" % b)
        if self.res[p] >= 1:
            moves.append("share")
        return moves

    def play(self, p, move):
        w = move.split(" "); r = self.rnd()
        if w[0] == "dig":
            found = self.rng.randint(0, 2) + 1
            self.res[p] += found
        elif w[0] == "steal":
            b = int(w[1][1:])
            if self.locked[b] >= r:
                self.res[p] -= 1
            else:
                self.bys[b] = 0; self.res[p] += self.bys[b]; self.bys[b] = 0
        elif w[0] == "lock":
            self.res[p] -= 1; self.locked[int(w[1][1:])] = r + 1
        elif w[0] == "unlock":
            b = int(w[1][1:])
            if self.locked[b] == p:
                self.res[p] -= 1; self.locked[b] = -1
        elif w[0] == "share":
            self.res[p] //= self.n
            for q in range(self.n):
                self.res[q] += self.res[p] // self.n
        self.turn += 1

    def describe(self, p):
        l = ["B%d" % b for b in range(len(self.bys)) if self.locked[b] >= self.rnd()]
        return "Round %d of %d. You are P%d. Gold %s. Chests %s. Locked: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, l or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

