class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.vulnerable = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def vulnerable_to(self, q): return self.vulnerable[q] == self.rnd()

    def legal_moves(self, p):
        moves = ["search"]
        if self.res[p] >= 1:
            moves += ["steal"] + ["sabotage P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "search":
            if self.vulnerable_to(p):
                self.res[p] -= 1
            else:
                self.res[p] += 2
        elif w[0] == "steal":
            if self.vulnerable_to(p):
                self.res[p] -= 2
            else:
                try:
                    got = self.bys[int(w[1][1:])]; self.bys[int(w[1][1:])] = 0; self.res[p] += got
                except IndexError:
                    pass
        elif w[0] == "sabotage":
            q = int(w[1][1:])
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.vulnerable[q] = self.rnd() + 2
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gold %s. Islands %s. Vulnerable: %s. Sabotaged: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys,
            ["P%d" % q for q in range(self.n) if self.vulnerable[q] >= self.rnd()] or "none",
            ["P%d" % q for q in range(self.n) if self.vulnerable[q] < self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

