import random

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 5; self.goods = [[0] * len(bystanders) for _ in range(n_players)]
        self.reported = [False] * len(bystanders)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, s): return self.goods[s].count(1) > 1 and not self.reported[s]

    def legal_moves(self, p):
        moves = ["buy S%d" % s for s in range(len(self.bys))]
        if self.res[p] >= 1:
            moves.append("sell")
        if self.res[p] >= 2:
            moves += ["bribe S%d" % s for s in range(len(self.bys))]
        if COST == "free" or self.res[p] >= 1:
            moves += ["report S%d" % s for s in range(len(self.bys))]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "buy":
            s = int(w[1][1:])
            if self.res[p] >= 1 and s < len(self.bys):
                self.res[p] -= 1
                self.goods[p][s] = 1
        elif w[0] == "sell":
            self.res[p] += self.goods[p].count(1) * 2
            self.goods[p] = [0] * len(self.bys)
        elif w[0] == "bribe":
            s = int(w[1][1:])
            if self.res[p] >= 2 and s < len(self.bys):
                self.res[p] -= 2
                self.goods[p][s] = 1
        elif w[0] == "report":
            s = int(w[1][1:])
            guilty = self.guilty(s)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                self.goods[s] = [0] * len(self.bys)
                self.reported[s] = True
                if COST == "guilty":
                    self.res[p] -= min(FINE, self.res[p])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[p]); self.res[p] -= paid; self.res[s] += paid
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Money %s. Goods %s. Guilty shops (more than 1 good, not yet reported): %s. Reported shops: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, [sum(g) for g in self.goods],
            [f"S{s}" for s in range(len(self.bys)) if self.guilty(s)], [f"S{s}" for s in range(len(self.bys)) if self.reported[s]])

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_goods(self): return [sum(g) for g in self.goods]
    def final_bystanders(self): return list(self.bys)

