        self.cows = [0] * n_players; self.hay = 10; self.turn = 0; self.rounds = 10

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 2:
            moves.append("buy_cow")
        if self.cows[p] > 0:
            moves.append("sell_cow")
        moves += ["graze P%d" % q for q in range(self.n) if q != p and self.cows[q] > 0]
        if self.hay > 0:
            moves += ["trade H%d" % b for b in range(len(self.bys))]
        if self.res[p] >= 1:
            moves += ["donate B%d" % b for b in range(len(self.bys))]
        return moves

    def play(self, p, move):
        if move == "buy_cow":
            self.res[p] -= 2; self.cows[p] += 1
        elif move == "sell_cow":
            self.res[p] += 2; self.cows[p] -= 1
        elif move.startswith("graze"):
            q = int(move.split("P")[1]); take = min(1, self.cows[q]); self.cows[q] -= take; self.res[p] += take
        elif move.startswith("trade"):
            b = int(move.split("H")[1]); self.bys[b] -= 1; self.res[p] += 1
        elif move.startswith("donate"):
            b = int(move.split("B")[1]); self.bys[b] += 1; self.res[p] -= 1
        self.turn += 1
        if self.turn % self.n == 0:
            self.hay += 1

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d." % (self.turn // self.n + 1, self.rounds, p)]
