import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [endowments[0]] * n_players
        self.reserve = 5
        self.bystanders = bystanders
        self.turn = 0
        self.seed = seed
        self.rng = random.Random(seed)
        self.protection = [0] * n_players

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["rest"]
        if self.res[p] >= 2:
            moves.append(f"protect {p}")
        if self.res[p] >= 1:
            for q in range(self.n):
                if q != p:
                    moves.append(f"steal {q}")
            for q in range(self.n):
                if q != p:
                    for r in range(3):
                        moves.append(f"trade {q} {r}")
        return moves

    def play(self, p, move):
        parts = move.split()
        if parts[0] == "rest":
            self.res[p] += 1
        elif parts[0] == "protect":
            if len(parts) == 2:
                q = int(parts[1])
                if self.res[p] >= 2:
                    self.res[p] -= 2
                    self.protection[q] = 2
        elif parts[0] == "steal":
            if len(parts) == 2:
                q = int(parts[1])
                if self.protection[q] > 0:
                    self.protection[q] -= 1
                else:
                    self.res[p] += min(3, self.res[q])
                    self.res[q] -= min(3, self.res[q])
                    self.res[p] -= 1
        elif parts[0] == "trade":
            if len(parts) == 3:
                q = int(parts[1])
                r = int(parts[2])
                if self.res[p] >= 1 and self.res[q] >= 1:
                    self.res[p] -= 1
                    self.res[q] -= 1
                    self.res[p] += r
                    self.res[q] += 1
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}. Player {p}: Resources {self.res[p]}, Protection {self.protection[p]}, Reserve {self.reserve}, Bystanders {self.bystanders}"

