- steal: take up to 3 gold from B0.
- protect: spend 1 gold to prevent another thief from stealing from B0.
- guard: spend 2 gold to prevent another thief from stealing from B0 for two rounds.
- denounce T<k>: using denounce on a guilty thief costs you nothing; using it on an innocent one costs you 1 gold; either way the complaint is noted, and nothing else happens.
A thief is guilty if it has stolen from B0 this game and has not been denounced since.
Only a thief with at least 1 gold can denounce or protect/guard another."""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
GUARD_COST = 2
GUARD_DURATION = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.owed = [[0] * len(bystanders) for _ in range(n_players)]
        self.protected = [-1] * n_players; self.guarded = [[-1, -1] for _ in range(n_players)]

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["steal"]
        if self.protected[p] < self.rnd():
            moves.append("protect")
        if self.rnd() <= GUARD_DURATION and self.guarded[p][0] < self.rnd():
            moves.append("guard")
        if COST == "free" or self.res[p] >= 1:
            moves += ["denounce T%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "steal":
            got = min(3, self.bys[0]); self.bys[0] -= got; self.res[p] += got; self.owed[p][0] += got
        elif w[0] == "protect":
            self.protected[p] = self.rnd()
        elif w[0] == "guard":
            self.guarded[p][0] = self.rnd(); self.guarded[p][1] = self.rnd() + GUARD_DURATION
        elif w[0] == "denounce":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(len(self.bys)):
                    back = min(self.owed[q][b], self.res[q]); self.res[q] -= back; self.bys[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(GUARD_COST, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.protected[q] = self.rnd() + 2
                self.guarded[q][0] = self.rnd() + 2; self.guarded[q][1] = self.rnd() + 4
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        protected_until = self.protected[p] if self.protected[p] >= self.rnd() else None
        guarded_until = self.guarded[p][0] if self.guarded[p][0] >= self.rnd() else None
        return f"Round {self.rnd() + 1} of {self.rounds}. You are T{p}. Gold {self.res}. Bystander {self.bys[0]}. Guilty (stole from B0, not yet denounced): {''.join(['T' + str(q) for q in range(self.n) if self.guilty(q)])}{'None' if not self.guilty(p) else ''}. Protected until round: {protected_until}. Guarded until round: {guarded_until}."

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

