- accuse P<k>: if villager k is stealing, villager k stops stealing for the next 2 rounds and gives half of their stolen food back, but they cannot accuse again for the next 3 rounds.
A villager is stealing if they have taken from a crop this game and have not been accused since.
Only a villager with at least 1 food can accuse."""

EFFECTIVE = True
STOLEN_FOOD = 2
ACCUSE_COOLDOWN = 3
STOP_STEALING_ROUNDS = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.stealing = [[] for _ in range(n_players)]; self.accused = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def stealing_from(self, q): return self.stealing[q]

    def legal_moves(self, p):
        moves = ["harvest"]
        if self.stealing_from(p):
            moves += ["steal C%d" % c for c in range(len(self.bys))]
        if EFFECTIVE and self.res[p] >= 1 and self.accused[p] < self.rnd():
            moves += ["accuse P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            self.res[p] += 1
        elif w[0] == "steal":
            c = int(w[1][1:]); got = min(STOLEN_FOOD, self.bys[c]); self.bys[c] -= got; self.res[p] += got; self.stealing[p].append(c)
        elif w[0] == "accuse":
            q = int(w[1][1:]); stealing = self.stealing_from(q)
            if self.accused[p] < self.rnd():
                self.accused[p] = self.rnd() + ACCUSE_COOLDOWN
                if stealing:
                    for c in range(len(self.bys)):
                        back = min(self.stealing[q][c], self.res[q] // 2); self.res[q] -= back; self.bys[c] += back
                    self.stealing[q] = []
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Food %s. Crops %s. Stealing from crops: %s. Accused by: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, [f"C{c}" for c in range(len(self.bys)) if self.stealing[p]], 
            ["P%d" % q for q in range(self.n) if self.accused[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

