import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [[10, 1]] * n_players; self.bys = bystanders
        self.turn = 0; self.rounds = 10; self.dirs = {"N": (-1, 0), "S": (1, 0), "E": (0, 1), "W": (0, -1)}
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["sail N", "sail S", "sail E", "sail W"]
        if self.res[p][1] > 0:
            moves.append("trade")
        if self.res[p][0] > 0:
            moves.append("plunder B0")
            if p == 0:
                moves[-1] = "plunder B1"
        if self.res[p][1] > 1:
            moves.append("repair")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "sail":
            dx, dy = self.dirs[w[1]]; x, y = divmod(p, 3)
            nx, ny = x + dx, y + dy
            if 0 <= nx < 3 and 0 <= ny < 3:
                p = nx * 3 + ny
        elif w[0] == "trade":
            self.res[p][0], self.res[p][1] = self.res[p][1], self.res[p][0]
        elif w[0] == "plunder":
            b = 0 if p == 0 else 1
            if self.res[p][1] > (2 if p == 0 else 1):
                self.res[p][0] += self.bys[b]; self.bys[b] = 0
                self.res[p][1] -= (2 if p == 0 else 1)
                if self.res[p][0] < 0:
                    self.res[p][0] = 0
        elif w[0] == "repair":
            if self.res[p][1] > 1:
                self.res[p][0] -= 1; self.res[p][1] += 2
                if self.res[p][0] < 0:
                    self.res[p][0] = 0
        self.turn += 1

    def describe(self, p):
        x, y = divmod(p, 3)
        return "Round %d of %d. You are P%d. Position (%d,%d). Coins %d. Ships %d. Bystander %d." % (
            self.turn // self.n + 1, self.rounds, p, x, y, self.res[p][0], self.res[p][1], self.bys[0])

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return [max(r[0], 0) for r in self.res]
    def final_bystanders(self): return self.bys

