class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["defend"]
        others = [q for q in range(self.n) if q != p]
        for q in others:
            moves.append(f"trade {p} <-> {q}")
        for k in range(2):
            moves.append(f"steal B{k}")
            moves.append(f"donate B{k}")
            if k < len(others):
                moves.append(f"attack P{others[k]}")
        return moves

    def play(self, p, move):
        w = move.split()
        if w[0] == "trade":
            try:
                p1, p2 = int(w[1][1:]), int(w[2][1:])
                tmp = self.res[p1]; self.res[p1] = self.res[p2]; self.res[p2] = tmp
            except (IndexError, ValueError):
                pass
        elif w[0] == "steal":
            try:
                k = int(w[1][1:]); got = min(3, self.bys[k]); self.bys[k] -= got; self.res[p] += got
            except (IndexError, ValueError):
                pass
        elif w[0] == "donate":
            try:
                k = int(w[1][1:]); donated = min(self.res[p], 3); self.res[p] -= donated; self.bys[k] += donated
            except (IndexError, ValueError):
                pass
        elif w[0] == "attack":
            try:
                k = int(w[1][1:]); self.res[k] //= 2
            except (IndexError, ValueError):
                pass
        elif w[0] == "defend":
            self.res[p] += 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1}. You are P{p}. Resources: {self.res}, Bystanders: {self.bys}"

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

