            moves += ["steal B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
            moves += ["trap P%d" % q for q in range(self.n) if q != p and self.res[q] >= 1]
            moves += ["guard P%d" % q for q in range(self.n) if q != p]
            moves += ["help P%d" % q for q in range(self.n) if q != p and self.res[p] >= 1]
