import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.buildings = [2, 2]; self.bribe_cooldown = [-1] * n_players; self.rnd = 0

    def to_move(self): return self.rnd % self.n

    def legal_moves(self, p):
        moves = ["design"]
        if self.bribe_cooldown[p] < self.rnd:
            moves += ["bribe P%d" % q for q in range(self.n) if q != p]
        if self.res[p] >= 1:
            moves += ["renovate B%d" % b for b in range(len(self.bys))]
            moves += ["sabotage B%d" % b for b in range(len(self.bys))]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "design":
            self.res[p] += 1
        elif w[0] == "bribe":
            q = int(w[1][1:])
            bribe = min(3, self.res[p])
            self.res[p] -= bribe
            self.bribe_cooldown[q] = self.rnd + 2
            if self.rnd == 0:
                self.bribe_effect(p, q)
        elif w[0] == "renovate":
            b = int(w[1][1:])
            self.buildings[b] = min(5, self.buildings[b] + 1)
        elif w[0] == "sabotage":
            b = int(w[1][1:])
            self.buildings[b] = max(0, self.buildings[b] - 1)

        self.rnd += 1

    def bribe_effect(self, p, q):
        if self.rnd == 1:
            if random.random() < 0.5:
                self.buildings[random.randint(0, 1)] += 1
            else:
                self.buildings[random.randint(0, 1)] -= 1

    def describe(self, p):
        return f"Round {self.rnd}. You are P{p}. Reputation {self.res[p]}. Buildings {self.buildings}."

    def over(self): return self.rnd >= 10

    def final_resources(self):
        return [self.res[p] + sum(self.buildings[i*2:(i+1)*2]) for i, p in enumerate(range(self.n))]

    def final_bystanders(self):
        return [0, 0]

