class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.goods = 10; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.market = (sum(endowments) + sum(bystanders)) // 3
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["wait"] + ["offer B%d services" % q for q in others]
        moves = ["buy goods"] + ["sell goods"] + ["steal from P%d" % q for q in others if self.res[q] > 0]
        moves += ["trade with B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "buy":
            if self.goods > 0 and self.res[p] > 0:
                self.goods -= 1; self.res[p] -= 1; self.market += 1
        elif w[0] == "sell":
            if self.res[p] > 0:
                self.res[p] -= 1; self.market += 1
        elif w[0] == "steal":
            if len(w) > 1:
                try:
                    q = int(w[1][1:])
                    if 0 <= q < self.n and self.res[q] > 0:
                        got = min(4, self.res[q]); self.res[q] -= got; self.res[p] += got
                except ValueError:
                    pass
        elif w[0] == "trade":
            if len(w) > 1:
                try:
                    b = int(w[1][1:])
                    if 0 <= b < len(self.bys) and self.bys[b] > 0:
                        self.bys[b] -= 1; self.res[p] += 1
                        self.market += 1
                except ValueError:
                    pass
        self.turn += 1
        if self.turn % self.n == 0:
            self.market = max(0, self.market - 1)

    def describe(self, p):
        return "Round %d of %d. You are P%d. Merchants hold %s, goods %d. Market %d. Bystanders hold %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.goods, self.market, self.bys)

