        self.n = n_players
        self.res = [[3, 1] for _ in range(n_players)]  # Each player starts with 3 coins and 1 item
        self.stolen = [False] * n_players
        self.protected = [False] * n_players
        self.turn = 0
        self.rounds = 6
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.stolen[p]:
            moves.append(f"steal {p}")
        if not self.protected[p]:
            moves.append(f"protect {p}")
        if self.res[p][1] != self.res[(p + 1) % self.n][1]:  # Different items available for trading
            moves.append(f"trade {p}")
        moves.append("rest")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "steal":
            target = int(w[1])
            if not self.stolen[target] and target != p:
                self.stolen[target] = True
                if not self.protected[p]:
                    self.res[p][0] += 1
                    self.res[target][0] -= 1
        elif w[0] == "protect":
            target = int(w[1])
            if target != p:
                self.protected[target] = True
        elif w[0] == "trade":
            target = int(w[1])
            if self.res[p][1] != self.res[target][1]:
                self.res[p][1] = 1 - self.res[p][1]
                self.res[target][1] = 1 - self.res[target][1]
        elif w[0] == "rest":
            self.res[p][0] += 1
        self.turn += 1

    def describe(self, p):
