        elif w[0] == "intimidate":
            q = int(w[1][1:]); self.rep[q] -= 1
        elif w[0] == "defend":
            q = int(w[1][1:]); self.res[p] -= 1; self.rep[q] += 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gems %s. Reputation %s. Bystander Caravans %s." % (
