        self.turn = 0; self.rounds = 7; self.warnings = [False] * n_players
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def cheating(self, p): return self.warnings[p]

    def legal_moves(self, p):
        moves = ["fish"]
        if self.bys[0] > 0:
            moves.append("catch B0")
        if self.bys[1] > 0:
            moves.append("catch B1")
        if self.res[p] >= 1:
            moves.append("warn P%d" % ((p + 1) % self.n))
            moves.append("warn P%d" % ((p + 2) % self.n))
        if self.res[p] >= 2:
            moves.append("bribe B0" if self.bys[0] > 0 else "")
            moves.append("bribe B1" if self.bys[1] > 0 else "")
        return [move for move in moves if move]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            self.res[p] += 1
        elif w[0] == "catch":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                got = self.rng.randint(1, min(4, self.bys[b]))
                self.bys[b] -= got
                self.res[p] += got
                if self.cheating((p - 1) % self.n):
                    self.res[(p - 1) % self.n] = 0
                if self.cheating((p - 2) % self.n):
                    self.res[(p - 2) % self.n] = 0
        elif w[0] == "warn":
            q = int(w[1][1:])
            self.warnings[q] = True
        elif w[0] == "bribe":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                self.bys[b] -= 2
                self.res[p] += 4
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Fish %s. Holes %s. Cheaters: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.cheating(q)] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

