class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.tokens = list([5] * n_players); self.bys = list(bystanders); self.rng = random.Random(seed)
        self.turn = 0; self.rounds = 10

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["gamble"]
        if self.tokens[p] >= 2:
            moves.append("challenge P%d" % ((p + 1) % self.n))
            moves.append("challenge P%d" % ((p - 1) % self.n))
            moves.append("steal from P%d" % ((p + 1) % self.n))
            moves.append("steal from P%d" % ((p - 1) % self.n))
        if self.tokens[p] >= 1:
            moves.append("donate to P%d" % ((p + 1) % self.n))
            moves.append("donate to P%d" % ((p - 1) % self.n))
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gamble":
            outcome = self.rng.randint(1, 2)
            result = 3 if outcome == 1 else 1
            self.tokens[p] += result - 1
        elif w[0] == "challenge":
            target = int(w[1][1:])
            result = self.rng.randint(0, 1)
            if result == 0:
                self.tokens[p] += 1
                self.tokens[target] -= 1
            else:
                self.tokens[p] -= 1
                self.tokens[target] += 1
        elif w[0] == "steal":
            from_player = int(w[2][1:])
            taken = min(1, self.tokens[from_player])
            self.tokens[p] += taken
            self.tokens[from_player] -= taken
        elif w[0] == "donate":
            to_player = int(w[2][1:])
            donated = min(1, self.tokens[p])
            self.tokens[p] -= donated
            self.tokens[to_player] += donated
        self.turn += 1

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d." % (self.turn // self.n + 1, self.rounds, p)]
        rows += ["Player %d: %d tokens" % (q, self.tokens[q]) for q in range(self.n)]
        return "\n".join(rows)

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.tokens)

    def final_bystanders(self):
        return list(self.bys)

