class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.trusted = [1]*n_players; self.accused = [False]*n_players; self.stolen = False

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["plant"]
        if not self.stolen:
            moves += ["steal"]
        if self.res[p] > 0:
            moves += ["harvest F%d" % f for f in range(len(self.bys))]
        if self.trusted[p] > 0:
            for j in range(self.n):
                if p!=j:
                    moves.append("trade P%d" % j)
                    if self.trusted[j]:
                        moves.append("bribe P%d" % j)
                    if not self.accused[j]:
                        moves.append("accuse P%d" % j)
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "plant":
            self.res[p] += 2
        elif w[0] == "steal": 
            self.res[p] += 4; self.stolen = True
        elif w[0] == "harvest":
            f = int(w[1][1:]); gained = self.bys[f]; self.bys[f] = 0; self.res[p] += gained
        elif w[0] == "trade":
            j = int(w[1][1:])
            if self.trusted[j]:
                self.res[p], self.res[j] = self.res[j], self.res[p]
            else:
                self.accused[j] = True
        elif w[0] == "bribe":
            j = int(w[1][1:])
            if self.res[p] >= 3 and self.trusted[j]>0:
                self.res[p] -= 3; self.trusted[j] += 1
        elif w[0] == "accuse":
            j = int(w[1][1:])
            if self.res[p] >= 1:
                self.res[p] -= 1; self.trusted[j] = TRAITOR
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Crops %s. Farms %s. Trusted: %s. Accused: %s. Stolen: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, [f"P{q}" for q in range(self.n) if self.trusted[q]==EFFECTIVE] or "none",
            [f"P{q}" for q in range(self.n) if self.accused[q]] or "none", self.stolen)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

