class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = 3; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.cost = 1
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["farm"]
        for q in range(self.n):
            if q != p and self.res[q] >= 1:
                moves += ["trade G%d" % q]
                moves += ["trade P%d" % q]
                moves += ["rob P%d" % q]
        for b in range(len(self.bys)):
            if self.bys[b] >= 2:
                moves += ["bribe B%d" % b]
            if self.bys[b] >= 1:
                moves += ["gather B%d" % b]
        if self.res[p] >= 1:
            moves += ["help P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        m = move.split(" ")
        if m[0] == "farm":
            self.res[p] -= self.cost; self.res[p] += 1
            self.cost += 1 // max(1, self.cost)
        elif m[0] == "trade":
            if m[1].startswith("G"):
                q = int(m[1][1:])
                if self.res[q] >= 1:
                    self.res[p] -= 1; self.res[p] += 1
                    self.res[q] -= 1; self.res[q] += 1
            else:
                q = int(m[1][1:])
                if self.res[p] >= 1:
                    self.res[p] -= 1; self.res[p] += 1
                    self.res[q] -= 1; self.res[q] += 1
        elif m[0] == "rob":
            q = int(m[1][1:])
            if self.res[q] >= 2:
                self.res[q] -= 2; self.res[p] += 2
        elif m[0] == "bribe":
            b = int(m[1][1:])
            if self.bys[b] >= 2:
                self.bys[b] -= 2; self.res[p] += 1
        elif m[0] == "gather":
            b = int(m[1][1:])
            if self.bys[b] >= 1:
                self.bys[b] -= 1; self.res[p] += 1
        elif m[0] == "help":
            q = int(m[1][1:])
            if self.res[p] >= 1:
                self.res[p] -= 1; self.res[q] += 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Grains: {self.res} Bystanders: {self.bys}"

    def over(self):
        return self.turn >= self.n * self.rounds

