        if self.water[1] > 0:
            moves.append("sail to W1")
        if any(other != p for other in range(self.n)):
            moves.append(f"trade P{p} with you")
        if any(other != p for other in range(self.n)):
            moves.append(f"raid P{p}")
        if any(other != p for other in range(self.n)):
            moves.append(f"gift food to P{p}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            self.res[p] += 1
        elif w[0] == "build dock":
            self.res[p] -= 2
            self.boats[p] -= 1
            self.food_production[p] += 1
        elif w[0] == "sail to W0":
            self.water[0] -= self.food_production[p]
            self.res[p] += self.food_production[p]
        elif w[0] == "sail to W1":
            self.water[1] -= self.food_production[p]
            self.res[p] += self.food_production[p]
        elif w[0] == f"trade P{p} with you":
            self.res[p] -= 1
            for other in range(self.n):
                if other != p and self.res[other] >= 1:
                    self.res[other] -= 1
                    self.res[p] += 1
        elif w[0] == f"raid P{p}":
            for other in range(self.n):
                if other != p:
                    stolen = min(2, self.res[other])
                    self.res[p] += stolen
                    self.res[other] -= stolen
                    self.res[other] -= self.boats[other]
        elif w[0] == f"gift food to P{p}":
            for other in range(self.n):
                if other != p:
                    self.res[other] += 1
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}. You are P{p}. Food {self.res[p]}, Boats {self.boats[p]}, Production {self.food_production[p]}, Water from W0 {self.water[0]}, Water from W1 {self.water[1]}."

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.water)

