- build R: spend money to build a residential building (cost: 5).
- build C: spend money to build a commercial building (cost: 8).
- develop G<k>: spend money to develop plot k and convert into a mixed-use district (cost: 10, yields income each round).
- take B<k>: steal money from developer k.
- donate P<k>: share half of your money with developer k.
- offer P<k>: propose an exchange where you give them your residential buildings and receive their commercial buildings, and vice versa.
At the end, the developer with the most total wealth (buildings + cash) wins.

Good strategies include balancing development and spending, taking advantage of offers, and carefully guarding against theft.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.buildings = [[0, 0] for _ in range(n_players)]  # [residential, commercial]
        self.plots = [10, 10]  # Mixed-use district yields 5 each round
        self.turn = 0
        self.rounds = 10

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 5:
            moves.append(f"build R")
        if self.res[p] >= 8:
            moves.append(f"build C")
        if self.res[p] >= 10:
            for i in range(2):
                moves.append(f"develop G{i}")
        for j in range(self.n):
            if j != p and self.res[j] > 0:
                moves.append(f"take B{j}")
            if j != p:
                moves.append(f"dontate P{j}")
            if j != p and self.buildings[j][0] > 0 and self.buildings[j][1] > 0:
                moves.append(f"offer P{j}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "build":
            kind = w[1]
            cost = 5 if kind == "R" else 8
            if self.res[p] >= cost:
                self.buildings[p][kind == "R"] += 1
                self.res[p] -= cost
        elif w[0] == "develop":
            k = int(w[1][1:])
            if self.res[p] >= 10:
                self.plots[k] = 0
                self.res[p] -= 10
        elif w[0] == "take":
            j = int(w[1][1:])
            got = min(5, self.res[j])
            self.res[j] -= got
            self.res[p] += got
        elif w[0] == "dontate":
            j = int(w[1][1:])
            gave = self.res[p] // 2
            self.res[p] -= gave
            self.res[j] += gave
        elif w[0] == "offer":
            j = int(w[1][1:])
            if self.buildings[j][0] > 0 and self.buildings[j][1] > 0:
                self.buildings[j][0], self.buildings[j][1] = 0, 0
                self.buildings[p][0], self.buildings[p][1] = self.buildings[p][1], self.buildings[p][0]

        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Resources: {self.res}, Buildings: R={self.buildings[p][0]}, C={self.buildings[p][1]}, Plots: {self.plots}"

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return [r + b for r, b in zip(self.res, sum(self.buildings, []))]

    def final_bystanders(self):
        return self.bys

