        self.turn = 0; self.rounds = 10; self.detected = False
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = []
        if self.detected:
            moves.append("hide")
        else:
            moves.extend(["raid"])
            moves.extend(["steal P%d" % q for q in range(self.n) if q != p])
            moves.extend(["spy P%d" % q for q in range(self.n)])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "raid":
            self.bys[0] -= min(4, self.bys[0]); self.res[p] -= 1; self.detected = True
        elif w[0] == "spy":
            q = int(w[1][1:]); self.res[p] -= 1; self.res[q] -= 1
        elif w[0] == "steal":
            q = int(w[1][1:]); self.res[p] += 2; self.res[q] -= 2
        elif w[0] == "hide":
            pass
        self.turn += 1

    def describe(self, p):
        return f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Treasure {self.res[p]}. Ship B0 {self.bys[0]}. Detected: {'yes' if self.detected else 'no'}."

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        for i in range(self.n):
            if self.res[i] < 0:
                self.res[i] = 0
        return self.res

    def final_bystanders(self):
        return self.bys

