class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 10
        self.fortified = [False] * n_players
        self.allies = {i: set() for i in range(n_players)}
        self.risk = [0] * n_players

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def legal_moves(self, p):
        moves = ["recruit"]
        if not self.fortified[p]:
            moves.append(f"fortify C{self.turn % 2}")
        if self.risk[p] == 0:
            moves.append(f"steal C{self.turn % 2}")
        if self.res[p] >= 2:
            moves.append(f"attack C{self.turn % 2}")
        for q in range(self.n):
            if q != p and len(self.allies[q]) > 0:
                moves.append(f"negotiate P{q}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "recruit":
            self.res[p] += 1
        elif w[0] == "fortify":
            b = int(w[1][1:])
            if b == self.turn % 2 and self.res[p] >= 1:
                self.fortified[p] = True
                self.res[p] -= 1
        elif w[0] == "steal":
            b = int(w[1][1:])
            got = min(3, self.bys[b])
            self.bys[b] -= got
            self.res[p] += got
        elif w[0] == "attack":
            b = int(w[1][1:])
            if self.fortified[p]:
                if b == self.turn % 2:
                    self.res[p] -= 2
                    self.risk[p] = 1
                else:
                    self.res[p] -= 2
                    self.risk[p] = 2
                    self.res[p] += self.bys[b]
                    self.bys[b] = 0
            else:
                if b == self.turn % 2:
                    self.res[p] -= 2
                    self.risk[p] = 1
                else:
                    self.res[p] -= 2
                    self.risk[p] = 2
                    self.res[p] += self.bys[b] // 2
                    self.bys[b] //= 2
        elif w[0] == "negotiate":
            q = int(w[1][1:])
            if len(self.allies[q]) > 0:
                self.allies[p].add(q)
                self.allies[q].add(p)
        self.turn += 1

    def describe(self, p):
        return f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Troops {self.res}. Cities {self.bys}. Fortified: {'Yes' if self.fortified[p] else 'No'}. Risk: {self.risk[p]}. Allies: {', '.join(str(q) for q in self.allies[p])}."

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

