class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.flowers = list(endowments); self.bed = list(bystanders)
        self.turn = 0; self.rounds = 10; self.tended = [False] * len(self.bed)

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        for b in range(len(self.bed)):
            if not self.tended[b]:
                moves.append(f"wate B{b}")
            else:
                moves.append(f"sabo B{b}")
        moves.extend([f"steal {q}" for q in range(self.n) if q != p])
        moves.extend([f"gift {self.flowers[p]} to P{q}" for q in range(self.n) if q != p])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "wate":
            b = int(w[1][1:])
            self.flowers[p] += 1
            self.tended[b] = True
        elif w[0] == "sabo":
            b = int(w[1][1:])
            self.bed[b] = max(0, self.bed[b] // 2)
            self.tended[b] = False
        elif w[0] == "steal":
            q = int(w[1])
            stolen = min(2, self.flowers[q]); self.flowers[q] -= stolen; self.flowers[p] += stolen
        elif w[0].startswith("gift"):
            amount = int(w[1])
            q = int(w[3][1:])
            if amount <= self.flowers[p]:
                self.flowers[p] -= amount; self.flowers[q] += amount
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Flowers {self.flowers}. Beds {self.bed}."

    def over(self): 
        return self.turn >= self.n * self.rounds
    def final_resources(self): 
        return list(self.flowers)
    def final_bystanders(self): 
        return list(self.bed)

