import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10
        self.health = [5] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["scavenge P%d" % q for q in others] + ["sneak B%d" % b for b in range(len(self.bys))]
        moves = ["hunt B%d" % b for b in range(len(self.bys))]
        moves += ["defend P%d" % q for q in others if self.health[q] < self.health[p]]
        moves += ["repair B%d" % b for b in range(len(self.bys)) if self.bys[b] < 5 and self.res[p] >= 2]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "hunt":
            b = int(w[1][1:]); gained = self.rng.randint(1, 4); self.bys[b] -= gained; self.res[p] += gained
        elif w[0] == "scavenge":
            q = int(w[1][1:]); gained = self.rng.randint(1, 3); self.res[p] += gained; self.res[q] -= gained
        elif w[0] == "defend":
            q = int(w[1][1:]); self.health[p] += 2; self.health[q] = min(10, self.health[q])
        elif w[0] == "sneak":
            b = int(w[1][1:]); stolen = min(2, self.res[-b - 1]); self.res[p] += stolen; self.res[-b - 1] -= stolen
        elif w[0] == "repair":
            b = int(w[1][1:]); added = min(2, self.res[p]); self.res[p] -= added; self.bys[b] += added
        self.turn += 1
        if self.turn % self.n == 0:
            self.res = [min(x + 5, x) for x in self.res]
            self.bys = [max(0, min(y + 3, y)) for y in self.bys]

    def describe(self, p):
        return "Turn %d of %d. You are P%d. Treasure %s. Health %s. Neutrals %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.health, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return [max(0, x) for x in self.bys]

