Two bystander caves (B0, B1) hold stones but do not play.
- mine: earn 1 stone.
- steal B<k>: take up to 2 stones from cave k.
- guard P<k>: spend 1 stone to prevent P<k> from stealing from the other cave.
- sabotage P<k>: spend 2 stones to reduce P<k>'s stone production by 1 until their next turn.
- bribe P<k>: spend 3 stones to force P<k> to skip their turn.
A miner can only mine once per round unless guarded."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.produced = list(endowments)
        self.guarded = [-1] * n_players; self.sabotaged = [-1] * n_players; self.skipped = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["mine"]
        if p not in self.guarded and self.bys[0] > 0 and self.bys[1] > 0:
            moves += ["steal B%d" % b for b in range(2)]
        if self.res[p] >= 1:
            moves += ["guard P%d" % q for q in range(self.n) if q != p]
        if self.res[p] >= 2:
            moves += ["sabotage P%d" % q for q in range(self.n) if q != p]
        if self.res[p] >= 3:
            moves += ["bribe P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 1; self.produced[p] += 1
        elif w[0] == "steal":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "guard":
            self.res[p] -= 1; self.guarded[int(w[1][1:])] = self.rnd()
        elif w[0] == "sabotage":
            self.res[p] -= 2; self.sabotaged[int(w[1][1:])] = self.rnd() + 1
        elif w[0] == "bribe":
            self.res[p] -= 3; self.skipped[int(w[1][1:])] = self.rnd()
        self.turn += 1

    def describe(self, p):
        s = "Round %d of %d. You are P%d. Stones %s. Produced %s. Bystander caves %s.\n" % (
            self.rnd() + 1, self.rounds, p, self.res, self.produced, ', '.join(map(str, self.bys)))
        s += "Guarded: " + ", ".join(("P%d" % q for q in range(self.n) if self.guarded[q] >= self.rnd())) + "\n"
        s += "Sabotaged: " + ", ".join(("P%d" for q in range(self.n) if self.sabotaged[q] >= self.rnd())) + "\n"
        s += "Skipped: " + ", ".join(("P%d" for q in range(self.n) if self.skipped[q] >= self.rnd()))
        return s

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

