import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.sanctioned = [-1] * n_players
        self.risk = 0.3

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["Extract"]
        if self.sanctioned[p] <= self.rnd():
            moves.append("Mine asteroid")
        moves += ["Sanction P%d" % q for q in range(self.n) if q != p]
        moves += ["Contribute to B%d" % b for b in range(len(self.bys))]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Extract":
            self.res[p] += 1
        elif w[0] == "Mine asteroid":
            if random.random() < self.risk:
                self.res[p] -= 1
            self.res[p] += 2
        elif w[0] == "Sanction":
            self.sanctioned[p] = self.rnd()
        elif w[0] == "Contribute":
            try:
                b = int(w[1][1:])
                self.res[p] -= 1
                if self.bys[b] > 0:
                    self.res[p] += 2 * self.bys[b]
            except (ValueError, IndexError):
                pass
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gas %s. Contribution to B0: %d, B1: %d. Sanctioned against: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys[0], self.bys[1],
            "P%d" % self.sanctioned[p] if self.sanctioned[p] >= 0 else "None")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

