            if q != p and q < len(self.res):
                moves.append(f"trade {q}")
                moves.append(f"rob {q}")
            if q < len(self.bys) and self.bys[q] > 0:
                moves.append(f"attack {q}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            self.res[p] += 1
        elif w[0] == "build":
            self.res[p] -= 1
            self.population[p] += 1
        elif w[0] == "trade":
            q = int(w[1])
            if q != p and self.res[p] > 0 and self.res[q] > 0 and self.population[p] > 0 and self.population[q] > 0:
                self.res[p], self.res[q] = self.res[q], self.res[p]
                self.population[p], self.population[q] = self.population[q], self.population[p]
        elif w[0] == "rob":
            q = int(w[1])
            if q != p and self.res[q] > 0:
                got = min(3, self.res[q])
                self.res[q] -= got
                self.res[p] += got
        elif w[0] == "attack":
            q = int(w[1])
            if q != p and self.res[p] >= 2 and q < len(self.bys):
                self.res[p] -= 2
                self.bys[q] = max(self.bys[q] - 2, 0)
                self.inflation += 1

        self.turn += 1

        if self.population[p] == 0:
            self.res[p] = 0

        if self.inflation > 4 and self.population[p] < 5 and self.res[p] < 2 * self.population[p]:
            self.population[p] = max(1, self.population[p] - 1)

        if self.turn % self.n == 0:
            self.land_value *= 1.1
            self.res[p] += self.population[p]
            for q in range(self.n):
                if q < len(self.bys) and self.bys[q] > 0:
                    self.bys[q] -= 1
                else:
                    self.res[q] += 1
            if self.rng.randint(0, 100) < self.inflation * 10:
                self.bys[0] += 1

        if self.bys[0] >= 10:
            self.final_resources()[0] -= 5
            self.final_bystanders()[0] -= 10

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Resources {self.res}, Population {self.population}, Inflation {self.inflation}. Land value {self.land_value:.2f}, Treasure site {self.treasure_site}, Bystander treasures {self.bys[0]}."

    def over(self): 
        return self.turn >= self.n * self.rounds

    def final_resources(self): 
        return list(self.res)

    def final_bystanders(self): 
        return list(self.bys)

