Two bystander traps (T0, T1) hold food but do not play.
- hunt: shoot an arrow and earn 1 food.
- lay trap B<k>: set a trap to catch food, which will be available for up to 2 rounds.
- steal F<k>: take up to 3 food from trap k if you were there when it was filled.
- accuse P<k>: use accusation on a suspect hunter costs you nothing; using it on an innocent one costs you 1 arrow; either way the allegation is noted, and nothing else happens.
A hunter is guilty if they stole from a trap this game and have not been accused since.
Only a hunter with at least 1 arrow can accuse."""

EFFECTIVE = False
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.traps = list(bystanders)
        self.turn = 0
        self.rounds = 10
        self.owed = [[0] * 2 for _ in range(n_players)]
        self.accused = [-1] * n_players
        self.trap_times = [0] * 2

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def guilty(self, q):
        return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["hunt"]
        if self.trap_times[0] <= self.rnd() or self.trap_times[1] <= self.rnd():
            moves += ["lay trap B%d" % b for b in range(2) if self.traps[b] == 0]
        if self.res[p] >= 1 and (self.trap_times[0] <= self.rnd() or self.trap_times[1] <= self.rnd()):
            moves += ["steal F%d" % b for b in range(2)]
        if COST == "free" or self.res[p] >= 1:
            moves += ["accuse P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "hunt":
            self.res[p] += 1
        elif w[0] == "lay trap":
            b = int(w[1][1:])
            if b == 0:
                self.traps[0] = self.rnd() + 2
            elif b == 1:
                self.traps[1] = self.rnd() + 2
        elif w[0] == "steal":
            b = int(w[1][1:])
            if (self.trap_times[0] <= self.rnd() and b == 0) or (self.trap_times[1] <= self.rnd() and b == 1):
                got = min(3, self.traps[b])
                self.traps[b] = 0
                self.res[p] += got
                self.owed[p][b] += got
        elif w[0] == "accuse":
            q = int(w[1][1:])
            guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(2):
                    back = min(self.owed[q][b], self.res[q])
                    self.res[q] -= back
                    self.traps[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q])
                    self.res[q] -= paid
                    self.res[p] += paid
                self.accused[q] = self.rnd() + 2
            self.owed[q] = [0] * 2
        self.turn += 1

    def describe(self, p):
        return "Round {} of {}. You are P{}. Arrows {}. Traps {}. Guilty (stole from a trap, not yet accused): {}. Accused from accusing: {}".format(
            self.rnd() + 1, self.rounds, p, self.res[p], self.traps, ['P' + str(q) for q in range(self.n) if self.guilty(q)] or "none", 
            ['P' + str(q) for q in range(self.n) if self.accused[q] >= self.rnd()] or "none")

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.traps)

