import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 10
        self.stolen_tokens = {p: [] for p in range(n_players)}
        self.accusation_timer = {p: 0 for p in range(n_players)}
        self.guard_timer = {p: 0 for p in range(n_players)}

        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Hunt", "Fish"]
        if self.res[p] >= 1:
            moves += [f"Steal B{i}" for i in range(len(self.bys))]
        if self.accusation_timer[p] <= 0:
            moves += [f"Accuse P{i}" for i in range(self.n) if i != p]
        if self.res[p] >= 1:
            moves += [f"Guard P{i}" for i in range(self.n) if i != p]
        if self.res[p] >= 2:
            moves += [f"Bribe P{i}" for i in range(self.n) if i != p]
        if self.res[p] >= 1:
            moves += [f"Trade B{i}" for i in range(len(self.bys))]
        return moves

    def play(self, p, move):
        w = move.split()
        if w[0] == "Hunt":
            self.res[p] += 2
        elif w[0] == "Fish":
            self.res[p] += 1
        elif w[0].startswith("Steal"):
            b = int(w[1][1:])
            if self.bys[b] > 0:
                tokens_stolen = min(3, self.bys[b])
                self.bys[b] -= tokens_stolen
                self.res[p] += tokens_stolen
                self.res[p] -= 1
                self.stolen_tokens[p].append(tokens_stolen)
        elif w[0].startswith("Accuse"):
            q = int(w[1][1:])
            if self.stolen_tokens[q]:
                for tokens in self.stolen_tokens[q]:
                    self.res[q] -= tokens
                self.stolen_tokens[q] = []
                self.accusation_timer[q] = 2
        elif w[0].startswith("Guard"):
            q = int(w[1][1:])
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.guard_timer[q] = 2
        elif w[0].startswith("Bribe"):
            q = int(w[1][1:])
            if self.res[p] >= 2:
                self.res[p] -= 2
                self.guard_timer[q] = 2
        elif w[0].startswith("Trade"):
            b = int(w[1][1:])
            if self.bys[b] > 0:
                self.res[p] += self.bys[b]
                self.bys[b] = 0
        self.turn += 1

    def describe(self, p):
        my_tokens = self.res[p]
        bystanders = ', '.join([f"B{i}: {self.bys[i]}" for i in range(len(self.bys))])
        stolen_by_me = ', '.join(map(str, self.stolen_tokens[p]))
        accused_by_me = ', '.join([f"P{i}" for i in range(self.n) if self.accusation_timer[i]])
        guarded_by_me = ', '.join([f"P{i}" for i in range(self.n) if self.guard_timer[i]])
        return f"Turn {self.turn + 1}/{self.rounds}. You are P{p}. Tokens: {my_tokens}. Bystanders: {bystanders}. Stolen by you: {stolen_by_me}. Accused by you: {accused_by_me}. Guarded by you: {guarded_by_me}."

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

