        if self.buildings[p][1] < 2:
            moves.append(f"construct B{1}")
        if self.stones[p] >= 2:
            moves.append(f"demolish B{0}")
        if self.stones[p] >= 2:
            moves.append(f"demolish B{1}")
        if self.stones[p] >= 1:
            moves.append(f"inspect P{p}")
