        other_buildings = ", ".join([f"P{i}: B0x{self.buildings[i][0]}, B1x{self.buildings[i][1]}" for i in range(self.n) if i != p])
        return f"Turn {self.turn}. You are P{p}. Stones {self.stones[p]}. Buildings {my_buildings}. Other Buildings {other_buildings}"

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return self.stones

