class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.goods = [10] * n_players; self.coins = [10] * n_players; self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8; self.guarded = [-1] * n_players; self.sanctioned = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = []
        if self.goods[p] > 0:
            moves.append("trade")
        moves.append("buy")
        if self.goods[p] > 0:
            moves.append("sell")
        if self.bys[0] > 0 or self.bys[1] > 0:
            moves.extend(["rob B%d" % b for b in range(2)])
        if self.goods[p] > 0:
            for q in range(self.n):
                if q != p and self.goods[q] > 0:
                    moves.append("rob P%d" % q)
        if self.goods[p] > 0:
            for q in range(self.n):
                moves.append("guard P%d" % q)
            for q in range(-1, self.n - 1):
                moves.append("sanction P%d" % q)
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            self.goods[p] -= 1; self.coins[p] += 1
        elif w[0] == "buy":
            self.goods[p] += 1; self.coins[p] -= 1
        elif w[0] == "sell":
            self.goods[p] -= 1; self.coins[p] += 1
        elif w[0] == "rob":
            if w[1][0] == "B":
                b = int(w[1][1:])
                stolen = min(self.bys[b], 1); self.bys[b] -= stolen; self.goods[p] += stolen
            else:
                q = int(w[1][1:])
                stolen = min(self.goods[q], 1); self.goods[q] -= stolen; self.goods[p] += stolen
        elif w[0] == "guard":
            q = int(w[1][1:])
            self.guarded[p] = q
        elif w[0] == "sanction":
            q = int(w[1][1:]) if w[1] != "all" else -1
            if q == -1:
                for i in range(self.n):
                    if self.sanctioned[i] < self.rnd():
                        self.sanctioned[i] = -1
            elif q != p and self.goods[q] > 0:
                self.goods[q] -= 1; self.coins[q] -= 1
                if self.sanctioned[q] < self.rnd():
                    self.sanctioned[q] = self.rnd() + 1
        self.turn += 1

    def describe(self, p):
        guarded = ["P%d" % q for q in range(self.n) if self.guarded[p] == q] or "none"
        sanctioned = ["P%d" % q for q in range(self.n) if self.sanctioned[q] == self.rnd()] or "none"
        return f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Goods {self.goods[p]}, Coins {self.coins[p]}. Guarded against: {guarded}. Sanctioned: {sanctioned}. Bystander B0 holds {self.bys[0]} goods, Bystander B1 holds {self.bys[1]} goods."

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return [g + c for g, c in zip(self.goods, self.coins)]
    def final_bystanders(self): return self.bys

