import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = []
        for b in range(len(self.bys)):
            moves.append(f"steal from B{b}")
            moves.append(f"guard B{b}")
            if self.bys[b] >= 4 and p != 0:
                moves.append(f"bribe B{b}")
        for m in range(self.n):
            if p != m and self.res[m] >= 2:
                moves.append(f"fence stolen goods to P{m}")
        if p != 0:
            moves.append(f"report P{p}")
        return moves

    def play(self, p, move):
        try:
            w = move.split(" ")
            action = w[0]
            if action == "steal":
                b = int(w[2][1:]) if len(w) > 2 and w[2].startswith("B") else None
                if b is not None and b >= 0 and b < len(self.bys):
                    if p != 0 and b == 0 and self.bys[1] < 10:
                        self.bys[1] += 2
                    got = min(5, self.bys[b])
                    self.bys[b] -= got
                    self.res[p] += got
            elif action == "guard":
                b = int(w[1][1:]) if len(w) > 1 and w[1].startswith("B") else None
                if b is not None and b >= 0 and b < len(self.bys):
                    if self.res[p] >= 3:
                        self.res[p] -= 3
                        self.bys[b] += 1
            elif action == "bribe":
                b = int(w[1][1:]) if len(w) > 1 and w[1].startswith("B") else None
                if b is not None and b >= 0 and b < len(self.bys):
                    if self.bys[b] >= 4 and p != 0:
                        self.bys[b] -= 4
                        self.res[p] += 1
            elif action == "fence":
                m = int(w[2][1:]) if len(w) > 2 and w[2].startswith("P") else None
                if m is not None and m >= 0 and m < len(self.res):
                    if self.res[m] >= 2:
                        self.res[m] -= 2
                        self.res[p] += 2
            elif action == "report":
                m = int(w[1][1:]) if len(w) > 1 and w[1].startswith("P") else None
                if m is not None and m >= 0 and m < len(self.res):
                    for q in range(self.n):
                        if self.res[q] >= 2:
                            self.res[q] -= 2
        except ValueError:
            pass
        self.turn += 1

    def describe(self, p):
        return f"Round {self.rnd()+1} of {self.rounds}. You are P{p}. Gold coins {self.res}. Bystanders {self.bys}."

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Trade City. 3 traders, 10 rounds, one move each per round. Start with goods (resources).
- buy S: spend 1 good to get 2 from stock.
- sell S: earn 1 good for every good you own.
- trade S with P<k>: exchange all your goods with trader k.
- bribe B<k>: pay 1 good to bypass the inspection of bystander k's goods.
- inspect B<k>: pay 1 good to see how many goods bystander k has.
- guard P<k>: pay 1 good to prevent trader k from selling goods.
- sanction P<k>: pay 2 goods to force trader k to discard half their goods.
A trader with 0 goods is bankrupt and can no longer make trades. Goods in bystander bags increase by 1 each round."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.goods = list(endowments); self.bys_goods = list(bystanders)
        self.turn = 0; self.rounds = 10
        self.inspection = [-1] * len(bystanders)
        self.guarded = [False] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        bystanders = [(i, g) for i, g in enumerate(self.bys_goods) if self.inspection[i] == -1]
        moves = ["buy S"]
        if self.goods[p] > 0:
            moves.append("sell S")
        for i, _ in bystanders:
            moves.append(f"bribe B{i}")
            moves.append(f"inspect B{i}")
        if not self.guarded[p]:
            for q in others:
                moves.append(f"guard P{q}")
        if self.goods[p] > 1:
            for q in others:
                moves.append(f"sanction P{q}")
        return moves

    def play(self, p, move):
        w = move.split()
        if w[0] == "buy":
            if self.goods[p] > 0:
                self.goods[p] -= 1
                self.goods[p] += 2
        elif w[0] == "sell":
            self.goods[p] += 1
        elif w[0] == "trade":
            q = int(w[1][1:])
            self.goods[p], self.goods[q] = self.goods[q], self.goods[p]
        elif w[0] == "bribe":
            b = int(w[1][1:])
            self.goods[p] -= 1
            self.bys_goods[b] += 1
        elif w[0] == "inspect":
            b = int(w[1][1:])
            self.goods[p] -= 1
            self.inspection[b] = self.turn
        elif w[0] == "guard":
            q = int(w[1][1:])
            self.goods[p] -= 1
            self.guarded[q] = True
        elif w[0] == "sanction":
            q = int(w[1][1:])
            self.goods[p] -= 2
            self.goods[q] //= 2
        self.turn += 1
        if self.turn % self.n == 0:
            for b in range(len(self.bys_goods)):
                if self.inspection[b] == self.turn - 1:
                    self.bys_goods[b] += 1
                self.inspection[b] = -1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Goods {self.goods}. Bystander goods {self.bys_goods}. Guarded: {self.guarded}"

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return [max(g, 0) for g in self.goods]
    def final_bystanders(self): return [max(g, 0) for g in self.bys_goods]

