import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.wells = [0] * 2; self.fields = [[0, 0, 0] for _ in range(n_players)]; self.turn = 0; self.rounds = 10
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        for i, amount in enumerate(self.wells):
            if amount < 3:
                moves.append(f"dig well{i}")
        for j, crop in enumerate(self.fields[p]):
            if crop == 0 and self.res[p] >= 2:
                moves.append(f"plant {j}")
        if self.res[p] >= 1:
            moves.append(f"irrigate well{p%2}")
        for q in range(self.n):
            if q != p:
                moves.append(f"trade {q} {min(3, self.res[p])}")
        for b in range(len(self.bys)):
            moves.append(f"rob B{b} {min(3, self.bys[b]) // 2}")
        return moves

    def play(self, p, move):
        parts = move.split()
        if parts[0] == "dig":
            w = int(parts[1][-1])
            self.res[p] -= 1; self.wells[w] += 2
        elif parts[0] == "plant":
            f = int(parts[1])
            self.res[p] -= 2; self.fields[p][f] = 2
        elif parts[0] == "irrigate":
            w = int(parts[1][-1])
            self.res[p] -= 1; self.wells[w] += 1; self.wells[(w+1)%2] -= 1
        elif parts[0] == "trade":
            q = int(parts[1]); amount = int(parts[2])
            if self.res[p] >= amount and self.res[q] >= amount:
                self.res[p] -= amount; self.res[q] -= amount; self.res[p] += amount; self.res[q] += amount
        elif parts[0] == "rob":
            b = int(parts[1][1:]) - 1
            amount = int(parts[2])
            if self.bys[b] >= amount:
                self.res[p] += amount; self.bys[b] -= amount
        self.turn += 1

    def describe(self, p):
        res_str = ", ".join(str(x) for x in self.res)
        well_str = ", ".join(str(x) for x in self.wells)
        field_str = "; ".join(", ".join(str(crop) for crop in farmer) for farmer in self.fields)
        bystander_str = ", ".join(str(max(0, x)) for x in self.bys)  # Ensure non-negative values
        return f"Round {self.turn // self.n + 1} of {self.rounds}. Player {p}: {res_str} resources. Wells: {well_str}. Fields: {field_str}. Bystanders: {bystander_str}"

    def over(self): return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(map(max, self.res, [0]*len(self.res)))  # Ensure non-negative values

    def final_bystanders(self):
        return list(map(max, self.bys, [0]*len(self.bys)))  # Ensure non-negative values

