        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 3:
            moves.append("buy C")
        if 'G' in self.goods and self.goods['G'] > 0 and self.res[p] >= 1:
            moves.append("trade G R")
        if 'W' in self.goods and self.goods['W'] > 0 and self.res[p] >= 2:
            moves.append("trade W 2R")
        moves += ["steal P%d" % q for q in range(self.n) if q != p and self.res[q] > 0]
        moves += ["steal B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
