import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.apples = list(endowments); self.gold = [0] * n_players; self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 7; self.fences = [False] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = []
        if self.apples[p] > 0:
            moves.append("sell")
        moves += ["buy A%d" % q for q in range(self.n) if q != p and self.apples[q] > 0]
        moves += ["buy B%d" % b for b in range(len(self.bys))] if self.apples[p] > 0 else []
        if self.apples[p] > 0:
            moves.append("guard A")
        moves += ["guard B%d" % b for b in range(len(self.bys))]
        if not self.fences[p]:
            moves.append("fence")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "sell":
            self.gold[p] += self.apples[p]; self.apples[p] = 0
        elif w[0] == "buy":
            k = int(w[1][1:])
            if w[1][0] == "A":
                if self.apples[k] > 0 and self.apples[p] > 0:
                    self.apples[p] -= 2; self.apples[k] += 2; self.gold[p] += 2
            else:
                if self.bys[k] > 0 and self.apples[p] > 0:
                    self.apples[p] -= 2; self.bys[k] += 2; self.gold[p] += 2
        elif w[0] == "attack":
            k = int(w[1][1:])
            if w[1][0] == "A":
                success = self.rng.randint(0, 1) == 0; self.apples[p] -= 1
                if success:
                    self.apples[k] -= 1
            else:
                success = self.rng.randint(0, 1) == 0; self.apples[p] -= 1
                if success:
                    self.bys[k] -= 1
        elif w[0] == "guard":
            if w[1] == "A":
                self.fences[p] = True
            else:
                self.fences[p] = True
        elif w[0] == "fence":
            self.fences[p] = True

        self.turn += 1
        if self.turn % self.n == 0 and self.fences[p]:
            self.apples[p] = max(self.apples[p] - 1, 0)

    def describe(self, p):
        return "Round %d of %d. You are P%d. Apples %s. Gold %s. Fenced: %s. Bystander apples %s." % (
            self.rnd() + 1, self.rounds, p, self.apples, self.gold, self.fences[p], self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return [self.apples[p] + self.gold[p] for p in range(self.n)]
    def final_bystanders(self): return self.bys

