class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        import random
        self.rng = random.Random(seed)
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.safe = [True, True]
        self.reserve = sum(endowments) // 2 + 3

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["fish"]
        if self.safe[0]:
            moves.append("plunder B0")
        if self.safe[1]:
            moves.append("plunder B1")
        if self.res[p] >= 1:
            moves += ["trade P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            got = min(1, self.reserve); self.reserve -= got; self.res[p] += got
        elif w[0] == "plunder":
            b = 0 if w[1][1:] == "0" else 1; got = self.bys[b]; self.bys[b] = 0; self.res[p] += got
            self.safe[b] = False
        elif w[0] == "trade":
            q = int(w[1][1:]); self.res[p] -= 1; self.res[q] += 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Fish %s. Boats %s. Safe boats: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys,
            ["B%d" % b for b in range(len(self.bys)) if self.safe[b]] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

