class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 7
        self.felled = [[False] * len(bystanders) for _ in range(n_players)]
        self.sacred = [[False] * len(bystanders) for _ in range(n_players)]

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def marked(self, p, t):
        return self.sacred[p][t]

    def felled_at(self, t):
        return any(self.felled[i][t] for i in range(self.n))

    def legal_moves(self, p):
        moves = ["chop"]
        for t in range(len(self.bys)):
            if not self.felled_at(t):
                moves += ["fell T%d" % t]
            if not self.marked(p, t) and not self.felled_at(t):
                moves += ["mark T%d" % t]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "chop":
            self.res[p] += 1
        elif w[0] == "fell":
            t = int(w[1][1:])
            if not self.felled_at(t):
                self.felled[p][t] = True
        elif w[0] == "mark":
            t = int(w[1][1:])
            if not self.marked(p, t) and not self.felled_at(t):
                self.sacred[p][t] = True
                if p != self.to_move():
                    self.res[self.to_move()] -= 1

        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Wood %s. Trees %s. Felled: %s. Sacred: %s. Your opponent will pay if you mark their tree." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, 
            ["T%d" % t for t in range(len(self.bys)) if self.felled_at(t)], 
            ["T%d" % t for t in range(len(self.bys)) if self.marked(p, t)])

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

