import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.food = [0] * n_players
        self.bystander_food = list(bystanders)
        self.hunting_round = 0
        self.steal_cooldowns = [-1] * n_players
        self.guard_cooldowns = [-1] * n_players
        self.rng = random.Random(seed)

    def to_move(self):
        return self.hunting_round % self.n

    def legal_moves(self, p):
        moves = []
        if self.food[p] >= 1:
            moves.append(f"hunt R")
        if self.food[p] >= 2:
            moves.append(f"hunt D")
        if self.bystander_food[0] > 1 and self.steal_cooldowns[p] <= self.hunting_round:
            moves.append("steal R from B0")
        if self.bystander_food[1] > 1 and self.steal_cooldowns[p] <= self.hunting_round:
            moves.append("steal D from B1")
        if self.food[p] >= 1 and self.guard_cooldowns[p] <= self.hunting_round:
            moves.append("guard B0")
        if self.food[p] >= 1 and self.guard_cooldowns[p] <= self.hunting_round:
            moves.append("guard B1")
        return moves

    def play(self, p, move):
        action = move.split(' ')
        if action[0] == "hunt":
            prey_type = action[1]
            if prey_type == "R":
                self.food[p] -= 1
                self.bystander_food[0] += 1
            elif prey_type == "D":
                self.food[p] -= 2
                self.bystander_food[1] += 1
        elif action[0] == "steal":
            target_bystander = action[-1]
            target_index = int(target_bystander[1:]) - 1
            if self.bystander_food[target_index] > 1:
                stolen_count = self.bystander_food[target_index] // 2
                self.bystander_food[target_index] -= stolen_count
                self.food[p] += stolen_count
                self.steal_cooldowns[p] = self.hunting_round + 1
        elif action[0] == "guard":
            target_bystander = action[-1]
            target_index = int(target_bystander[1:]) - 1
            self.food[p] -= 1
            self.guard_cooldowns[p] = self.hunting_round + 1

        self.hunting_round += 1

    def describe(self, p):
        return f"Hunting Round {self.hunting_round} of 10. You are Hunter {p}. Your food: {self.food[p]}.\nBystander B0 has {self.bystander_food[0]} rabbits, Bystander B1 has {self.bystander_food[1]} deers."

    def over(self):
        return self.hunting_round >= 10

    def final_resources(self):
        return self.food[:]

    def final_bystanders(self):
        return self.bystander_food[:]

