            moves.append("bribe")
        if self.bys[0] > 0 and self.bank_coins >= 3:
            moves.append("rob B0")
        if self.bank_access[p] < self.rounds:
            moves.append("sabotage B0")
        if self.bank_coins >= 1:
            moves.append("finesse B0")
        return moves

