            self.bys[0] -= got; self.res[p] += got
        elif w[0] == "sabotage":
            self.res[p] -= 1; self.bank_coins = 0
        elif w[0] == "finesse":
            self.res[p] -= 1; taken = self.bys[0] // 2; self.bys[0] -= taken; self.res[p] += taken
