    def legal_moves(self, p):
        moves = ["mine"]
        for q in range(self.n):
            if q != p and self.res[q] > 0:
                moves.append(f"rob V{q}")
        for b in range(len(self.bys)):
            if self.bys[b] > 0:
                moves.append(f"steal H{b}")
        for b in range(2):
            if self.bys[b] > 0 and self.vulnerability[p][b] == 0:
                moves.append(f"bribe B{b}")
