            for q in range(self.n):
                for b in range(2):
                    if self.bys[b] > 0 and self.vulnerability[q][b] > 0:
                        self.vulnerability[q][b] -= 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Villages hold {self.res}, huts hold {self.bys}. Vulnerability to robbery: {self.vulnerability}"

