                self.res[p] -= 1; self.plots[p] += 1
        elif w[0] == "harvest":
            self.res[p] += self.plots[p]; self.plots[p] = 0
        elif w[0] == "trade":
            if self.res[p] >= 1 and self.res[int(w[2][1:])] >= 1:
                self.res[p] -= 1; self.res[int(w[2][1:])] -= 1; self.res[p] += 1; self.res[int(w[2][1:])] += 1
        elif w[0] == "steal":
            b = int(w[1][1:])
            max_steal = min(4, self.bys[b])
            if max_steal > 0:
                self.bys[b] -= max_steal; self.stolen[p] += max_steal
        elif w[0] == "donate":
            b = int(w[1][1:])
            if self.res[p] >= 1:
                self.res[p] -= 1; self.bys[b] += 1
        elif w[0] == "guard":
            q = int(w[1][1:])
            if self.res[p] >= 1:
                self.res[p] -= 1; self.stolen[q] = max(0, self.stolen[q] - 1)
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Farmers hold {self.res}, plots {self.plots}. Bystanders hold {self.bys}. Stolen by {self.stolen}."

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return [max(r, 0) for r in self.res]

    def final_bystanders(self):
        return self.bys

