- fish B<k>: take up to 1 arrow from bystander k, a river guide who does not play.
A hunter at 0 arrows can only heal or target P<k> (the forest provides 1). The forest is limited."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.arrows = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.health = [5] * n_players
        self.reserve = (sum(endowments) + sum(bystanders)) // 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.arrows[p] == 0:
            return ["heal"] + ["target P%d" % q for q in others]
        moves = ["heal"] + (["hunt"] if self.health[p] >= 3 else [])
        moves += ["shoot P%d" % q for q in others]
        return moves + ["fish B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] in ("hunt", "heal"):
            q = int(w[1][1:]) if w[0] == "target" else p
            got = min(2 if q == p else 1, self.reserve); self.reserve -= got; self.arrows[q] += got
        elif w[0] == "heal":
            self.health[p] = min(8, self.health[p] + 2)
        elif w[0] == "shoot":
            q = int(w[1][1:]); self.health[q] = max(0, self.health[q] - 2)
            if self.health[q] == 0:
                self.arrows[p] += self.arrows[q]; self.arrows[q] = 0; self.health[q] = 3
        elif w[0] == "fish":
            b = int(w[1][1:]); got = min(1, self.bys[b]); self.bys[b] -= got; self.arrows[p] += got
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Arrows %s. Health %s. Reserve %d. Guides %s." % (
            self.turn // self.n + 1, self.rounds, p, self.arrows, self.health, self.reserve, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.arrows)
    def final_bystanders(self): return list(self.bys)

