import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 10
        self.owed = [[0] * len(bystanders) for _ in range(n_players)]
        self.barred = [-1] * n_players
        self.current_guard = None
        self.warning_issued = False
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["gather"]
        if self.current_guard != p:
            moves.append(f"plunder G{p}")
        if self.warning_issued:
            moves.append(f"warn W{p}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            self.res[p] += 1
        elif w[0] == "plunder":
            if 0 <= int(w[1][1:]) < len(self.bys):
                g = int(w[1][1:])
                if self.current_guard == p:
                    self.bys[g] += 4
                else:
                    self.bys[g] -= 4
                    if self.bys[g] < 0:
                        self.bys[g] = 0
                        self.res[p] = 0
        elif w[0] == "warn":
            if self.warning_issued is False:
                self.warning_issued = True
                self.res[p] -= 1
        self.current_guard = None
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn} of {self.rounds}. You are P{p}. Seeds {self.res[p]}. Groves {self.bys}. Potential Plunderers: {[f'P{i}' for i in range(3) if i != p and self.current_guard != i]}"

    def over(self):
        return self.turn >= self.rounds * self.n

