class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 9; self.atm = [1.0] * len(bystanders)
        self.vcap = [6, 6]  # Venue capacities
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        mvs = ["sing V%d" % v if self.res[p] >= 2 else ""
               for v in range(len(self.bys))]
        mvs.extend(["move V%d" % v for v in range(len(self.bys))])
        if self.res[p] >= 1:
            mvs.append("rest")
            mvs.extend(["attract P%d" % q for q in range(self.n) if q != p])
            mvs.extend(["donate B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0])
        return [mv for mv in mvs if mv]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "sing":
            v = int(w[1][1:])
            if v < len(self.bys) and self.atm[v] <= 0.5:
                self.res[p] += self.bys[v]  # Weak atmosphere helps boost performance
            elif v < len(self.bys):
                self.res[p] += int((self.bys[v] * self.atm[v]) ** 0.5)
        elif w[0] == "move":
            self.res[p] -= 1
        elif w[0] == "rest":
            self.res[p] += 1
        elif w[0] == "attract":
            q = int(w[1][1:])
            if q < len(self.bys):
                self.bys[q] += 1
        elif w[0] == "donate":
            b = int(w[1][1:])
            if b < len(self.bys):
                self.bys[b] -= 1
                self.res[p] += 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Energy {self.res}. Atmosphere {self.atm}. Venues {self.bys}."

    def over(self): return self.turn >= self.n * self.rounds

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

