class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.flowers = list(bystanders)
        self.turn = 0
        self.rounds = 7
        self.investigated = [0] * self.n
        self.guarded = [-1] * len(self.flowers)

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def legal_moves(self, p):
        moves = ["plant"]
        if self.res[p] >= 1:
            moves += ["steal F%d" % f for f in range(len(self.flowers))]
        if self.res[p] >= 1:
            moves += ["accuse P%d" % q for q in range(self.n) if q != p]
        if -1 not in self.guarded:
            moves += ["guard F%d" % f for f in range(len(self.flowers)) if f not in self.guarded]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "plant":
            self.res[p] += 1
        elif w[0] == "steal":
