            if self.investigated[q] == 1:
                self.res[p] -= 1
            self.investigated[q] += 1
        elif w[0] == "guard":
            f = int(w[1][1:])
            self.guarded[f] = p
        self.turn += 1

    def describe(self, p):
        guards = [f for f, g in enumerate(self.guarded) if g == p]
        return f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Seeds {self.res}. Flower pots {self.flowers}. Guards {guards}. Investigated {self.investigated}."

    def over(self):
        return self.turn >= self.n * self.rounds

