import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.guards = [[2, 2] for _ in range(n_players)]
        self.bys = list(bystanders); self.security = [0, 0]; self.turn = 0; self.rounds = 12
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        for q in range(self.n):
            if q != p:
                moves.append(f"steal from P{q}")
        moves.append("defend yourself")
        for b in range(len(self.bys)):
            moves.extend([f"fortify B{b}", f"attack B{b}"])
        moves.append("trade R")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "steal":
            try:
                q = int(w[1][2:])
                stolen = min(2, self.res[q])
                self.res[q] -= stolen; self.res[p] += stolen
            except ValueError:
                return False
        elif w[0] == "defend":
            self.guards[p][0] += 1
        elif w[0] == "fortify":
            self.security[int(w[1][1:])] += 1
        elif w[0] == "attack":
            b = int(w[1][1:])
            self.security[b] -= 1
        elif w[0] == "trade":
            if self.bys[0] > 0:
                self.bys[0] -= 1; self.guards[p][1] += 1
            elif self.bys[1] > 0:
                self.bys[1] -= 1; self.guards[p][1] += 1
        self.turn += 1
        return True

    def describe(self, p):
        return f"Turn {self.turn}/{self.rounds}. You are P{p}. Resources {self.res}, Guards {self.guards[p]}, Security {self.security}"

    def over(self): return self.turn >= self.rounds * self.n

    def final_resources(self):
        scores = [r + g for r, g in zip(self.res, [g[1] for g in self.guards])]
        for i in range(self.n):
            if self.res[i] == 0:
                scores[i] = 0
        return scores

    def final_bystanders(self): return self.bys

