        moves = ["plant"] if self.res[p] > 0 and self.fields[p] not in (0, 1) else []
        moves += ["harvest"] if self.fields[p] != 2 else []
        moves += ["rob F%d" % f for f in range(3) if f != p and self.fields[f] == f]
        moves += ["guard F%d" % f for f in range(3) if f != p and self.fields[f] != 2]
        moves += ["forgive P%d" % q for q in range(self.n) if q != p and self.debts[p][q] > 0]
        moves += ["repay P%d" % q for q in range(self.n) if q != p and self.debts[q][p] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "plant":
            self.fields[p] = p; self.res[p] -= 1
        elif w[0] == "harvest":
            self.res[p] += 2 * (self.fields[p] == p)
