        elif w[0] == "forgive":
            q = int(w[1][1:]); self.debts[p][q] = 0
        elif w[0] == "repay":
            q = int(w[1][1:]); pay = min(self.debts[q][p], self.res[p]); self.debts[q][p] -= pay; self.res[p] -= pay
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Crops %s. Fields %s. Debts: %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, ["F%d" % f for f in range(3)], self.debts[p])

