        self.money = [0] * n_players
        self.bys = bystanders
        self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["build house"]
        if sum(self.houses) < sum([h//2 for h in self.houses]):
            moves.append(f"sell land to P{p}")
        if self.money[p] > 0:
            for b in range(2):
                moves.append(f"buy land from B{b}")
        return moves

    def play(self, p, move):
        if move.startswith("build house"):
            if self.land[p] > 0:
                self.land[p] -= 1
                self.houses[p] += 1
        elif move.startswith("sell land to P"):
            q = int(move[-1])
            if self.land[p] > 0 and self.money[q] > 0:
                self.land[p] -= 1
                self.money[p] += 1
                self.money[q] -= 1
        elif move.startswith("buy land from B"):
            b = int(move[-1])
            if self.bys[b] > 0 and self.money[p] > 0:
                self.bys[b] -= 1
                self.land[p] += 1
                self.money[p] -= 1

        self.penalties()
        self.fines()
        self.turn += 1

    def penalties(self):
        avg_housing = sum(self.houses) / self.n
        for p in range(self.n):
            if self.houses[p] < avg_housing / 2:
                self.houses[p] = 0

    def fines(self):
        avg_land = sum(self.land) / self.n
        for p in range(self.n):
            if self.land[p] < avg_land / 2:
                self.money[p] = max(0, self.money[p] - 1)

    def describe(self, p):
        avg_housing = sum(self.houses) / self.n
        avg_land = sum(self.land) / self.n
        penalty_str = f"Penalized: {', '.join([f'P{i}' for i in range(self.n) if self.houses[i] < avg_housing / 2])}" if sum(self.houses) > 0 else ""
        fine_str = f"Fined: {', '.join([f'P{i}' for i in range(self.n) if self.land[i] < avg_land / 2])}" if sum(self.land) > 0 else ""
        return f"Round {self.turn // self.n + 1} of 6. You are P{p}. Land {self.land}, Houses {self.houses}, Money ${self.money}. Avg Housing: {avg_housing:.2f}, Avg Land: {avg_land:.2f}. {penalty_str} {fine_str}"

    def over(self):
        return self.turn >= 300

    def final_resources(self):
        return [max(0, self.houses[p] - self.land[p]) for p in range(self.n)]

    def final_bystanders(self):
        return self.bys

