- hunt: gain 2 food.
- fish: gain 2 food.
- trade F: buy 1 tool for 2 food.
- build B: spend 2 tools to increase production of your next action (max 4 times).
- sell T: sell 1 tool for 1 food.
- bribe B0/B1: pay 3 food to influence the outcome of a bystander's action (50% chance to succeed).

The village has three crops (C0, C1, C2) that produce food once per round. Bystander crops (BC0, BC1) alternate between producing food and tools each round.
Players can sabotage bystander crops (SC0/SC1) to reduce their yield to none for one round. Sabotage costs 2 tools.
Sabotage can be countered by repairing it (R0/R1) for 1 tool. Villagers can steal 1 food from a bystander crop (STF0/STF1) once per round.
Players can influence bystander actions using the bribe action.
Bribe outcomes are determined deterministically based on the previous bribe outcome and the briber's choice."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.crop = [1, 1, 1]; self.bycrop = [1, 1]; self.toolmult = [1] * n_players
        self.turn = 0; self.max_build = 4; self.last_steal = [-1] * n_players
        self.rng = random.Random(seed)
        self.bribe_outcome = {p: None for p in range(n_players)}

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["hunt", "fish"]
        if self.res[p] >= 2:
            moves.append("trade F")
        if sum([c * m for c, m in zip(self.crop, self.toolmult)]) >= 2:
            moves.append("build B")
        if self.res[p] >= 1:
            moves.append("sell T")
        if self.turn - self.last_steal[p] > 0:
            moves.extend(["steal B%d" % b for b in range(2)])
        if self.res[p] >= 3:
            moves.extend(["bribe B%d" % b for b in [0, 1]])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "hunt":
            self.res[p] += 2
        elif w[0] == "fish":
            self.res[p] += 2
        elif w[0] == "trade":
            self.res[p] -= 2; self.res[p] += 1; self.toolmult[p] *= 2
        elif w[0] == "build":
            self.res[p] -= 2; self.toolmult[p] *= 2
        elif w[0] == "sell":
            self.res[p] -= 1; self.toolmult[p] /= 2
        elif w[0] == "steal":
            b = int(w[1][1:])
            if b == 0 and self.bycrop[0] > 0:
                self.bycrop[0] = 0
                self.last_steal[p] = self.turn
            elif b == 1 and self.bycrop[1] > 0:
                self.bycrop[1] = 0
                self.last_steal[p] = self.turn
        elif w[0] == "bribe":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                self.res[p] -= 3
                last_outcome = self.bribe_outcome.get(p, None)
                if last_outcome is None:
                    self.bribe_outcome[p] = self.rng.choice([True, False])
                else:
                    self.bribe_outcome[p] = not last_outcome
                if self.bribe_outcome[p]:
                    self.bys[b] -= 1
        self.crop[self.turn % 3] *= self.toolmult[self.to_move()]
        self.bycrop[0] = self.crop[(self.turn + 1) % 3]
        self.bycrop[1] = self.crop[(self.turn + 2) % 3]
        self.turn += 1

    def describe(self, p):
        return "Turn %d. You are P%d. Food %s. Tools %s. Crop Production %s. Bystander Crop Production %s. Bribe Outcome %s." % (
            self.turn, p, self.res, self.toolmult[p], self.crop, self.bycrop, self.bribe_outcome[p])

    def over(self): return self.turn >= 6 * self.n
    def final_resources(self): 
        return [max(r, 0) for r in self.res]
    def final_bystanders(self): 
        return [max(b, 0) for b in self.bys]

