Theft and Protection. Three players start with resources and two bystanders. Each round, players take turns choosing
one of the following actions:
- Steal 3 resources from P0, P1, P2, B0, or B1. If successful, they gain the resources; otherwise, they receive no gain.
- Defend yourself against a potential theft attempt. This prevents the next potential theft against you.
- Trade resources with another player (e.g., trade 1 resource with P0).
If a player tries to steal and is defended, the theft attempt fails. However, defending costs 2 resources from the player.
At the end of the game, players and bystanders take their current resources. The game ends after 10 rounds.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.rng = random.Random(seed)
        self.defend = [False] * n_players
        self.turn = 0
        self.rounds = 10

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["defend"]
        if self.res[p] >= 2:
            moves.append("trade P%d" % p)
        moves += ["steal %s" % target for target in ("P0", "P1", "P2", "B0", "B1")]
        return moves

    def play(self, p, move):
        if move == "defend":
            self.defend[p] = True
            self.res[p] -= 2
        elif move.startswith("trade"):
            other = int(move.split(" P")[1])
            trade_amount = 1
            if self.res[p] >= trade_amount and self.res[other] >= trade_amount:
                self.res[p] -= trade_amount
                self.res[other] -= trade_amount
                self.res[p] += trade_amount
                self.res[other] += trade_amount
        elif move.startswith("steal"):
            target = move.split(" ")[1]
            if target.startswith("P"):
                q = int(target[1:])
                if not self.defend[q]:
                    steal_amount = min(3, self.res[q])
                    self.res[q] -= steal_amount
                    self.res[p] += steal_amount
            elif target.startswith("B"):
                b = int(target[1:])
                steal_amount = min(3, self.bys[b])
                self.bys[b] -= steal_amount
                self.res[p] += steal_amount

        self.turn += 1
        if self.turn % self.n == 0:
            for q in range(self.n):
                self.defend[q] = False

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d. Resources: %s" % (self.turn // self.n + 1, self.rounds, p, self.res)]
        rows += ["Defending? " + ("Yes" if self.defend[p] else "No")]
        rows += ["Bystander B%d holds %d" % (b, v) for b, v in enumerate(self.bys)]
        return "\n".join(rows)

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(map(max, zip(self.res, [0] * self.n)))

    def final_bystanders(self):
        return list(map(max, zip(self.bys, [0] * 2)))

