import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders); self.seed = seed
        self.rng = random.Random(seed)
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["trade P%d" % q for q in range(self.n) if q != p and abs(self.res[p] - self.res[q]) <= 1]
        moves += ["steal P%d" % q for q in range(self.n) if q != p and self.res[q] > 1]
        moves += ["donate P%d" % q for q in range(self.n) if q != p and self.res[p] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            q = int(w[1][1:])
            self.res[p], self.res[q] = self.res[q], self.res[p]
        elif w[0] == "steal":
            q = int(w[1][1:])
            stolen = min(2, self.res[q])
            self.res[p] += stolen; self.res[q] -= stolen
        elif w[0] == "donate":
            q = int(w[1][1:])
            donated = 1
            self.res[p] -= donated; self.res[q] += donated
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn + 1}. You are P{p}. Tokens {self.res}. Bystander Chests {self.bys}."

    def over(self): return self.turn >= 20 or not any(moves for moves in [self.legal_moves(i) for i in range(self.n)])

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

