import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.shared = [0] * n_players
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def rich(self, q): return self.res[q] > 10

    def legal_moves(self, p):
        moves = ["plant"] if self.res[p] >= 1 else []
        if self.bys[0] > 0:
            moves += ["steal B0"]
        if self.res[p] >= 1:
            moves += ["bribe P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "plant":
            self.res[p] -= 1; self.res[p] += 2
        elif w[0] == "steal":
            got = min(4, self.bys[0]); self.bys[0] -= got; self.res[p] += got
        elif w[0] == "bribe":
            q = int(w[1][1:])
            if self.rng.randint(0, 1) == 0:
                self.shared[q] += 1
                if self.shared[q] == 3:
                    self.res[q] += self.res[self.to_move()]
                    self.shared[q] = 0
        self.apply_drought_penalty(p)
        self.turn += 1

    def apply_drought_penalty(self, p):
        if self.res[p] > 2:
            penalty = self.res[p] // 2
            self.res[p] -= penalty

    def describe(self, p):
        return "Round %d of %d. You are P%d. Seeds %s. Field %s. Rich (more than 10 seeds): %s. Shares given: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.rich(q)] or "none",
            self.shared)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

