import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = [6] * self.n
        self.barred = [False] * self.n
        self.round = 0; self.max_round = 30;
        self.bystanders = bystanders

