    def legal_moves(self, p):
        if not self.over():
            if self.resources[p] > 0 and any(res > 0 for res in self.resources):
                return ["Give R", "Take R", "Trade R"]
            if self.barred[p]:
                return []
            ban_moves = [f"Ban P{i}" for i in range(self.n) if i != p and not self.barred[i]]
            drive_moves = [f"Drive P{i}" for i in range(self.n) if i != p and not self.barred[i]]
            return ban_moves + drive_moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Give R":
            others = [i for i in range(self.n) if i != p and self.resources[i] > 0]
            if others:
                recipient = self.rng.choice(others)
                self.resources[p] -= 1
                self.resources[recipient] += 1
