                recipient = self.rng.choice(others)
                if self.resources[recipient] > 0:
                    self.resources[p] += 1
                    self.resources[recipient] -= 1
                    print(f"P{p} takes 1 resource from P{recipient}")
        elif w[0] == "Trade R":
            others = [i for i in range(self.n) if i != p and self.resources[i] > 0]
            if others:
                recipient = self.rng.choice(others)
                if self.resources[p] > 0 and self.resources[recipient] > 0:
                    self.resources[p] -= 1
                    self.resources[recipient] -= 1
                    self.resources[p] += 1
                    self.resources[recipient] += 1
                    print(f"P{p} trades 1 resource with P{recipient}")
        elif w[0] == "Ban":
            p_banned = int(w[1][1:])
            if self.barred[p_banned]:
                return
            self.barred[p_banned] = True
            print(f"P{p} bans P{p_banned}")
        elif w[0] == "Drive":
            p_driven = int(w[1][1:])
            if self.barred[p_driven]:
                return
            if self.resources[p_driven] > 0:
                self.resources[p_driven] -= 1
                print(f"P{p} drives P{p_driven} by 1 resource")
        self.round += 1

    def describe(self, p):
        return f"Round {self.round}. You are P{p}. Resources: {self.resources}. Barred: " + ", ".join([f"P{i}" for i in range(self.n) if self.barred[i]])

    def over(self): 
        return self.round >= self.max_round

    def final_resources(self): 
        return tuple(self.resources)

    def final_bystanders(self): 
