    def to_move(self): return self.days % self.n

    def legal_moves(self, p):
        return ["produce", "sell"]

    def play(self, p, move):
        if move == "produce":
            self.ideas[p] += 1
        elif move == "sell":
            self.days += 1
            self.buy(p)

    def buy(self, p):
        idea_counts = [(i, c) for i, c in enumerate(self.ideas)]
        # Sell the idea with the current price
        for i, c in reversed(sorted(idea_counts, key=lambda x: x[0])):
            if c <= 0:
                continue
            if self.price <= c:
                self.ideas[i] = max(0, c - self.price)
                self.ideas[p] += self.price
                break
            if c < self.price:
                self.ideas[i] = max(0, c - 1)
                self.ideas[p] += 1

        # Calculate new price and adjust starting idea prices
        self.change_price()
        self.adjust_prices()

    def change_price(self):
        self.price += 1

    def adjust_prices(self):
        success = [False, False, False]
        for i in range(self.n):
            if self.ideas[i] >= self.price:
                success[i] = True

        if not success[0]:
            self.ideas[0] = 0
            self.ideas[1] += 1
            self.ideas[2] += 1

        if not success[1]:
            self.ideas[0] += 1
            self.ideas[1] = 0
            self.ideas[2] += 1

        if not success[2]:
            self.ideas[0] += 1
            self.ideas[1] += 1
            self.ideas[2] = 0

        for i, s in enumerate(success):
            if s:
                self.ideas[i] = 2

    def describe(self, p):
        return f"Day {self.days}. Produce: {self.ideas[p]}. Price: {self.price}"

    def over(self): return self.days >= self.n * 6
    def final_resources(self): 
        return list(self.ideas)
    def final_bystanders(self): 
        return [0] * 2  # No bystanders

RULES = """
Cave Escape. 3 players, 8 rounds, one move per round. 3 hidden rooms (R0-R2), a safe room (S), a pit (P), and an escape tunnel (E).
- move R<k>: go to cave room Rk (no resources lost). If you are in the pit, you fall into deep darkness.
- guard Pk: protect player Pk from falling into the pit. They cannot move to R1 if they are there when you guard.
- rescue S: try to open the door to S. If you succeed, you win the game.
- report B<k>: pay 2 resources; prevent Pk from being guarded for the next round.
- trade B<k>: pay 1 resource; give up your access to room k+1 for the next round.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [e // 3 for e in endowments]; self.bys = list(bystanders)
        self.pit_status = [False] * self.n
        self.room_status = [False, True, False, False]  # True means room is safe, False means room is not safe
        self.s_safe = 0  # 0 for not accessible, 1 for accessible
        self.escape_available = False
        self.round = 0; self.rounds = 8

    def to_move(self): return self.round % self.n

    def legal_moves(self, p):
        moves = []
        if not self.pit_status[p]: moves.append("move R0")
        if self.res[p] >= 2:
            moves.append("guard P0"); moves.append("guard P1"); moves.append("guard P2")
        if self.s_safe == 1: moves.append("rescue S")
        if self.res[p] > 1:
            moves.append("report B0"); moves.append("report B1"); moves.append("report B2")
            moves.append("trade B0"); moves.append("trade B1"); moves.append("trade B2")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "move R0":
            pass
        elif w[0] == "guard P0":
            if self.room_status[1]: self.pit_status[p] = True
        elif w[0] == "guard P1":
            if self.room_status[1]: self.pit_status[p] = True
        elif w[0] == "guard P2":
            if self.room_status[1]: self.pit_status[p] = True
        elif w[0] == "rescue S":
            if self.s_safe == 0:
                self.s_safe = 1
                self.escape_available = True
                self.round = 7  # Assume the game is over as soon as the safe room is opened
        elif w[0] == "report B0":
            self.res[p] -= 2
        elif w[0] == "report B1":
            self.res[p] -= 2
        elif w[0] == "report B2":
            self.res[p] -= 2
        elif w[0] == "trade B0":
            self.res[p] -= 1
        elif w[0] == "trade B1":
            self.res[p] -= 1
        elif w[0] == "trade B2":
            self.res[p] -= 1
        self.round += 1

    def describe(self, p):
        # Return a description of the player's viewpoint
        return f"Round {self.round} of {self.rounds}. You are Player {p}.\nThe room statuses are: [Room 0: {'Safe' if not self.room_status[0] else 'Not Safe'}, Room 1: {'Safe' if not self.room_status[1] else 'Not Safe'}, Room 2: {'Safe' if not self.room_status[2] else 'Not Safe'}]"

    def over(self):
        return self.escape_available or self.round > 7

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

