A lumberjack can't sabotage themselves.
A lumberjack can't sabotage someone they've already cut.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.barred = [-1] * n_players; self.sabotage = [[False] * 2 for _ in range(n_players)]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["cut"]
        if isinstance(self.sabotage[p], bool) and not self.sabotage[p]:
            moves.append("sabotage P%d" % self.barred[p])
        moves += ["sabotage B%d" % i for i in range(2, 4) if not self.sabotage[p][i % 2]]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "cut":
            got = min(4, self.res[p]); self.res[p] -= got
        elif w[0] == "sabotage":
            who = int(w[1][1:])
            if who == p:
                return None
            if isinstance(self.sabotage[p], bool) or (w[0][-1] == 'P'):
                cost = 2; who_type = "P"
                if w[0][-1] == 'B':
                    cost = 1; who_type = "B"
                    who -= 2
                if not self.sabotage[p][who]:
                    self.sabotage[p] = list(self.sabotage[p]); self.sabotage[p][who] = True
                    self.res[p] -= cost
                    for i in range(self.n):
                        if who_type == "P":
                            if who != i and not self.sabotage[i][p]:
                                self.res[i] -= min(5, self.res[i])
                        else:
                            if self.sabotage[i][who]:
                                self.res[i] -= min(5, self.res[i])
        self.turn += 1
    def describe(self, p):
        moves = ["cut, "]
        if isinstance(self.sabotage[p], bool) and not self.sabotage[p]:
            moves.append("sabotage P%d" % self.barred[p])
        moves += ["sabotage B%d" % i for i in range(2, 4) if not self.sabotage[p][i % 2]]
        return "Round %d of 6. You are the Lumberjack %d. Wood %s" % (self.turn // self.n + 1, p, self.res) + ''.join(moves)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
