            if self.res[p] > 0: moves.append("Harvest")
        elif p > 0 and self.res[p] > 0 and (not self.res[0] or not self.res[1]):
            moves.append("Rob")
        if self.bys[0] > 0:
            moves.append("Neutral Action")
