class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.sessions = 9; self.treasury = 6
        self.sessions_meditated = [0] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0 and self.sessions_meditated[p] == 0:
            return ["wait"] + ["teach P%d" % q for q in range(self.n) if q != p]
        moves = ["meditate"] + (["sponsor"] if self.treasury >= 2 else [])
        moves += ["steal P%d" % q for q in range(self.n) if self.res[q] > 0 and q != p and q != p]
        moves += ["donate P%d" % q for q in range(self.n) if q != p and p not in (0,)]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "meditate":
            self.res[p] += 1; self.treasury -= 1; self.sessions_meditated[p] += 1
            for q in range(self.n):
                if (p != q and q != 0) or (p == q and p != 0 and self.sessions_meditated[q] == 0):
                    self.res[q] += 1
        elif w[0] == "sponsor":
            self.res[p] -= 2; self.treasury += 1
        elif w[0] == "steal":
            other_player = int(w[1][1:])
            if self.res[other_player] > 0:
                got = min(5, self.res[other_player]); self.res[other_player] -= got; self.res[p] += got
                if self.sessions_meditated[other_player] == 0:
                    self.sessions_meditated[other_player] = self.res[other_player]
                else:
                    self.sessions_meditated[other_player] -= 2
        elif w[0] == "donate":
            other_player = int(w[1][1:])
            self.res[p] -= min(3, self.res[p])
            self.res[other_player] += 1
        self.turn += 1
        if self.over():
            return

    def describe(self, p):
        return "Turn %d of 9. You are P%d. Have %d sessions, %d total, %d treasury, have %d sessions available for P2." % (
            self.turn // self.n + 1, p, self.sessions_meditated[p], self.res[p], self.treasury, self.sessions if p == 2 else -1)

