- Protect B0: Stop bystander B0 from stealing resources from P0.
- Cheat P0: Steal resources from P0 (up to 4).
Every move increases the round counter. The game ends when all resources are exhausted or after 8 rounds. The final scores are determined by the amount of resources each player has left at the end.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10 for _ in range(self.n)]; self.bys = bystanders
        self.rng = random.Random(seed); self.turn = 0; self.protected = False

