        moves = []
        if self.turn < 8:
            moves.extend(["Trade P0", "Trade P1", "Trade B1", "Protect B0", "Cheat P0"])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Trade P0":
            if p != 0:
                res_to_p0 = min(5, self.res[p])
                self.res[p] -= res_to_p0
                self.res[0] += res_to_p0
        elif w[0] == "Trade P1":
            if p != 1:
                res_to_p1 = min(3, self.res[p])
                self.res[p] -= res_to_p1
                self.res[1] += res_to_p1
        elif w[0] == "Trade B1":
            got = min(5, self.bys[1] - self.res[p])
            self.res[p] += got
            self.bys[1] -= got
        elif w[0] == "Protect B0":
            self.protected = True
        elif w[0] == "Cheat P0":
            res_from_p0 = min(4, self.res[p])
            self.res[p] -= res_from_p0
            self.res[0] += res_from_p0
        self.turn += 1

    def describe(self, p):
        return "Your resources: {}. Protect B0 is {}.".format(self.res[p], self.protected)

