        return (self.res[p] > 0 or 0 <= self.res[self.to_move()] < 1)

    def available_transfer(self, p):
        return (self.res[p] > 0) + (self.res[self.to_move()] > 0)

    def available_rob(self, p):
        return not (self.res[self.to_move()] <= 0)

    def available_help(self, p):
        return self.res[p] > 0

    def available_block(self, p):
        return self.turn >= 1 and (not (self.res[p] > 0) and self.res[self.players[self.to_move()]] > 0)

