            self.players[p] += steal
            self.bystanders[1] -= steal
        elif move == "form_alliance":
            steal = min(self.bystanders[0], 1) + min(self.bystanders[1], 1)
            self.players[p] += 3 * steal
            self.bystanders = [0, 0]
        self.turn += 1

    def describe(self, p):
        desc = f"Round {self.turn}.\n"
        if self.turn == 15:
            desc += "Final Round! Players must make their last moves.\n"
        if self.players[p] < 0:
            desc += f"Not enough points to continue! You have {self.players[p]} points.\n"
        return desc

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        points = []
        for p in range(self.n):
            points.append(self.players[p])
        return points

    def final_bystanders(self):
        return self.bystanders

RULES = """
Resource Allotment. Four players (P0, P1, B0, B1), 10 rounds, one move each per round. P0 and P1 start with 3 tokens each, while B0 and B1 start with 2 tokens each.

#### Moves:
1. **Collect Tokens (C)**: Spend 0 tokens to collect 1 token from a resource bucket.
2. **Trade Tokens (T)**: Spend 0 tokens to trade any number of tokens to another player (e.g., C0 T P1).
3. **Sanction Tokens (S)**: Spend 1 token to take up to half of the opponent's tokens (e.g., S0 C0 P1).
4. **Block Resources (B)**: Spend 1 token to control another player's resource bucket (e.g., B1 T P0).

#### Consequences:
- Collecting tokens adds tokens to your player score.
- Trading can redistribute tokens or leverage influence over opponents.
- Sanctions reduce the opponent's player score.
- Blocking prevents the opponent from collecting additional tokens.
"""

import random  # optional; math is also allowed. Nothing else may be imported.

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.score = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["C"]
        if self.score[p] > 0:
            moves.append("T")
        if self.score[p] > 0 and self.score[(p + 1) % self.n] > 0:
            moves.append("S")
        if not self.score[(p + 1) % self.n] or self.score[p] > 1:
            moves.append("B")
        return moves

    def play(self, p, move):
        if move == "C":
            self.score[p] += 1
        elif move == "T":
            if self.score[p] > 0:
                opponent = (p + 1) % self.n
                trade_amount = min(self.score[p] // 2, self.score[opponent])
                self.score[p] -= trade_amount
                self.score[opponent] += trade_amount
        elif move == "S":
            if self.score[p] > 0:
                opponent = (p + 1) % self.n
                if self.score[opponent] > 0:
                    steal_amount = min(self.score[p], self.score[opponent] // 2)
                    self.score[p] -= steal_amount
                    self.score[opponent] -= steal_amount
                else:
                    self.score[p] -= 1
        elif move == "B":
            if self.score[p] > 0:
                opponent = (p + 1) % self.n
                if self.score[opponent]:
                    self.score[opponent] -= 1
        self.turn += 1

    def describe(self, p):
        return "Turn %d\nScores: P0=%d, P1=%d, B0=%d, B1=%d" % (
            self.turn, self.score[0], self.score[1], self.bys[0], self.bys[1])

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.score)
    def final_bystanders(self): return list(self.bys)

RULES = """
Forest Conservation. Three loggers, Log1, Log2, and Log3, and a forest manager, Mgr. 
- Log1, Log2, Log3: harvest up to 1 wood from the forest.
- Mgr: issue sanction: reduce log's daily harvest by 1.
- Mgr: issue block: prevent log from harvesting the entire day.
- At night, the forest regenerates by 1-3 trees.
- The game ends when Mgr finishes all actions or max harvesting exceeds N days (N can be set). 
- Log with 0 can't harvest, but can still receive trees.
- Managers goal: maximize forest health over N days. 
- Logs' goal: maximize their individual harvest.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.log_res = list(endowments[:3]); self.bys = list(bystanders)
        self.max_harvest = 3; self.days = 10; self.log_turn = 0; self.day = 0
        self.manager_harvested = 0
        self.manager_blocked_logs = []

    def to_move(self): return self.log_turn % self.n

    def legal_moves(self, p):
        if p == 3:  # Mngr
            if self.log_turn > 2: return []
            if self.log_turn <= 1:
                if self.log_res[0] == self.log_res[1] == self.log_res[2]: return ["sanction P0", "sanction P1"]
                else: return ["sanction P0", "sanction P1", "block P1"] if self.log_res[0] >= self.log_res[1] else ["sanction P1", "sanction P2", "block P2"] if self.log_res[1] >= self.log_res[2] else ["sanction P0", "sanction P2", "block P0"]
            if self.log_turn == 2:
                if self.log_res[0] == self.log_res[1] and self.log_res[0] == self.log_res[2]: return ["block P0", "block P1", "block P2"]
                else:
                    if self.log_res[0] >= self.log_res[1] and self.log_res[0] >= self.log_res[2]:
                        if self.log_res[1] >= self.log_res[2]: return ["block P0", "block P1", "sanction P2"]
                        else: return ["block P0", "sanction P0", "sanction P2"]
                    elif self.log_res[1] >= self.log_res[0] and self.log_res[1] >= self.log_res[2]:
                        if self.log_res[0] >= self.log_res[2]: return ["block P1", "sanction P1", "sanction P2"]
                        else: return ["sanction P1", "block P1", "sanction P2"]
                    elif self.log_res[2] >= self.log_res[0] and self.log_res[2] >= self.log_res[1]:
                        if self.log_res[0] >= self.log_res[1]: return ["block P2", "sanction P2", "sanction P1"]
                        else: return ["sanction P2", "block P2", "sanction P1"]
        else:
            if self.day < self.days:
                return ["harvest", "rest"]
            else:
                return []

    def play(self, p, move):
        w = move.split(" ")
        if p == 0: # Log1
            if w[0] == "harvest": self.log_res[p] = min(self.log_res[p] + 1, self.max_harvest)
        elif p == 1: # Log2
            if w[0] == "harvest": self.log_res[p] = min(self.log_res[p] + 1, self.max_harvest)
        elif p == 2: # Log3
            if w[0] == "harvest": self.log_res[p] = min(self.log_res[p] + 1, self.max_harvest)
        elif p == 3: # Mgr
            if w[0] == "sanction":
                l = int(w[1][1:])
                if l >= 0 and l < self.n:
                    if l in self.manager_blocked_logs: return
                    if self.log_res[l] > 0: self.log_res[l] -= 1
            elif w[0] == "block":
                l = int(w[1][1:])
                if l >= 0 and l < self.n:
                    if l in self.manager_blocked_logs: return
                    self.manager_blocked_logs.append(l)
        self.log_turn += 1
        self.day += 1

    def describe(self, p):
        if p == 0:
            return f"Day {self.day}, Log1 has {self.log_res[0]} wood. Resources managed by Mgr: {self.manager_harvested}. Blocked logs: {self.manager_blocked_logs}"
        elif p == 1:
            return f"Day {self.day}, Log2 has {self.log_res[1]} wood. Resources managed by Mgr: {self.manager_harvested}. Blocked logs: {self.manager_blocked_logs}"
        elif p == 2:
            return f"Day {self.day}, Log3 has {self.log_res[2]} wood. Resources managed by Mgr: {self.manager_harvested}. Blocked logs: {self.manager_blocked_logs}"
        elif p == 3:
            return f"Day {self.day}. Logs managed {self.manager_harvested} wood. Blocked logs now: {self.manager_blocked_logs}"

    def over(self): return self.manager_harvested >= self.max_harvest or self.day >= self.days

    def final_resources(self): return list(self.log_res)
    def final_bystanders(self): return list(self.bys)

RULES = """
The Hide-and-Seek Challenge
3 players and 2 bystanders
- Hide: Increase points by 2. Detection probability 75%
- Find: Detect opponent, find bystander, gain bystander's points (+3), detecter loses all points
- Expose: Detected by more than half the players, lose all points
- Take Points: Attempt to steal points from bystander. Gain equal points, take from bystander
- Block: Attempt to block opponent's detection. Gain points, prevent detection, opponent loses points
Objective: Be the player with the most points after 10 turns.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [5] * n_players
        self.detection_prob = 0
        self.bystanders = list(bystanders)
        self.reserve = (sum(endowments) + sum(bystanders)) // 3
        self.turn = 0

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] >= 2:
            moves.append("Hide")
        if len(moves) == 0:
            moves.append("Take Points")
            moves.append("Block")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Hide":
            self.resources[p] += 2
            self.detection_prob += random.random() * 0.25
        elif w[0] == "Take Points":
            if self.resources[p] >= 2:
                bystander = random.choice(self.bystanders)
                points_stolen = min(bystander, self.resources[p] - 2)
                self.resources[p] += points_stolen
                self.bystanders.remove(bystander)
        elif w[0] == "Block":
            if self.resources[p] >= 3:
                self.resources[p] -= 3
                detected = False
                for q in range(self.n):
                    if q != p:
                        detected = random.random() < self.detection_prob
                        if detected:
                            self.detection_prob = 0
                            self.resources[q] += 3
                            for r in range(self.n):
                                if r != p and r != q:
                                    self.resources[r] -= 3
                            break
        self.detection_prob = min(1, self.detection_prob)
        self.turn += 1

    def describe(self, p):
        desc = f"Turn {self.turn}: Player {p} has {'hidden' if self.detection_prob > 0 else 'safe'} and has {self.resources[p]} points."
        if self.detection_prob > 0:
            desc += f" Detection probability: {self.detection_prob:.2f}"
        if len(self.bystanders) > 0:
            desc += f", Bystanders: {', '.join(str(b) for b in self.bystanders)}"
        return desc

    def over(self):
        return self.turn >= 10

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

