COST = None

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.gold = list(endowments)
        self.mountain = list(bystanders)
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["explore"]
        if self.gold[p] > 0:
            moves.append("pillage B0")
            if self.mountain[1] > 0:
                moves.append("pillage B1")
        # Add blocking move only if the mountain hasn't fallen apart yet and the current player hasn't blocked already
        if self.mountain[0] > 0 and self.mountain[1] > 0 and self.turn <= 2 * self.n:
            moves.append("block P{}".format((self.to_move() + 1) % self.n))
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "explore":
            self.gold[p] += 1
