            elif w[1] == "B1":
                take = min(2, self.mountain[1])
                self.mountain[1] -= take
                self.gold[p] += take
        elif w[0] == "block":
            if self.turn % 2 == (self.to_move() + 1) % 2:  # Block opponent from exploring the opposite round
                self.gold[(self.to_move() + 1) % self.n] = 0
        self.turn += 1

    def describe(self, p):
        return ("Turn {}: " + 
                "Player {} has {} gold. " +
                "Bystander 0 has {} gold, Bystander 1 has {} gold.").format(
                    self.turn, p, self.gold[p],
                    self.mountain[0], self.mountain[1])

