        self.turn += 1
        w = move.split(" ")
        if w[0] == "Share with P1":
            if self.bys[0] < self.res[0]:
                self.bys[0] += 1
            self.res[1] += self.res[p]  # P1 gets the resources
            self.res[p] = 0
        elif w[0] == "Share with P2":
            if self.bys[0] < self.res[1]:
                self.bys[0] += 1
            self.res[2] += self.res[p]  # P2 gets the resources
            self.res[p] = 0
        elif w[0] == "Take from P1":
