        if self.resources[p][0] > 4:
            moves = ["Protect", "Block", "Sanction P0", "Sanction P1", "Share P0", "Share P1"]
        elif self.resources[p][0] > 0:
            moves = ["Work", "Gain", "Protect", "Trade P0", "Trade P1", "Trade B0", "Trade B1", "Steal P0", "Steal P1", "Steal B0", "Steal B1"]
        return moves

    def play(self, p, move):
        if move == "Work":
            if self.resources[p][0] < self.max_resource:
                self.resources[p][0] += 1
        elif move == "Gain":
            if self.resources[p][0] < self.max_resource:
                self.resources[p][0] += 1
        elif move == "Protect":
            if self.resources[p][0] > 0:
                self.resources[p][0] -= 1
        elif move.startswith("Trade"):
            parts = move.split()
            if parts[1].startswith("P"):
