                    self.resources[q][0] -= 1
        elif move.startswith("Share"):
            parts = move.split()
            if parts[1].startswith("P"):
                q = int(parts[1][1:])
                if self.resources[p][0] > 0:
                    self.resources[p][0] -= 1
                    if self.resources[q][0] < self.max_resource:
                        self.resources[q][0] += 1
        elif move == "Block":
            if self.resources[p][0] > 0:
                self.resources[p][0] -= 1
        self.turn += 1

