import random

RULES = """Mutual Assistance Alliance. 3 players, 20 rounds, two moves per round.
- collect: take 1 from the reserve. Spend 1.
- offer 2: give 2 to an ally. Get 1 back for each successful offer.
- defend j: protect a player (j) from being taken away. Defended players cannot reach zero.
- sanction Pm: prevent player Pm from making an Offer or Defense.
- block Pn: prevent player Pn from collecting, offering, or defending.
The game ends at the end of 20 rounds. The winner is the last player with resources remaining."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.reserve = sum(endowments) + sum(bystanders)
        self.resources = [0, 0, 0]; self.bystander_resources = bystanders
        self.aids = [False] * self.n; self.aids_counted = [False] * self.n
        self.sanctions = [-1] * self.n; self.blocks = [-1] * self.n
        self.round = 0

    def to_move(self): return self.round % 2

    def legal_moves(self, p):
        moves = []
        if self.to_move() == p:
            if self.resources[p] >= 1:
                moves += ["collect"]
            if self.resources[p] >= 2 and not self.aids_counted[p]:
                moves += ["offer 2"]
        if p != self.sanctions[p] and p != self.blocks[p]:
            moves += ["sanction P%d" % q for q in range(self.n) if q != p]
        if p != self.sanctions[p] and p != self.blocks[p]:
            moves += ["block P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        split_move = move.split()
        if split_move[0] == "collect":
            if self.resources[p] >= 1:
                self.resources[p] -= 1; self.reserve -= 1; self.resources[p] -= 1
        elif split_move[0] == "offer 2":
            if self.resources[p] >= 2:
                self.resources[p] -= 2; self.bystander_resources[1] += 1
                self.aids[p] = False
                self.aids_counted[p] = True
        elif split_move[0] == "defend P%d" % p:
            # This move is just informational and does not affect gameplay
            pass
        elif split_move[0] == "sanction P%d" % p:
            if p != self.sanctions[p] and p != self.blocks[p]:
                self.sanctions[p] = int(split_move[1])
        elif split_move[0] == "block P%d" % p:
            if p != self.sanctions[p] and p != self.blocks[p]:
                self.blocks[p] = int(split_move[1])
        self.round += 1

    def describe(self, p):
        return f"Round {self.round} of 20. You are P{p+1}. Resources: {self.resources[p]}, Reserved: {self.reserve}. "

    def over(self): return self.round >= 20

    def final_resources(self): return self.resources
    def final_bystanders(self): return self.bystander_resources

RULES = """Resource Allocation with Alliances. 3 players, 6 rounds.
Three resource owners A, B, and C. Players A and B form an alliance. Defector C attacks allied players.
- mine: Gain 1 resource.
- trade_with_A: Trade 1 resource to gain 1 resource from A, or 1 resource from B.
- trade_with_C: Trade 2 resources to lose 2 resources, gain 2 resources from C.
- trade_defect: Attacking the defector to steal 1 resource."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [4] * n_players
        self.bystander = bystanders
        self.turn = 0
        self.rounds = 6
        self.trades = [[0] for _ in range(self.n)]  # Record trades done so far

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["mine"]
        if self.resources[p] >= 1:
            moves.extend(["trade_with_A", "trade_with_C"])
        if p in [0, 1]:
            moves.append("trade_defect")
        return moves

    def play(self, p, move):
        if move == "mine":
            self.resources[p] += 1
        elif move == "trade_with_A":
            if self.resources[p] >= 1:
                self.resources[p] -= 1
                if p == 0 or p == 1:
                    self.resources[1 - p] += 1
                elif p == 2:
                    self.resources[p] += 1
                    self.trades[p][0] = 1  # Record the trade
        elif move == "trade_with_C":
            if self.resources[p] >= 2:
                self.resources[p] -= 2
                if not any(self.trades[p]):
                    self.resources[p] += 2
                elif self.trades[p][0]:
                    self.resources[p] += 2
        elif move == "trade_defect":
            if self.resources[p] >= 1 and p == 2 and self.trades[2][0]:
                self.bystander[1] -= 1
                self.bystander[0] += 1  # Transfer resources between bystander stores

        self.turn += 1

    def describe(self, p):
        desc = "Round {} of {}.".format((self.turn // self.n) + 1, self.rounds)
        desc += " You are P{}, Resources {}, Bystander {}".format(
            p, self.resources, self.bystander
        )
        if p in [0, 1] and self.trades[p][0]:
            desc += ", Trade made this round.\n"
        return desc

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.resources)
    def final_bystanders(self): return list(self.bystander)

RULES = """Graffiti Gallery. 3 artists, 12 rounds, one move each per round. Three bystander galleries (B0, B1, B2) hold paintings but do not play.
- paint: earn 1 painting.
- steal B<k>: take up to 3 paintings from gallery k.
- protect P<k>: using protect on an artist costs you nothing; using it on an innocent one costs you 1 painting; either way the theft is noted, and nothing else happens.
An artist is guilty if it has stolen from a gallery this game and has not been protected since.
Only an artist with at least 1 painting can protect."""

EFFECTIVE = False
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 12; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["paint"]
        if self.barred[p] < self.rnd():
            moves += ["steal B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["protect P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "paint":
            self.res[p] += 1
        elif w[0] == "steal":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got
        elif w[0] == "protect":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(len(self.bys)):
                    back = min(self.owed[q][b], self.res[q]); self.res[q] -= back; self.bys[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)

        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Paintings %s. Galleries %s. Guilty (stole from a gallery, not yet protected): %s. Barred from steal: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Three Players vs. Two Bystanders. 3 players, 6 rounds. One move each per round. 
- Mining ore: Earn up to 4 resources.
- Selling copper: Sell 3 resources from your inventory at a fixed price of 2.
- Borrowing: Take up to 5 resources from the first bystander. Pay 2 resources later.
- Lending: Give up to 4 resources to the second bystander. Receive 1 resource for each loan.
- Trading (with bystander): Exchange resources with either bystander (no transaction cost).
- Sanction (against bystander): Remove 1 resource from the bystander if they haven't made a successful trade yet.
- Guard: Prevent any borrowing by the bystander if they haven't made a successful trade yet.

In deterministic state, players can only loan and trade once per round.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [0] * self.n
        self.bys = list(bystanders)
        self.turn = 0
        self.bypass_turn = 0
        self.deterministic = False

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["guard", "sanction"]
        moves = []
        if self.res[p] <= 4:
            moves.append("mining ore")
        if self.res[p] >= 3:
            moves.append("selling copper")
        if self.bys[0] < 5 and p != 0:
            moves.append("borrowing")
        if self.bys[1] < 4 and p != 1:
            moves.append("lending")
        if len(self.bys) > 1 and p != 2:
            moves.append("trading (with bystander)")
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "mining ore":
            self.res[p] += random.randint(0, 4)
        elif w[0] == "selling copper":
            if self.res[p] >= 3:
                self.res[p] -= 3
                self.res[p] += 2
        elif w[0] == "borrowing":
            if self.bys[0] > 0:
                self.res[p] += min(5, self.bys[0])
                self.bys[0] = max(self.bys[0] - min(5, self.bys[0]), 0)
                self.deterministic = True
        elif w[0] == "lending":
            if self.bys[1] > 0:
                self.res[p] -= min(4, self.bys[1])
                self.bys[1] = max(self.bys[1] - min(4, self.bys[1]), 0)
                for i in range(self.n):
                    if i != p and i != 1:
                        self.res[i] += 1
        elif w[0] == "trading (with bystander)":
            if len(self.bys) > 1:
                if p == 2:
                    b = random.randint(0, 1)
                else:
                    b = 1 - p
                other_player_resources = self.res[2] if b == 0 else self.bys[1 - b]
                if b == 0:
                    self.bys[0] -= other_player_resources
                else:
                    self.bys[1] -= other_player_resources
                self.res[self.to_move()] += other_player_resources
        elif w[0] == "guaranty":
            if self.deterministic:
                self.deterministic = False
        elif w[0] == "sanction":
            if self.bys[0] > 0 and self.bypass_turn == 0:
                self.bys[0] -= 1
                self.bypass_turn += 1

        self.turn += 1

    def describe(self, p):
        desc = f"Round {self.turn // self.n + 1}. You are P{p}. Resources: {self.res[p]}. "
        desc += f"Bystander (0): {self.bys[0]}. Bystander (1): {self.bys[1]}."
        if self.deterministic and p != 0:
            desc += " Deterministic mode: you may only make a loan or a trade once per round."
        return desc

    def over(self): return self.turn >= self.n * 6
    def final_resources(self):
        return list(self.res)
    def final_bystanders(self):
        return self.bys

