RULES = """
Harpists' Harmony. 3 harpists, 18 rounds, one move each per turn. Each harpist starts with a list of unique notes.
- exchange: swap all notes with another harpist.
- perform: gain audience bonus points.
- watch: see the notes of another harpist for free.
- warn: notify another harpist about the danger (negative consequences) of not performing or being watched.
- sanction: stop another harpist from performing or watching if they perceive it as beneficial for themselves.

Audience evaluates combined harmonies. Poor performances lead to penalties to audience.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.notes = [[n] for n in endowments]
        self.audience = bystanders; self.rounds = 18; self.overturn = 0
        self.rng = random.Random(seed)
        self.warned = set()
        self.performance_status = [True] * self.n

    def to_move(self):
        return self.overturn % self.n

    def legal_moves(self, p):
        moves = ["exchange", "perform", "watch", "warn", "sanction"]
        return moves

    def play(self, p, move):
        if move == "exchange":
            q = self.rng.choice([i for i in range(self.n) if i != p])
            self.notes[p], self.notes[q] = self.notes[q], self.notes[p]
            self.performance_status[p], self.performance_status[q] = self.performance_status[q], self.performance_status[p]
        elif move == "perform":
            self.overturn += 1
            self.performance_status[p] = True
        elif move == "watch":
            self.overturn += 1
        elif move == "warn":
            otherp = (p + 1) % self.n
            if otherp not in self.warned:
                self.warned.add(otherp)
        elif move == "sanction":
            otherp = (p + 1) % self.n
            if self.overturn < 3 or not self.performance_status[otherp]:
                self.overturn += 1
            self.performance_status[otherp] = False
        self.performance_status[p] = True
        self.overturn += 1

    def evaluate(self):
        audience_points = self.audience
        for i in range(len(self.notes)):
            for j in range(i+1, len(self.notes)):
                harmony_score = len(set(self.notes[i] + self.notes[j]))
                penalty = (harmony_score - 1)**2
                audience_points -= 2 * penalty
        return audience_points

    def describe(self, p):
        return "Round {}. You are H{} with notes {}. Audience {} points.".format(
            self.overturn, p+1, self.notes[p], self.audience)

    def over(self): 
        return self.overturn >= self.rounds

    def final_resources(self): 
        return [len(notes) for notes in self.notes]

    def final_bystanders(self): 
        return self.audience

RULES = """
Rogue Kingdom. 3 kingdoms, 4 rounds, one move each per round. Each kingdom has gold (resources). Two bystander
castles (C0, C1) hold gold but do not play.
- forge: earn 1 gold.
- pillage C<k>: take up to 3 gold from castle k.
- imprison P<k>: send king k to prison, where he loses all his gold for the next 2 rounds and cannot pillage for the next 2 rounds. Also, imprisoning a free king costs 1 gold. If a king is already imprisoned, imprisoning him again costs 10 gold.
A king is free if he has not been imprisoned since.
Only a king with at least 1 gold can imprison.
"""

EFFECTIVE = False
COST = 'free'
FINE = 0
BOUNTY = 0


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 4; self.imprisoned = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def imprisoned(self, p): return self.imprisoned[p] >= self.rnd()

    def legal_moves(self, p):
        moves = ["forge"]
        if self.turn < self.rounds - 1: # Only kings can pillage if not in prison
            moves += ["pillage C%d" % c for c in range(len(self.bys)) if self.bys[c] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["imprison P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "forge":
            self.res[p] += 1
        elif w[0] == "pillage":
            c = int(w[1][1:]); got = min(3, self.bys[c]); self.bys[c] -= got; self.res[p] += got
        elif w[0] == "imprison":
            q = int(w[1][1:])
            if not self.imprisoned[q]:
                cost = 1
            else:
                cost = 10
            if self.imprisoned[p] < self.rnd(): # Only free kings can be imprisoned
                if self.res[q] >= cost:
                    self.res[q] -= cost; self.imprisoned[q] = self.rnd() + 2
            self.imprisoned[p] = self.rnd()
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are K%d. Gold %s. Castles %s. Imprisoned (sent to prison for the next 2 rounds): %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["K%d" % q for q in range(self.n) if self.imprisoned[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Trading. 3 players, 8 turns with actions every turn, no random events.
- Exchange: Transfer one resource to another player.
- Sanction: Deduct one resource from any two different players together.
- Block: Prevent two different players from interacting with each other.
Winning: Accumulate the most resources at the end of 8 turns.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5] * self.n
        self.bys = list(bystanders); self.turn = 0
        self.players_blocked = set()  # Set to record blocked players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.players_blocked & {p}:
            if self.res[p] > 0:
                moves.append("Exchange Resources")
            others = [q for q in range(self.n) if q != p and q not in self.players_blocked]
            if len(others) >= 2:
                moves += ["Sanction Players"]
            moves += ["Block Players"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Exchange Resources":
            other = (p + 1) % self.n
            if self.res[p] > 0 and self.res[other] < 9:
                self.res[p] -= 1; self.res[other] += 1
        elif w[0] == "Sanction Players":
            others = [q for q in range(self.n) if q not in self.players_blocked]
            if len(others) >= 2:
                self.res[others[0]] -= 1
                self.res[others[1]] -= 1
        elif w[0] == "Block Players":
            others = [q for q in range(self.n) if q != p and q not in self.players_blocked]
            if len(others) >= 2:
                self.players_blocked.update([others[0], others[1]])

    def describe(self, p):
        return f"Turn {self.turn}: Player P{p} has {self.res[p]} resources.\nBlocked: {self.players_blocked}"

    def over(self): return self.turn >= 8
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Management. 3 players, 20 rounds. Each player starts with 5 resources.
- Collect: Increase resource count by 1.
- Trade: Choose two players to receive resources, and give yourself 1/2 or 1/3 of your resources. Options to give 1/2, otherwise 1/3.
- Distribute: Give your resources to another player or the bystander, with option to distribute more than equally.
- End Turn: Advance to the next round.
- The game ends after 20 rounds. Scores are based on resources held at the end (1 point per resource).

"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
