        self.players = list(endowments)
        self.bystander = list(bystanders)
        self.rounds = 20
        self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.players[p] > 0:
            moves.append("Collect")
        if self.players[p] > 0:
            for i in range(self.n):
                if i != p:
                    moves.append(f"Trade P{i} -> me")
            moves.append("Distribute -> me")
        moves.append(f"Distribute -> B")
        return moves

    def play(self, p, move):
        if move == "Collect":
            self.players[p] += 1
        elif move.startswith("Trade P"):
            idx = int(move.split(" ")[1][1:])
            if 0 <= idx < self.n and idx != p:
                if self.players[p] >= 1:
                    if self.players[p] % 2 == 0:
                        self.players[p] -= 1
                        self.players[idx] += 1
                    else:
                        trade = self.players[p] // 3
                        self.players[p] -= trade
                        self.players[idx] += trade
        elif move == "Distribute -> me":
            if self.players[p] > 0:
                div = self.players[p] // 2
                self.players[p] %= 2
                self.bystander[0] += div
        elif move == "Distribute -> B":
            if self.players[p] > 0:
                div = self.players[p] // 3
                self.players[p] %= 3
                self.bystander[0] += div
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn}. "

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return [p for p in self.players]

    def final_bystanders(self):
        return self.bystander

RULES = """Treasure Hunt and Resource Exchange Game.

In this game, three players search for treasure among four hidden locations. They can share their treasure with other players or keep it for themselves. The location where the most treasure is held wins. However, there's a catch: other players might intentionally harm your treasure to secure their own victory. Actions:
1. Hide Treasure (Ht): Hides treasures at any of your four locations. Can be done up to three times.
2. Find and Share Treasure (Fts): Finds nearby treasure and shares it. This action only works in the locations adjacent to yours.
3. Search for Others (SfO): Searches for other players' locations to discover hidden treasure. This action may reveal other people's treasures.
4. Neutral Resource Swap (NSw): Swap 2 treasures with the neutral resource at B0.
5. Guard Against Attack (GAt): Protects your treasure from attacks by shielding nearby enemies.

Each location has a different amount of gold, which can be found during the `find_and_share_treasure` action.
The game lasts for 10 turns, and the winner is the player with the most treasure across all locations combined.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5] * self.n
        self.bys = list(bystanders); self.bys_idx = [0]; self.turn = 0
        self.locations = [(0, 9), (4, 4), (3, 0), (1, 1)]  # Locations (x, y)
        self.treasures = [random.randint(1, 8) for _ in range(4)]
        self.barred = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def hidden_at(self, q, p):
        for x, y in self.locations:
            if q[0] == x and q[1] == y:
                return True
        return False

    def legal_moves(self, p):
        moves = ["Hide Treasure (Ht)", "Find and Share Treasure (Fts)", "Search for Others (SfO)", "Neutral Resource Swap (NSw)", "Guard Against Attack (GAt)"]
        if self.barred[p] < self.rnd():
            moves += ["Raid All"]
        return moves

    def play(self, p, move):
        w = move.split(" ")

        self.turn += 1

        if w[0] == "Hide Treasure (Ht)":
            if self.rnd() < 3:
                got = random.randint(1, 3)  # Limit hiding to three times
                self.res[p] -= got
                self.treasures[self.turn % 4] += got
        elif w[0] == "Find and Share Treasure (Fts)":
            x, y = self.locations[p]
            valid_neighbours = [
                ((x - 1, y), (x + 1, y)),  # Left, right
                ((x, y - 1), (x, y + 1))   # Up, down
            ]
            for neighbour, opposite_neighbor in valid_neighbours:
                if self.hidden_at(neighbour, self.to_move()) and self.hidden_at(opposite_neighbor, self.to_move()):
                    self.res[p] += self.treasures[self.turn % 4]
                    # Share the treasure equally between players
                    for oq in range(self.n):
                        if oq != p:
                            self.treasures[self.turn % 4] -= 3  # Share 3 treasure units
                            self.res[oq] += 3  # Give 3 treasure units
                            break

        elif w[0] == "Search for Others (SfO)":
            for oq in range(self.n):
                if oq != p:
                    x, y = self.locations[oq]
                    valid_neighbours = [
                        ((x - 1, y), (x + 1, y)),  # Left, right
                        ((x, y - 1), (x, y + 1))   # Up, down
                    ]
                    for neighbour, opposite_neighbor in valid_neighbours:
                        if self.hidden_at(neighbour, self.to_move()) and self.hidden_at(opposite_neighbor, self.to_move()):
                            self.res[p] += self.treasures[oq % 4]
                            # Give 3 treasure units from player oq to P
                            self.res[oq] -= 4
                            break
        elif w[0] == "Neutral Resource Swap (NSw)":
            if 2 in self.res and self.bys[self.bys_idx[0]] > 0:
                self.res[p] -= 2
                self.bys[self.bys_idx[0]] -= 2
                self.treasures[0] += 4  # Increase the neutral by 4 treasure for balance

        elif w[0] == "Guard Against Attack (GAt)":
            pass  # Placeholder for guarding logic

        elif w[0] == "Raid All":
            for oq in range(self.n):
                if oq != p:
                    x, y = self.locations[oq]
                    valid_neighbours = [
                        ((x - 1, y), (x + 1, y)),  # Left, right
                        ((x, y - 1), (x, y + 1))   # Up, down
                    ]
                    for neighbour, opposite_neighbor in valid_neighbours:
                        if self.hidden_at(neighbour, self.to_move()) and self.hidden_at(opposite_neighbor, self.to_move()):
                            self.res[oq] -= 4
                            # Give 4 treasure units from player oq to P, and decrease in the neutral
                            if self.bys[self.bys_idx[0]] >= 2:
                                self.bys[self.bys_idx[0]] -= 2
                                self.res[p] += 4
                                self.treasures[0] -= 4
                            else:
                                self.res[p] += self.bys[self.bys_idx[0]]
                                self.bys[self.bys_idx[0]] = 0

    def describe(self, p):
        return (f"Turn {self.turn}:\nYou are Player {p}, have {self.res[p]} treasures.\n"
                f"Locations:\n1: Treasures 0: {self.treasures[0]}, 1: {self.treasures[1]}, 2: {self.treasures[2]}, 3: {self.treasures[3]}\n"
                f"Barred from raid: {self.barred}")

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Prisoners' Dilemma. Two players: you and the other player. Each player must make a decision
to either 'cooperate' or 'defect' on each round.

If both players cooperate, both get 4 points.
If one player cooperates and the other defects, the defector gets 0 points and the cooperator gets 6 points.
If both players defect, both get 2 points.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.rng = random.Random(seed)
        self.round = 0; self.rounds = 10; self.player_actions = [[None] * self.rounds for _ in range(2)]

    def to_move(self): return self.round % 2

    def legal_moves(self, p):
        return ["cooperate", "defect"]

    def play(self, p, move):
        if move not in self.legal_moves(p): raise ValueError(f"Illegal move {move}")
        self.player_actions[p][self.round] = move
        opponent_action = self.player_actions[1 - p][self.round]
        if move == "cooperate":
            if opponent_action == "cooperate":
                self.res[p] += 4; self.res[1 - p] += 4
            else:
                self.res[p] += 6; self.res[1 - p] -= 3
        else:
            if opponent_action == "cooperate":
                self.res[p] -= 3; self.res[1 - p] += 3
            else:
                self.res[p] += 2; self.res[1 - p] += 2
        self.round += 1

    def describe(self, p):
        return "Round %d. You made '%s'. They made '%s'. Points: %s." % (
            self.round, self.player_actions[p][self.round - 1] if self.round > 0 else "none",
            self.player_actions[1 - p][self.round - 1] if self.round > 0 else "none",
            self.res)

    def over(self): return self.round >= self.rounds

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return [0, 0]  # No bystanders in this game

RULES = """
Marketplace with Multiple Scenarios. Three players, 10 turns.
