        moves = ["gather"]

        # Defensive actions
        if self.res[p] > 0:
            for k in range(self.n):
                defense = "defend"
                if self.shields[k] == self.round + 1:
                    defense = "shield"
                if defense not in moves:
                    moves.append(defense)
                if self.blocks[k] == self.round and k != p:
                    moves.append(f"block P{k}")

        # Attack and steal
        if (not self.stolen[p]) and self.res[p] > 0:
            for h in range(len(self.bys)):
                enemy_stolen = self.stolen[random.randint(0, len(self.bys) - 1)]
                if enemy_stolen:
