        # Guard or block (if not already blocked)
        for k in range(self.n):
            if self.blocks[k] < self.round:
                moves.append(f"guard P{k}")

        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.stolen = [False] * self.n

        if w[0] == "gather":
