            h = int(w[1][1:])
            if self.bys[h] > 0:
                self.bys[h] -= min(2, self.bys[h])
                self.res[p] += min(2, self.bys[h])
                self.stolen[random.randint(0, len(self.bys) - 1)] = True
                if self.bys[h] <= 0:
