RULES = """
Three-player game with resource management, soldier count, and defense mechanisms including defending against another player 
and attacking bystanders. The objective is to accumulate as many resources as possible without giving too much away to the
bystanders.

- **Resource Management:** Players start with 5 resources each, totaling 15. 
- **Soldiers:** Each player starts with 2 soldiers, totaling 6.
- **Bystanders:** There are two bystanders with 7 resources each, totaling 14.
- **Moves:**
  - **Tax:** Earn 1 resource.
  - **Recruit:** Cost 1 resource to get 1 additional soldier. Maximum of 5 soldiers.
  - **Defend B1:** Guard against B1 gaining more resources each turn. Pay 1 resource and 1 soldier.
  - **Attack B0:** Attempt to steal up to 4 resources from B0 without detection by B1.
  - **Challenge P2:** Attack player P2 and steal 3 resources if this player has more soldiers than P2. Loss of one soldier.

The game continues for 10 rounds. Players cannot leave early.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [5] * n_players  # Each player starts with 5 resources
        self.bys = bystanders         # Bystanders start with specified resources
        self.sold = [2] * n_players  # Each player starts with 2 soldiers
        self.escorted = [None] * 2     # No players are initially escorted
        self.defending = False       # Initially, no one is defending
        self.target_bystander = -1    # Target bystander is None initially
        self.seed = seed
        self.rng = random.Random(seed)
        self.turn = 0
        self.rounds = 10

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 1: moves.append("tax")
        if self.res[p] >= 1 and self.sold[p] < 5: moves.append("recruit")
        if not self.defending:
            if self.bys[0] > 0 and self.escorted[0] != p and self.escorted[0] is not None:
                moves.append("attack B0")
        if self.bys[1] > 0 and self.escorted[1] != p and self.escorted[1] is not None:
            moves.append("attack B1")
        targets = [q for q in range(self.n) if q != p]
        if len(targets) > 0:
            moves.append("challenge P%d" % targets[0])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "tax":
            self.res[p] += 1
        elif w[0] == "recruit":
            self.res[p] -= 1
            self.sold[p] += 1
        elif w[0] == "defend B1":
            if self.escorted[1] is not None:
                self.res[p] -= 1
                self.sold[p] -= 1
                self.defending = True
                self.target_bystander = 1
        elif w[0] == "attack B0":
            if self.escorted[0] is not None:
                got = min(4, self.bys[0])
                self.bys[0] -= got
                self.res[p] += got
        elif w[0] == "attack B1":
            if self.escorted[1] is not None:
                got = min(4, self.bys[1])
                self.bys[1] -= got
                self.res[p] += got
        elif w[0] == "challenge P2":
            q = int(w[1][1:])
            if self.sold[p] > self.sold[q]:
                got = 3
                self.bys[q] -= got
                self.res[p] += got
            self.sold[p] -= 1
            self.sold[q] -= 2
        self.turn += 1
        if self.turn % self.n == 0:
            self.defending = False
            self.target_bystander = -1

    def describe(self, p):
        defesc = "defended" if self.defending and self.target_bystander == 1 else "not defended"
        return "Round %d of %d. You are P%d. Resources: %s. Soldiers: %s. Bystanders: B0=%d, B1=%d. Defense status: %s by B1." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.sold, self.bys[0], self.bys[1], defesc)

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """
Resource Allocation with Strategic Deception:

Each player begins with 6 resources.
- **Trade**: Can directly exchange resources, increasing or decreasing both parties' resources.
- **Malign Action**: Manipulates other players' positions, potentially taking resources or changing alliances.
- **Cooperation**: Negotiates agreements to maintain resource balances.
- **Escape**: Can exit the game after 4 moves to avoid harm or take half of available resources if all other players are zero.

Players must balance strategy to maximize their resource gain while avoiding harm to others.
The game lasts for 10 rounds or more, and the final scores are determined by remaining resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [6] * self.n
        self.bys = bystanders
        self.round = 0

    def to_move(self):
        return self.round % self.n

    def legal_moves(self, p):
        moves = ["Trade with P0", "Trade with P1", "Trade with P2", "Malign Action P1", "Malign Action P1 & P2", "Cooperation with P0", "Cooperation with P1", "Cooperation with P2", "Escape"]
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Trade with P0":
            if w[1] == "0":
                self.resources[1] += int(w[2])
                self.resources[p] -= int(w[2])
            else:
                self.resources[0] += int(w[2])
                self.resources[p] -= int(w[2])

        elif w[0] == "Trade with P1":
            if w[1] == "0":
                self.resources[2] += int(w[2])
                self.resources[p] -= int(w[2])
            else:
                self.resources[1] += int(w[2])
                self.resources[p] -= int(w[2])

        elif w[0] == "Trade with P2":
            self.resources[0] += int(w[2])
