class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [4] * self.n; self.bys = list(bystanders)
        self.turn = 0; self.rounds = 100; self.destructed = False

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["collect"]
        if self.rnd() >= 1: moves.append("sanction")
        if self.rnd() >= 2: moves.append("harvest B0")
        if self.rnd() >= 3: moves.append("harvest B1")
        if self.rnd() >= 4 and not self.destructed and self.res[p] > 1:
            moves.append("destruct P1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "collect":
            self.res[p] += 1
        elif w[0] == "sanction":
            if p == 0:
                self.deduct(1)
            elif p == 2:
                self.deduct(1)
        elif w[0] == "harvest B0":
            if self.bys[0] > 0:
                self.bys[0] -= 1; self.res[p] += 1
        elif w[0] == "harvest B1":
            if self.bys[1] > 0:
                self.bys[1] -= 1; self.res[p] += 1
        elif w[0] == "destruct P1":
            if self.res[p] >= 2:
                self.res[p] -= 2
                self.res[1] = 0; self.deduct(1)
                self.destructed = True
        self.turn += 1

    def deduct(self, amount):
        for i in range(self.n):
            self.res[i] = max(0, self.res[i] - amount)

    def describe(self, p):
        return (
            f"Round {self.rnd()+1} of {self.rounds}. Player {p} has "
            f"{', '.join(map(str, self.res))}. Resources: [{self.bys[0]}, {self.bys[1]}]"
        )

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
In the "Resource Protection Strategy," players aim to accrue the most resources by strategically managing their interactions with the two bystanders. Players begin with an initial resource pool, and each turn, they can choose from various actions: trade, guard, block, or a combination thereof. Each action affects the number of resources you can gain, as well as the ability to influence the behavior of other players. The game ends when a predetermined number of rounds is completed, and the final outcome is determined by the collective resources of all players. Balancing trade, guarding, and blocking is crucial to maximizing resource accumulation while minimizing harm to others.

- trade B0: trade with bystander 0
- trade B1: trade with bystander 1
- guard P0: prevent P0 from trading with either bystander (-1 = disable)
- guard P1: prevent P1 from trading with either bystander (-1 = disable)
- block P0 N: force P0 to trade N resources until blocked again
- block P1 N: force P1 to trade N resources until blocked again
- combine (guard P0 N and block P0 N): similar to block
- combine (guard P1 N and block P1 N): similar to block

- Rewards/Consequences:
  - trade gives 1 resource
  - guard/block has no immediate reward
  - combining results in the same behavior as block

- Objective: Accumulate the most resources by strategically choosing which actions to take. Avoid harming other players to maintain long-term cooperation and mutual benefit.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        if n_players != 3:
            raise ValueError("This game requires exactly 3 players.")
        self.n = n_players; self.resources = list(endowments); self.bystanders = list(bystanders)
        self.rounds = 10; self.turn = 0; self.guarding = [-1] * n_players; self.blocking = [-1] * n_players; self.blocked = [-1] * n_players

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.guarding[p] < self.turn and self.guarding[p] != -1:
            moves.append("revoke guard")
        if self.blocking[p] < self.turn and self.blocking[p] != -1:
            moves.append("revoke block P0")
            moves.append("revoke block P1")
        if self.resources[p] > 0 and self.guarding[p] == -1:
            moves.append("trade B0")
            moves.append("trade B1")
        if self.guarding[p] == -1:
            moves.append("guard P0")
            moves.append("guard P1")
        if self.guarding[p] == -1 and self.blocking[p] == -1:
            moves.append("block P0 1")
            moves.append("block P0 2")
            moves.append("block P1 1")
            moves.append("block P1 2")
        return moves

    def play(self, p, move):
        if move == "revoke guard":
            self.guarding[p] = -1
        elif move == "revoke block P0":
            self.blocking[p] = -1
            moves = self.legal_moves(p)
            if "block P0 1" in moves:
                self.blocking[p] = self.turn + 1
            elif "block P0 2" in moves:
                self.blocking[p] = self.turn + 2
        elif move == "revoke block P1":
            self.blocking[p] = -1
            moves = self.legal_moves(p)
            if "block P1 1" in moves:
                self.blocking[p] = self.turn + 1
            elif "block P1 2" in moves:
                self.blocking[p] = self.turn + 2
        elif move.startswith("trade"):
            b = move.split(" ")[1][1:]
            if b.isdigit() and 0 <= int(b) < len(self.bystanders):
                got = min(3, self.bystanders[int(b)])
                if got > 0:
                    self.resources[p] += 1
                    self.bystanders[int(b)] -= got
        elif move.startswith("guard"):
            p2 = int(move.split(" ")[1][1:])
            self.guarding[p] = -2
        elif move.startswith("block"):
            p2 = int(move.split(" ")[1][1:])
            N = int(move.split(" ")[2])
            self.blocking[p] = self.turn + N
        else:
            raise ValueError(f"Invalid move {move}")
        self.turn += 1

    def describe(self, p):
        guards = "none"
        blocks = "none"
        if self.guarding[p] == -2:
            guards = f"P{p}"
        if self.blocking[p] > self.turn and self.blocking[p] != -1:
            blocks = f"P{self.blocking[p]}"
        return (
            f"Round {self.turn//self.n+1} of {self.rounds}. "
            f"You are P{p}. Resources {self.resources}. "
            f"Bystander holdings {self.bystanders}. "
            f"Guarding {guards}. "
            f"Blocking {blocks}. "
        )

    def over(self): 
        return self.turn >= self.n * self.rounds

    def final_resources(self): 
        return list(self.resources)

    def final_bystanders(self): 
        return list(self.bystanders)

