import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5] * n_players; self.buyer_wealth = {1: 0, 2: 0}
        self.turn = 0; self.total_turns = 6; self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = ["sell", "buyer demand"]
        if self.turn < self.total_turns - 1:
            moves += ["block buyer"]
        return moves + ["wait"]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "sell":
            amount = int(min(self.res[p], 2.5) / 2)
            self.res[p] -= 2 * amount
            self.buyer_wealth[1] += amount
            self.buyer_wealth[2] += amount
        elif w[0] == "buyer demand":
            buyer = int(w[1][1:])
            if self.rng.random() <= 0.5 and abs(self.buyer_wealth[buyer] - self.res[p]) > 6:
                self.block_buyer(buyer)
            else:
                self.buy(buyer, self.res[p])
        elif w[0] == "block buyer":
            if self.turn < self.total_turns - 1:
                bidder = (b := random.randint(1, 2)) if self.buyer_wealth[b] == 0 \
                         else self.buyer_wealth.index(self.buyer_wealth[b])
                self.buy(bidder, 0)
        elif w[0] == "wait":
            pass
        self.turn += 1

    def buy(self, buyer, amount):
        spent = min(self.res[buyer], amount)
        self.res[buyer] -= spent
        self.res[p] += spent
        self.buyer_wealth[buyer] -= spent

    def block_buyer(self, buyer):
        self.buyer_wealth[buyer] = 0

    def describe(self, p):
        desc = f"Turn {self.turn}: You have ${self.res[p]}.\n"
        desc += f"B1's wealth is ${self.buyer_wealth[1]}, B2's wealth is ${self.buyer_wealth[2]}.\n"
        return desc

    def over(self): return self.turn >= self.total_turns

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return [0, 0]

RULES = """
Inequality Control. 3 players, 8 rounds. Players take turns making actions affecting the others' access to resource pools.

Goals:
- Maximize your total resources.
- Protect yourself and your friends from being exploited.
- Take advantage of opportunities to weaken others.

Actions:
- collect: add 1 resource to your pool.
- swap with P0: trade 1 resource with P0.
- swap with P1: trade 1 resource with P1.
- swap with B0: trade 1 resource with B0.
- swap with B1: trade 1 resource with B1.
- lend resources: give 1 resource to a specified player.
- sanction P0: temporarily prevent P0 from gaining resources.
- sanction P1: temporarily prevent P1 from gaining resources.
- sanction B0: temporarily prevent B0 from gaining resources.
- sanction B1: temporarily prevent B1 from gaining resources.

The game is considered over after 8 rounds. Players end up winning or tying based on the number of resources they have at the conclusion.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bys = list(bystanders);
        self.pool = len(endowments) + len(bystanders)
        self.round = 0; self.sanctions = {0: False, 1: False, 2: False}

    def to_move(self): return self.round % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] < 1:
            moves.extend(["sanction P0", "sanction P1", "sanction B0", "sanction B1"])
        else:
            moves.append("collect")
        if self.resources[p] > 0:
            moves.append("swap with B0")
        if self.resources[p] > 1:
            moves.append("swap with P0")
        if self.resources[p] > 2:
            moves.append("sanction B1")
        if self.resources[p] > 3:
            moves.append("swim with B1")
            moves.append("lend resources to P0")
            moves.append("lend resources to P1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "collect":
            self.resources[p] += 1
        elif w[0] in ["swap with B0", "swap with P0", "swap with B1", "swap with P1", "sanction B1", "lend resources to P0", "lend resources to P1"]:
            opponent = (p + 1) % self.n
            if opponent in self.sanctions:
                print("Player {} is sanctioned from moving.".format(opponent))
                return
            if not self.sanctions[p]:
                if w[0] == "swap with":
                    if self.pool > 0:
                        self.resources[p], self.resources[opponent] = self.resources[opponent], self.resources[p]; self.pool -= 1
                elif w[0] == "lend resources to":
                    if self.resources[p] > 0:
                        other = int(w[3][1:])
                        self.resources[p] -= 1; self.resources[other] += 1
                elif w[0] == "sanction B0":
                    if not self.sanctions[0]: self.sanctions[0] = True
                elif w[0] == "sanction P1":
                    if not self.sanctions[1]: self.sanctions[1] = True
        self.round += 1

    def describe(self, p):
        return "Round {} of {}. P{} has {} resources. Pool has {} resources. Sanctions: P0: {}, P1: {}".format(
            self.round + 1, 8, p, self.resources[p], self.pool, self.sanctions[0], self.sanctions[1])

    def over(self): return self.round >= 8
    def final_resources(self): return self.resources.copy()
    def final_bystanders(self): return self.bys.copy()

RULES = """
Mountain Climbing Game. 3 climbers. 8 turns, one move per turn.
- climb: gain 2 points but risk falling (1 in 3 chance). Health decreases by 1.
- sanction (only for climbers not already at the summit): prevents another player from climbing. Stamina decreases by 1.
- block (only for non-blockers): prevents an opponent from sanctioning you. Stamina decreases by 1.
- defend (only during the final attempt): shields against falling or sanctions. Stamina decreases by 1.
- guard (for all): prevents the bystander from blocking another player. Health increases.
- rob (for bystander): steals 1 point. Health decreases by 1.
Health starts at 100, stamina at 100.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.points = list(endowments)
        self.health = [100] * self.n
        self.stamina = [100] * self.n
        self.bystander_health = list(bystanders)
        self.blocked = [False] * self.n
        self.summit = 7  # Maximum points needed to win
        self.turn = 0
        self.bluffing = False
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.health[p] > 0:
            moves.append("climb")
            if self.stamina[p] >= 1:
                moves.extend(["sanction", "block", "defend"])
        if self.stamina[p] >= 1:
            moves.append("rest")  # Rest to recover stamina (costs 2 health)
        if self.bluffing and self.stamina[p] >= 2:
            moves.append(" bluff")
        if self.n > 1 and p < self.n - 1:
            moves.append("guard")
        if not self.bluffing and p >= 1:
            moves.append("rob")
        return moves

    def play(self, p, move):
        if move == "bluff":
            self.bluffing = True
            self.bystander_health[p % 2] = max(0, self.bystander_health[p % 2] - 1)
            self.stamina[p] -= 2
            self.turn += 1
            return

        if move == "climb":
            if self.rng.randint(1, 3) == 1:
                self.health[p] -= 1
            else:
                self.points[p] += 2
            self.stamina[p] -= 1
            if self.points[p] >= self.summit:
                self.health[p] -= 1  # Deduct health if summit is reached
            self.turn += 1

        elif move == "sanction":
            q = (p + 1) % self.n
            if not self.blocked[q]:
