        self.turns = 6; self.gold_island1 = True; self.gold_island2 = False
        self.riddles_solved = self.bystard_items_collected = self.mine_visits = [0] * self.n
        self.guarded = [False] * 4; self.gate_bribed = False

    def to_move(self): return self.turns % 3

