        moves = []
        if self.guarded[self.to_move()] == False and self.gate_bribed == False:
            moves.append("guard G%d" % self.to_move())
        elif self.guarded[self.to_move()] == True:
            moves.append("bribe G%d" % self.to_move())
        moves += ["solve R%d" % i for i in range(1, 4)]
        moves += ["grab L%d" % i for i in range(1, 4)]
        moves += ["mine M%d" % i for i in range(1, 4)]
        return moves

