        elif move == "buy C": 
            if self.res[p] >= 8: 
                self.res[p] -= 8; self.wC += 6
        elif move == "sell":
            total = self.wA + self.wB + self.wC
            self.res[p] += total; self.wA, self.wB, self.wC = 0, 0, 0
        elif move == "steal P%d" % p:
            if self.res[(p+1) % self.n] > 0:
                self.res[(p+1) % self.n] -= 1; self.res[p] += 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. Player P%d has %d rice.\n Warehouses: A=%d, B=%d, C=%d." % (
            self.turn // self.n + 1, self.rounds, p, self.res[p], self.wA, self.wB, self.wC)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Robber's Dilemma. 3 robbers, 10 rounds, two moves per round. Each robber starts with 50 stolen goods. There are no bystanders.

- Steal from opponent: Spend 1 resource to steal 1 stolen good from the robber opposite you.
- Guard against theft (1 resources): Spend 1 resource to prevent yourself from being robbed during the opponent's next turn.

Winning Criteria: 
- Most stolen goods. Secondary win on safety margin when tied overall.
- Safety margin calculation includes all actions taken by all players, including guard actions.
- Excluded from safety margin calculation when a guard is activated.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.stolen_goods = list(endowments); self.safety_margin = self.n * 10
        self.turn = 0; self.current_player = 0
        self.round = 0; self.opponent = (self.current_player + 1) % self.n
        self.guarded_this_round = -1

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Steal from opponent", "Guard against theft"]
        if p == self.opponent or self.guarded_this_round == p:
            moves.remove("Steal from opponent")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Steal from opponent":
            if self.stolen_goods[p] > 0:
                self.stolen_goods[p] -= 1; self.stolen_goods[self.opponent] += 1
                self.current_player = (self.current_player + 1) % self.n
                self.opponent = (self.current_player + 1) % self.n
        elif w == "Guard against theft":
            if self.stolen_goods[p] > 0:
                self.stolen_goods[p] -= 1
                self.guarded_this_round = p
        self.turn += 1

    def describe(self, p):
        return "Turn %d of 10. Player %d has %d stolen goods left. Safety margin: %d."  % (self.turn + 1, p, self.stolen_goods[p], self.safety_margin)

    def over(self): 
        return self.turn >= 10

    def final_resources(self): 
        return self.stolen_goods; self.safety_margin = self.n * 10

    def final_bystanders(self): 
        return [0,0]; self.safety_margin = self.n * 10

RULES = """
The Game of Three. 3 players, 10 rounds. Three strategies are available:
1. Trade: Give 2 to the other two players evenly.
2. Block: Prevent the other two players from giving resources to you evenly.
3. Skip: Skip your turn.

**Objective:** Maximize your own resources at the end of 10 rounds, without giving all your resources to the other two players when they trade. Skipped turns do not count towards your resources.

Each player starts with 5 resources. Each player can only give or receive 1 resource per turn. Players who give or receive resources have an opportunity to protect themselves from being traded away, but cannot influence the other player's actions beyond defending.

**Winning Condition:** A player wins if they have the highest number of resources at the end of 10 rounds. If there is a tie, the player with the lowest starting resource count wins."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        assert len(endowments) == n_players, "endowments must have exactly n_players elements"
        assert len(bystanders) == 2, "bystanders must have exactly 2 elements"

        self.resources = list(endowments)
        self.bys = list(bystanders)
        self.rounds = 10
        self.round = 0
        self.player_with_treasure = -1

    def to_move(self): return self.round % self.n

    def legal_moves(self, p):
        moves = []
        if True:  # Always available: skip
            moves += ["Skip"]
        if self.resources[p] > 1:
            moves += ["Trade"]
        if self.resources[p] > 0:
            moves += ["Block"]

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Skip":
            pass
        elif w[0] == "Trade":
            resources_to_trade = min(self.resources[p], 2)
            self.resources[p] -= resources_to_trade
            for opponent in range(self.n):
                if opponent != p:
                    self.resources[opponent] += resources_to_trade // 2
        elif w[0] == "Block":
            if self.resources[p] > 0:
                self.resources[p] -= 1
        else:
            print(f"Invalid move: {move}")
        self.round += 1

    def describe(self, p):
        desc = f"Round {self.round} of {self.rounds}. "
        desc += f"Player {p} has {self.resources[p]} of total resources {sum(self.resources)}. "
        desc += f"Wealth is shared equally among players {self.player_with_treasure} and the bystanders."
        return desc

    def over(self):
        return self.round >= self.rounds

    def final_resources(self):
        return self.resources[:]

    def final_bystanders(self):
        return self.bys

