Dining Dilemma. 3 diners, 7 turns. Initial food: P0=5, P1=5, P2=5, B0=7. Players can eat from the plate, share, defend, or block the second diner.

Goal: Eat the plate while avoiding getting stuck with zero resources. 
- Eat: Eat from the plate.
- Share: Give an extra food unit to a neighbor (either P0 or P2).
- Defend: Prevent the other neighbors from eating.
- Block: Take away food units from B0. The more food B0 has, the harder to block.
"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = [endowments[i] for i in range(n_players)]
        self.bystander = bystanders; self.last_turn = 0

    def to_move(self): 
        return self.last_turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] > 0:
            moves.append("Eat")
        if p == 1 and self.resources[1] > 1:
            moves.append("Share")
        moves.append("Defend")
        if p == 0 or p == 2 and self.bystander[0] > 2:
            moves.append("Block")
        return moves

    def play(self, p, move):
        if move == "Eat":
            self.resources[p] -= 1
        elif move == "Share":
            q = 0 if p == 1 else 2
            self.resources[q] += 1
            self.resources[p] -= 1
        elif move == "Defend":
            self.resources[(p + 1) % self.n] = 0
        elif move == "Block":
            t = min(2, self.bystander[0])
            self.bystander[0] -= t
            self.resources[p] += t
        self.last_turn += 1

    def describe(self, p):
        return f"Turn {self.last_turn}: You are P{p}. Food: [{', '.join(str(r) for r in self.resources)}]. Bystander has {self.bystander[0]}."

    def over(self): 
        return self.last_turn >= 7

    def final_resources(self): 
        return self.resources

    def final_bystanders(self):
        return self.bystander

RULES = """
Fishery. 3 fishers share a lake for 7 rounds, one move each per round.  
- fish 1 / fish 3: take that many fish (resources) from the lake if it has them.
- rest: take nothing. At the end of the round the lake regrows 1-3 fish from the reserve, but only while it holds 4 or more.
- sink P<k> boat: take everything fisher k holds.
- net B<k> pond: take up to 2 from bystander k's private pond (they do not play).
A fisher at 0 has no boat: they can only wait or row for P<k> (the reserve pays P<k> 1). The reserve is limited."""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 7; self.lake = 8
        self.reserve = (sum(endowments) + sum(bystanders)) // 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["wait"] + ["row for P%d" % q for q in others]
        moves = ["rest"] + ["fish %d" % k for k in (1, 3) if self.lake >= k]
        moves += ["sink P%d boat" % q for q in others if self.res[q] > 0]
        return moves + ["net B%d pond" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            k = int(w[1]); self.lake -= k; self.res[p] += k
        elif w[0] in ("row", "wait"):
            if w[0] == "row" and self.reserve > 0:
                self.reserve -= 1; self.res[int(w[2][1:])] += 1
        elif w[0] == "sink":
            q = int(w[1][1:]); self.res[p] += self.res[q]; self.res[q] = 0
        elif w[0] == "net":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got + (1 if got > 0 else 0)
        self.turn += 1
        if self.turn % self.n == 0 and self.lake >= 4:
            grow = min(self.rng.randint(1, 3), self.reserve); self.reserve -= grow; self.lake += grow

    def describe(self, p):
        return "Round %d of %d. You are P%d. Players hold %s. Lake %d fish. Reserve %d. Bystander ponds %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.lake, self.reserve, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Marketplace Conflict. 3 traders, 10 rounds, one move each per round. Each trader starts with 3 resources. There are 2 bystander
shops, B0 and B1; each with initially 2 resources.
- Trade: Earn 1 resource.
- Rob: Pay 1 resource to rob a shop. If successful, gain an equal number of resource tokens to the shop's current balance.
- Guard: Place a guard on the shop of your choice to prevent another player from robbing it.
- Sanction: Ban another player from the game for the remainder of the game. Cost 2 resources per sanction.
- Players cannot rob a shop if they have already guarded it or attempted to rob the shop in the same round.
- Banishing yourself costs all remaining resources.
The objective is to have more resources than all other players combined at the end of the game."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = endowments
        self.bys = bystanders
        self.guards = [-1] * n_players
        self.sanctions = {}
        self.turn = 0
        self.rounds = 10

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["trade"]

        if self.bys[self.guards[p]] > 0:
            moves.append(f"guard B{self.guards[p]}")

        other_payers = [i for i in range(self.n) if i != p and self.res[i] > 0]
        if any([p in self.sanctions for p in other_payers]):
            moves.append(f"sanction P{random.choice(other_payers)}")

        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "trade":
            self.res[p] += 1

        elif w[0] == "guard":
            b = int(w[1][1:])
            if self.guarded(p, b):
                raise ValueError("Cannot guard a shop guarded by someone else.")
            self.guards[p] = b

        elif w[0] == "sanction":
            p2 = int(w[1][1:])
            if p2 < 0 or p2 >= self.n:
                raise ValueError("Invalid player to sanction.")
            if p2 == p:
                raise ValueError("Cannot sanction oneself.")
            if p2 in self.sanctions:
                raise ValueError("Player is already sanctioned.")

            cost = 2
            if self.res[p] >= cost:
                self.res[p] -= cost
                self.sanctions[p2] = self.turn + 10
            else:
                raise ValueError("Insufficient resources to sanction player.")

        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn} of {self.rounds}. You are P{p}. Guards: {self.guards}; Resources: {self.res}; Bystanders: {self.bys}; Sanctions: {self.sanctions}"

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

    def guarded(self, p, b):
        return self.guards[b] == p

RULES = """
Treasure Hunt. Three teams (A, B, C) and two neutral groups (M, N) participate in a treasure hunt.
Teams start each round with 10 gold. They can explore caches,.trade gold, defend attacks, bribe, and report offenses.
The goal is to accumulate gold and minimize damage to rivals, while strategically dealing with neutral groups.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.gold = list(endowments)
        self.bystanders = list(bystanders)
        self.score = [0] * self.n
        self.turn = 0
        self.turn_max = self.n * 3
        self.attacks = {f"A{i}": 0 for i in range(n_players)}
        self.brings = {f"A{i}": 0 for i in range(n_players)}
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.gold[p] > 0:
            moves += ["explore"]
        for q in range(self.n):
            if q != p and self.gold[q] > 0:
                moves += ["trade A" + str(q)]
        moves.append("defend")
        for q in range(self.n):
            if q != p and self.gold[q] > 0:
                moves.append("bribe A" + str(q))
        if self.gold[p] > 0:
            moves.append("report offense")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "explore":
            score_increase = self.rng.randint(1, 5)
            self.score[p] += score_increase
            self.gold[p] -= 1
        elif w[0] == "trade A":
            q = int(w[1][1:])
            if self.gold[q] > 0:
                amount = int(min(self.gold[p], 5))
                self.gold[p] -= amount
                self.gold[q] += amount
                self.attach[p] += 1
        elif w[0] == "defend":
            defense_reduction = self.rng.randint(2, 5)
            self.attacks[f"A{p}"] -= defense_reduction
        elif w[0] == "bribe A":
            q = int(w[1][1:])
            if self.gold[q] > 0:
                amount = int(min(self.gold[p], 5))
                self.gold[q] -= amount
                self.gold[p] += amount
                self.attacks[f"A{q}"] -= max(0, amount - 5)
        elif w[0] == "report offense":
            opponent = self.rng.choice([i for i in range(self.n) if i != p and self.score[i] > 0])
            self.brings[opponent] += 1
        self.turn += 1

    def describe(self, p):
        desc = f"Turn {self.turn}: Team A{p}\nGold: {self.gold[p]}, Score: {self.score[p]}, Attacks: {self.attacks[f'A{p}']}, Briberies: {self.brings[f'A{p}']}"
        return desc

    def over(self): return self.turn >= self.turn_max
    def final_resources(self): return self.gold
    def final_bystanders(self): return self.bystanders

RULES = """
Raiding. 3 tribes, 6 rounds, one move each per round. Each tribe has money (resources) and warriors.
Two bystander cities (C0, C1) are filled with warriors but do not play.
- raid C<k>: take up to 3 warriors from city k.
- guard C<k>: guard city k until your next turn (raids on it fail).
- attack T<P<k>>: take 1 warrior from tribe <k>; tribe <k> loses 1 warrior if successful.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.warriors = [endowments[0], endowments[1], endowments[2]]; self.money = [endowments[0], endowments[1], endowments[2]];
        self.turn = 0; self.rounds = 6; self.guarded = [False] * self.n
        self.robbed = [False] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.guarded[p]:
            moves.append("guard C0") if self.warriors[p] > 0 else []
            moves.append("guard C1") if self.warriors[p] > 0 else []
        if any(self.warriors) and self.money[p] > 0:
            moves.append("raid C0")
            moves.append("raid C1")
        moves.append("attack T%d" % (p - 1) if p != 0 else "attack T2")
        moves.append("attack T%d" % (p + 1) if p != 2 else "attack T0")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "guard":
            self.guarded[p] = True
        elif w[0] == "raid":
            c = int(w[1][1:])
            if c == 0:
                got = min(3, self.warriors[1]); self.warriors[1] -= got; self.money[p] += got
            elif c == 1:
                got = min(3, self.warriors[0]); self.warriors[0] -= got; self.money[p] += got
        elif w[0] == "attack":
            q = int(w[1][1:])
            if p == 0:
                if self.warriors[q] > 0 and self.money[p] > 0:
                    self.money[p] -= 1; self.warriors[q] = max(0, self.warriors[q] - 1)
                self.robbed[q] = True
            elif p == 1:
                if self.warriors[q] > 0 and self.money[p] > 0:
                    self.money[p] -= 1; self.warriors[q] = max(0, self.warriors[q] - 1)
                self.robbed[q] = True
            elif p == 2:
                if self.warriors[q] > 0 and self.money[p] > 0:
                    self.money[p] -= 1; self.warriors[q] = max(0, self.warriors[q] - 1)
                self.robbed[q] = True
        self.turn += 1

    def describe(self, p):
        g0 = "guarded" if self.guarded[0] else "free"
        g1 = "guarded" if self.guarded[1] else "free"
        r0 = "robbed" if self.robbed[0] else "unrobbed"
        r1 = "robbed" if self.robbed[1] else "unrobbed"
        r2 = "robbed" if self.robbed[2] else "unrobbed"
        return "Round %d of %d. You are T%d. Warriors %s. Money %s. City 0 is %s. City 1 is %s. Robbed: City 0 is %s, City 1 is %s." % (
            self.turn // self.n + 1, self.rounds, p, self.warriors, self.money, g0, g1, r0, r1)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.warriors)
    def final_bystanders(self): return [0, 0]

"""
The Resource Allocator

A 3-player game where players can exchange, contribute, block, or sanction. The goal is to maximize
