    def legal_moves(self, p):
        moves = []
        if p == 0:
            if self.bystanders[0]:
                moves.append("Exchange from B0")
            if self.resources[p] <= 12:
                moves.append("Contribute to P1")
            if not self.blocks[0]:
                moves.append("Block for P0")
            if self.resources[p] <= 6:
                moves.append("Sanction P1")
        elif p == 1:
            if self.bystanders[1]:
                moves.append("Exchange from B1")
