        if p not in [0, 1]:
            moves += ["rob_B0", "rob_B1", "sanction", "guard_B0", "guard_B1", "trade_B0", "trade_B1", "trade_self", "wait"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "build_road":
            self.resources[p] += 1
        elif w[0] == "rob_B0":
            if p != 0 and self.bys0 > 0:
                self.bys0 -= 1
                if self.bys0 > 0:
                    self.resources[p] += 1
                self.resources[p] = min(1, self.resources[p])
        elif w[0] == "rob_B1":
