        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.poached = [-1] * self.n; self.traded = [-1] * self.n; self.sanctioned = [-1] * self.n
        self.waiting = []
        self.borrowed = [[0] * len(bystanders) for _ in range(self.n)]

    def to_move(self): 
        return self.turn % self.n if not self.waiting else -1

    def round(self):
        return self.turn // self.n

