        if self.res[p] == 0:
            return ["wait"]
        moves = ["net"]
        if self.res[p] < 10:
            moves += ["trade"]
        if self.res[p] > 0:
            moves += ["poach B0", "poach B1"]
        if min(self.bys) > 0:
            for b in range(len(self.bys)):
                if self.borrowed[p][b] < self.turn // self.n:
                    moves.append(f"borrow B{b}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "net":
            self.res[p] += 1
        elif w[0] == "trade":
            q = self.to_move()
            self.traded[p] = self.turn
            if q != -1:
                trades = min(5, self.res[p] - 5)
                self.res[p] -= trades; self.res[q] += trades
        elif w[0] == "poach B0":
            if self.res[p] < 3 or self.poached[p] == self.turn - 1:
