            if self.borrowed[p][b] < self.round():
                self.borrowed[p][b] = self.turn
                self.bys[0] -= 3
            else:
                return
        self.turn += 1

    def describe(self, p):
        return f"Round {self.round()+1} of {self.rounds}. Player P{p} has {self.res[p]} fish."

