import random   # optional; math is also allowed. Nothing else may be imported.

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.market_goods = 12
        self.banned_from_buy = [-1] * n_players
        self.banned_from_sell = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.banned_from_buy[p] < self.turn and self.market_goods >= self.res[p]:
            moves.append("Buy")
        if self.banned_from_sell[p] < self.turn and self.res[p] >= 1:
            moves.append("Sell")
        moves += ["Gift to P%d" % q for q in range(self.n) if q != p]
        if self.bys:
            moves += ["Gift to B0", "Gift to B1"]
        moves += ["Exchange with B"] if self.bys else []
        moves += ["Trade with P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Buy":
            got = min(3, self.market_goods, self.res[p])
            self.market_goods -= got; self.res[p] += got; self.banned_from_buy[p] = self.turn + 7
        elif w[0] == "Sell":
            self.market_goods += 1; self.res[p] -= 1; self.banned_from_sell[p] = self.turn + 3
