        self.turn = 0; self.rounds = 10
        self.criminal_count = 2
        self.targeted_players = set()

    def to_move(self): return self.turn % self.n

    def steal(self, value):
        self.res[self.to_move()] += value if value <= self.bys[0] else 0
        self.bys[0] -= value if value <= self.bys[0] else 0

    def target(self, index):
        self.targeted_players.add(index)

    def bribe(self, index, amount):
        if index < self.n:
            self.res[index] += amount

    def threaten(self, index):
        self.criminal_count = min(2, self.criminal_count + 1)

    def legal_moves(self, p):
        if self.res[p] < 100:
            return ['steal 1', 'steal 10']
        if p in self.targeted_players:
            return []

        moves = ['steal 1',
                'steal 10',
                'steal 20',
                'steal 50',
                'steal 80',
                'steal 100']
        if p < self.n:
            moves.append('target {}'.format(p))
        if p < self.n:
            moves.append('bribe {} 1'.format(p))
        if self.criminal_count > 0:
            moves.append('threaten {}'.format(p))
        return moves

    def play(self, p, move):
        parts = move.split(' ')
        if parts[0] == 'steal':
            self.steal(int(parts[1]))
        elif parts[0] == 'target':
            self.target(int(parts[1]))
        elif parts[0] == 'bribe':
            index = int(parts[1])
            amount = int(parts[2])
            self.bribe(index, amount)
        elif parts[0] == 'threaten':
            self.threaten(int(parts[1]))
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn} of {self.rounds}. You are Player {p}. Wealth: ${self.res[p]}, Targeted: {self.targeted_players}, Crime Count: {self.criminal_count}"

