import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders); self.rng = random.Random(seed)
        self.turn = 0; self.rounds = 10
        self.share_cache = {i: [None] * n_players for i in range(self.n)}

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["collect B0", "collect B1", "divide"]
        if self.res[p] > 0:
            moves += ["share P%d" % q for q in range(self.n) if q != p]
            moves += ["share B%d" % q for q in range(len(self.bys)) if q < len(self.bys)]
            moves += ["bailout B0"]
            moves += ["bailout B1"]
            moves += ["take all B0"]
            moves += ["take all B1"]
            moves += ["declare"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "collect B0":
            got = min(5, self.bys[0]); self.bys[0] -= got; self.res[p] += got
        elif w[0] == "collect B1":
            got = min(5, self.bys[1]); self.bys[1] -= got; self.res[p] += got
        elif w[0] == "divide":
            all_res = sum(self.res); self.res = [all_res // self.n] * self.n
        elif w[0] == "share P":
            others = [q for q in range(self.n) if q != p]
            q = int(w[1][1:])
            if self.share_cache[p][q] is None or self.share_cache[p][q].startswith("accept"):
                if self.res[p] >= 3:
                    self.res[p] -= 3
                    self.res[q] += 3
                    self.share_cache[p][q] = "accept"
                    self.share_cache[q][p] = "%s: accept" % p
                else:
                    self.share_cache[p][q] = "reject"
            else:
                self.share_cache[p][q] = "pending"
        elif w[0] == "share B":
            others = [q for q in range(len(self.bys)) if q < len(self.bys)]
            q = int(w[1][1:])
            if self.share_cache[p][q] is None or self.share_cache[p][q].startswith("accept"):
                if self.res[p] >= 3 and q != 0:
                    self.res[p] -= 3
                    self.bys[q] += 3
                    self.share_cache[p][q] = "accept"
                    self.share_cache[q][p] = "%s: accept" % p
                else:
                    self.share_cache[p][q] = "reject"
            else:
                self.share_cache[p][q] = "pending"
        elif w[0] == "bailout B0":
            got = min(50, self.bys[0]); self.bys[0] -= got; self.res[p] += got
        elif w[0] == "bailout B1":
            got = min(50, self.bys[1]); self.bys[1] -= got; self.res[p] += got
        elif w[0] == "take all B0":
            self.bys[0] = 0; self.res[p] += self.bys[0]
        elif w[0] == "take all B1":
            self.bys[1] = 0; self.res[p] += self.bys[1]
        elif w[0] == "declare":
            pass  # This can be used privately, no direct enforcement here.
        self.turn += 1

    def describe(self, p):
