              "Bystander B0: %d, Bystander B1: %d.\n" 
              "Shared cache: %s.\n") % ( 
            self.turn // self.n + 1, self.rounds, p, self.res[p], self.bys[0], self.bys[1], 
            self.share_cache[p])

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Complex Game. 3 players, 10 rounds, one move per round. A neutral village B0 has 5 resources, and a neutral village B1 has 5 resources.
- Farm: Gain 1 resource.
- Move Resources Pk: Transfer 1 or more resources from yourself to player k. 
- Divert Bk: Transfer 3 resources from the village Bk to yourself. Player k cannot divert again during the remaining rounds.
- Sanction Pk: Deduct 1 resource from player k without affecting their ability to make subsequent moves.
- Block Pk: Prevent player k from making a specific move (e.g., moving, diverting, sanctioning) for the next round.
The game ends after 10 rounds, and the final standings are assessed.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.endowments, self.bystanders = list(endowments), list(bystanders)
        self.resources = [0] * self.n
        self.blocked = [{'moves': [], 'turn': float('inf')} for _ in range(self.n)]
        self.turns_left = 10
        self.seed = seed
        self.rng = random.Random(seed)

    def to_move(self): 
        return self.turns_left % self.n

    def legal_moves(self, p):
        moves = ["farm"]

        def check_blocked(move, target):
            if self.blocked[p]['moves'] and move in self.blocked[p]['moves']:
                if self.blocked[p]['turn'] <= self.turns_left + 1:
                    return False
            return True

        if self.resources[p] >= 1:
            moves.append("move resources P0")
            if check_blocked("move resources P0", 0):
                moves.append("move resources P1")
                if check_blocked("move resources P1", 1):
                    moves.append("move resources P2")
        if self.resources[p] >= 3:
            moves.append("divert B0")
            moves.append("divert B1")
        if self.resources[p] >= 2:
            moves.append("sanction P0")
            moves.append("sanction P1")
            moves.append("sanction P2")

        return moves

    def play(self, p, move):
        self.turns_left -= 1

        def check_blocked(move, target):
            if self.blocked[p]['moves'] and move in self.blocked[p]['moves']:
                if self.blocked[p]['turn'] <= self.turns_left + 1:
                    self.play(target, move)
                return

        w = move.split(" ")
        if w[0] == "farm":
            self.resources[p] += 1
        elif w[0] == "move resources P0":
            self.resources[p] -= 1; self.resources[0] += 1
        elif w[0] == "move resources P1":
            self.resources[p] -= 1; self.resources[1] += 1
        elif w[0] == "move resources P2":
            self.resources[p] -= 1; self.resources[2] += 1
        elif w[0] == "divert B0":
            if self.rng.random() < 0.5:
                self.bystanders[0] -= 3; self.resources[p] += 3
        elif w[0] == "divert B1":
            if self.rng.random() < 0.5:
                self.bystanders[1] -= 3; self.resources[p] += 3
        elif w[0] == "sanction P0":
            if self.rng.random() < 0.5:
                self.resources[0] -= 1
        elif w[0] == "sanction P1":
            if self.rng.random() < 0.5:
                self.resources[1] -= 1
        elif w[0] == "sanction P2":
            if self.rng.random() < 0.5:
                self.resources[2] -= 1
        elif w[0] == "block P0":
            self.blocked[0]['turn'] = self.turns_left + 1; self.blocked[0]['moves'].append(move)
        elif w[0] == "block P1":
            self.blocked[1]['turn'] = self.turns_left + 1; self.blocked[1]['moves'].append(move)
        elif w[0] == "block P2":
            self.blocked[2]['turn'] = self.turns_left + 1; self.blocked[2]['moves'].append(move)

    def describe(self, p):
        return (f"Turn {self.turns_left} of {self.n}.\n"
                f"You are P{p}. Resources: {self.resources[p]}, B0: {self.bystanders[0]}, B1: {self.bystanders[1]}.")

    def over(self):
        return self.turns_left <= 0

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

