Players can gain 1 resource, transfer to another player, boost an opponent's defense,
attack an opponent, or block an opponent's attack. The game ends when resources run out
and the winner is determined by the number of resources each player has left."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.pool = 100  # Shared resource pool
        self.resources = [10] * n_players  # Initial resources for each player
        self.turn = 0
        self.winner = -1
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] > 0:
            moves.append("Resource Gain")
        for q in (p + 1) % self.n, (p + 2) % self.n:
            if self.resources[q] > 0:
                moves.append(f"Transfer to P{q}")
                if self.resources[p] > 1:
                    moves.append(f"Attack P{q}")
                if(self.resources[q] > 2):
                    moves.append(f"Block from P{q}")
        return moves

    def play(self, p, move):
        def transfer(amount, target):
            if amount <= self.resources[p]:
                self.resources[p] -= amount
                self.resources[target] += amount

        def attack(amount, target):
            gained = min(amount, self.resources[target])
            self.resources[p] += gained
            self.resources[target] -= gained

        def block():
            pass  # No immediate effect until an attack occurs

        w = move.split(" ")
        if w[0] == "Resource Gain":
            self.resources[p] += 1
        elif w[0] == "Transfer to P":
            transfer(1, int(w[2]))
        elif w[0] == "Attack P":
            attack(int(w[2]), int(w[2]))
        elif w[0] == "Block from P":
            pass  # Block is not implemented since it needs to target an attack
            # block()

        self.turn += 1
        self.pool -= 1

    def describe(self, p):
        return f"Turn {self.turn}: Player P{p} has {self.resources[p]} resources."

    def over(self):
        return self.turn >= 30  # Game lasts 30 turns

    def final_resources(self):
        self.winner = self.resources.index(max(self.resources))
        return list(self.resources)

    def final_bystanders(self):  # There are no bystanders in this game
        return [0, 0]

RULES = """
Resource Management. Three players attempt to collect resources and manage them to maximize their final score. The Manager is a neutral party that can be used to increase resources but comes with the temptation of harming other players.
- Collect (1 resource each player)
- Guard (defend a segment, each player)
- Attack (attempt to take resources from any player, -1 point if successful)
- Manage Resources (attempt to take resources from the Manager if possible, +2 points for managing successfully)
- Block Attempts (stop Manager from influencing other players' decisions, -1 point if successful)
The game ends after 5 turns or when one player reaches a score of 8 resources. The final score is calculated based on the total number and quality of resources collected and defended.
Players must balance direct actions with indirect benefits/risks.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed)
        self.score = {p: 0 for p in range(3)}
        self.manager_score = {m: 0 for m in range(2)}
        self.round = 0
        self.turn = 0
        self.defended = [False] * 3

    def to_move(self): return self.round % self.n

    def legal_moves(self, p):
        moves = ["collect"] + (["guard"] if not self.defended[p] else []) 
        moves += ["attack P%d" % q for q in range(self.n) if q != p and self.score[p] > 0]
        moves += ["manage Resources M%d" % s for s in range(len(self.manager_score)) if self.manager_score[s] > 0]
        return moves

    def play(self, p, move):
        if move == "collect":
            if self.res[p] < 1:
                self.score[p] -= 1  # Penalty for trying to collect but not enough resources
            else:
                self.res[p] -= 1
                self.score[p] += 1
        elif move == "guard":
            self.defended[p] = True
        elif move.startswith("attack"):
            q = int(move.split("P")[1])
            if self.score[q] > 0:
                if self.defended[p]:
                    self.score[q] -= 1  # Only deduct if the player was guarding
                else:
                    self.score[p] -= 2  # Deduct more for attacking a non-guarded player
        elif move.startswith("manage Resources"):
            r = int(move.split("M")[1])
            if self.manager_score[r] > 0:
                for s in range(self.res[self.to_move()]):
                    self.res[self.to_move()] -= 1
                    self.res[r] += 1
                    self.manager_score[r] -= 1
        elif move.startswith("block Attempts"):
            self.manager_score[self.to_move()] -= 1
        self.turn += 1
        self.round += self.turn // self.n

    def describe(self, p):
        return ("Round %d. Your score: %d. Player scores: P0 %d P1 %d P2 %d. Manager scores: M0 %d M1 %d."
            % (self.turn + 1, self.score[self.to_move()], self.score[0], self.score[1], self.score[2], self.manager_score[0], self.manager_score[1])).replace(
                "P%d" % (self.n + 1), "P0").replace(
                    "M%d" % (self.n + 2), "M0")

    def over(self):
        return self.round >= 5 or max(self.score.values()) >= 8 or min(self.manager_score.values()) <= -25

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

RULES = """The Resource Allocation Game. Three players compete in a resource allocation challenge. Each player starts with a set of resources, and there are external subsidies (bystanders) available. Players can allocate resources, claim subsidies, and engage in conflict. The goal is to maximize resources while avoiding conflicts.
- allocate: Spend resources to increase or decrease your resource pool.
- claim subsidy: Take up to 10 coins from a bystander.
- fight: Engage with another player in a conflict. If successful, claim the other player's entire resource pool. If unsuccessful, give them a penalty.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.rscs = list(endowments); self.bys = bystanders
        self.turn = 0; self.conflicts = set()

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if p in self.conflicts: return []
        moves = ["allocate"]
        if self.bys[0] > 0 and p not in self.conflicts:
            moves.append("claim subsidy")
        if p not in self.conflicts: moves.append("fight")
        return moves

    def play(self, p, move):
        if move == "allocate":
            amt = int(min(self.rscs[p], 5)); self.rscs[p] -= amt
        elif move == "claim subsidy":
            got = min(self.bys[0], 10); self.bys[0] -= got; self.rscs[p] += got
        elif move == "fight":
            q = (self.to_move() + 1) % 3; self.conflicts.add(q) if self.over() else None
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}. You are P{p}. Resources {self.rscs[p]}: Subsidy {self.bys[0]}; Fighting: {'Yes' if p in self.conflicts else 'No'}."

    def over(self): return self.turn == 300 or len(self.conflicts) >= 3
    def final_resources(self): return [self.rscs[p] for p in range(self.n)]
    def final_bystanders(self): return self.bys

RULES = """
Resource Allocation Game
Three players, two bystanders
- Share, Steal, Guard, Recruit, Challenge, Pass, End Turn
Each turn, players take turns in a sequential order (P0, P1, then P2)
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        random.seed(seed)
        self.turn = 0
        self.soldiers = [5] * n_players
        self.action_count = {i: 0 for i in range(n_players)}

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] >= 3:
            moves.append("Share")
        if self.bys[0] > 0:
            moves.append("Steal B0")
        if self.bys[1] > 0:
            moves.append("Steal B1")
        if self.soldiers[p] < 5:
            moves.extend(["Recruit"] * (5 - self.soldiers[p]))
        moves.append("End Turn")
        if all(a > 0 for a in self.action_count.values()) and sum(self.action_count.values()) < 3:
            moves.append("Pass")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Share":
            for q in [0, 1]:
                if q != p:
                    self.res[q] += 3
        elif w[0] == "Steal B0":
            if self.bys[0] > 0:
                self.res[p] += 3
                self.bys[0] -= 3
        elif w[0] == "Steal B1":
            if self.bys[1] > 0:
                self.res[p] += 3
                self.bys[1] -= 3
        elif w[0] == "Recruit":
            self.soldiers[p] += 1
        elif w[0] == "Challenge P0":
            if self.res[0] > self.res[p]:
                self.res[0] -= 1
                self.res[p] -= 1
            self.soldiers[p] = max(0, self.soldiers[p] - 1)
        elif w[0] == "Challenge P1":
            if self.res[1] > self.res[p]:
                self.res[1] -= 1
                self.res[p] -= 1
            self.soldiers[p] = max(0, self.soldiers[p] - 1)
        elif w[0] == "Pass":
            pass
        self.action_count[p] += 1
        self.turn += 1

    def describe(self, p):
        return (
            f"Turn {self.turn}. "
            f"You are P{p}. Resource: {self.res[p]}, "
            f"Soldiers: {self.soldiers[p]}, "
            f"Bystander 0: {self.bys[0]}, "
            f"Bystander 1: {self.bys[1]}"
        )

    def over(self):
        return self.turn >= self.n * 3

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """City Council. 3 policymakers, 10 days, one move each per day. Each policymaker has points (resources). Two bystander
organizations (O0, O1) hold points but do not play.
- vote: earn 1 point.
- bribe O<k>: steal up to 2 points from organization k.
- threaten O<k>: if organization k is guilty, organization k hands back all of its points this game (unless they are zero) and cannot bribe or threaten for the next 2 turns.
A policymaker is guilty if it has stolen from an organization this game and has not been threatened since.
Only a policymaker with at least 1 point can bribe or threaten."""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.ores = list(bystanders)
        self.turn = 0; self.days = 10; self.stolen = [[0] * len(bystanders) for _ in range(n_players)]; self.thanked = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def day(self): return self.turn // self.n

    def guilty(self, q): return sum(self.stolen[q]) > 0

    def legal_moves(self, p):
        moves = ["vote"]
        if self.thanked[p] < self.day():
            moves += ["bribe O%d" % o for o in range(len(self.ores)) if self.ores[o] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["threaten O%d" % o for o in range(len(self.ores)) if o != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "vote":
            self.res[p] += 1
        elif w[0] == "bribe":
            o = int(w[1][1:]); stole = min(2, self.ores[o]); self.ores[o] -= stole; self.res[p] += stole; self.stolen[p][o] += stole
        elif w[0] == "threaten":
            o = int(w[1][1:]); guilty = self.guilty(o)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                self.ores[o] = 0
                self.thanked[o] = self.day() + 2
            self.stolen[o] = [0] * len(self.ores)
        self.turn += 1

    def describe(self, p):
        return "Day %d of %d. You are P%d. Points %s. Organizations %s. Guilty (stole from an organization, not yet threatened): %s. Threatened until day: %s." % (
            self.day() + 1, self.days, p, self.res, self.ores, ["O%d" % o for o in range(len(self.ores)) if self.guilty(o)] or "none",
            ["O%d" % o for o in range(len(self.ores)) if self.thanked[o] > self.day()] or "none")

    def over(self): return self.turn >= self.n * self.days
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.ores)

