        self.turn = 0; self.rounds = 8; self.energy = [0] * n_players
        self.stones = 3; self.buildingstones = 3; self.nests_strength = [3] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] >= 1:
            moves.append("Train")
        if self.energy[p] >= 1:
            moves.append("Mine")
        if self.nests_strength[p] > 0:
            moves.append("Attack")
        if self.stones > 0:
            moves.append("Build")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Train":
            self.energy[p] += 1
        elif w[0] == "Mine":
            self.resources[p] += 1; self.energy[p] -= 1
            if self.resources[p] >= 10:
                self.resources[p] = 10  # Assume resource cap
        elif w[0] == "Attack":
            opp = (p + 1) % self.n; self.nests_strength[opp] -= 2
            if self.nests_strength[opp] == 0:
                print(f"P{p} wins by controlling P{opp}'s nest!")
        elif w[0] == "Build":
            self.stones -= 1; self.nests_strength[p] += 1
        self.turn += 1
        if self.over():
            weakest_nest = min(i for i, s in enumerate(self.nests_strength) if s > 0)
            for i, s in enumerate(self.nests_strength):
                if i != weakest_nest:
                    self.nests_strength[i] = 0

    def describe(self, p):
        return ("Round {}: Player {}. Energy: {}, Resources: {}, Nest Strength: {}".format(
            self.turn // self.n + 1, p, self.energy[p], self.resources[p], self.nests_strength[p]))

    def over(self): return self.turn >= self.n * self.rounds
