RULES = """
River Rush. Three players (P0, P1, P2), 5 rounds, one move each per round. Each player starts with a river (resources).

#### Moves:
1. **Build Bridge (B**): Spend 2 resources to build a bridge that allows you to cross the river with both boats.
2. **Boat** (O): Use your boat to cross the river and visit the other side. The first time you do this after building a bridge, you will win 3 resources.
3. **Boat Back** (OB**: Use your boat to cross back and continue your current sequence without spending resources. This action can be used multiple times but is limited to one per round. The second time you do this, you gain another 2 resources.

#### Consequences:
- Winning allows the player to move next without using resources.
- Building a bridge allows you to use your boat the following round, regardless of whether it has been used in previous rounds.
- Losing all river resources means you cannot use your boat again that round, even if you have built a bridge.
"""

import random  # optional; math is also allowed. Nothing else may be imported.

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.river = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 5; self.bridge = False; self.used_boat = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.river[p] >= 2 and not self.bridge:
            moves.append("B")
        if self.used_boat:
            moves.append("OB")
        elif self.river[p]:
            moves.append("O")
        return moves

    def play(self, p, move):
        if move == "B":
            self.bridge = True
            self.river[p] -= 2
        elif move == "O":
            self.used_boat = True
            self.river[p] -= 2
            if self.bridge:
                self.river[self.to_move()] += 3
            else:
                self.river[self.to_move()] -= 2
        elif move == "OB":
            if self.used_boat:
                self.used_boat = False
                if not self.bridge:
                    self.river[p] += 2
        self.turn += 1

    def describe(self, p):
        status = "River %d" % self.river[p]
        if self.bridge:
            status += " (with bridge)"
        if self.used_boat:
            status += ", used boat"
        if self.river[p] < 0:
            status += " (all resources lost)"
        return status

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.river)
    def final_bystanders(self): return list(self.bys)

