"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * self.n; self.bys = list(bystanders); self.turn = 0
        self.blocked = [False] * self.n; self.treasure_hunt = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Trade with the next player", "Block", "Tribute to Bystander"] if p != 2 else ["Treasure Hunt"]
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Trade with the next player":
            other = (p + 1) % self.n
            if not self.blocked[p]:
                got = min(self.res[p], self.res[other])
                self.res[p] -= got
                self.res[other] += got
            else:
                self.res[p] += 1

        elif w[0] == "Block":
            if not self.blocked[p] and p < self.n - 1:
                self.blocked[p] = True
                self.res[p] -= 1
            else:
                self.res[p] += 1

        elif w[0] == "Tribute to Bystander":
            if self.bys[p] > 18 and not self.blocked[p]:
                self.bys[p] -= 2
                self.res[p] += 2
            else:
                self.res[p] += 1

        elif w[0] == "Treasure Hunt":
            self.treasure_hunt = True
            self.res[p] += 8
            self.blocked[p] = True
            self.res[p] -= 1

        self.turn += 1

    def describe(self, p):
        return(f"Turn {self.turn}. Player P{p}:\n - Resources: {self.res[p]}\n - Bystander: {self.bys}")

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

