import random   # optional; math is also allowed. Nothing else may be imported.

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders); self.rng = random.Random(seed)
        self.trees = [0] * n_players; self.stock = 6; self.turn = 0; self.round = 0; self.rounds = 10
        self.reserve = sum(endowments) // 3    # new fruit and regrowth are paid from this reserve

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["harvest"]
        if self.res[p] >= 1:
            moves.append("plant")
        moves += ["raid P%d" % q for q in range(self.n) if q != p and self.res[q] > 0]
        moves += ["glean B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        return moves

    def play(self, p, move):
        if move == "plant":
            self.res[p] -= 1; self.trees[p] += 1
        elif move == "harvest":
            take = min(2, self.stock); self.stock -= take; self.res[p] += take
        elif move.startswith("raid"):
            q = int(move.split("P")[1]); take = min(3, self.res[q]); self.res[q] -= take; self.res[p] += take
        elif move.startswith("glean"):
            b = int(move.split("B")[1]); take = min(2, self.bys[b]); self.bys[b] -= take; self.res[p] += take
        self.turn += 1
        if self.turn % self.n == 0:
            if self.res[self.to_move()] >= 2 and self.stock > 0:
                if self.rng.randint(0, 1):
                    self.play(self.to_move(), "harvest")
            self.round += 1
            for q in range(self.n):
                pay = min(self.trees[q], self.reserve); self.reserve -= pay; self.res[q] += pay
            if self.stock > 0 and self.reserve > 0:
                self.stock += 1; self.reserve -= 1

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d." % (self.round + 1, self.rounds, p)]
        rows += ["P%d: %d resources, %d trees" % (q, self.res[q], self.trees[q]) for q in range(self.n)]
        rows += ["Shared stock: %d" % self.stock] + ["Bystander B%d holds %d" % (b, v) for b, v in enumerate(self.bys)]
        return "\n".join(rows)

    def over(self):
        return self.round >= self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

RULES = """The Farming Alliance. Three allied farmers work together to grow crops, protect fields, 
and outcompete a neutral bystander. The goal is to maximize crop yield and prevent the 
bystander from stealing all crops. Each player starts with 10 seeds and 5 tools. The game 
ends after 300 turns or when the bystander successfully steals all crops. """
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.turn = 0
        self.yields = [10, 10, 10]
        self.tools = [5, 5, 5]
        self.strength = [1, 1, 1]
        self.bystander_strength = 1
        self.bystander_crops = 5
        self.bystander_tools = 1

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.tools[p] > 0:
            moves.append("plant seeds")
        if self.tools[p] > 0 and self.yields[p] > 0:
            moves.append("protect fields")
        if self.tools[p] > 0 and self.yields[p] > 0:
            moves.append("defend fields")
        if self.tools[p] > 0:
            moves.append("threaten robbery")
        if self.tools[p] > 0:
            moves.append("conduct secret trade")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "plant seeds":
            self.tools[p] -= 1
            self.yields[p] += 6
            self.strength[p] += 1
        elif w[0] == "protect fields":
            self.tools[p] -= 1
            self.strength[p] += 1
        elif w[0] == "defend fields":
            self.tools[p] -= 1
            self.strength[p] += 1
        elif w[0] == "threaten robbery":
            self.tools[p] -= 1
            if random.random() < 0.8:
                self.bystander_tools -= 1
        elif w[0] == "conduct secret trade":
            self.tools[p] -= 1
            self.yields[p] += min(self.bystander_crops, 3)
            self.bystander_crops = max(0, self.bystander_crops - 3)
            self.bystander_tools -= 1
        self.turn += 1

    def describe(self, p):
        yield_yields = list(zip(range(self.n), self.yields))
        tool_tools = list(zip(range(self.n), self.tools))
        defend_defend = list(zip(range(self.n), self.strength))
        return f"Turn {self.turn}. Player {p} yields {yield_yields[p]}, has {tool_tools[p]} tools, " \
               f"fields at strength {defend_defend[p]}."

    def over(self):
        return self.turn == 300 or self.bystander_crops == 0

    def final_resources(self):
        return list(self.yields)

    def final_bystanders(self):
        return [self.bystander_crops, self.bystander_tools]

RULES = """Harpists' Harmony. 3 harpists, 9+9 rounds, one move each per round. Each harpist starts with a list of notes. 
- exchange: exchange all notes with another harpist.
- encore: perform a virtuosic encore for one round, gaining extra reputation points.
Each round, a harpist can either exchange or perform. The audience evaluates the combined harmony and awards extra points."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.notes = [[n] for n in endowments]
        self.audience = bystanders; self.rounds = 18; self.overturn = 0
        self.arense = [0] * self.n; self.rng = random.Random(seed)

    def to_move(self):
        return self.overturn % self.n

    def legal_moves(self, p):
        moves = ["exchange"]
        if self.overturn == self.rounds or self.arense[p] < 18 - self.rounds:
            moves.append("encore")
        return moves

    def play(self, p, move):
        if move == "exchange":
            q = self.rng.choice([i for i in range(self.n) if i != p])
            self.notes[p], self.notes[q] = self.notes[q], self.notes[p]
            self.arense[p] += 1
            self.arense[q] += 1
        elif move == "encore":
            self.overturn = self.overturn + 2
            self.arense[p] += 1
        self.overturn += 1

    def describe(self, p):
        notes = ', '.join(str(note) for note in self.notes[p])
        return f"Round {self.overturn}. You are H{p+1}. Notes {notes}, Audience {len(self.audience)}."

    def over(self): 
        return self.overturn == self.rounds * 2 + 18

    def final_resources(self): 
        return [len(notes) for notes in self.notes]

    def final_bystanders(self): 
        return list(self.audience)

RULES = """
The Robber Barracks. 3 players, 10 rounds.
- Rob B0: take 1 coin from bystander B0.
- Defend: shield the barracks for 3 rounds (costs 1 coin).
- Report: alert the Guard (costs 1 coin).

Players can choose to defend multiple rounds to prolong security, and report to delay the robber.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.guard = self.bys[0]; self.defend_turn = -1; self.report_turn = -1

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["rob B0"] if p == 0 else ["defend"] + (self.defend_turn < 0 and ["report"] or [])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "rob":
            if self.res[p] > 0 and self.bys[0] > 0:
                self.res[p] += 1; self.bys[0] -= 1
        elif w == "defend":
            if self.defend_turn == -1:
                self.defend_turn = self.turn + 3
                self.res[p] -= 1
        elif w == "report":
            if self.report_turn == -1:
                self.report_turn = self.turn + 1
                self.res[p] -= 1
        self.turn += 1

    def describe(self, p):
        s = "Robber" if p == 0 else ("Defender" if p == 1 else "Guard")
        return "%d of %d. %s. Rob B0: %d coins. Stalls: %d, %d. Defend until %d, report until %d." % (
            self.turn // self.n + 1, self.rounds, s, self.res[p], self.bys[0], self.bys[1], self.defend_turn, self.report_turn)

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

