RULES = """

Secret Alliance and Betrayal.
Three players start with 10 coins each. Each player chooses to initiate an alliance
with P1 or P2 in the first round. Players may:

- "Destroy P1"
- "Destroy P2"
- "Destroy (Third Player)"
- "Exchange 2 With Bystander B0"
- "Give 2 Coins To Another Player"
- "Take 2 Coins from P0"
- "Take 2Coins from P1"
- "Take 2 Coins from Bystander B0"
- "Take 2 Coins from Bystander B1"

In alliance, they guard against each other's destruction, while players try to 
destroy the third player to achieve objectives. Game over after 12 rounds.

Players must find the best balance between destroying their enemy and defending 
themselves, considering the potential for exposing themselves to betrayal. 
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.round = 0; self.ai_turn = False

    def to_move(self): return self.round % self.n
    moves = ("Initiate Alliance with P1", "Initiate Alliance with P2",
             "Destroy P1", "Destroy P2", "Destroy (Third Player)",
             "Exchange 2 With Bystander B0", "Give 2 Coins To Another Player",
             "Take 2 Coins from P0", "Take 2 Coins from P1", "Take 2 Coins from Bystander B0", "Take 2 Coins from Bystander B1")

    def legal_moves(self, p):
        return self.moves

    def play(self, p, move):
        if move == "Initiate Alliance with P1":
            if p == 0:
                self.ai_turn = False
            elif p == 1 and self.res[0] >= 2:
                self.ai_turn = True
            elif p == 2 and self.res[1] >= 2:
                self.ai_turn = True
        elif move == "Initiate Alliance with P2":
            if p == 1:
                self.ai_turn = False
            elif p == 0 and self.res[1] >= 2:
                self.ai_turn = True
            elif p == 2 and self.res[2] >= 2:
                self.ai_turn = True
        elif move == "Destroy P1":
            if p == 0 or p == 2:
                self.res[p] = 0
        elif move == "Destroy P2":
            if p == 1 or p == 2:
                self.res[p] = 0
        elif move == "Destroy (Third Player)":
            if p == 0 or p == 1:
                self.res[p] = 0
        elif move == "Exchange 2 With Bystander B0":
            if self.bys[0] >= 2:
                self.bys[0] -= 2; self.res[p] += 2
        elif move == "Give 2 Coins To Another Player":
            if p == 0 and self.res[1] >= 2:
                self.res[1] -= 2; self.res[0] += 2
            elif p == 1 and self.res[2] >= 2:
                self.res[2] -= 2; self.res[1] += 2
            elif p == 2 and self.res[0] >= 2:
                self.res[0] -= 2; self.res[2] += 2
        elif move == "Take 2 Coins from P0":
            self.res[p] += 2
        elif move == "Take 2 Coins from P1":
            self.res[p] += 2
        elif move == "Take 2 Coins from Bystander B0":
            if self.bys[0] >= 2:
                self.bys[0] -= 2
        elif move == "Take 2 Coins from Bystander B1":
            if self.bys[1] >= 2:
                self.bys[1] -= 2
        self.round += 1
        if self.round == 1:
            if self.res[0] <= 2: self.ai_turn = False
            elif self.res[1] <= 2: self.ai_turn = True
            elif self.res[2] <= 2: self.ai_turn = True

    def describe(self, p):
        msg = f"Round {self.round}. Player {p} has {self.res[p]} coins.\nBystander B0 has {self.bys[0]} coins."
        if self.ai_turn:
            msg += "\nI am currently on AI turn."
        return msg

    def over(self): return self.round == 12
    def final_resources(self): return self.res
    def final_bystanders(self): return self.bys

RULES = """
Robber's Dilemma. 3 robbers, 8 rounds. Three strategies are available:
1. Take Steal: Steals from the bystander, gaining all resources in one turn.
2. Guard: Protects the bystander from robbery for one turn.
3. Run: Loses one resource immediately, but protects the bystander indefinitely.

**Objective:** Maximize your own wealth while ensuring the bystander's resources are protected. Robbers can gain substantial benefits from stealing, but protecting the bystander carries long-term risks.

Each player starts with 3 resources and can lose up to 1 resource each turn. Robbers have real choices on most turns and must balance taking, guarding, and running strategically. """

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [3] * n_players
        self.bys = [1] * 2
        self.rounds = 8
        self.turn = 0
        self.robber_count = 2
        self.targeted_players = set()

    def to_move(self): return self.turn % self.n

    def steals(self, value):
        if value <= self.bys[0]:
            self.resources[self.to_move()] += value
            self.bys[0] -= value
            for j in range(self.n):
                if j != self.to_move():
                    self.resources[j] -= 1

    def targets(self, index):
        self.targeted_players.add(index)

    def guards(self):
        self.targeted_players.clear()

    def runs(self):
        if any(v < 1 for v in self.resources):
            self.resources[self.to_move()] -= 1

    def legal_moves(self, p):
        moves = []
        if self.resources[p] > 0:  # Guard
            moves.append("Guard")
        if self.resources[p] > 1: # Run
            moves.append("Run")
        if p in self.targeted_players: # Targets
            moves.append("Targets {}".format(p))

        for i in range(self.n):  # Steal
            if self.resources[p] > 0:
                moves.append(f"Steals {i}")

        return moves

    def play(self, p, move):
        if 'Steals' in move:
            index = int(move.split(' ')[-1])
            self.steals(1)  # Assuming each steal takes 1 resource
        elif move == "Guard":
            self.guards()
        elif move == "Run":
            self.runs()
        elif 'Targets' in move:
            index = int(move.split(' ')[-1])
            self.targets(index)

        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn} of {self.rounds}. Player {p}'s resources: {self.resources}, Targeted by: {self.targeted_players}, Robber Count: {self.robber_count}"

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.resources[:]

    def final_bystanders(self):
        return self.bys

RULES = """
Resource Allocation and Coordination. 4 players, 6 rounds, each player has 3 resources.
- move('take'): Take 1 resource from bystander.
- move('give', player): Give 1 resource to player P0, P1, or P2.
- move('share', resource): Swap with player P0, P1, or P2.
- move('block', player): Prevent that player from taking resources from the bystander for the next 2 turns.
- move('shield'): Stop all non-blocking players from taking resources from the bystander.
- move('unblock', player): Allow player to take resources again after being blocked.
- Goal: Maximize own resources while preventing bystander from exceeding 3 resources.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [3] * self.n; self.bys = list(bystanders)
        self.blocked = [-1] * self.n; self.shielded = False
        self.turn = 0; self.rounds = 6; self.shield_turns_remaining = 0; self.block_turns_remaining = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.shielded:
            if self.res[p] > 0 and self.res.count(0) < 2:
                moves.append("give B")
        else:
            if self.res[p] > 0 and self.bys[0] > 0:
                moves.append("take")
            if self.block_turns_remaining[p] == 0: self.block_turns_remaining[p] = -1
            for i in range(2):
                if self.res[p] > 0 and self.res[i] > 0 and self.bys[i] > 0:
                    if self.block_turns_remaining[i] == 0: self.block_turns_remaining[i] = -1
                    if self.res[i] <= 2 and self.bys[i] <= 2:
                        moves.append(f"give P{i}")
                if self.res[p] > 0 and self.bys[i] > 0:
                    if self.block_turns_remaining[i] == 0: self.block_turns_remaining[i] = -1
                    if self.res[i] <= 0 or self.bys[i] <= 0:
                        moves.append(f"share P{i}")
            if self.shield_turns_remaining == 0: self.shield_turns_remaining = -1
            if self.shielded:
                moves.append("unblock all")
            else:
                moves.append("shield")
        if self.bys[0] > 1:
            if self.shielded:
                if self.res[p] > 0 and self.res.count(0) < 2:
                    moves.append(f"give P1")
            else:
                moves.append(f"give P1")
        if self.block_turns_remaining[p] != 0:
                moves.append(f"unblock P{p}")

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "take":
            if self.bys[0] > 0:
                self.bys[0] -= 1
                self.res[p] += 1
                self.res[0] -= 1
                for i in range(2):
                    if self.res[i] > 0 and self.bys[i] > 0:
                        self.res[i] -= 1
                        self.bys[i] -= 1
                        self.res[0] += 1
        elif w[0] == "give":
            if w[1] == 'B':
                if self.res[p] > 0 and self.bys[0] > 0:
                    self.res[p] -= 1
                    self.res[0] += 1
                    self.bys[0] -= 1
            elif w[1] in ('P0', 'P1'):
                if w[1] == 'P0':
                    i = 0
                else:
                    i = 1
                if self.res[p] > 0 and self.res[i] > 0 and self.bys[i] > 0:
                    self.res[p] -= 1
                    self.res[i] -= 1
                    self.res[0] += 1
                    self.bys[i] -= 1
        elif w[0] == "share":
            if w[1] == 'P0':
                i = 0
            elif w[1] == 'P1':
                i = 1
            if self.res[i] > 0 and self.res[p] > 0 and self.bys[i] > 0:
                self.res[p] -= 1
                self.res[i] -= 1
                self.bys[i] -= 1
                self.res[0] += 1
                self.res[i] += 1
        elif w[0] == "block":
            if w[1] in ('P0', 'P1'):
                i = 0 if w[1] == 'P0' else 1
                if self.res[1] > 0:
                    self.block_turns_remaining[i] = 2
        elif w[0] == "shield":
            self.shielded = True
        elif w[0] == "unblock":
            if w[1] in ('P0', 'P1'):
                i = 0 if w[1] == 'P0' else 1
                self.block_turns_remaining[i] = -1

        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.turn} of {self.rounds}. You are P{p}. "
            f"Resources: P0 {self.res[0]}, P1 {self.res[1]}, P2 {self.res[2]}, B {self.bys[0]}, Shields active: {str(self.shielded)[0]}.\n"
            f"(Blocked actions: B= {self.block_turns_remaining}, Others= {str([x > 0 for x in self.block_turns_remaining])[1:-1]})"
        )

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return self.res
    def final_bystanders(self): return self.bys

RULES = """
Rivalry Rivals. 3 rivals, 9 rounds, one move each per round. Each rival has points (resources) and power (max 8).
- train: earn 2 points from the reserve (only with power 3 or more).
- block: prevent a rival from using strike.
- defend: gain an extra point for the turn.
- strike E>k: lower rival k's power by 3. At 0 you take ALL their points and they return with power 3.
- raid N<k> nation: take up to 3 points from nations k, neutral parties who do not play.
The nation reserve is limited."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 9; self.pow = [5] * n_players; self.reserve = (sum(endowments) + sum(bystanders)) // 4

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["block"] + ["hail P%d" % q for q in others]
        moves = ["train"] + (["block"] if self.pow[p] >= 3 else [])
        moves += ["defend"]
