        self.blocked = [-1] * n_players
        self.sanctioned = []

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def blocked_by(self, p): 
        return any([self.blocked[q] == p for q in range(self.n)])

    def legal_moves(self, p):
        moves = ["research"]

        if self.blocked[p] - self.rnd() < 0 and p < len(self.res):
            moves += ["copy S%d" % s for s in range(4)]

        if p >= len(self.res):
            moves += ["sanction P%d" % s for s in range(n_players)]


