        # Playing resources
        if p == 0:
            moves.append("Play Resources P0 to 0-5")
        if p == 1:
            moves.append("Play Resources P1 to 0-5")
        if p == 2:
            moves.append("Play Resources P2 to 0-5")

        # Borrow resources from bystanders
        if self.bys[0] > 2:
            moves.append(f"Borrow Resources B0 to 0-3")
        if self.bys[1] > 2:
            moves.append(f"Borrow Resources B1 to 0-3")

        # Sanction a player from having more than 2 resources
        if self.res == [3, 3, 3]:
