- Gold B1: 15"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bys = bystanders
        self.rounds = 5; self.turn = 0; self.health = [10] * self.n; self.gold = [15] * self.n; self.blocked = [False] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["deflect", "strike"]
        if self.blocked[p]: moves.append("guard")
        return moves

    def play(self, p, move):
        if move == "deflect":
            if self.resources[p] >= 2:
                self.resources[p] -= 2
                if self.blocked[self.to_move()] and random.random() < 0.5:
                    self.health[self.to_move()] -= 1
                    self.gold[self.to_move()] = min(15, self.gold[self.to_move()] + random.randint(1, 5))
                    self.blocked[self.to_move()] = False
        elif move == "strike":
            if self.resources[p] >= 3:
                self.resources[p] -= 3; dam = max(0, self.health[self.to_move()] - random.randint(1, 3))
                self.health[self.to_move()] = dam
                if random.random() < 0.5: self.gold[p] = min(15, self.gold[p] + random.randint(2, 5))
                else: self.gold[p] = 0
        elif move == "capture":
            if self.resources[p] >= 3 and self.health[self.to_move()] > 0:
                self.gold[p] = min(self.gold[p] + self.gold[self.to_move()], 15)
                self.resources[p] += self.resources[self.to_move()]
                self.health[p] += self.health[self.to_move()]
                self.health[self.to_move()] = 0
                self.resources[self.to_move()] = 0
        elif move == "block":
            if self.resources[p] >= 2:
                self.resources[p] -= 2
                self.blocked[self.to_move()] = True

        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.turn // self.n + 1}/{self.rounds}. "
