        return self.turn % self.n  # Determine whose turn it is

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 1:
            moves.append("Quarrel")
        if self.turn == 1 and self.res[p] == 4:
            moves.append("Attack")
        if self.res[p] > 0:
            moves.append("Gift")
        if self.res[p] > 2:
            moves.append("Help")
        moves.append("Neutral")
        return moves

    def play(self, p, move):
        if move == "Quarrel":
            self.res[p] -= 1
            self.bys[0] += 1
            self.turn += 1
            self.final_resources()  # Update final resources
        elif move == "Attack":
            if self.res[p] < 4:
                raise ValueError("Not enough resources to attack.")  # Check if enough resources
            self.res[p] -= 4
            self.bys[1] += 4
            self.turn += 1
            self.final_resources()  # Update final resources
        elif move == "Gift":
