RULES = """
Dungeon Runner Game
- Objective: The goal is to escape the dungeon using the least resources while outmaneuvering the monster.
- Moves:
  - Move: run
  - Attack: attack
  - Guard: guard
  - Heal: heal
  - Escape: escape
- Game Over: The game ends after 10 turns, or when all players have escaped.
- Resources: Players start with 10 resources and can collect up to 10 resources in total throughout the game.
- Temptation: Guarding the player's health by attacking the monster can be tempting, but it incurs a resource cost.
- Honesty: Players who act honestly are rewarded with a health boost, increasing their chances of escaping safely.
- Interactions: Players can interact with other players and bystanders. Players can attack, heal, or guard, but cannot influence bystanders to take resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.health = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.guarded = [False] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.health[p] < 10:
            moves = ["heal"]
        else:
            moves = ["run", "attack", "guard", "escape"]
        return moves

    def attack(self, p, p_other):
        if self.turn % 2 == 0:
            if p_other >= self.n:
                p_other += self.n
            else:
                p_other -= self.n
        self.res[p] += 4 - max(0, 5 - self.health[p_other])
        self.health[p_other] = max(0, self.health[p_other] - 5)
        if self.turn % 2 == 0:
            p_other -= self.n

    def heal(self, p):
        heal_by = min(4, self.res[p])
        self.res[p] -= heal_by
        self.health[p] += heal_by

    def guard(self, p):
        self.guarded[p] = True

    def escape(self, p):
        if not self.guarded[p]:
            self.res[p] = 0
            return
        if self.health[p] >= 13:
            self.res[p] = 0

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "run":
            pass
        elif w[0] == "attack":
            if p < self.n:
                self.attack(p, p)
            else:
                self.attack(p - self.n, p)
        elif w[0] == "guard":
            self.guard(p)
        elif w[0] == "heal":
            self.heal(p)
        if w[0] == "escape":
            if self.turn % 2 == 0:
                self.escape(p)
            else:
                self.escape(p - self.n)
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}. You are P{p}. Resources: {self.res[p]}, Health: {self.health[p]}, Guarded: {self.guarded[p]}."

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

