import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.catch = list(endowments)
        self.bystanders = bystanders.copy()
        self.turn = 0
        self.rounds = 10
        self.owed_fines = [0, 0]

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["fish"]
        if self.catch[p] > 0:
            moves.append("trade P%d" % p)
        if p < self.n - 1 and self.catch[p + 1] > 0:
            moves.append("trade P%d" % (p + 1))
        if p > 0 and self.catch[p - 1] > 0:
            moves.append("trade P%d" % (p - 1))
        return moves

    def play(self, p, move):
        if move == "fish":
            self.catch[p] += 1
        elif move == "trade P%d" % p:
            target = p + 1 if p < self.n - 1 else 0
            self.catch[p] -= 1
            self.catch[target] += 1
        elif move == "trade P%d" % (p + 1):
            target = p - 1 if p > 0 else self.n - 1
            self.catch[p] -= 1
            self.catch[target] += 1
        elif move == "fine P%d" % p:
            if self.catch[p] > 0:
                self.catch[p] -= 1
                if self.catch[p] == 0 and self.owed_fines[p] > 0:
                    target = p + 1 if p < self.n - 1 else 0
                    self.catch[p] -= 1
                    self.catch[target] += 1
                    self.owed_fines[p] -= 1
