If a player runs out of resources, they lose the game immediately.
No move is possible if an opponent's stash is being sabotaged and you have not defended it.
The first player to reach a zero-stash state loses.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.defended = [False] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if not self.over():
            moves = ["sabotage", "guard"]
            if self.turn == 0 or self.res[p] > 0:
                moves.append("spy")
                if self.turn >= 1 and self.res[p] >= 2 and not self.defended[self.to_move()]:
                    moves.append("attack")
            return moves
        return []

    def play(self, p, move):
        if self.over():
            return
        w = move.split(" ")
        if w[0] == "sabotage":
            q = self.to_move()
            if self.res[q] > 1:
                self.res[p] += 2
                self.res[q] -= 1
        elif w[0] == "guard":
            self.defended[p] = True
        elif w[0] == "spy":
            if not self.defended[self.to_move()]:
                q = self.to_move()
                if self.res[q] <= 0:
                    print("Spy failed, nothing in stash.")
                else:
                    print("Spy detected sabotage in player", q + 1)
                    self.defended[p] = True
        elif w[0] == "attack":
            q = self.to_move()
            if self.defended[self.to_move()] and self.defended[q]:
                print("Both players sabotage each other!")
                self.res[p] -= 2
                self.res[q] -= 2
                self.defended = [False] * self.n
        for p in range(self.n):
            if self.res[p] <= 0:
                print("Player", p + 1, "lost due to lack of resources.")
        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.turn}. "
            f"Your stash: {self.res[p]}; opponent's stash: {self.res[self.to_move()]}."
        )

    def over(self):
        return all(res == 0 for res in self.res) or self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

