Only a trader with at least 1 coins can denounce."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [e for e in endowments]
        self.bys = [b for b in bystanders]
        self.turn = 0
        self.rounds = 7
        self.owed = [[0] * len(self.bys) for _ in range(self.n)]
        self.denounced = [-1] * self.n

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["trade"]
        if self.turn < self.rounds and self.res[p] > 0:
            moves.append("rob B0")
        if self.turn < self.rounds and self.res[p] > 0:
            moves.append("rob B1")
        if self.res[p] > 0:
            moves.append("denounce P0")
        if self.res[p] > 0:
            moves.append("denounce P1")
        return moves

    def play(self, p, move):
        if move == "trade":
            self.res[p] += 1
        elif move == "rob B0":
            steal = min(3, self.bys[0])
            self.bys[0] -= steal
            self.res[p] += steal
            self.owed[p][0] += steal
        elif move == "rob B1":
            steal = min(3, self.bys[1])
            self.bys[1] -= steal
            self.res[p] += steal
            self.owed[p][1] += steal
        elif move == "denounce P0":
            guilty = self.is_guilty(p, 0)
            if self.res[p] > 0:
                if guilty:
                    self.res[p] -= self.res[p]
                    self.denounced[p] = self.turn + 2
                    self.owed[p][0] = 0
        elif move == "denounce P1":
            guilty = self.is_guilty(p, 1)
            if self.res[p] > 0:
                if guilty:
                    self.res[p] -= self.res[p]
                    self.denounced[p] = self.turn + 3
                    self.owed[p][1] = 0
        self.turn += 1

    def describe(self, p):
        robbed = self.owed[p]
        stolen_B0 = robbed[0]
        stolen_B1 = robbed[1]
        return f"Round {self.turn} of {self.rounds}. You are P{p} with coins {self.res}. Stole B0: {stolen_B0} coins, B1: {stolen_B1} coins. Bystander shops have {self.bys[0]}, {self.bys[1]} coins."

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

    def is_guilty(self, p, b):
        return self.owed[p][b] > 0 and self.denounced[p] < self.turn

