The game ends after 30 turns. Players gather their final resources at the end.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [3] * self.n
        self.bandits = [5] * 2  # Start with high resources to ensure they attack aggressively
        self.turn = 0
        self.total_turns = 30
        self.potential_attacker = None
        self.bystanders = list(bystanders)
        self.rng = random.Random(seed)

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Gather Resources"]
        if self.bandits[self.rng.randint(0, 1)] > 6:
            if p < self.n - 1: 
                moves.append(f"Attack Bystander P1 {self.resources[p + 1]}")
            if p > 0: 
                moves.append(f"Attack Bystander P0 {self.resources[p - 1]}")
        if self.bandits[self.rng.randint(0, 1)] > 11: 
            moves.append(f"Sanction Bandit P1 {self.resources[p + 1]}")
        if self.bandits[self.rng.randint(0, 1)] > 16:  
            moves.append(f"Sanction Bandit P0 {self.resources[p - 1]}")
        if self.bandits[self.rng.randint(0, 1)] > 21:
            if p < self.n - 1: 
                moves.append(f"Block Aggressive Bystander P1 {self.resources[p + 1]}")
            if p > 0: 
                moves.append(f"Block Aggressive Bystander P0 {self.resources[p - 1]}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Gather Resources":
            self.resources[p] += 1
        elif w[0] == "Attack Bystander P0":
            self.resources[p] -= w[2];
            self.bandits[self.rng.randint(0, 1)] -= 6
        elif w[0] == "Attack Bystander P1":
            self.resources[p] -= w[2];
            self.bandits[self.rng.randint(0, 1)] -= 6
        elif w[0] == "Sanction Bandit P0":
            attacker = p + 1
            if self.bandits[0] > 11:
                self.resources[p] -= 1
                self.bandits[0] -= 11
                self.resources[attacker] -= 2
        elif w[0] == "Sanction Bandit P1":
            attacker = p - 1
            if self.bandits[1] > 11:
                self.resources[p] -= 1
                self.bandits[1] -= 11
                self.resources[attacker] -= 2
        elif w[0] == "Block Aggressive Bystander P0":
            attacker = p + 1
            if self.bandits[0] > 21:
                self.bandits[0] -= 21
        elif w[0] == "Block Aggressive Bystander P1":
            attacker = p - 1
            if self.bandits[1] > 21:
                self.bandits[1] -= 21
        self.turn += 1
        if self.bandits[0] < self.bandits[1]:
            self.potential_attacker = 0
        else:
            self.potential_attacker = 1

    def describe(self, p):
        desc = f"Player {p} has {self.resources[p]} resources."
        if self.potential_attacker == 0:
            desc += " Potential attacker: P0"
        else:
            desc += " Potential attacker: P1"
        return desc

    def over(self): 
        return self.turn >= self.total_turns

    def final_resources(self): 
        return self.resources

    def final_bystanders(self): 
        return self.bandits

