import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * n_players; self.bys = list(bystanders)
        self.turn = 0; self.rounds = 5; self.sanctions = [[False] * n_players for _ in range(2)]

