    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = ["take P0"] + ["take P1"] + ["take B0"] + ["take B1"] + ["guard"] + ["sanction"]
        for q in others:
            moves.append(f"guard P{q}")
            moves.append(f"sanction P{q}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "take P0":
            got = min(3, self.res[self.n // 2] - self.bys[0])
            self.res[self.n // 2] -= got
            self.bys[0] += got
        elif w[0] == "take P1":
            got = min(3, self.res[self.n // 2 + 1] - self.bys[1])
            self.res[self.n // 2 + 1] -= got
            self.bys[1] += got
        elif w[0] == "take B0":
            got = min(3, self.bys[0])
            self.bys[0] -= got
            self.res[self.n // 2] += got
        elif w[0] == "take B1":
            got = min(3, self.bys[1])
            self.bys[1] -= got
            self.res[self.n // 2 + 1] += got
        elif w[0] == "guard":
            self.sanctions[0][p] = True
        elif w[0] == "sanction":
            self.sanctions[1][p] = True
        elif w[0].startswith("guard P"):
            self.sanctions[int(w[0][-1])][p] = True
        elif w[0].startswith("sanction P"):
            self.sanctions[int(w[0][-1])][p] = False  # Allow unsanctioning
        self.turn += 1
        if self.sanctions[0][p]:
            if self.res[p] > 0:
                self.res[p] -= 1
        if self.sanctions[1][p]:
            if self.res[p] > 0:
                self.res[p] -= 1

    def describe(self, p):
        return f"""Round {self.turn // self.n + 1} of {self.rounds}. Player {p}, Resource Holdings: {self.res}.
Bystander Ponds: [{self.bys[0]}, {self.bys[1]}].
Sanction Statuses: P0 {self.sanctions[0][p]}, P1 {self.sanctions[1][p]}."""

