        elif w[0] == "Block Player 0" or w[0] == "Block Player 1":
            self.blocked[p] = self.turn + 1 if p != (p + 1) % self.n else self.turn + 2
        elif w[0] == "Block P2":
            self.blocked[p] = self.turn + 1 if p == 2 else self.turn + 2

        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn} of {self.rounds}. You are Player {p}. Resources: {self.res}. Blocked: {'Yes' if self.blocked[p] > self.turn else 'No'}."

    def over(self): return self.turn == self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return [self.bys[0], self.bys[1]]

