            moves += ["sell"] + ["buy B%d" % b for b in range(len(self.bys)) if self.barred[p] < self.rnd()]
        if self.coins[p] > 0:
            moves += ["steal B%d" % b for b in range(len(self.bys)) if self.barred[p] < self.rnd()]
        return moves

    def play(self, p, move):
