        elif w[0] == "steal B0":
            self.coins[p] += 1; self.res[p] -= 1
        elif w[0] == "steal B1":
            self.coins[p] -= 1; self.res[p] += 1
        self.barred[p] = self.rnd() + 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.rnd()+1} of {self.rounds}. You are P{p}. Cash {self.res[p]}, Coins {self.coins[p]}. Coins stolen from B0: {self.barred[p] < self.rnd() and 'Yes' or 'No'}."

