class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8; self.reserve = 0
        self.guarded_bystander = None

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["guard B0", "guard B1"]
        moves = ["mine"]
        if self.guarded_bystander is None:
            moves.append("guard B0")
            moves.append("guard B1")
        if self.bys[0] > 0:
            moves.append("steal from B0")
        if self.bys[1] > 0:
            moves.append("steal from B1")
        if self.res[p] > 0:
            moves.append("steal from P0")
            moves.append("steal from P1")
            moves.append("steal from P2")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 1
        elif w[0] == "steal" and w[1] == "from" and w[2] == "B0":
            if self.bys[0] > 0:
                got = min(2, self.bys[0]);
                self.bys[0] -= got;
                self.res[p] += got;
                self.reserve += 1;
        elif w[0] == "steal" and w[1] == "from" and w[2] == "B1":
            if self.bys[1] > 0:
                got = min(2, self.bys[1]);
                self.bys[1] -= got;
                self.res[p] += got;
                self.reserve += 1;
        elif w[0] == "steal" and w[1] == "from" and w[2] == "P0":
            if self.res[0] > 0:
                got = min(1, self.res[0]);
                self.res[0] -= got;
                self.res[p] += got;
                self.reserve += 1;
        elif w[0] == "steal" and w[1] == "from" and w[2] == "P1":
            if self.res[1] > 0:
                got = min(1, self.res[1]);
                self.res[1] -= got;
                self.res[p] += got;
                self.reserve += 1;
        elif w[0] == "steal" and w[1] == "from" and w[2] == "P2":
            if self.res[2] > 0:
                got = min(1, self.res[2]);
                self.res[2] -= got;
                self.res[p] += got;
                self.reserve += 1;
        elif w[0] == "guard" and (w[1] == "B0" or w[1] == "B1"):
            if self.guarded_bystander is None:
                self.guarded_bystander = int(w[1][1:]);
        elif w[0] == "guard" and w[1] == "none":
            self.guarded_bystander = None;
        self.turn += 1
        if self.guarded_bystander is not None:
            self.bys[self.guarded_bystander] = 0

    def describe(self, p):
        return f"Round {self.turn // self.n} of {self.rounds}. You are P{p}. Resources {self.res}. Bystanders {self.bys}. Guarded Bystander {self.guarded_bystander}. Guarding: {'true' if self.guarded_bystander is not None else 'false'}."

    def over(self): 
        if self.turn >= self.rounds or any(r == 0 for r in self.res):
            return True
        else:
            return False

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

