Resource Allocation:
Three players and two bystanders start with 10 resources each. The game lasts for 30 turns. Players can:
1. Even Distribution: Divide all resources equally among P0, P1, P2, and B0, B1, ensuring none gains or loses.
2. Give All: Transfer all resources to Player P0, P1, or P2. If giving to B0 or B1, you risk losing resources.
3. Steal: Steal up to 2 resources from any other player or bystander. Note that stealing from P0, P1, or P2 is considered theft and leads to severe penalties.

The goal is to strategically distribute and allocate your resources, aiming to achieve the highest possible score by turning others' resources into your own. Be cautious of your actions, as overstealing may reduce your own resources further, leaving your path to victory dimmed.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0
        self.picked = [False] * n_players + [False] * len(bystanders)
        self.bystander_resources = self.bys

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.picked[p]:
            moves.append("Even Distribution")
        for q in range(self.n + len(self.bys)):
            if q != p:
                if q > self.n - 1:
                    moves.append(f"Steal 2 Resources from B{q - self.n}")
                else:
                    moves.append(f"Give All Resources to P{q}")

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Even Distribution":
            total_resources = sum(self.res)
            self.res = [total_resources // 4] * self.n + [total_resources // 4] * 2
        elif w[0] == "Give All":
            if int(w[1]) != p:
                to_player = int(w[1])
                if to_player == 0:
                    self.res[0] += self.res[p]
                    self.res[p] = 0
                    self.picked[0] = True
                else:
                    self.res[to_player] += self.res[p]
                    self.res[p] = 0
                    self.picked[to_player] = True
        elif w[0] == "Steal":
            if int(w[1]) < self.n:
                to_player = int(w[1])
                if self.res[to_player] >= 2:
                    self.res[to_player] -= 2
                    self.res[p] += 2
                    self.picked[to_player] = True

        self.turn += 1

    def describe(self, p):
        msg = f"Turn {self.turn}. You are Player P{p}. "
        if self.picked[p]:
            msg += f"You have already allocated your resources."
        else:
            msg += f"You must choose between 'Even Distribution', 'Give All Resources', or 'Steal'. "
            msg += f"Current resources: {self.res[p]}"
        msg += f"\nBystander B0 has {self.bys[0]} resources."
        return msg

    def over(self): return self.turn >= 30

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

