        elif w[0] == "defend":
            if self.defended[p] >= self.rnd():
                return False
            if self.plotted[p] >= 0:
                self.defended[p] = self.rnd() + 1
                if self.plotted[p] == p:
                    self.res[self.plotted[p]] = 1
                else:
                    self.res[self.plotted[p]] //= 2
        self.turn += 1

    def describe(self, p):
