2. Keep Coins: Don't give any coins to anyone.
3. Give All Coins to P1: Take all their coins and give them to P1.
4. Give 2 Coins to Bystander B0: If Bystander B0 has 2 or more coins, take 2 coins from Bystander B0 before making any other decision.
5. Give 4 Coins to Bystander B1: If Bystander B1 has 4 or more coins, take 4 coins from Bystander B1 and leave their own coins as is.
6. Wait and Continue: Optionally, do nothing for 1 or 2 turns.
Bystander B0 starts with 6 coins and Bystander B1 starts with 6 coins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * self.n
        self.bys = list(bystanders); self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Divide Coins Equally"] + ["Keep Coins"]
        if p == 0 or p == 2:
            moves.append("Give All Coins to P1")
        if self.bys[0] >= 2:
            moves.append("Give 2 Coins to Bystander B0")
        if self.bys[1] >= 4:
            moves.append("Give 4 Coins to Bystander B1")
        moves.append("Wait and Continue (0 or 1 turn)")
        return moves

    def play(self, p, move):
        if move == "Divide Coins Equally":
            for q in range(self.n):
                if q != p:
                    share = (self.res[p] - 3) // (self.n - 1)
                    self.res[p] -= share
                    self.res[q] += share
        elif move == "Keep Coins":
            pass
        elif move == "Give All Coins to P1":
            self.bys[0] += self.res[p]; self.res[p] = 0
        elif move == "Give 2 Coins to Bystander B0":
            if self.bys[0] >= 2:
                self.bys[0] -= 2; self.res[p] += 2
        elif move == "Give 4 Coins to Bystander B1":
            if self.bys[1] >= 4:
                self.bys[1] -= 4; self.res[p] += 4
        elif move == "Wait and Continue (0 turns)":
            pass
        elif move == "Wait and Continue (1 turn)":
            self.turn += 1
        self.turn += 1

    def describe(self, p):
        msg = f"Turn {self.turn}. You are P{p}. You have {self.res[p]} coins.\nBystander B0 has {self.bys[0]} coins."
