The Rivalry of Nations. A game for three players representing rival nations.
- trade: increase resources by 2 units.
- assassinate: remove an opponent from the game immediately.
- sanction: reduce an opponent's resources by 4 units, but they can keep some resources until they reach 0.
- block: prevent an opponent from making a move for the rest of the round.

The game ends after 10 rounds, and the player with the maximum resources wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.blocked = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.blocked[p] == self.turn:
            return []
        moves = ["trade"]
        if p < 1: 
            return moves
        moves += ["assassinate P%d" % (i+1) for i in range(self.n)]
        if p < 2:
            moves += ["sanction P%d" % (i+1) for i in range(self.n) if self.res[i] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade": 
            if self.res[p] >= 2:
                self.res[p] += 2
        elif w[0] == "assassinate": 
            q = int(w[1][1:])
            if 0 <= q < self.n and q != p:
                self.res[q] = 0
        elif w[0] == "sanction": 
            q = int(w[1][1:])
            if 0 <= q < self.n and self.res[q] > 0:
                if self.res[p] >= 4:
                    self.res[p] -= 4
                else:
                    self.res[p] = 0
        elif w[0] == "block": 
            self.blocked[p] = self.turn + 1 if p < 2 else self.turn + 2

        self.turn += 1

    def describe(self, p):
        if self.res[p] == 0:
            return f"Round {self.turn} of {self.rounds}. Player P{p} has been assassinated."
        else:
            return f"Round {self.turn} of {self.rounds}. You are P{p}. Resources: {self.res}. Blocked: {'Yes' if self.blocked[p] > self.turn else 'No'}."

    def over(self): return self.turn == self.rounds
    def final_resources(self): return self.res
    def final_bystanders(self): return [0] * len(self.bys)

