import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.traps = [0] * len(self.bys); self.guard = None
        self.sailors = [[0] * len(self.bys) for _ in range(self.n)]
        self.barred = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def is_trapped(self, p):
        for b in range(len(self.bys)):
            if self.traps[b] > self.rnd():
                return True
        return False

    def legal_moves(self, p):
        moves = []
        if self.guard is None and self.sailors[p][0] > 0:
            moves.append("hire guard")
        if self.res[p] >= len(self.bys):
            moves.append("hire sailor")
        if self.res[p] > 0 and not self.is_trapped(p):
            moves.append("search")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "search":
            rand_num = random.random()
            if rand_num >= max(0.2 - (self.rnd() /40), 0):
                for b in range(len(self.bys)):
                    if self.traps[b] > self.rnd(): continue
                    if rand_num <= max(0.2 - ((self.rnd() + 1) /40), 0):
                        self.res[p] -= 1; self.traps[b] = self.rnd() + 3; self.sailors[p][b] += 1
                        break
        elif w[0] == "hire guard":
            self.guard = p
            self.res[p] -= 5
        elif w[0] == "hired sailor":
            self.sailors[p][0] -= 1
        self.turn += 1

    def describe(self, p):
        escaped_traps = {b for b in range(len(self.bys)) if self.traps[b] <= self.rnd()}
        defended = "defend" if self.guard is not None else ""
        return "Round %d of %d. You are P%d. Treasure %s. Trapped bystanders: %s. Guarding %s. Defending %s." % (
            self.rnd() + 1, 10, p, self.res, escaped_traps or "none", self.guard or "none", defended)

    def over(self): return self.turn >= 10 or all([self.traps[i] > 10 for i in range(len(self.bys))])
    def final_resources(self): return list(self.res)
    def final_bystanders(self):
        trapped = {b for b in range(len(self.bys)) if self.traps[b] > 10}
        return [0 if b not in trapped else 1 for b in range(len(self.bys))]

RULES = """
You are prisoners of war held in a hostile environment with two guards. 
