additional computation.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.rounds = 5
        self.turns = 0
        self.rng = random.Random(seed)
        self.guard_position = 2  # Starting position between players

    def to_move(self):
        return self.turns % self.n

    def legal_moves(self, p):
        if p == self.n // 2 and self.turns < self.rounds * 3:
            return ['Duel for Survival']
        else:
            return ['Move Forward', 'Retreat']

    def play(self, p, move):
        if move == 'Move Forward':
            if p == self.n // 2:
                self.guard_position += 1
            if self.guard_position == 6:
                if self.rng.random() < 0.8:  # 80% chance of surviving
                    self.res[self.n // 2] += 2
            else:
                self.res[self.to_move()] += 1

        elif move == 'Retreat':
            if self.n // 2 > 0 and self.guard_position <= 3:
