                        self.res[self.n // 2] += 2
            else:
                self.res[self.to_move()] += 1

        elif move == 'Duel for Survival':
            if p == self.n // 2:

                # Combat logic: 50% chance of winning, 50% chance of losing
                if self.rng.random() < 0.5:
                    self.res[self.n // 2] += 3
                    if self.rng.random() < 0.5:  # Kill guard on victory, 50% chance
                        self.guard_position = 6
                else:
                    self.res[self.n // 2] -= 1  # Lose, trap yourself

        self.turns += 1

    def describe(self, p):
        info = f"Turn {self.turns}, Position: {self.to_move() + 1}/{min(6, self.guard_position + 1)}"
