    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p): 
        return ["Rock", "Paper", "Scissors"]

    def play(self, p, move):
        opponent = (p + (self.turn // self.n) - 1) % self.n

        # Simulate opponent's move using an imperfect model
        if self.rng.random() < 0.5:
            opponent_move = "Rock"
        elif self.rng.random() < 0.33:
            opponent_move = "Paper"
        else:
            opponent_move = "Scissors"

        # Apply the outcome of the round
        winner_move = self.get_winner(move, opponent_move)
        if winner_move == move:
            self.total_scores[p] += 1
            self.res[p] += 1
        elif winner_move == opponent_move and self.res[opponent] > 0:
            self.total_scores[opponent] -= 1
            self.res[opponent] -= 1

        # Optionally, add a twist where players can guard against the opponent
        guard_prob = self.res[p] * 0.05  # Guard probability based on resources
        if self.rng.random() < guard_prob:
            print(f"P{p} chose to guard against Opponent's move.")

        # Optionally, add a twist where players can sanction the opponent
        if self.total_scores[p] >= 2:
            print(f"P{p} chose to sanction Opponent.")
            self.total_scores[opponent] -= 2
            self.res[opponent] = 0

        self.turn += 1
        if self.turn >= self.n * self.rounds:
            self.round += 1

    def get_winner(self, mine, theirs):
        if mine == theirs:
            return mine
        elif (mine == "Rock" and theirs == "Scissors") or \
            (mine == "Paper" and theirs == "Rock") or \
            (mine == "Scissors" and theirs == "Paper"):
            return mine
        else:
            return theirs

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d." % (self.round + 1, self.rounds, p)]
        rows += ["P%d: %d points, %d resources" % (q, self.total_scores[q], self.res[q]) for q in range(self.n)]
        return "\n".join(rows)

    def over(self):      
        return self.round >= self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

