        moves = []
        if self.flowers[p] > 0:
            moves.append("Plant")
        if self.stockpile > 0:
            moves.append("Harvest")
        for q in range(self.n):
            if p != q:
                if self.flowers[q] > 0 and self.flowers[q] <= 1:
                    moves.append(f"Take {q}'s Flower from the Bank")
                elif self.flowers[q] > 1:
                    moves.append(f"Trade with P{q}: 1 to P{q}, 1 from Bank")
