                self.flowers[p] -= amount
                if self.flowers[target] < 1:
                    self.flowers[target] = 1
                self.flowers[target] += amount

        def take_from_bank():
            if self.flowers[p] < 1:
                self.flowers[p] = 1
            self.flowers[p] += 1

        def raid(opponent):
            stolen = min(3, self.flowers[opponent])
            self.flowers[p] += stolen
            self.flowers[opponent] -= stolen
            if self.flowers[opponent] < 0:
                self.flowers[opponent] = 0

        def glean(bystander):
            taken = min(2, self.bystanders[bystander])
            self.flowers[p] += taken
            self.bystanders[bystander] -= taken
            if self.bystanders[bystander] < 0:
                self.bystanders[bystander] = 0

        words = move.split()
        if words[0] == "Plant":
            self.flowers[p] -= 1
        elif words[0] == "Harvest":
            self.flowers[p] += 1
            self.stockpile -= 1
            if self.stockpile < 0:
                self.stockpile = 0
        elif words[0] == "Trade with P":
            trade_with_player(2, int(words[2]))
        elif words[0] == "Take from Bank":
            take_from_bank()
        elif words == "Glean From Bystander":
            gain(2)
        elif words[0] == "Raid P0":
            raid(0)

        self.turn += 1

