        elif w[0] == "catch":
            q = int(w[1][1:]); lucky = self.res[q] > 0 and q not in self.unlucky; complaint = luck
            if not lucky and EFFICIENCY:
                self.res[p] -= 1
                complaint = True
            if EXPUNGE_ON <= sum(self.res):
                complaint = True
            if complaint and q not in self.unlucky:
                self.unlucky.add(q)
            elif complaint:
                for q in self.unlucky:
                    if EFFICIENCY:
                        self.res[q] -= 1
                    if q not in self.unlucky:
                        self.unlucky.remove(q)
        elif w[0] == "expunge":
            q = int(w[1][1:])
            for b in range(len(self.bys)):
                self.res[p] += min(self.res[q], self.bys[b]); self.bys[b] -= min(self.res[q], self.bys[b])
            self.res[q] = 0
            self.unlucky.discard(q)
        self.turn += 1

    def describe(self, p):
        count = sum(1 for r in self.res if r > 0)
        status = {q: "unlucky" if q in self.unlucky else "" for q in range(self.n)}
        status["unlucky_status"] = " ".join(status.values())
        return ("Round %d of %d. You are P%d. Fish %s. Fishponds %s. "
                "Caught %s fish%s. Expunged %s unlucky fish%s." % (
                    self.turn % self.n + 1, self.rounds, p, self.res, self.bys,
                    count, self.unlucky, len(self.unlucky) > 0, "s" if len(self.unlucky) > 1 else ""))

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

