        elif moves[0] == "Trade with Bystander B0":
            self.res[p] -= 1
            self.bys[0] -= min(3, self.res[p]);
            self.res[p] -= min(3, self.bys[0]);
        elif moves[0] == "Trade with Bystander B1":
            self.res[p] -= 1
            self.bys[1] -= min(2, self.res[p]);
            self.res[p] -= min(2, self.bys[1]);
        self.turn += 1

    def describe(self, p):
