RULES = """
Prisoner's Dilemma. 6 players, 9 rounds, one action each round. Each player's goal is to maximize their own reward while minimizing the
reward of another player.
- cooperate: give up resources to player P0 and receive a small reward 1.
- defect (cooperate 0): do nothing and receive no reward.
- cheat (give up 3): take all of player P2's resources and give up all of yourself, receiving zero for yourself.

Resources start at 3 each. Players cannot have more than 5 resources at the beginning or end of the game.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 9

