        moves = ["cooperate", "defect", "cheat"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "cooperate":
            other = self.n // 2; res_other = self.resources[other]
            gained = min(res_other, 1); self.resources[other] -= gained; self.resources[p] -= gained
            self.resources[p] += 1
        elif w[0] == "defect":
            pass
        elif w[0] == "cheat":
            defector = (self.to_move() + 1) % self.n
            my_res = self.resources[self.to_move()]
            defector_res = self.resources[defector]
            if defector_res > 1:
                self.resources[self.to_move()] -= my_res - 1
                self.resources[defector] = 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources %s." % (
            self.turn // self.n + 1, self.rounds, p, self.resources)

