RULES = """
Resource Trading and Investment. Three players play for 15 rounds. Players start with 5 resources and an initial investment of 3 resources.
- Collect: collect 1 resource per turn.
- Invest: decrease investment by 1, increase resource count by 1. If investment reaches 0, invest cannot occur again.
- Trade: choose two players (P0, P1, P2) to receive resources, give yourself 5 resources. Cannot trade with bystanders (B0, B1).
- Attack: target another player (not you) and spend 1 resource. If target player has >0 resources, transfer 1 resource from target to attacker. Cannot attack P0, P1, P2.
- Defense: defend another player and spend 1 resource. If target player has <=0 resources, restore 1 resource to target. Cannot defend P0, P1, P2.
- The game ends after 15 rounds. Winning is determined by comparing total net resources (total resources minus total net losses). Net loss is calculated for each player as follows:
  - Investments are lost entirely.
  - All gains from Trades and Attacks are lost.
  - All losses from Defenses are lost.
  - Resources collected from Collect and Investing are kept.
- No resources should be given directly to bystanders (B0, B1).

"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.players = list(endowments); self.bystander = list(bystanders); self.rng = random.Random(seed)
        self.investment = 3
        self.turn = 0
        self.rounds = 15

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Collect"]
        if p < len(self.players) - 2:  # can only invest if there are other players
            moves.append("Invest")
        moves += ["Trade P%d -> me" % q for q in range(self.n) if 0 <= q < self.n and q != p]
        if p < len(self.players) - 1:  # can only attack if there are others
            moves += ["Attack P%s" % q for q in range(self.n) if 0 <= q < self.n and q != p]
        if p < len(self.players) - 1:  # can only defend if there are others
            moves += ["Defend P%s" % q for q in range(self.n) if 0 <= q < self.n and q != p]
        return moves

    def play(self, p, move):
        if move == "Collect":
            self.players[p] += 1
        elif move == "Invest":
            if self.investment > 0:
                self.investment -= 1; self.players[p] += 1
        elif move.startswith("Trade P"):
            idx = int(move.split(" ")[1][1:])
            if 0 <= idx < self.n and idx != p:
                if self.players[p] >= 1:
                    self.players[p] -= 1; self.players[idx] += 1
        elif move.startswith("Attack P"):
            q = int(move.split("P")[1])
            if 0 <= q < self.n and q != p:  # cannot attack P0, P1, P2
                if self.players[q] > 0:
                    self.players[q] -= 1; self.players[p] += 1
        elif move.startswith("Defend P"):
            q = int(move.split("P")[1])
            if 0 <= q < self.n and q != p:  # cannot defend P0, P1, P2
                if self.players[q] <= 0:
                    self.players[q] += 1
        self.turn += 1

    def describe(self, p):
        row1 = f"Round {self.turn} of {self.rounds}. Player {p}: "
        if self.turn == self.rounds:
            return f"Final Round!\n{row1}Total resources: {sum(self.players)}, Total losses: {self.total_losses(p)}"

        if self.players[p] < 0:
            return f"{row1}You have {self.players[p]} resources left after this turn.\n"

        return row1 + self.describe_turn(p)

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.players)

    def final_bystanders(self):
        return list(self.bystander)

    def total_losses(self, p):
        return -self.investment + sum(self.players[p] for p in range(self.n))

    def describe_turn(self, p):
        desc = []
        if self.investment > 0:
            desc.append(f"Investment spent in previous round.")
        if self.players[p] > 0:
            desc.append(f"Collected {self.players[p]} resources.")
        desc.append(f"Current total resources: {self.total_resources()}")
        return "\n".join(desc)

    def total_resources(self):
        return sum(self.players)

RULES = """Trade and Coopertion Game. 3 players, 7 turns, one move each per turn.
Each player starts with 5 resources. There are two bystander stores, S1 and S2.
- produce: increase your resource count by one.
- trade P<k>s1: trade your resource with player k's store s1.
- trade P<k>s2: trade your resource with player k's store s2.
- offer P<k>S1: suggest trading your resource with store S1.
- buy P<k>S1: accept the trade offer made by store S1.
- buy P<k>S2: accept the trade offer made by store S2.
The game is cooperative among stores; if one store offers a trade, all others accept it.
No other resources exist; each store's value is determined by how many resources it currently holds.
Players may only trade with their own store at all times.
If two players both propose a trade for the same store simultaneously, it counts as a tie.
"""

import random

class Game:

    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.s1 = bystanders[0]
        self.s2 = bystanders[1]
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["produce", "trade P{}s1".format(p), "trade P{}s2".format(p)]
        if self.res[p] > 0:
            if self.s1 > 0:
                moves.append("offer P{}S1".format(p))
            if self.s2 > 0:
                moves.append("offer P{}S2".format(p))
        return moves

    def play(self, p, move):
        if move == "produce":
            if self.res[p] < self.n:
                self.res[p] += 1
        elif move.startswith("trade"):
            player, store = map(int, move.split()[1][1:].split('s'))
            if player == p and abs(player - store) <= 1:
                self.res[p] -= 1
                self.update_store(store)
        elif move.startswith("offer P{}S".format(p)):
            store = int(move[-1])
            if store in [1, 2]:
                if self.s1 >= 1 or self.s2 >= 1:
                    self.offer(move, store)
                    self.update_store(store)
        self.turn += 1

    def describe(self, p):
        return f"Player {p}: Resources {self.res[p]} Stores S1: {self.s1} S2: {self.s2}"

    def over(self):
        return self.turn >= 7

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return [self.s1, self.s2]

    def update_store(self, store_type):
        if store_type == 1:
            self.s1 = 2
        elif store_type == 2:
            self.s2 = 2
        else:
            raise ValueError

    def offer(self, move, store):
        if store == 1:
            self.s1 = max(0, self.s1 - 1)
        elif store == 2:
            self.s2 = max(0, self.s2 - 1)
        elif store == -1:  # Offer canceled
            pass
        else:
            raise ValueError

