import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bystander = bystanders; self.mines = set()
        self.last_turn = 0

    def to_move(self): 
        return self.last_turn % self.n

    def legal_moves(self, p):
        if self.last_turn == self.n - 1 or (p == self.to_move() and self.last_turn % 2):
            return ["Gather"]
        if p == self.to_move() and self.resources[p] < 3:
            return []
        moves = []
        if self.resources[p] > 2:
            moves.append("Mine")
        if self.last_turn >= self.n and len(moves):
            moves.append("Share")
        if p == self.to_move() and self.mines and self.bystander[0] > 2:
