            self.bystander[0] -= t
            self.resources[self.to_move()] += t
        elif move == "Defend":
            if p == self.to_move():
                self.resources[p] -= 1
        elif move == "Block B1":
            if self.bystander[1] > 2:
                self.bystander[0] -= 1
                self.bystander[1] += 1
        self.last_turn += 1

    def describe(self, p):
