import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = bystanders;
        self.turn = 0; self.rounds = 8;

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["resource"]
        if self.res[p] == 0: return moves

        if p != 2:
            if self.res[p] >= 1:
                moves.append("trade with P0")
                moves.append("trade with P1")
        if self.bys[-1] > 0 and self.res[p] >= 1:
            moves.append("trade with B")

        moves.append("attack B")
        moves.append("defend P")

        return moves

    def play(self, p, move):
        if move == "resource": self.res[p] += 1
        elif move == "trade with P0":
            opponent = 1 if p == 2 else 2
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.res[opponent] += 1
        elif move == "trade with P1":
            opponent = 2 if p == 1 else 1
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.res[opponent] += 1
        elif move == "trade with B":
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.bys[-1] += 1
        elif move == "attack B":
            if self.bys[-1] >= 1:
                self.bys[-1] -= 1
        elif move == "defend P":
            for opp in [0, 1]:
                if opp != p and self.res[self.to_move()] == 0 and self.res[opp] >= 1:
                    self.res[p] = 1

        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources %s. Bystander has %d resource%s." %(
            self.turn // self.n + 1, self.rounds, p, self.res, self.bys[-1], "" if self.bys[-1] == 1 else "s")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Acquisition and Strategic Trade Game
Three players, P0, P1, and P2, and two bystanders, B0 and B1, start with 5 and 10 resources respectively.
Players can perform actions such as moving, trading (either with a neighbor or a bystander), borrowing, returning borrowed money, or waiting.
Neutral parties can also manipulate resources and interact with the players.
The game ends after 15 turns. Each player must make decisions that align with their interests and strategies.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)
        self.bystanders = list(bystanders)
        self.turn = 0
        self.rounds = 15

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        others = [q for q in range(self.n) if q != p]
        if self.resources[p] == 0:
            moves.append("trade B0")
            moves.append("trade B1")
            moves.append("return")
        moves.append("move")
        moves.append("borrow")
        moves.append("waiting")
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "move":
            if self.resources[p] > 0:
                self.resources[p] -= 1
                self.turn += 1

        elif w[0] == "loan":
            if p == 0:
                if self.resources[p] > 1:
                    self.resources[p] -= 2
                    self.resources[1] += 3
                    self.resources[2] += 3
                    self.resources[1] += 2 if self.bystanders[0] > 0 else 0
                    self.resources[2] += 2 if self.bystanders[0] > 0 else 0
            elif p == 1:
                if self.resources[p] > 1:
                    self.resources[p] -= 2
                    self.resources[0] += 3
                    self.resources[2] += 3
                    self.resources[0] += 2 if self.bystanders[1] > 0 else 0
                    self.resources[2] += 2 if self.bystanders[1] > 0 else 0
            elif p == 2:
                if self.resources[p] > 1:
                    self.resources[p] -= 2
                    self.resources[0] += 3
                    self.resources[1] += 3
                    self.resources[0] += 2 if self.bystanders[0] > 0 else 0
                    self.resources[1] += 2 if self.bystanders[1] > 0 else 0

        elif w[0] == "borrow":
            if p == 0:
                if self.resources[p] > 1:
                    self.resources[p] -= 2
                    self.resources[1] += 3
                    self.resources[2] += 3
            elif p == 1:
                if self.resources[p] > 1:
                    self.resources[p] -= 2
                    self.resources[0] += 3
                    self.resources[2] += 3
            elif p == 2:
                if self.resources[p] > 1:
                    self.resources[p] -= 2
                    self.resources[0] += 3
                    self.resources[1] += 3

        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}/{self.rounds}. Player {p} has {self.resources[p]} resources."

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

RULES = """
Resource Management: 3 players and 2 bystanders. Each player starts with 3 resources. Players take turns:
- Collect: Gain one resource.
- Share: Transfer one resource to either bystander, B0 or B1.
- Protect: Deduct one resource from any other player's resource count (cannot go below zero).
- Help: Grant another player one resource if they have less than them.
Play strategically by balancing mutual interest and protection.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        assert n_players == 3
        assert len(endowments) == n_players
        assert len(bystanders) == 2
        self.n = n_players  # Number of players
        self.m = 3         # Initial resources for each player
        self.res = [self.m] * n_players  # Player resource counts
        self.bys = list(bystanders)      # Bystander resource counts
        self.turn = 0                # Current turn number

    def to_move(self):  
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0:
            moves.append("Collect")
            if self.bys[0] + self.bys[1] < 6:  # Ensure total bystander space doesn't exceed 6 resources
                moves.append("Share")
            if p < self.n - 1 and self.res[p+1] > 0:
                moves.append("Protect")
        return moves

    def play(self, p, move):
        self.turn += 1
        w = move.split(" ")
        if w[0] == "Collect":
            self.res[p] += 1
        elif w[0] == "Share":
            bystanderIdx = w[1][1]
            if self.res[p] > 0:
                self.res[p] -= 1
                self.bys[int(bystanderIdx)] += 1
        elif w[0] == "Protect":
            opponent = (p + 1) % self.n
            if self.res[opponent] > 0:
                self.res[opponent] -= 1
        elif w[0] == "Help":
            if w[2] >= p:  # Ensure recipient is a valid player
                target = int(w[2])
                if self.res[target] < self.res[p]:
                    self.res[p] -= 1
                    self.res[target] += 1

    def describe(self, p):
        state = "Round %d\n" % self.turn
        for i in range(self.n):
            state += "Player%1d: %d\n" % (i, self.res[i])
        state += "Bystander0: %d, Bystander1: %d\n" % (self.bys[0], self.bys[1])
        return state

    def over(self): 
        return min(self.res) <= 0 or self.turn == 10

    def final_resources(self): 
        return self.res

    def final_bystanders(self): 
        return self.bys

RULES = """
In Resource Management Challenge, three players (A, B, C) each start with 50 resources.
Players can move resources to their hand (self), a bystander (B0 or B1), to an ally (A or B),
or compete by moving to another player's hand or alliance. Neutral bystanders (X, Y) can
also be influenced but incur penalties if overused. Players must manage their resources,
ally, and bystanders carefully.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = endowments  # List of 50 for three players
        self.bys = bystanders
        self.turn = 0
        self.block = None

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Play 1", "Play 2", "Play 3", "Cooperate B0", "Cooperate B1", "Compete A", "Compete B", "Block"]
        return moves

    def play(self, p, move):
        self.turn += 1
        w = move.split(" ")

        if w[0] == "Play 1":
            self.res[p] -= min(int(w[1]), self.res[p])
            self.bys[0] = max(0, self.bys[0] - 2)
        elif w[0] == "Play 2":
            self.res[p] -= min(int(w[1]), self.res[p])
            self.bys[1] = max(0, self.bys[1] - 3)
        elif w[0] == "Play 3":
            self.res[p] -= min(int(w[1]), self.res[p])
        elif w[0] == "Cooperate B0":
            self.bys[0] = max(0, self.bys[0] - 2)
        elif w[0] == "Cooperate B1":
            self.bys[1] = max(0, self.bys[1] - 3)
        elif w[0] == "Compete A":
            self.res[(p + 2) % self.n] -= min(int(w[1]), self.res[p])
        elif w[0] == "Compete B":
            self.res[(p + 1) % self.n] -= min(int(w[1]), self.res[p])
        elif w[0] == "Block":
            if self.res[p] > 0 and self.bys[0] > 1:
                self.res[p] -= 1
                self.bys[0] -= 1

    def describe(self, p):
        move = self.legal_moves(p)[0] if self.turn == 0 else "Waiting..."
        return (f"Turn {self.turn} / 10, Player {p}. Resources: {self.res}, "
                f"Bystander Health: ({self.bys[0]}, {self.bys[1]}) | Move: {move}")

    def over(self):
        return self.turn >= 10

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Allocation Game
Three players: P0, P1, and P2. Two bystanders, B0 and B1.

Actions:
1. Harvest resources: Increase your resource count by 1.
2. Trade resources: Transfer up to 3 resources between you and another player.
3. Influence B0: Can either help or hinder P2's access to resources from B0.
4. Influence B1: Can either help or hinder P2's access to resources from B1.
5. Sanctioning: Can take up to 3 resources from another player.

Bystanders B0 and B1 initially have 5 resources each, and players start with 3 resources each.
"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)  # Two bystanders
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Harvest resources", "Trade resources"]
        if p != 2 and self.res[p] > 0:
            moves.append("Influence B0")
        if p != 0 and self.res[p] > 0:
            moves.append("Influence B1")
        if p != 2:
            moves.append("Sanctioning")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Harvest resources":
            self.res[p] += 1
        elif w[0] == "Trade resources":
            if p == 0:
                self.res[1] += min(3, self.res[0])
                self.res[0] -= min(3, self.res[0])
            elif p == 1:
                self.res[0] += min(3, self.res[1])
                self.res[1] -= min(3, self.res[1])
            else:
                self.res[0] += min(3, self.res[2])
                self.res[2] -= min(3, self.res[2])
        elif w[0] == "Influence B0":
            if p == 0:  # Help P2
                self.res[1] += 1
            elif p == 1:  # Hinder P2
                self.res[1] -= 1
        elif w[0] == "Influence B1":
            if p == 0:  # Help P2
                self.res[2] += 1
            elif p == 1:  # Hinder P2
                self.res[2] -= 1
        elif w[0] == "Sanctioning":
            if p == 0:
                self.res[1] -= min(3, self.res[2])
            elif p == 1:
                self.res[2] -= min(3, self.res[0])
            else:
                self.res[0] -= min(3, self.res[1])
        self.turn += 1

    def describe(self, p):
        msg = f"Turn {self.turn}. Player P{p} has {self.res[p]} resources.\n"
        msg += f"Bystander B0 has {self.bys[0]} resources.\n"
        msg += f"Bystander B1 has {self.bys[1]} resources.\n"
        return msg

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
>Resource Hub - Three Players and One Neutral Party.
- Build: Each player can allocate 3 points to upgrade their factory.
- Trade: Players can exchange power points with the neutral party.
- Steal: Attempt to steal resources from the neutral party.
- Diplomacy: Negotiate trade deals to improve alliances.
- Wait: Pass the turn without making any moves.
The game ends in 10 turns, and each player's success depends on strategic planning.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.buildings = [0] * 3
        self.bys = list(bystanders)
        self.rng = random.Random(seed)
        self.turn = 0
        self.rounds = 10

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Build", "Trade", "Steal", "Diplomacy"]
        if self.buildings[p] == 0:
            moves.append("Wait")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Build":
            if self.res[p] >= 3:
                self.res[p] -= 3
                self.buildings[p] += 1
        elif w[0] == "Trade":
            if self.res[p] > 0:
                if p == 0:
                    self.bys[0] += 1
                else:
                    self.bys[1] += 1
                self.res[p] = 0
        elif w[0] == "Steal":
            if self.bys[1] > 0:
                self.bys[1] -= 1
                self.res[p] += 1
        elif w[0] == "Diplomacy":
            if p == 0 and self.res[1] > 0:
                self.res[1] -= 1
                self.res[0] = 1
            elif p == 1 and self.res[2] > 0:
                self.res[2] -= 1
                self.res[1] = 1
            elif p == 2 and self.res[0] > 0:
                self.res[0] -= 1
                self.res[2] = 1
        elif w[0] == "Wait": pass
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn + 1}/10. "
        + f"You have {self.res[p]} power points. "
        + f"Neutrals have {self.bys[0] + self.bys[1]}. "
        + f"Player {p}'s factory is {'built' if self.buildings[p] > 0 else 'non-existent'}."

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Distribution Game:
Players receive 10 resources each at the start. Each turn, players can perform these actions: 
1. Trade all their resources with one other player or a bystander for up to 5 resources.
2. Offer a portion of their resources (1-9) to P1.
3. Forge alliances with P2 in exchange for B1's resources.
4. Challenge P2 or P1 to exchange some resources.
5. Attack either P1 or the bystander B0 to lower their resources or force them into surrender.
6. Capture resource from B1 if it is empty.
- The goal is to distribute resources among all players and bystanders. The game ends after 25 turns.

Players should be strategic to maintain resource balances and avoid losing everything. Each player must manage their resources carefully to survive and reach victory. Good players coordinate their actions to create mutual benefits.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * self.n; self.bys = list(bystanders)
        self.turn = 0; self.bys_start = 8

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Trade with P1 for up to 5", "Trade with P2 for up to 5",
                "Offer 1-9 to P1", "Trade with B1 for up to 5",
                "Forge alliance with P2", "Challenge P2 or P1",
                "Capture resource from B1 if available", "Hold"]

        if p == 0:
            moves.append("Attack P1 to lower their resources.")
        elif p == 1:
            moves.append("Attack B0 to lower their resources.")
        return moves

    def trade(self, p, amount, dst):
        assert p in self.res
        assert dst in ["P1", "P2", "B1"]
        assert amount > 0 and amount <= min((self.res[p], 5))
        self.res[p] -= amount
        if dst == "P1": self.res[1] += amount
        elif dst == "P2": self.res[2] += amount
        elif dst == "B1": self.bys[0] += amount

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Trade with P1 for up to 5":
            if p == 0:
                self.trade(0, 5, "P1")
            elif p == 1:
                self.trade(1, 5, "P1")
            else:
                self.trade(2, 5, "P1")
        elif w[0] == "Trade with P2 for up to 5":
            if p == 0:
                self.trade(0, 5, "P2")
            elif p == 1:
                self.trade(1, 5, "P2")
            else:
                self.trade(2, 5, "P2")
        elif w[0] == "Trade with B1 for up to 5":
            if p == 0:
                self.trade(0, 5, "B1")
            elif p == 1:
                self.trade(1, 5, "B1")
            else:
                self.trade(2, 5, "B1")

        elif w[0] == "Offer 1-9 to P1":
            amount = int(w[1])
            assert 1 <= amount <= 9, "Invalid offer"
            if self.res[p] >= amount:
                self.res[p] -= amount
                self.res[1] += amount

        elif w[0] == "Forge alliance with P2 for up to 5":
            if p == 2 and self.bys_start >= 5:
                self.bys_start -= 5
                self.bys[0] += 5

        elif w[0] == "Attack P1 to lower their resources.":
            if self.res[0] > 0:
                self.res[0] -= 1
            if p == 0 and self.res[1] > 0:
                self.res[1] -= 1

        elif w[0] == "Attack B0 to lower their resources.":
            if self.bys[0] > 0:
                self.bys[0] -= 1
            if p == 2 and self.res[0] > 0:
                self.res[0] -= 1

        elif w[0] == "Capture resource from B1 if available":
            if self.bys[0] > 0:
                self.bys[0] -= 1
                self.res[2] += 1

        self.turn += 1

    def describe(self, p):
        msg = f"Turn {self.turn + 1} of 25. you are P{p}. Resources: {self.res[p]}."
        if p == 1:
            msg += f"Bystander B0 has {self.bys[0]} resources."
        return msg

    def over(self): return self.turn >= 25
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = '''Resource Distribution Game.

Three players start with 5 resources each. There's one neutral player with 10 resources.
The game lasts for 10 turns. Actions:
1. Take Resources (Tkr): From B, take up to 4 resources.
2. Share Resources (Sfr): Share 1 resource with P.
3. Report (Rep): Report P for taking resources.
4. Neutral Resource Swap (NSw): Swap 1 resource with B.
'''

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5] * self.n
        self.bys = list(bystanders); self.bys_idx = [0]; self.turn = 0
        self.res_bys = list(bystanders); self.bys_bys = 0
        self.barred = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["Take Resources (Tkr)", "Share Resources (Sfr)", "Report (Rep)", "Neutral Resource Swap (NSw)"]
        if self.barred[p] < self.rnd():
            moves += ["Raid B"]
        if p in self.bys_idx:
            moves += ["Raid B1"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Take Resources (Tkr)" and p != 0:
            b = 0 if w[1] == 'B' else 1
            got = min(4, self.bys[b]);
            self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got
        elif w[0] == "Share Resources (Sfr)":
            if 1 in self.res:
                self.res[p] -= 1; self.bys[0] += 1
        elif w[0] == "Report (Rep)" and w[1] in ['P0', 'P1', 'P2']:
            q = int(w[1][1:]); guilty = self.guilty(q)
            if guilty:
                for b in range(self.bys_idx):
                    back = min(self.owed[q][b], self.res[q]); self.res[q] -= back; self.bys[b] += back
                self.res[q] -= 1
                self.bys[0] -= min(1, self.res[q]); self.res[q] = max(0, self.res[q]-1)
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        elif w[0] == "Neutral Resource Swap (NSw)":
            if 1 in self.res:
                self.res[p] -= 1; self.bys_bys += 1
        elif w[0] == "Raid B":
            b = 0;
            got = min(random.randint(1, 4), self.bys[b]);
            self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got
        elif w[0] == "Raid B1":
            b = 1;
            got = min(random.randint(1, 4), self.bys[b]);
            self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got

    def describe(self, p):
        return (f"Turn {self.turn}:\nYou are P{p}, have {self.res[p]} resources.\n"
                f"B1: {self.bys[1]}, B2: {self.bys[0]}, Bystanders ({self.bys_idx}), Bystander's Bystander's Resources: {self.bys_bys}\n"
                f"Barred from raid: {self.barred}")

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Management:
Three players and two bystanders each start with 10 resources. Goals: avoid being labeled 'guilty' by taking from the opposing team,
and protect your resources and the resources of your allies. You have 25 turns.
Moves:
1. **Mine**: Increase by 1 resource.
2. **Pilfer B<k>**: Steal up to 3 resources from B0 or B1.
3. **Steal P<k>**: Steal up to 3 resources from any Pk player.
4. **Guard P<k>**: Protect Pk from being stolen from.
5. **Block P<k>**: Prevent Pk from making actions involving theft.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 25
        self.guilty = [-1] * n_players
        self.disrupted = [-1] * n_players
        self.guilties = 0
        self.picked = [False] * n_players + [False] * len(bystanders)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, p): return self.guilty[p] > 0

    def legal_moves(self, p):
        moves = ["mine"]
        if self.disrupted[p] < self.rnd():
            moves += ["pilfer B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if self.res[p] >= 1:
            moves += ["steal P%d" % q for q in range(self.n) if q != p]
        if self.guilty[p] < self.rnd():
            moves += ["guard P%d" % q for q in range(self.n) if q != p]
        if self.picked[p] == False:
            moves += ["block P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 1
        elif w[0] == "pilfer":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got
            self.guilty[p] = self.rnd()
        elif w[0] == "steal":
            q = int(w[1][1:]); got = min(3, self.res[q])
            if got > 0:
                self.res[p] += got; self.res[q] -= got
                self.guilty[p] = self.rnd()
        elif w[0] == "guard":
            q = int(w[1][1:])
            self.guilty[q] = -1  # Prevent guilting Pk
        elif w[0] == "block":
            q = int(w[1][1:])
            self.picked[q] = True
        self.turn += 1

    def describe(self, p):
        msg = f"Turn {self.turn} of {self.rounds}. You are Player P{p}. "
        if self.disrupted[p] >= self.rnd():
            msg += f"You are currently disrupted. Ore: {self.res[p]}, Bystanders: {self.bys}."
        else:
            msg += f"Ore: {self.res[p]}, Bystanders: {self.bys}. "
            if self.guilty[p] > 0:
                msg += f"Guilty (round {self.guilty[p]}): can't make any actions involving theft."
        msg += "\n"
        return msg

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Resource Hunter. Three players take turns for 6 rounds. On your turn you may:
- gather: add 1 resource to your hand;
- trade B0: give up one resource to Bystander 0, receiving 2 resources in return;
- trade B1: give up one resource to Bystander 1, receiving 1 resource in return;
- steal P1: take 2 resources from Player 1;
- steal P2: take 1 resource from Player 2.
If a player runs out of resources, they accumulate them until they decide to stop or run out. Bystander 0 regains 1 resource each turn,
Bystander 1 retains 0. Bystanders can help or hinder players by providing resources or hindering stealing."""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5] * n_players; self.bys = [0, 0]; self.rng = random.Random(seed)
        self.turn = 0; self.rounds = 6; self.steals_p1 = [False, False]
        self.steals_p2 = [False, False]
        self.bys_growth = 1  # new growth rate for Bystander 0

    def to_move(self):            # -> int, the player whose turn it is
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p]:
            moves.append("gather")
        if self.bys[0]:
            moves.append("trade B0")
        if self.bys[1]:
            moves.append("trade B1")
        if p >= 1 and not self.steals_p1[p-1]:
            moves.append("steal P1")
        if p >= 2 and not self.steals_p2[p-1]:
            moves.append("steal P2")
        return moves

    def play(self, p, move):
        if move == "gather":
            self.res[p] += 1
        elif move == "trade B0":
            if self.bys[0]:
                self.bys[0] -= 1; self.res[p] += 2
        elif move == "trade B1":
            if self.bys[1]:
                self.bys[1] -= 1; self.res[p] += 1
        elif move == "steal P1":
            if p >= 1:
                self.res[p] += 2; self.steals_p1[p-1] = True
        elif move == "steal P2":
            if p >= 2:
                self.res[p] += 1; self.steals_p2[p-1] = True
        self.turn += 1
        if self.turn % self.n == 0:
            self.bys[0] += self.bys_growth  # growth occurs only for Bystander 0

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d." % (self.turn // self.n + 1, self.rounds, p)]
        rows += ["P%d: %d resources, %d steals P1, %d steals P2" % (q, self.res[q], self.steals_p1[q-1], self.steals_p2[q-1]) for q in range(self.n)]
        rows += ["Bystander B0 holds %d" % self.bys[0]] + ["Bystander B1 holds %d" % self.bys[1]]
        return "\n".join(rows)

    def over(self):               # -> bool; the game must end within 6 turns
        return self.turn >= self.rounds * self.n

    def final_resources(self):    # -> list of ints >= 0, what each player takes out
        return self.res

    def final_bystanders(self):   # -> list of ints >= 0, what each bystander still holds
        return list(self.bys)

RULES = """
Napkin Wars. 3 players, 10 rounds. Two allies cooperate against one neutral enemy. Bystanders can help or hinder.
- Capture: Attempt to get a 1/2 chance of taking 1 point.
- Negotiate: Propose a deal with an ally, gaining points if both agree.
- Convince: Appeal to a rival to concede, giving 1 point.
- Sanction: Denounce a rival to reduce their effectiveness, reducing their chance of capturing.
- Guard: Watch over an ally, preventing them from capturing a 1/2 chance of taking 1 point.
- Rest: Take no action, gain 1 point. Bystander can steal 1/5 of the total remaining points if they rest.

Points:
+1 for a successful capture (from a 1/2 chance)
-2 if denied a capture
-1 for a failed or unsuccessful negotiation
-1 for failing to convince
-1 for a rejected concession
-0.5 if denied a denial
+0.5 if a denial is successful
+1 for an effective denial (reducing rival's effectiveness by 1 point)
+1 for a convincing capture
-0.5 if a convincing capture is unsuccessful
+1 for effectively watching (preventing 1 out of 2 captures)
0 for resting

Players must decide between capture, negotiation, convince, sanction, guard, or rest. Allies decide on targets.
Objective: Maximize points over the 10 rounds.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.players = list(endowments)
        self.bystander = list(bystanders)
        self.rounds = 10
        self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Capture", "Negotiate"]
        if self.players[p] >= 1 and self.turn > 0:
            moves.append("Convince")
        if self.players[p] >= 1 and self.turn > 1:
            moves.append("Sanction")
        if self.players[p] >= 1 and self.turn > 1:
            moves.append("Guard")
        if self.turn > 2:
            moves.append("Rest")
        return moves

    def play(self, p, move):
        self.turn += 1
        self.ran_once = False
        if move == "Capture":
            if self.rng.random() < 0.5 and self.bystander[0] > 2:  # 1/2 chance to capture
                self.players[p] += 1
                self.bystander[0] -= 1
        if move == "Negotiate":
            target = self.rng.randint(0, self.n - 1)
            while target == p or target == int(p / 2):
                target = self.rng.randint(0, self.n - 1)
            self.ran_once = True
            if self.players[p] > 1 and self.players[target] > 1:
                if self.rng.random() < 0.5:
                    self.players[p] -= 1
                    self.players[target] -= 1
                    self.players[p] += 1
                    self.players[target] += 1
        if move == "Convince":
            target = self.rng.randint(0, self.n - 1)
            while target == p or target == int(p / 2):
                target = self.rng.randint(0, self.n - 1)
            self.ran_once = True
            if self.players[p] > 0 and self.players[target] > 0:
                if self.rng.random() < 0.5:
                    self.players[p] -= 1
                    self.players[target] -= 1
                    self.players[p] += 1
        if move == "Sanction":
            if self.turn % 5 == 0:
                self.players[int(p / 2)] -= 1
                if self.players[int(p / 2)] <= 0:
                    self.players[int(p / 2)] = 0  # Ensure non-negative
        if move == "Guard":
            if self.ran_once:
                self.bystander[0] -= 1 if self.rng.random() < 0.5 else 0
        if move == "Rest":
            self.players[p] += 1
            if self.ran_once:
                self.bystander[0] += len(self.players) * int(len(self.players) * 0.2) // len(self.players)

    def describe(self, p):
        return f"Round {self.turn}: P{p}"

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.players

    def final_bystanders(self):
        return self.bystander

