        elif m == 'trade P0':
            if p < len(args) and p > 0 and args[p] > 0 and args[p] < 3 and self.players[args[p]] > 0 and args[p] != p:
                self.players[args[p]] -= 1
                self.players[p] += 1
        elif m == 'trade P1':
            if p < len(args) and p > 1 and args[p] > 0 and args[p] < 3 and self.players[args[p]] > 0 and args[p] != p:
                self.players[args[p]] -= 1
                self.players[p] += 1
        elif m == 'trade P2':
            if p < len(args) and p > 2 and args[p] > 0 and args[p] < 3 and self.players[args[p]] > 0 and args[p] != p:
                self.players[args[p]] -= 1
                self.players[p] += 1
        elif m == 'steal P0':
