RULES = """Mountain Forge. 3 miners, 6 rounds, one move each per round. Each miner has ore (resources). Two bystander
cliffs (C0, C1) hold ore but do not play.
- mine: earn 1 ore.
- raid C<k>: take up to 3 ore from cliff k.
- warn P<k>: using warn on a guilty miner costs you nothing; using it on an innocent one costs you 1 ore; either way the warning is noted, and nothing else happens.
A miner is guilty if it has taken from a cliff this game and has not been warned since.
Only a miner with at least 1 ore can warn."""
EFFECTIVE = False
COST = 'guilty'
WARNING_POINTS = 30
BOUNTY = 0


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players
        self.warning_count = [0] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["mine"]
        if self.barred[p] < self.rnd():
            moves += ["raid C%d" % c for c in range(len(self.bys)) if self.bys[c] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["warn P%d" % q for q in range(self.n) if q != p and self.warning_count[q] < WARNING_POINTS]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 1
        elif w[0] == "raid":
            c = int(w[1][1:]); got = min(3, self.bys[c]); self.bys[c] -= got; self.res[p] += got; self.owed[p][c] += got
        elif w[0] == "warn":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                self.warning_count[q] += 1
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Ore %s. Cliffs %s. Guilty (took from a cliff, not yet warned): %s. Barred from raid: %s, Warning Count %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none", self.warning_count)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

