import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players;self.resources = [endowments[0]] * n_players; self.bidder = 0
        self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["bid"]
        if p != self.bidder: moves += ["block", "pass"]
        return moves

    def play(self, p, move):
        if move == "bid":
            if len([r for r in self.resources if r > 0]) < self.n and self.to_move() != self.bidder:
                self.resources[self.to_move()] += 1
                self.bidder = self.p_to_move(self.to_move() + 1)
        elif move == "block":
            if self.to_move() != self.bidder and self.resources[self.to_move()] > 0:
                self.resources[self.to_move()] = 0
        elif move == "pass":
            self.bidder = self.p_to_move(self.to_move() + 1)
        self.turn += 1

    def p_to_move(self, player): return (player % self.n if player < self.n else (player - self.n + 1))

    def describe(self, p):
        return ("Round %d. Player P%d is bidding. Your resources: %d. " 
                 % (self.rounds - (self.turn + 1) // self.n, p + 1, self.resources[p]))

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.resources)
    def final_bystanders(self): return self.bys.copy()

