        if self.res[p] > 0:
            moves += ["trade B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
            moves += ["share P%d" % q for q in range(self.n) if q != p]
            moves += ["declare P%d" % q for q in range(self.n) if q != p]
