        if w[0] == "collect":
            got = min(5, self.bys[0]); self.bys[0] -= got; self.res[p] += got
        elif w[0] == "trade":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "share":
            others = [q for q in range(self.n) if q != p]
            q = int(w[1][1:])
            if self.share_cache[p][q] is None or self.share_cache[p][q].startswith("accept"):
                if self.res[p] >= 2:
