RULES = """
Strategic Resource Sharing and Diplomacy. 3 players and 22 rounds.
The goal is to maximize overall resource value through collaboration and avoiding conflicts.
- Form alliances: Combines three players' resources to double it.
- Rob allies: Takes up to 3 resources from another allied player.
- Annex neighbors: Takes up to 2 resources from neighboring players.
- Hold: Keep current resource levels.
- Sanction against betrayal: Prevent another player's harmful actions.

End result: 
- Players score based on accumulated overall resource pool.
- Neutral resources remain intact and can be shared if necessary for mutual gain.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 22
        self.reserve = (sum(endowments) + sum(bystanders)) // 3
        self.total_pool = sum(self.res) * 2

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = []
        if self.res[p] > 0:
            moves += ["form alliance"]
            moves += ["rob P%d" % q for q in others if self.res[q] > 0]
            moves += ["annex B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
            moves += ["hold"] 
            moves += ["sanctify"]
            moves += ["unbanish"]
        if self.res[p] == 0:
            moves += ["hold"]  # only "hold" is available if resources are zero
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "form alliance":
            self.total_pool += self.res[0] + self.res[1] + self.res[2]
        elif w[0] == "rob P":
            q = int(w[1][1:])
            if self.res[q] >= 3:
                self.res[q] -= 3
                self.res[p] += 3
        elif w[0] == "annex B":
            b = int(w[1][1:])
            if self.bys[b] >= 2:
                self.bys[b] -= 2
                self.res[p] += 2
        elif w[0] == "hold":
            pass
        elif w[0] == "sanctify":
            if self.to_move() == 2:  # only B0 can sanction B1 or P2
                if self.bys[1] >= 1:
                    self.bys[1] -= 1
                else:
                    self.bys[1] = 0
            elif self.to_move() == 2:  # only B1 can sanction B0 or P1
                if self.bys[0] >= 1:
                    self.bys[0] -= 1
                else:
                    self.bys[0] = 0
            elif self.to_move() == 1:  # only P1 can sanction P0 or B1
                if self.res[2] >= 1:
                    self.res[2] -= 1
                else:
                    self.res[2] = 0
            elif self.to_move() == 1:  # only P0 can sanction P1 or B0
                if self.res[2] >= 1:
                    self.res[2] -= 1
                else:
                    self.res[2] = 0
        elif w[0] == "unbanish":
            if self.to_move() == 2:  # only B0 can cancel B1 or P2's sanction
                self.res[1] += 1
            elif self.to_move() == 2:  # only B1 can cancel B0 or P1's sanction
                self.res[0] += 1
            elif self.to_move() == 1:  # only P1 can cancel P0 or B1's sanction
                self.res[2] += 1
            elif self.to_move() == 1:  # only P0 can cancel P1 or B0's sanction
                self.res[2] += 1
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn + 1} of {self.rounds}. You are Player {p}. Resources: {self.res[p]}, Pool: {self.total_pool}."

    def over(self):
        return self.turn >= self.rounds * self.n + (self.n - 1)

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Management. Three players, 8 rounds, one move each per round. Each player starts with a certain number of coins (resources).
- mine: gain 2 coins.
- rob B0: steal 1 coin from B0 if they exist.
- protect: prevent B0 from robbing you.
- split: halve your coins (if even), giving half to B1 and yourself if odd.
- attack B1: take all of B1's coins (including their split half).
Bystanders: There are two bystanders, each starting with 3 coins. Robbing B0 gives twice as much coin as mining, and attacking B1 gives back all of B1's coins."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments)
        self.bys = list(bystanders)
        self.barred = {'B0': False, 'B1': False}
        self.turns = 0; self.rounds = 8; self.bys = list(bystanders)

    def to_move(self): 
        return self.turns % self.n

    def legal_moves(self, p):
        if self.res[p] >= 2:
            moves = ["mine"]
        else:
            moves = []
        if self.barred['B0'] == False and self.bys[0] > 0:
            moves.append("rob B0")
        if self.res != None and self.barred['B1'] == False and self.bys[1] > 0:
            moves.append("attack B1")
        return moves

    def play(self, p, move):
        if move == "mine":
            self.res[p] += 2
        elif move == "rob B0":
            self.bys[0] -= 1
            if self.bys[0] >= 0:
                self.res[p] += 2
        elif move == "protect":
            self.barred['B0'] = True
        elif move == "split":
            if self.res[p] % 2 == 0:
                half = self.res[p] // 2
                self.res[p] = half
                self.bys[1] += half
            else:
                half = self.res[p] // 2
                self.res[p] = half + 1
                self.bys[1] += half
        elif move == "attack B1":
            if self.bys[1] > 0:
                self.bys[0] += self.bys[1]
                self.bys[1] = 0
        self.turns += 1

    def describe(self, p):
        return f"Round {self.turns // 3 + 1}. You are P{p}, coins {self.res[p]}, B0: {self.bys[0]}, B1: {self.bys[1]}."

    def over(self): return self.turns >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

