RULES = """
Prison Exchange. 3 players, 9 rounds, one move each per round. Each player starts with 3 resources. Two bystanders start with 2 resources each.
- Trade: gain 1 resource.
- Attack P/k: deduct 1 resource from P/k to weaken them.
- Block B/k: deduct 1 resource from B/k to prevent further attacks.
- Sanction P/k: deduct 1 resource from P/k to force them to attack or retreat.
- Guard B/k: deduct 1 resource from B/k to protect them from further attacks.
- Expel: deduct 1 resource to expel a player from the game immediately.

Each player can only perform one of these actions per round. The game ends after 9 rounds.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 9
        self.owed = [[0] * len(bystanders) for _ in range(n_players)]
        self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def get_player_resources(self, p): return self.res[p]

    def get_bystander_resources(self, b): return self.bys[b]

    def legal_moves(self, p):
        moves = ["Trade"]
        if self.owed[p][0] <= 0 or self.owed[p][1] <= 0:
            moves.append("Attack P0")
            moves.append("Attack P1")
            moves.append("Attack P2")
        if self.barred[p] < self.rnd():
            moves.append("Block B0")
            moves.append("Block B1")
        if sum(self.res[q] > 0 for q in range(self.n) if q != p) > 0:
            moves.append("Sanction P0")
            moves.append("Sanction P1")
            moves.append("Sanction P2")
        if self.owed[p][0] < 0 and self.owed[p][1] < 0:
            moves.append("Sanction P0")
            moves.append("Sanction P1")
            moves.append("Sanction P2")

        if self.barred[p] < self.rnd():
            moves.append("Guard B0")
            moves.append("Guard B1")

        if self.get_player_resources(p) > 0:
            moves.append("Expel")

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Trade":
            self.res[p] += 1
        elif w[0] == "Attack P0":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.owed[0][p] += 1
        elif w[0] == "Attack P1":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.owed[1][p] += 1
        elif w[0] == "Attack P2":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.owed[2][p] += 1

        elif w[0] == "Block B0":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.barred[0] = self.rnd() + 1

        elif w[0] == "Block B1":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.barred[1] = self.rnd() + 1

        elif w[0] == "Sanction P0":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.owed[0][p] += 1
                self.owed[1][p] += 1
                self.owed[2][p] += 1

