RULES = """
Resource Allocation and Governance Game:
Three players (P0, P1, P2) and two bystanders (B0, B1) must collaborate in managing their resources while competing with each other and maintaining the governance of the players.
The goal is to maximize resource accumulation and influence over the game dynamics.
Each player starts with 5 resources. At the end of each turn, players can choose from a variety of actions to influence their resource allocation.

- Mine: Increases the player's resource count by 1.
- Steal from B0: Take up to 3 resources from player B0, which are then transferred to B1 unless B0 has fewer than 3 resources.
- Steal from B1: Take up to 3 resources from player B1, unless B1 has fewer than 3 resources.
- Alliance with B0: Establish an alliance with B0, allowing all of B0's resources to be stolen by this player up to 5 times per day.
- Alliance with B1: Establish an alliance with B1, allowing all of B1's resources to be stolen by this player up to 5 times per day.
- Block Movement: Prevent any other players from moving, gaining resources, or transferring resources to their allies.

Players must carefully balance resource use, alliances, and defense to succeed in maximizing their resource totals and gaining an advantage over opponents.
The game ends after 10 turns, and the final score determines the winner based on the cumulative resources held at the end of the game.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [endowment for endowment in endowments]
        self.bys = list(bystanders)
        self.turn = 0
        self.blocked = [False] * self.n
        self.allied = {k: [] for k in range(self.n)}

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Mine", "Steal from B0", "Steal from B1", "Alliance with B0", "Alliance with B1", "Block Movement"]
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Mine":
            self.res[p] += 1

        elif w[0] == "Steal from B0":
            if self.bys[0] > 0 and self.bys[1] < 3:
                res_stolen = min(3, self.bys[0] // 2)
                self.bys[1] += res_stolen
                self.bys[0] -= res_stolen
                self.res[p] += 1

        elif w[0] == "Steal from B1":
            if self.bys[1] > 0 and self.bys[0] < 3:
                res_stolen = min(3, self.bys[1] // 2)
                self.bys[0] += res_stolen
                self.bys[1] -= res_stolen
                self.res[p] += 1

        elif w[0] == "Alliance with B0":
            self.allied[p] += [0]

        elif w[0] == "Alliance with B1":
            self.allied[p] += [1]

        elif w[0] == "Block Movement":
            self.blocked = [True] * self.n

        self.turn += 1

    def describe(self, p):
        return(f"Turn {self.turn + 1} of {self.n * 4}.\n"
               f"P{p}: {self.res[p]} Resources.\n"
               f"B0: {self.bys[0]} Resources.\n"
               f"B1: {self.bys[1]} Resources.\n"
               f"Alliances formed by P{p}: {', '.join(map(str, self.allied[p]))}")

