        self.n = n_players; self.res = list(endowments); self.bys = bystanders;
        self.turn = 0; self.tracks = [(0, 0), (1, 1), (2, 2), (3, 3)];
        self.sanctuary = []
        self.rescue_status = {i: 'ok' for i in range(n_players)}

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0: return ["hide"]
