        if move == "hunt":
            if self.res[p] < 3:
                self.res[p] += 1
                print("Hunt successful! You gained 1 resource!")
        elif move == "track":
            if self.res[p] < 2:
                print("Cannot find a resource! You lost 1 resource.")
            else:
                loc = self.tracks[self.turn % len(self.tracks)]
                if loc not in self.sanctuary:
                    self.sanctuary.append(loc)
