        elif move == "hide":
            self.sanctuary.append(p)
            print("You are safe in the cave!")
        elif move == "rescue":
            self.rescue_status[(p + 1) % self.n] = 'pending'
            print("Rescue request sent to the team next to you. Wait for them to respond.")
