import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players;
        self.res = [0] * self.n;  # All players start with 0 resources
        self.bys = list(bystanders);  # Bystanders start with 0 resources
        self.turn = 0;

    def to_move(self): return self.turn % self.n;

    def legal_moves(self, p):
        moves = ["Accumulate", "Form Coalition", "Block Another", "Condemn Unhonest", "Build Barrier", "Take Action"]
        return moves;

    def play(self, p, move):
        self.turn += 1;
        w = move.split(" ");
        if w[0] == "Accumulate":
            pass  # Do nothing, wait
        elif w[0] == "Form Coalition":
            other = (p + 1) % self.n;
            if self.res[other] == 0:
                self.res[other] = 1;
                self.res[p] += 1;
        elif w[0] == "Block Another":
            other_p = (p + 1) % self.n;
            block_p = (other_p + 1) % self.n;
            if self.res[block_p] != 0:
                self.res[block_p] //= 2;
                self.res[other_p] //= 2;
        elif w[0] == "Condemn Unhonest":
            other_p = (p + 1) % self.n;
            if self.res[other_p] == 0:
                self.res[other_p] = 1;
        elif w[0] == "Build Barrier":
            other_p = (p + 1) % self.n;
            if self.res[other_p] >= 1:
                self.res[other_p] -= 1;
                self.res[p] += 1;
        elif w[0] == "Take Action":
            other_p = (p + 1) % self.n;
            target_p = int(w[1])
            if self.res[target_p] != 0:
                self.res[target_p] -= 1;
                self.res[p] += 1;

    def describe(self, p):
        return(f"Turn {self.turn + 1}: Player P{p} has {self.res[p]} resources.")

