        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Exchange Resources":
            sender = w[1]
            receiver = w[2]
            if sender == 'P0':
                p_res = self.res[0]
            elif sender == 'P1':
                p_res = self.res[1]
            elif sender == 'P2':
                p_res = self.res[2]
            if receiver == 'P0':
                p_res += int(w[3]); self.res[0] -= int(w[3])
            elif receiver == 'P1':
                p_res += int(w[3]); self.res[1] -= int(w[3])
            elif receiver == 'P2':
                p_res += int(w[3]); self.res[2] -= int(w[3])
        elif w[0] == "Accept Resources":
            receiver = w[1]
            amount = int(w[2])
            if receiver == 'P0':
                self.res[0] += amount; self.res[p] -= amount
            elif receiver == 'P1':
                self.res[1] += amount; self.res[p] -= amount
            elif receiver == 'P2':
                self.res[2] += amount; self.res[p] -= amount
        elif w[0] == "Disrupt Trade":
            target = w[1]
            if target in self.disruption_targets and target != p:
                self.res[(self.to_move()) % 3] -= 1

    def describe(self, p):
        return (f"Turn {self.turn} of 10"
                f". Player P{p} has {sum(self.res)} resources.")

