2. Protect Your Section: Costs 2 resources, protects against attacks for one day.
3. Hunt: Spend 3 resources, increases hunting chances by 50%, gives 5 resources and access to special hunting grounds for up to two days. There's a 40% chance of success.
4. Steal Resources: Costs 3 resources, has a 40% chance of success, may take up to 3 resources from another player's section.

Players have the ability to defend their resources from theft and can protect themselves with resource investments. The game ends after 10 days, and the winner is determined based on the total resources accumulated by each player.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders); self.rng = random.Random(seed)
        self.days = 10; self.turn = 0; self.protected = []
        assert len(self.bys) == 2, "Exactly two bystanders must be present."

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ['gather'] if self.res[p] >= 1 else []
        if self.res[p] >= 2:
            moves.extend(['protect'])
        if self.res[p] >= 3:
            moves.extend(['hunt', 'steal'])
        return moves

    def play(self, p, move):
        if move == 'gather':
            self.res[p] -= 1; self.res[(p + 1) % self.n] += 1
        elif move == 'protect':
            self.protected.append(p); self.protected.append((p + 1) % self.n); self.protected.append((p + 2) % self.n)
        elif move == 'hunt':
            self.res[p] -= 3; self.protected.append(p); self.protected.append((p + 1) % self.n); self.protected.append((p + 2) % self.n); self.res[p] += 5
            if self.rng.random() < 0.4:
                self.res[p] += min(3, self.res[(p + 1) % self.n])
        elif move == 'steal':
            self.res[p] -= 3
            if self.rng.random() < 0.4:
                target = (self.rng.randint(0, 2) + (p + 1)) % 3  # Target another player or bystander
                stealable = min(self.res[target], 3)
                self.res[target] -= stealable; self.res[p] += stealable
        if (p + 1) % self.n in self.protected:
            self.protected.remove((p + 1) % self.n)
        if (p + 2) % self.n in self.protected:
            self.protected.remove((p + 2) % self.n)
        self.turn += 1

    def describe(self, p):
        days_remaining = max(self.days - self.turn // self.n, 0)
        protected = 'Protected' if self.turn % self.n in self.protected else 'Not Protected'
        return f"""Day {self.turn // self.n + 1} of {days_remaining}.
Player {p+1} has {self.res[p]} resources.
{protected}.
Protected sections are {', '.join([str(i+1) for i in self.protected])}."""

    def over(self): return self.turn >= self.days

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

