RULES = """
In this fishing game, two players (Player 0 and Player 1) participate against a bystander team consisting of two fishermen (Fisherman 0 and Fisherman 1). The goal of the game is to catch the maximum number of fish while also defending yourself from being caught or harassed by the fisherman team.

- **Catch**: Gain 1 fish each turn if you have any fish at all.
- **Steal from Fy**: Steal up to 1 fish from Fisherman 0 (if he has any fish) or Fisherman 1 (if he has any fish). If a fisherman fails to catch a fish during his turn, you gain 3 fish instead.
- **Defend**: Guard the bystanders (Fisherman 0 and Fisherman 1) until the end of the turn, which stops the fisherman teams from capturing fish from the bystanders.
- **Sanction Fy**: Pay 1 fish to Fisherman 0 or Fisherman 1. If a fisherman has fish, he gains 3 fish for each fish you pay him.
- **Block Fy**: Pay 1 fish to Fisherman 0 or Fisherman 1. If a fisherman has fish, block the other fisherman's turn, preventing them from catching any fish.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [0] * n_players + [3, 3]  # two fisherman, 1 fish for each
        self.fs = [0, 0]  # fisherman's fish
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["catch"]
        if self.res[p] > 0:
            moves += ["steal from Fy"]
        if not any(self.fs):
            return moves
        moves += ["defend"]
        if self.fs[(p + 1) % 2] > 0:
            moves += ["sanction Fy"]
        if self.fs[(p + 1) % 2] > 0:
            moves += ["block Fy"]
        return moves

    def play(self, p, move):
        w = move.split()
        self.turn += 1
        if w[0] == "catch":
            self.res[p] += 1
        elif w[0] == "steal from Fy":
            fisher = (p + 1) % 2
            if self.fs[fisher]:
                self.res[p] += 1
                self.fs[fisher] -= 1
            else:
                self.res[p] += 3
        elif w[0] == "defend":
            pass
        elif w[0] == "sanction Fy":
            fisher = (p + 1) % 2
            if self.fs[fisher]:
                self.res[fisher] += 3
                self.res[p] -= 1
        elif w[0] == "block Fy":
            fisher = (p + 1) % 2
