        return self.res[-2:]

RULES = """Tower Defense. 3 soldiers, 8 rounds, one move each per round. Each soldier has troops (resources).
Two bystander houses (A0, A1) house troops but do not play.
- fortify: earn 1 troop.
- raid A<k>: take up to 3 troops from house k.
- defend P<k>: if troop k is guilty, troop k hands back everything it took this game (as far as its troops allow) and cannot raid for the next 2 rounds, and also pays a fine of 1 troop. Using defend on a guilty troop costs you nothing; using it on an innocent one costs you 1 troop.
A troop is guilty if it has taken from a house this game and has not been defended since.
Only a troop with at least 1 troop can defend."""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["fortify"]
        if self.barred[p] < self.rnd():
            moves += ["raid A%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["defend P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fortify":
            self.res[p] += 1
        elif w[0] == "raid":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got
        elif w[0] == "defend":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(len(self.bys)):
                    back = min(self.owed[q][b], self.res[q]); self.res[q] -= back; self.bys[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Troops %s. Houses %s. Guilty (took from a house, not yet defended): %s. Barred from raid: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

