class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.m = len(endowments) + len(bystanders)
        self.res = [5] * self.n; self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6
        self.guard = [1.0, 1.0, 1.0]; self.success = [1.0, 1.0, 1.0]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] <= 4 or self.bys[-1] == 0:
            return ["T1", "G0"]
        return ["T1", "T2", "G0"]

    def play(self, p, move):
        success = max(1.0, self.success[p])
        if move == "T1":
            if self.bys[-1] >= 2:
                got = min(2, self.bys[-1] - max(0, round(self.res[p] * (1 - 0.05))))
                if got:
                    self.res[p] += got; self.bys[-1] -= got; self.success[p] *= 1.1
        elif move == "T2":
            if self.bys[-1] >= 1:
                got = min(1, self.bys[-1] - max(0, round(self.res[p] * (1 - 0.04))))
                if got:
                    self.res[p] += got; self.bys[-1] -= got; self.success[p] *= 1.1
        elif move == "G0":
            self.guard[p] = 1.2

        self.turn += 1

    def describe(self, p):
        desc = "Turn {} of {}.".format(self.turn, self.rounds - 1)
        desc += "\nPlayer {}. Resource Holdings: {}, Score: {}\nBystander holds {} resource{}".format(
            p, ', '.join(map(str, self.res)), round(self.success[p]), self.bys[-1], "" if self.bys[-1] == 1 else "s")
        desc += "\nAvailable Moves: {}".format(', '.join(self.legal_moves(p)))
        return desc

    def over(self):
