import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [4] * n_players  # Initialize each player with 4 gold coins (5 - 1)
        self.bystanders = bystanders
        self.current_turn = 0

    def to_move(self):
        return self.current_turn % self.n

    def legal_moves(self, p):
        moves = ["build hut"]
        if p > 0 and self.resources[p - 1] > 3:  # Check if the opponent has enough gold to be attacked
            moves.append("attack city")
        if p + 1 < self.n and self.resources[p + 1] > 3:
            moves.append("block attack")
        moves.append("retreat")
        return moves

    def play(self, p, move):
        if move == "build hut":
            self.resources[p] += 2
        elif move == "attack city":
            other_p = (p + 1) % self.n  # Attack the next opponent
            if self.resources[p] >= 3:
                self.resources[p] += 3
