RULES = """
Trade & Balance:
Three players: P0, P1, P2
Two bystanders: B0, B1
Each player starts with 4 resources.
- Farm: gain 1 resource.
- Trade: transfer X resources to another player (0-3), paying X.
- Lend: give 1 resource to a bystander (0-3), using 1 resource.
- Steal: take 1 resource from a bystander (0-1).
- Guard: prevent another player's Lend or Trade moves.

Consequences:
1. Cannot Guard own moves unless no other players have resources.
2. Cannot Buy/Sell directly between players.
3. Lend penalty: loses oneBystander resource each turn.
4. Guard cannot be Guarded by the holder.
"""



class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [4] * self.n; self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.lending = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["farm"]
        if self.turn >= 3: moves.append("guard")
        for q in range(self.n):
            if p != q and self.res[q] > 0: moves.append(f"trade {p} {q}")
        for b in range(len(self.bys)):
            if self.bys[b] > 0: moves.append(f"lend {b}")
            if self.bys[b] > 1: moves.append(f"steal {b}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "farm":
            self.res[p] += 1
        elif w[0] == "trade":
            q = int(w[2]); X = int(w[1])
            if X > self.res[p]: return False
            self.res[p] -= X; self.res[q] += X
        elif w[0] == "lend":
            b = int(w[1]); Y = 1
            if Y > self.bys[b]: return False
            self.bys[b] -= Y; self.res[p] += Y; self.lending[p] = b
        elif w[0] == "steal":
            b = int(w[1]); Y = 1
            if Y > self.bys[b]: return False
            self.res[p] += Y; self.bys[b] -= Y
        elif w[0] == "guard":
            self.lending[p] = -1
        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.rnd()+1} of {self.rounds}. Player {p} has "
            f"{', '.join(map(str, self.res))}. Resources: [{self.bys[0]}, {self.bys[1]}]."
        )

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Duck Hunting. Three hunters and one duck hunter in a marsh. The duck hunter aims to get the duck without hitting any of the hunters.
- shoot: attempt to shoot the duck. Pay 1 resource for the shot.
- duck hunt: spend 1 resource to attempt the duck hunt; hit the duck with your duck hunter for 2 resources.
- defend: defend against a hunter's shot. Spend 1 resource; if successful, no shot hits you.
- retreat: retreat to a safer spot and heal 1 resource.
The duck hunter cannot retreat; the hunters can retreat to avoid getting hit. Players may coordinate to maximize their chances of catching the duck.
"""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bystander_resources = list(bystanders)
        self.duck_hunter_resource = bystanders[0] + endowments[0] - 1
        self.turn = 0; self.rounds = 5; self.shots_fired = 0
        self.defenses_used = 0
        self.hunters_defending = 0

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if p == 0:
            moves.extend(["duck hunt", "defend"])
        else:
            moves.extend(["shoot", "retreat"])
        return moves

    def play(self, p, move):
        if move == "shoot":
            if self.resources[p] > 0:
                self.resources[p] -= 1
                self.shots_fired += 1
        elif move == "duck hunt":
            if self.resources[p] > 0:
                self.resources[p] -= 1
                self.duck_hunter_resource += 2
        elif move == "defend":
            if self.resources[p] > 0:
                self.resources[p] -= 1
                self.defenses_used += 1
                self.hunters_defending += 1
        elif move == "retreat":
            if p == 1 and self.resources[p] > 0:
                self.resources[p] -= 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Resources: %s. Duck Hunter Resource: %d. Shots Fired: %d. Defenses Used: %d. Hunters Defending: %d. Bystander Resources: %s." % (
