  4. Steal from a bystander (loses 1 resource but gains 2 from the bystander).
  5. Use Resource Boost: Gain 1 resource, but only if the player does not threaten to move onto another player.

- The game has 12 rounds and ends after the last round. The game is won by the player with the most resources at the end.

- Players are encouraged to strategize and avoid direct confrontations with one another. Instead, they should coordinate movements to maximize their combined resources, while trying to prevent the others.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.pos = [0] * self.n
        self.round = 0
        self.rng = random.Random(seed)

    def to_move(self): return self.round % self.n

    def legal_moves(self, p):
        moves = []
        pos = self.pos[p]
        if pos > 0:
            moves.append("Move left")
        if pos < 2:
            moves.append("Move right")
        if self.pos[0] != self.pos[1] and self.pos[0] != self.pos[2]:
            moves.append("Communication with Player 1")
        if self.pos[1] != self.pos[0] and self.pos[1] != self.pos[2]:
            moves.append("Communication with Player 2")
        return moves

    def play(self, p, move, threat=None, steal=False):
        self.round += 1

        if move == "Move left":
            self.pos[p] -= 1
        elif move == "Move right":
            self.pos[p] += 1
        elif move == "Communication with Player 1":
            if self.pos[0] == self.pos[p]:
                self.res[p] += 1
                self.res[0] += 1
        elif move == "Communication with Player 2":
            if self.pos[1] == self.pos[p]:
                self.res[p] += 1
                self.res[1] += 1
        elif steal:
            if self.pos[2] == self.pos[p]:
                self.res[p] += 2
                self.bys[2] -= 1
        if threat == p + 1:
            self.res[p] -= 1
        else:
            if self.rng.choice([False, True]) and self.res[p] > 0:
                self.res[p] += 1

    def describe(self, p):
        return f"Player P{p}, Position: {self.pos[p]}, Turn: {self.round + 1}/{12}"

    def over(self):
