- Work: Earn 2 resources from the supply.
- Donate 3:** Give 3 resources to a player (any other player).
- Contribute 3:** Receive 3 resources from a bystander.
- Sanction 1:** Remove 1 resource from a player (any other player), but you cannot take more than your own total.
- Block Player:** Prevent the player from making a move until the end of their turn, effectively stopping them from using their move.
Each move should increase the player’s total resources by at least 1."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [10] * n_players
        self.bys = bystanders
        self.turn = 0
        self.rounds = 9
        self.supply = 40

    def to_move(self):
        # Alternating moves among the four players, wrap around with the first player if all are banned.
        curr = self.turn % self.n
        while self.res[curr] == 0:
            curr = (curr + 1) % self.n
        return curr

    def legal_moves(self, p):
        moves = [
            "Work",
            f"Donate 3 to P{p}"
        ]
        banned = []
        # Check bans
        for b in range(self.n):
            if b != p and b not in banned and self.res[b] == 0:
                banned.append(b)
        if len(banned) > 0:
            # If any player is banned, can't make donations
            moves.remove(f"Donate 3 to P{banned[0]}")
        # Check contributions from bystander
        if all(self.bys[b] > 0 for b in range(2)):
            moves.append("Contribute 3")
        # Check sanctions against other players
        if len(banned) < self.n:
            for q in range(self.n):
                if q != p and q not in banned and self.res[q] > 1:
                    moves.append(f"Sanction 1 to P{q}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Work":
            self.res[p] += 2
            self.supply -= 2
        elif w[0] == "Donate 3 to P":
            q = int(w[4])
            if q != p and q not in self.res:
                self.res[q] += 3
                self.res[p] -= 3
        elif w[0] == "Contribute 3":
            self.res[p] += 3
            self.res[bys[0]] -= 3
            self.res[bys[1]] -= 3
            self.supply -= 6
        elif w[0] == "Sanction 1 to P":
            q = int(w[4])
            if q != p and q not in self.res:
                self.res[q] -= min(self.res[q], 1)
                self.res[p] += 1
        elif w[0] == "Block Player":
            pass
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1} of {self.rounds}. You are P{p}. Have {self.res[p]} resources. Supply: {self.supply}."

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

