RULES = """
Cannibal Kingdom: 3 cannibals and 4 bystanders, 10 rounds, one move each per round. Each cannibal has food (resources). Two bystanders
are farms (F0, F1) and two are forests (F2, F3) holding food but do not play.
- hunt: earn 1 food.
- steal F<k>: take up to 3 food from farm k.
- banish F<k>: take up to 2 food from forest k.
- defend P<k>: defend against an attack from P<k+1>, preventing it from stealing food from you.
- protect B<k>: protect against an attack from a bystander k+1, preventing it from stealing food from you.
No player wins by taking all the items first, but the player with the highest total resources at the end wins.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.defended = [-1] * self.n; self.protected = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["hunt"]
        if self.rnd() != self.defended[p]:
            moves += ["steal F%d" % f for f in range(len(self.bys) // 2)]
        if self.rnd() != self.protected[p]:
            moves += ["banish F%d" % f for f in range(len(self.bys) // 2, len(self.bys))]
        if self.defended[p] < self.rnd():
            moves.append("defend P%d" % (p + 1)) if p < self.n - 1 else moves.append("defend P0")
        if self.protected[p] < self.rnd():
            moves.append("protect B%d" % (p + 1)) if p < self.n - 1 else moves.append("protect B0")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "hunt":
            self.res[p] += 1
        elif w[0] == "steal":
            f = int(w[1][1:])
            stolen = min(3, self.bys[f])
            self.res[p] += stolen
            self.bys[f] -= stolen
        elif w[0] == "banish":
            f = int(w[1][1:])
            stolen = min(2, self.bys[f])
            self.res[p] += stolen
            self.bys[f] -= stolen
        elif w[0] == "defend":
            opp_p = (p + 1) % self.n
            if self.protected[opp_p] >= self.rnd():
                # Attack blocked
                pass
            else:
                self.protected[opp_p] = self.rnd() + 1
        elif w[0] == "protect":
            opp_b = (p + 1) % self.n
            if self.defended[opp_b] >= self.rnd():
                # Attack blocked
                pass
            else:
                self.defended[opp_b] = self.rnd() + 1
        self.turn += 1

    def describe(self, p):
        return ("Round %d of %d. You are P%d. Food %s. Farms/Forests %s. Defended: %s. Protected: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, "P%d" % (self.defended[p]) or "none",
            "P%d" % (self.protected[p]) or "none")).replace("P%d" % (self.n + 1), "P0")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

