    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["resource"]
        if not self.blocked:
            moves.append("trade with A/B")
            moves.append("trade with C")

        if self.bys[-1] > 0:  # Player A/B can trade with the bystander
            moves.append("trade with bystander")

        moves.append("attack bystander")
        moves.append("sabotage C")

