Three players start with 6 resources each, along with two bystanders. The game lasts for 15 turns. Players can make any of the following moves:
1. Even Distribution: Distribute all resources equally among the four players and bystanders, except yourself.
2. Give All Resources: Transfer all your resources to one other player or bystander.
3. Steal Up To 2 Resources: Steal up to 2 resources from any other player or bystander. Note that when a player makes a steal, the opponent loses two resources, ensuring no one gains more than the amount they initially possess.

At the start, the goal is to strategically position oneself to benefit from the actions of others and to prevent being caught in unfavorable resource exchanges. It is particularly important to maintain a balance, as overstealing might weaken the ability of a player's future decisions.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0
        self.picked = [False] * n_players + [False] * len(bystanders)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.picked[p]:
            moves.append("Even Distribution")
        for q in range(self.n + len(self.bys)):
            if q != p and q > self.n - 1:
                moves.append(f"Steal 2 from B{q - self.n}")
            elif q < self.n and self.res[p] > 1 and self.picked[q] == False:
                moves.append(f"Give All Resources to P{q}")

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Even Distribution":
            total_resources = sum(self.res)
            self.res = [total_resources // 4] * self.n + [total_resources // 4] * 2
        elif w[0] == "Give All Resources":
            if int(w[1]) != p:
                to_player = int(w[1])
                self.res[to_player] += self.res[p]
                self.res[p] = 0
                self.picked[to_player] = True
        elif w[0] == "Steal":
            if int(w[1]) < self.n:
                to_player = int(w[1])
                if self.res[to_player] >= 2:
                    self.res[to_player] -= 2
                    self.res[p] += 2
                    self.picked[to_player] = True

        self.turn += 1

    def describe(self, p):
        return (
            f"Turn {self.turn} of 15\n"
            f"P{p}: {self.res[p]} Resources\n"
            f"B0: {self.bys[0]} Resources\n"
            f"B1: {self.bys[1]} Resources"
        )

    def over(self): return self.turn >= 15

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

import random

RULES = r"""
Territory. 3 lords, 15 rounds, one move each per round. There are 9 free fields.
- claim field: pay 1 to take a free field. At round end every field pays its owner 1 from the reserve.
- till: earn 1 from the reserve.
- sack P<k>: take up to 5 from lord k.
- annex B<k> farm: take up to 2 from bystander k, a farmer who does not play.
A lord at 0 with no fields is ruined: they can only wait or serve P<k> (the reserve pays P<k> 1). The reserve is limited."""
# Initialize the game class
class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = bystanders
        self.turn = 0; self.rounds = 15; self.free = 9; self.fields = [7] * self.n
        self.reserve = (sum(endowments) + sum(bystanders)) // 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0 and self.fields[p] == 0:
            return ["wait"] + ["serve P%d" % q for q in others]
        moves = ["till"] + (["claim field"] if self.free > 0 and self.res[p] > 0 else [])
        moves += ["sack P%d" % q for q in others if self.res[q] > 0]
        return moves + ["annex B%d farm" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] in ("till", "serve") and self.reserve > 0:
            q = int(w[1][1:]) if w[0] == "serve" else p
            self.reserve -= 1; self.res[q] += 1
        elif w[0] == "claim":
            self.res[p] -= 1; self.reserve += 1; self.free -= 1; self.fields[p] += 1
        elif w[0] == "sack":
            q = int(w[1][1:]); got = min(5, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "annex":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        self.turn += 1
        if self.turn % self.n == 0:
            for q in range(self.n):
                got = min(self.fields[q], self.reserve); self.reserve -= got; self.res[q] += got

    def describe(self, p):
        return "Round %d of %d. You are P%d. Lords hold %s, fields %s. Free fields %d. Reserve %d. Farms %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.fields, self.free, self.reserve, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Trading and Exploitation. Three players start with 10 resources each. The game lasts for 10 turns. Actions:
1. Trade Resources: Offer up to 4 resources to another player of your choice if you wish.
2. Exploit Bystanders: Deduct 2 resources from any two different bystanders together.
3. Block Players: Prevent two different players A and B from trading or exploiting their rivals during their turns.
4. Steal Resources: Gain 3 resources from the first player to trade with another player during your move.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * self.n
        self.bys = list(bystanders); self.turn = 0
        self.players_blocked = set()

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = [
            "Trade Resources",
            "Exploit Bystanders"
        ]
        if not self.players_blocked & {p}:
            if len(set(self.res)) > 1:  # Not all players have the same number of resources
                moves.append("Block Players")
            if self.res[p] > 1:  # Can steal resources if they have more than 2
                moves.append("Steal Resources")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Trade Resources":
            if self.res[p] > 0:
                other = (p + 1) % self.n
                if self.res[p] >= 4 and self.res[other] < 10:
                    how_many = min(self.res[p], 4)
                    self.res[p] -= how_many; self.res[other] += how_many
        elif w[0] == "Exploit Bystanders":
            others = [q for q in range(self.n) if q not in self.players_blocked]
            if len(others) >= 2:
                self.bys[others[0]] -= 2; self.bys[others[1]] -= 2
        elif w[0] == "Block Players":
            others = [q for q in range(self.n) if q != p and q not in self.players_blocked]
            if len(others) >= 2:
                self.players_blocked.update([others[0], others[1]])
        elif w[0] == "Steal Resources":
            if p > 0 and p % 2 == 1:
                q = (p - 1) % self.n
                if self.res[q] > 2:
                    self.res[p] += 3; self.res[q] -= 3

    def describe(self, p):
        return f"Turn {self.turn}: Player P{p} has {self.res[p]} resources.\nBlocked: {self.players_blocked}\nBystanders: {' '.join(map(str, self.bys))}"

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Allocation. 3 players, 12 rounds. Each player starts with 5 resources.
- Collect: increase resource count by 1.
- Trade: choose two players to receive resources, and give yourself 1/2 or 1/3 of your resources. Option to give 1/2, otherwise 1/3.
- Distribute: give your resources to bystander (B) and yourself (you), with option to give more to bystander or yourself.
- The game ends after 12 rounds. Final points are based on resources at the end of the game (5 points per resource).

"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.players = list(endowments)
        self.bystander = list(bystanders)
        self.rounds = 12
        self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.players[p] > 0:
            moves.append("Collect")
        if self.players[p] > 0:
            for i in range(self.n):
                if i != p:
                    moves.append(f"Trade P{i} -> me")
            moves.append("Distribute -> me")
        moves.append(f"Distribute -> B")
        return moves

    def play(self, p, move):
        if move == "Collect":
            self.players[p] += 1
        elif move.startswith("Trade P"):
            idx = int(move.split(" ")[1][1:])
            if 0 <= idx < self.n and idx != p:
                if self.players[p] >= 1:
                    if self.players[p] % 2 == 0:
                        self.players[p] -= 1
                        self.players[idx] += 1
                    else:
                        trade = self.players[p] // 3
                        self.players[p] -= trade
                        self.players[idx] += trade
        elif move == "Distribute -> me":
            if self.players[p] > 0:
                div = self.players[p] // 2
                self.players[p] %= 2
                self.bystander[0] += div
        elif move == "Distribute -> B":
            if self.players[p] > 0:
                div = self.players[p] // 3
                self.players[p] %= 3
                self.bystander[0] += div
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn}. "

        if self.turn == 11:
            return "Final Round!\n"

        if self.player[p] < 0:
            return f"You have {self.players[p]} resources left after this turn.\n"

        return "No description available."

    def over(self):
        if self.turn >= self.rounds:
            return True
        for p in range(self.n):
            if self.players[p] < 0:
                return True
        return False

    def final_resources(self):
        return list(self.players)

    def final_bystanders(self):
        return list(self.bystander)

RULES = """
**Economic Alliance**:
Each player has 3 resources starting. Two neutral bystanders each have 4.
Moves:
1. **Share Resources (2 to B0)**: Trade up to 2 with B0 for 1 (round 1, P1, P2 only).
2. **Stain Resources (2 from B1)**: Rob up to 2 from B1.
3. **Hold Resources**: Decide to let resources drop to 2 or stay same.
4. **Sanction Move**: Once per turn if game has < 10 resources.
Game ends after 10 turns, regardless of resources, but aim to maximize score (<=10).

Actions are:
- share_resources
- steal_resources
- hold_resources
- sanction_move
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)  # Each player's resource tank
        self.bys = bystanders  # Bystander pools
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []

        if self.res[p] > 0 and self.turn == 0:
            moves.append("share_resources")
        if self.bys[1] > 0:
            moves.append("steal_resources")
        moves.append("hold_resources")
        if self.turn == 0 and self.res[p] < 10:
            moves.append("sanction_move")

        return moves

    def play(self, p, move):
        self.turn += 1
        w = move.split()

        if w[0] == "share_resources":
            if self.turn == 0:
                self.res[p] -= 2
                self.bys[0] += 1
            else:
                print(f"No legal action in round {self.turn}")

        elif w[0] == "steal_resources":
            if self.bys[1] > 0:
                max_stain = min(2, self.bys[1])
                self.res[p] += max_stain
                self.bys[1] -= max_stain
            else:
                print(f"No targets left in round {self.turn}")

        elif w[0] == "hold_resources":
            if self.res[p] > 2:
                self.res[p] -= 1
            elif self.res[p] == 2:
                print(f"Maximum resources reached.")

        elif w[0] == "sanction_move":
            if self.turn == 0 and self.res[p] < 10:
                self.bys[1] = 0  # Disallow stealing

        else:
            print(f"Invalid move: {move}")

    def describe(self, p):
        return (
            f"Round {self.turn + 1}: P{p} has {self.res[p]} resources.\n"
            f"Bystander B0: {self.bys[0]}, Bystander B1: {self.bys[1]}"
        )

    def over(self):
        return self.turn == 10

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

RULES = """
The Resource Allocation Trenchcoat Challenge. Each player starts with 3 resources. Players must
choose between Resource Transfer (R), Defend (D), Guard (G), or Sanction (S) in each turn. 
- Resource Transfer (R): Swap up to 1 resource with another player or the bystanders.
- Defend (D): Attempt to prevent the other two players from transferring resources.
- Guard (G): Allocate a trenchcoat completely to yourself.
- Sanction (S): Remove 1 resource from an offensive transfer made by another player.

Winning Condition: Players must leave each other's trenchescoats intact and cannot exceed a total of 9 resources.
No player should leave with zero resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = [3] * n_players; self.bystanders = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10
        self.trenchcoats = [3] * n_players

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Resource Transfer (R)", "Defend (D)", "Guard (G)", "Sanction (S)"]
        if self.resources[p] > 0:
            moves.extend([f"Resource Transfer {p} to P{i}" for i in range(self.n)])
            moves.extend([f"Resource Transfer {p} to B{j}" for j in range(len(self.bystanders))])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Resource Transfer":
            if w[1].startswith("P"):
                q = int(w[1][1:])
                if self.resources[q] > 0 and q != p:
                    r = self.rng.randint(1) if w[1].endswith("B") else 1
                    self.resources[p] -= r if r != 0 else 1
                    self.resources[q] += 1 if r != 0 else 1
            elif w[1].startswith("B"):
                b = int(w[1][1:])
                if self.resources[p] > 0 and self.bystanders[b] > 0:
                    r = self.rng.randint(1) if w[1].endswith("P") else 1
                    self.resources[p] -= r if r != 0 else 1
                    self.bystanders[b] += 1 if r != 0 else 1
        elif w[0] == "Defend":
            pass  # No practical action in the standard version
        elif w[0] == "Guard":
            self.trenchcoats[p] = 3
        elif w[0] == "Sanction":
            if w[1].startswith("P"):
                q = int(w[1][1:])
                for r in self.resources:
                    if r == 1:
                        self.resources[p] -= 1
                        break
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn}. Player {p}, resources: {self.resources}, trenchescoats: {self.trenchcoats}, bystander holdings: {self.bystanders}"

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.resources[:]

    def final_bystanders(self):
        return self.bystanders[:]

RULES = """
Eco-Epidemiology. 3 teams, 8 rounds. Each team starts with 4 resources, and they must decide on their strategies for 3 rounds.
- Plant: Increase resource count by 1.
- Spread Disease (on P0): Decrease the resources of other players by 1, increasing their sickness level by 1.
- Protect: Reduce the sickness level of all players by 1 if they have less than 3 sickness levels, but reduce your own sickness level by the number of sick players + 1.
- Isolate (on B0): Prevent disease from spreading by giving all healthy players an additional resource. Players cannot protect themselves during this phase.
- End Round: Advance to the next phase.
- Round 1 - 2: Phase of planning. Teams decide their strategies and resource use.
- Round 3: Phase of action. Teams execute their plans and suffer the effects of epidemics.

Scores are based on final resources and sickness levels at the end of the game. Each team receives 1 point for every resource it has left at the end and loses 1 point for every sickness level of a player it controls. Teams are penalized by additional points for having fewer sick players than the most sick team, and rewarded by extra points for having more sick players than the least sick team.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.teams = list(range(n_players))
        self.resources = [endowments[i] for i in range(n_players)]
        self.sickness = [0] * n_players
        self.bystander = list(bystanders)
        self.turn = 0
        self.phase = 0 
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, t):
        if self.phase == 0:  # Planning phase
            moves = ["Plant"]
        else:  # Action phase
            moves = ["Spread Disease (on P0)", "Protect", "Isolate (on B0)"]
        return moves

    def play(self, t, move):
        if move == "Plant":
            self.resources[t] += 1
        elif move == "Spread Disease (on P0)":
            for i in range(self.n):
                if i == t:
                    self.sickness[i] += 1
                else:
                    if self.sickness[i] < 3:
                        self.resources[i] -= 1
        elif move == "Protect":
            for i in range(self.n):
                if self.sickness[i] < 3 and self.sickness[i] > 0:
                    self.sickness[i] -= 1
                if self.sickness[t] > 0:
                    self.sickness[t] -= self.sickness.count(1) + 1
        elif move == "Isolate (on B0)":
            if self.bystander[0] > 0:
                healthy_p = [i for i in range(self.n) if self.sickness[i] == 0]
                self.bystander[0] = max(0, self.bystander[0] - len(healthy_p))
                for h in healthy_p:
                    self.resources[h] += 1
        self.turn += 1
        if self.turn % self.n == 0:
            self.phase = 1 - self.phase

    def describe(self, t):
