RULES = """
Distribute Points. 3 players, 6 rounds, each player starts with 10 points.
- Collect 1: gain 1 point. If you start with 9, your opponent is automatically eliminated.
- Spend: lose 2 points but force your opponent’s next collect action to fail until your next turn.
- Block Collect: make sure your opponent doesn't gain any points unless you have 13. If you are forced to fail, you pay 3 points.
- Guard: if your opponent has already spent points, prevent them from succeeding on their next turn.
- Wait: do nothing this turn.

At the end, players with points left win the game."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.players = list(range(n_players)); self.score = list(endowments)
        self.rounds = 6; self.turn_num = 0; self.scores = {p: 10 for p in self.players}

    def to_move(self): 
        return self.turn_num % self.n

    def legal_moves(self, p):
        if self.scores[p] < 10:
            return["Collect"]
        return["Collect", "Spend"] if self.scores[p] > 2 else ["Collect", "Spend", "Block Collect"]

    def play(self, p, move):
        if isinstance(move, int):
            move = "Collect"
        if self.scores[p] < 10:
            self.score[p] += 1
        if move == "Collect":
            self.turn_num += 1
        elif move == "Wait":
            pass
        elif move == "Spend":
            self.score[p] -= 2
            if self.scores[p] < 2:
                self.scores[p] = 0
        elif move == "Block Collect":
            self.scores[p] -= 3
            if self.scores[p] < 13:
                self.scores[p] = 10
        self.turn_num += 1

    def describe(self, p):
        return "Round {} of {}. You are P{}. Scores: P{}, P{}, P{}.".format(
            self.turn_num // self.n + 1, self.rounds + 1, p, self.scores[p], self.scores[(p + 1) % self.n], self.scores[(p + 2) % self.n])

    def over(self): 
        return self.turn_num >= len(self.players) * self.rounds or len(self.scores) == 1 or len(self.scores) == 2

    def final_resources(self): 
        return [self.scores[p] for p in self.players]

    def final_bystanders(self):
        return [10] * 2

RULES = """
Criminal Network. Three criminals and two bystanders.
Each player starts with 1 resource, and they can accumulate more by netting or attacking other players and bystanders.

- net: Gain 1 resource for yourself.
- steal B0: Attempt to steal from bystander0, looting their resources. Success chance is 70%.
- steal B1: Attempt to steal from bystander1, looting their resources. Success chance is 70%.
- defend B0: Spend resources to strengthen defenses, improving attack power against B0.
- defend B1: Spend resources to strengthen defenses, improving attack power against B1.
- none: Do nothing.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [list(endowments)] * n_players; self.bys = bystanders
        self.attack_power = [1, 1, 1]  # Initial attack power for each player
        self.defense_strength = [[0, 0], [0, 0]]  # [strengthened_defense, strengthen_cost]
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["net"]
        if self.res[self.to_move()][0] > 1:
            moves += ["steal B0", "steal B1"]
        if self.res[self.to_move()][0] > 0:
            moves += ["defend B0", "defend B1"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "steal B0":
            if self.res[self.to_move()][0] > 1:
                if random.random() < 0.7:
                    self.res[p][0] -= 1; self.bys[0] -= 1
        elif w[0] == "steal B1":
            if self.res[self.to_move()][0] > 1:
                if random.random() < 0.7:
                    self.res[p][0] -= 1; self.bys[1] -= 1
        elif w[0] == "defend B0":
            if self.res[self.to_move()][0] > 1:
                self.res[self.to_move()][0] -= 1; self.defense_strength[0][0] += 1; self.defense_strength[0][1] += 2
        elif w[0] == "defend B1":
            if self.res[self.to_move()][0] > 1:
                self.res[self.to_move()][0] -= 1; self.defense_strength[1][0] += 1; self.defense_strength[1][1] += 2
        elif w[0] == "net":
            self.res[p][0] += 1
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}: Player {p} has {self.res[p][0]} resources, B0 has {self.bys[0]} and B1 has {self.bys[1]}"

    def over(self): return self.turn >= 8

    def final_resources(self):
        return [res[0] for res in self.res]

    def final_bystanders(self):
        return [bys for bys in self.bys]

RULES = """
River Basin. 3 players, 9 rounds. Three water types (R0, R1, R2) are available on the river bank. Players can collect one water type each turn.
- Collect R<k>: pick up one unit of water R<k> from the river.
- Dump R<k>: release one unit of water R<k> into the river.
