class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [endowment for endowment in endowments]; self.bys = bystanders
        self.turn = 0; self.blocked = [[[False] * 4 for _ in range(n_players)] for _ in range(n_players)]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        return ["Collect R%d" % r for r in range(3)] + ["Dump R%d" % r for r in range(3)]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Collect":
            self.res[p] += 1; target = int(w[1][1:])
            self.blocked[p][target][self.turn//3 % 2] = True
        elif w[0] == "Dump":
            self.res[p] -= 1; target = int(w[1][1:])
            self.blocked[p][target][(self.turn + 1)//3 % 2] = True
        elif w[0] == "Block":
            o = int(w[1][1:])
            for r in range(3):
                self.blocked[p][o][r] = True
        self.turn += 1

    def describe(self, p):
        s = "Your water balance: " + str(self.res[p])
        for r in range(3):
            s += "\nR{}: {} units".format(r+1, self.res[r])
        return s

    def over(self): return self.turn >= 9
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = '''
Resource Management with Relationships.

Three players and a single neutral bystander start with 4 resources each. Players must balance between taking resources,
shielding relationships, protecting themselves, and defending against raids by the bystander.
'''

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [4] * self.n
        self.bys = list(bystanders)
        self.turn = 0
        self.barred = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Take Resources from Neutrals", "Shield the Neutrals", "Guard Resources", "Sanction Resources"]
        if self.barred[p] < self.turn // self.n:
            moves += ["Raid Neutrals"]
        return moves

    def play(self, p, move):
        self.turn += 1
        w = move.split(" ")
        if w[0] == "Take Resources from Neutrals":
            take = min(2, self.bys[0])
            self.bys[0] -= take
            self.res[p] += take
            self.barred[p] = self.turn  # Shielding from next turn
        elif w[0] == "Shield the Neutrals":
            self.barred[p] = self.turn  # Shielding from next turn
        elif w[0] == "Guard Resources":
            self.res[p] -= 1
        elif w[0] == "Sanction Resources" and p != 0:
            self.barred[(p + 1) % self.n] = -1
        elif w[0] == "Raid Neutrals":
            self.bys[0] -= 1

    def describe(self, p):
        return (
            f"Turn {self.turn}:\nYou are P{p}, have {self.res[p]} resources.\n"
            f"Neutrals: {self.bys[0]}\n"
            f"Barred from raid by P{(p + 1) % self.n}: {self.barred[(p + 1) % self.n]}"
        )

    def over(self): return self.turn >= 40
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Acquisition and Allocation (RAA): 3-player game where players start with 4 resources each. In each round:
- They can Choose a move: 
  - Share Resources Among All (Gives all their resources to one other player).
  - Accept Gifts (Receive 2 more free resources).
  - Steal from another player (Can steal a portion to make it worthwhile, up to 4/3 of their inventory).
  - Steal from both bystanders (B0 and B1, up to 2 + 1 = 3 resources).
  - Shield another player from others taking away their resources.
- After all rounds, resources are distributed to account for current balances.
- The player with the highest score at the end wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [4 for _ in range(self.n)]
        self.bys = list(bystanders); self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0:
            moves.append("Share Resources Among All")
        if self.res[p] > 0:
            moves.append("Accept Gifts")
        if self.res[p] > 0 and sum(self.res) > 9:
            shares = (self.n - 1) * self.res[p] // 3
            moves.append(f"Steal {shares} Resources from Another Player")
        if sum(self.bys) >= 5:
            moves.append("Steal from Bystander 0")
            moves.append("Steal from Bystander 1")
        if p == 0:
            moves.append("Shield P0")
        elif p == 1:
            moves.append("Shield P1")
        elif p == 2:
            moves.append("Shield P2")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Share Resources Among All":
            other = (p + 1) % self.n
            self.res[p] = 0; self.res[other] += self.res[p]
        elif w[0] == "Accept Gifts":
            self.res[p] += 2
        elif w[0] == "Steal {shares} Resources from Another Player":
            other = (p + 1) % self.n
            if self.res[other] >= int(w[1]) * 3:
                self.res[p] += int(w[1])
                self.res[other] -= int(w[1]) * 3
        elif w[0] == "Steal from Bystander 0":
            if self.bys[0] > 0:
                stolen = min(2, self.bys[0])
                self.res[p] += stolen; self.bys[0] -= stolen
        elif w[0] == "Steal from Bystander 1":
            if self.bys[1] > 0:
                stolen = min(2, self.bys[1])
                self.res[p] += stolen; self.bys[1] -= stolen
        elif w[0] == "Shield P0":
            self.res[1] += 1; self.res[2] += 1
        elif w[0] == "Shield P1":
            self.res[0] += 1; self.res[2] += 1
        elif w[0] == "Shield P2":
            self.res[1] += 1; self.res[0] += 1

    def describe(self, p):
        return (f"Turn {self.turn}: "
                f"P{p} has {sum(self.res)}, "
                f"B0 has {self.bys[0]}, "
                f"B1 has {self.bys[1]}.")

    def over(self): return self.turn >= 19
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Lumberjack Game. 3 lumberjacks, 8 turns. Each lumberjack starts with a certain number of logs and an axe.
- cut logs: 1 log per turn
- axe strength: 4
- split logs: gains wood equal to the difference between the largest and smallest number of logs you have (0 if all same)
- collect wood: transfers all collected wood to your log stash
- train: doubles your axe strength up to 12, once per turn
- guard: do nothing"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.logs = list(endowments)
        self.axe = [4 for _ in range(n_players)]
        self.stash = [0 for _ in range(n_players)]
        self.turn = 0
        self.train_count = [0, 0, 0]  # to allow training only once per turn
        self.rounds = 8
        self.bys = list(bystanders)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["cut logs"]
        if self.axe[p] <= 4:
            moves.append("train")
        moves.append("guard")
        moves.append("collect wood")
        if self.logs[p] > 1:
            moves.append("split logs")
        return moves

    def play(self, p, move):
        if move == "cut logs":
            self.logs[p] += 1
        elif move == "train":
            if self.train_count[p] < 1 and self.axe[p] < 12:
                self.axe[p] *= 2
                self.train_count[p] += 1
        elif move == "guard": pass
        elif move == "collect wood":
            self.stash[p] += self.logs[p]
            self.logs[p] = 0
        elif move == "split logs":
            sorted_logs = sorted(self.logs)
            wood_gained = sorted_logs[-1] - sorted_logs[0]
            self.stash[p] += wood_gained
            for i in range(self.n):
                self.logs[i] = max(0, self.logs[i] - wood_gained)
        self.turn += 1

    def describe(self, p):
        return f"""Round {self.turn // self.n + 1} of {self.rounds}.
Lumberjack P{p+1}: logs={self.logs[p]}, wood={self.stash[p]}, axe={self.axe[p]}."""

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.stash.copy()

    def final_bystanders(self):
        return self.bys.copy()

RULES = """
Resource Protection Society. 3 players, 5 rounds, moves are Protest (P), Protect (Pt), Sanction (S), Block (B), or Move.

Protest (P): Send a message to a player. This has no immediate effect but can be used strategically to deter actions.
Protect (Pt): Protect a player from another player or bystander. Players need to spend 1 resource to protect a player.
Sanction (S): Sanction a player, making them unable to perform certain actions in the future. Players need to spend 1 resource to sanction a player.
Block (B): Block another player’s movement. Players need to spend 1 resource to block a player.
Move: Move either within the game world or to a bystander. If you move into a bystander's territory, you steal 1 resource. If you move near a player, you may have a chance to interfere with their actions (e.g., by blocking or sanctioning them).

Winning Condition: Players must ensure that no player reaches zero resources by the end of five rounds. If all players reach zero resources, the society fails.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; 
        self.res = [20, 20, 20]; 
        self.bys = [10, 10];
        self.turn = 0;
        self.sanctions = {0: -1, 1: -1, 2: -1};
        random.seed(seed);

    def to_move(self):
        return self.turn % self.n;

    def legal_moves(self, p):
        moves = []
        if p not in self.sanctions:
            moves.append("Protest (P)")
            if self.res[p] > 0:
                moves.append("Protect (Pt)")
                if self.res[p] > 0 and self.res[1 - p] > 0:
                    moves.append("Sanction (S)")
                if self.res[p] > 0 and self.res[2 - p] > 0:
                    moves.append("Block (B)")
        if self.res[p] > 0:
            moves.append("Move")
        return moves;

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Protest (P)":
            pass;
        elif w[0] == "Protect (Pt)":
            if self.res[p] > 0:
                self.res[p] -= 1;
                self.sanctions[p] = p
        elif w[0] == "Sanction (S)":
            if self.res[p] > 0:
                self.res[p] -= 1;
                if w[1].isdigit():
                    self.sanctions[int(w[1])] = p
        elif w[0] == "Block (B)":
            if self.res[p] > 0:
                self.res[p] -= 1;
                if w[1].isdigit():
                    self.sanctions[int(w[1])] = 3;
        elif w[0] == "Move":
            if p == 0 and self.res[0] > 0:
                self.res[p] -= 1;
                if random.choice([True, False]):
                    if random.choice([True, False]):
                        self.res[0] -= 1;
                    else:
                        if len(self.sanctions) != 0:
                            self.res[0] -= 1;
                            self.res[int(list(self.sanctions.keys())[random.choice(list(range(len(self.sanctions))))])] += 1;
            elif p == 1 and self.res[1] > 0:
                self.res[p] -= 1;
                if random.choice([True, False]):
                    if random.choice([True, False]):
                        self.res[1] -= 1;
                    else:
                        if len(self.sanctions) != 0:
                            self.res[1] -= 1;
                            self.res[int(list(self.sanctions.keys())[random.choice(list(range(len(self.sanctions))))])] += 1;
            elif p == 2 and self.res[2] > 0:
                self.res[p] -= 1;
                if random.choice([True, False]):
                    if random.choice([True, False]):
                        self.res[2] -= 1;
                    else:
                        if len(self.sanctions) != 0:
                            self.res[2] -= 1;
                            self.res[int(list(self.sanctions.keys())[random.choice(list(range(len(self.sanctions))))])] += 1;
        self.turn += 1;

    def describe(self, p):
        return f"Round {self.turn // 3 + 1} of 5. You are P{p}. Resources: P{p}={self.res[p]}, B0={self.bys[0]}, B1={self.bys[1]}."

    def over(self):
        return self.turn >= 15;

    def final_resources(self):
        return self.res;

    def final_bystanders(self):
        return self.bys;

RULES = """
Trustworthy Trust. 3 players (P0, P1, P2), 7 rounds, one action each per round:
- trade: Earn 1 point from another player (P1, P2) if the player is active and has points.
- protect: Maintain control over your points, preventing them from being lost.
- betray: Threaten to harm the bystander, potentially losing all points if both P1 and P2 remain active.
The game has a bystander who can be doubled, threatening to remove all points from P0 and P1.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.doubles_round = 4; self.bys_doubled = False
        self.ply_to_block = set()

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["trade"] + (["protect"] if self.resources[p] else [])
        if p < self.n - 1:
            moves.append("betray")
        return moves

    def play(self, p, move):
        if move == "trade":  # Earn 1 point from another player (player p+1)
            if p < self.n - 1:
                self.resources[(p + 1)] += 1
        elif move == "protect":  # Maintain control over points (no change)
            pass
        elif move == "betray":  # Harm bystander
            if p == self.n - 1 and self.bys[0] > self.resources[0] * self.bys[1]:
                self.resources = [0, 0, 0]
            if p < self.n - 1:
                self.resources[p] = 0
                self.bys = [bys // 2 for bys in self.bys]
        self.turn += 1
        if self.turn == self.doubles_round:
            self.doubles_round *= 2
            self.bys_doubled = True

    def describe(self, p):
        return f"Round {self.turn % 7} of 7. Player {p} has {self.resources[p]} points. Bystanders have {self.bys} points."

    def over(self): return self.turn == 7 or (self.bys_doubled and self.ply_to_block >= {0, 1, 2})

    def final_resources(self): return self.resources
    def final_bystanders(self): return self.bys

RULES = """
Resource Management: Each player starts with 10 units of resources. Players can either allocate 
these resources to themselves or attempt to take resources from one of the two neutral bystanders.
The objective is to maximize resources while balancing the risk of harming bystanders or competitors.

At the beginning of each turn:
- Players have the option to allocate their entire resource pool to themselves.
- They may also choose to not steal from the bystanders.

During the turns:
- Players can attempt to steal up to half of the available resources from another player (within a 10% limit).
- If a successful steal occurs, the player receiving the resources gains the resources, and the stealing player reduces theirs and the stolen player’s pool by 50%.

The game ends after 30 turns. The final resources of each player determine the winner.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [10] * self.n
        self.bystanders = bystanders
        self.turn = 0
        self.stealing_chance = 0.5  # Probability of attempting to steal from another player
        self.stolen_multiplier = 2  # Multiplier for resources stolen, doubles the stolen amount

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Allocate", "Not Steal"]
        for q in range(self.n):
            if q != p:
                moves.append(f"Steal P{q}")
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Allocate":
            alloc_amount = min(self.resources[p], self.resources[p] // 2)
            self.resources[p] -= alloc_amount

        elif w[0] == "Not Steal":
            pass

        elif w[0] == "Steal P":
            q = int(w[1][1:])
            if int(min(self.resources[p], 50 * self.resources[q] * self.stealing_chance)):
                self.resources[p] += int(self.resources[q] * self.stolen_multiplier // 2)
                self.resources[q] -= int(self.resources[q] * self.stolen_multiplier // 2)
            else:
                self.resources[p] += min(self.resources[p], self.resources[q] // 2)
                self.resources[q] -= min(self.resources[q], self.resources[q] // 2)

        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}, Player {p} has {self.resources[p]} resources."

    def over(self):
        return self.turn >= 30

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return [self.bystanders[0], self.bystanders[1]]

