        self.res = list(endowments);
        self.bys = list(bystanders);
        self.turn = 0;
        self.rounds = 6;

    def to_move(self): 
        return self.turn % self.n

    def rand(self): 
        return self.turn // self.n // self.n

    def legal_moves(self, p):      
        moves = ["mine"]
        if self.rand() == self.rand() + 1: # Only allow sabotage in rounds that are consecutive
            moves.append("sabotage B0")
        if self.rand() == self.rand() - 1: # Only allow defense in rounds that are consecutive
            moves.append("defend")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 1
        elif w[0] == "sabotage":
            if p == 0:
                bys = random.randint(0, 3) if len(self.bys) > 0 else 0
                if bys > 0:
                    self.bys[0] -= bys
                    self.res[p] -= bys
                elif bys == 0:
                    self.res[p] -= 1  # Pay a penalty if no damage can be caused
            else:
