            bys = random.randint(0, 3) if len(self.bys) > 0 else 0
            if bys > 0:
                self.bys[0] += bys
                self.res[p] += bys
            elif bys == 0:
                self.res[p] -= 1  # Pay a penalty if no defense is successful
            else:
                print("Illegal move: non-miner cannot defend.")
        self.turn += 1

    def describe(self, p):
        return f"Round {self.rand() + 1} of {self.rounds}. You are Player {p}. Gold: {self.res[p]}, Sabotage damage: {self.bys[0]}."

    def over(self): 
        return self.turn >= self.n * self.rounds

    def final_resources(self): 
        return list(self.res)

