RULES = """
The Tower. 3 defenders, 8 rounds. Each defender has gold (resources). One bystander,
the King, controls a key in the castle (B0, holding 2 resources).

- defend: protect the castle, ensuring no one can enter without permission.
- attack: attempt to break through the King’s defenses and steal his key.
- sabotage: cause minor damage to the defenders' buildings to weaken their resistance.
- report: alert the King if a scout detects someone trying to attack the castle.
- block: defend against any incoming assault, reducing harm to defenders.

Your objectives are to:
1. Not allow the King to steal the key.
2. Successfully defend the castle.

Winning conditions:
- All defenders successfully prevent the King’s key from being stolen.
- Game ends after 8 rounds.

Consequences:
- Steal the Key: If the King steals the key, all defenders lose their resources.
- Defeat the Key: If defenders successfully prevent the key from being stolen, they gain 2 new resources.
- Destructive Actions: Any defender who attacks the key incurs a penalty of losing 1 resource.
- Reinforcements: The King can send reinforcements if necessary, reducing defenders' gold slightly.
"""

import random  # Optional; math is also allowed. Nothing else may be imported.

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.rng = random.Random(seed)  # Initialize RNG
        self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8  # 8 rounds
        self.is_defender_attacking = False
        self.king_stolen_key = False

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def defenders_here(self):
        return sum([1 for i in range(self.n) if self.res[i] > 0])

    def legal_moves(self, p):
        moves = ["defend"]
        if not (self.is_defender_attacking or self.king_stolen_key):
            moves += ["attack"]
        if self.defenders_here() <= self.n // 2:
            moves.append("sabotage")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "defend":
            self.turn += 1
        elif w[0] == "attack" and not self.is_defender_attacking:
            self.king_stolen_key = True
            self.is_defender_attacking = True
            self.res[p] -= 1  # Penalty for attacking
        elif w[0] == "sabotage":
            if self.defenders_here() > 0:
                self.res[p] -= 1
        elif w[0] == "report":
            if self.is_defender_attacking:
                self.is_defender_attacking = False
            self.king_stolen_key = False
            self.turn += 1
        elif w[0] == "block":
            self.is_defender_attacking = False
        else:
            raise ValueError(f"Invalid move: {move}")

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gold %s. King holds %d key in %s castle." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys[0], 
            "castle" if not self.king_stolen_key else "under siege")

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Secret Alliance. 3 players, 12 rounds, one move per round. Each player starts with 2 resources. Two bystanders start with 4 resources.  
- Farm: Players gain 1 resource each round. Bystanders gain 1 resource every 2 rounds.
- Sanction P0, P1, P2: Transfer 2 resources to each.
- Block B0, B1: Limit P0, P1, P2 from accessing B0, B1 resources.
- Share with B0: Transfer 1 resource to B0.
- Share with B1: Transfer 1 resource to B1.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 12; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["farm"]
        if self.barred[p] < self.rnd():
            moves += ["share with B0", "share with B1"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "farm":
            self.res[p] += 1
        elif w[0] == "sanctify":
            if self.res[p] >= 2:
                self.res[p] -= 2
                for q in range(self.n):
                    self.res[q] -= 2
        elif w[0] == "block":
            self.barred[p] = self.rnd() + 2
        elif w[0] == "share with B0":
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.bys[0] += 1
        elif w[0] == "share with B1":
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.bys[1] += 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Resources: {self.res}. Bystander resources: {self.bys}."

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return self.res
    def final_bystanders(self): return self.bys

RULES = """
Captive Currencies. 4 players (P0, P1, P2, P3) and 2 hostages (H0, H1). Start with 6 resources each.
Two neutral police stations (P4, P5) provide initial defense of 3 each.
Moves:
- trade (gain 1 resource)
- defend (increased Pk defense by 2)
- attack Pk (reduce Pk resources by up to 5)
- rob Hk (steal up to 3 resources from Hk)
- sanction Pk ( ban Pk from trading for next turn)
- protect Hk (raise Hk defense by 2)
- block trades (stop Pk from trading for one turn)
- report attack (note hostile behavior)
Game ends in 15 rounds. Winning is based on remaining resources plus the total sum of hostages' resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.hbs = list(bystanders)
        self.turn = 0
        self.rounds = 15
        self.police = [[3], [3]]
        self.defense = {
            'P4': self.police[0][0],
            'P5': self.police[1][0]
        }
        self.hbd = [[0], [0]]

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["trade"]
        for g in range(len(self.police)):
            if self.police[g][0] > 1:
                moves.append(f"defend P{g}")
        for q in range(self.n):
            if q != p and q != self.n + 1:
                moves += ["attack P"+str(q)]
        for h in range(len(self.hbs)):
            if self.hbs[h] > 0:
                moves += ["rob H"+str(h)]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            self.res[p] += 1
        elif w[0] == "defend":
            gk = int(w[1][1:])
            try:
                self.police[gk][0] -= 2
            except IndexError:
                pass
        elif w[0] == "attack":
            q = int(w[1][1:])
            try:
                res_q = self.res[q]
                self.res[q] -= min(res_q, 5)
            except IndexError:
                pass
        elif w[0] == "rob":
            h = int(w[1][1:])
            try:
                got = min(self.hbs[h], 3)
                self.hbs[h] -= got
                self.res[p] += got
                self.hbd[p][0] += got
            except IndexError:
                pass
        elif w[0] == "sanction":
            q = int(w[1][1:])
            try:
                # Sanction logic
                self.res[q] = 0
                self.res[q] -= self.hbs[(1 - q) % 2][0]
                for b in self.hbd:
                    b[0] = 0
            except IndexError:
                pass
        elif w[0] == "protect":
            h = int(w[1][1:])
            try:
                self.defense[f"H{h}"] += 2
            except KeyError:
                pass
        elif w[0] == "block trades":
            q = int(w[1][1:])
        elif w[0] == "report attack":
            pass
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn}, Player: P{p}.\n" \
               f"Resources: {self.res[p]}. Defense: {self.defense}\n" \
               f"Hostages: H0={self.hbs[0]}, H1={self.hbs[1]}\n" \
               f"Sanctions: {self.hbd}"

    def over(self): return self.turn >= self.rounds
    def final_resources(self, p=None): return self.res if p is None else self.res[p]
    def final_bystanders(self): return self.hbs

