        moves = ["mine"]

        if self.bystanders[0] > 0:
            moves.extend(["steal B0", "trade B0"])

        if self.resources[p] >= 3:
            moves.append("defend P0")

        if self.resources[p] > 0:
            moves.append("retreat")

        return moves

    def play(self, p, move):
        w = move.split(" ")

