- Guard: Increases resource allocation to max 9.
- Report P:<pid>: Temporarily reduces a player's ability to poach for two rounds due to guilt.
- Poach B:<bid>: Attempts to take up to 3 resources from the bystander's pond.
- Restock B:<bid>: Recovers up to 2 resources taken from the bystander's pond for the purpose of repaying harm or defending the bystander.

The game ends after 10 rounds, and the winner is determined by the remaining resources and the healthiest bystanders.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.max_turns = 10; self.lake = 12

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["forge", "guard"]
        if self.res[p] <= 7:
            moves += ["report P%d" % q for q in range(self.n) if q != p]
        if self.res[p] >= 3:
            moves += ["poach B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if self.res[p] >= 1:
            moves += ["restock B%d" % b for b in range(len(self.bys))]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "forge":
            gained = min(2, self.lake - 1); self.lake -= gained; self.res[p] += gained
        elif w[0] == "guard":
            self.res[p] = min(9, self.res[p] + 2)
        elif w[0] == "report":
            self.res[p] -= 1; self.res[int(w[1][1:])] -= 1
        elif w[0] == "poach":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        elif w[0] == "restock":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        self.turn += 1

    def describe(self, p):
        return "Turn %d. Player %d has %d resources. Lake: %d. Bystanders: %s." % (
            self.turn, p, self.res[p], self.lake, self.bys)

