"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [endowments[0], endowments[1], endowments[2]]  # Initial resources
        self.hubs = ['R0', 'R1', 'R2']
        self.steal_blocked = ['R1', 'R2', 'R3']  # Initial blockage for R1, R2, and R3
        self.bys = bystanders.copy()  # Bystanders start with 0 resources
        self.turn = 0
        self.rounds = 30
        self.move_to = 'R0'  # All players start at R0

