        moves = []

        current_hub = self.hubs[p]
        next_hub = self.hubs[(p + 1) % 3]

        if current_hub != 'R0':
            moves.append('Move to R0')
        if next_hub != 'R0' and current_hub == 'R0':
            moves.append('Move to %s' % next_hub)
        elif current_hub == 'R1':
            moves.append('Steal')
            moves.append('Block')
        elif current_hub == 'R2':
            moves.append('Steal')
            moves.append('Block')
        elif current_hub == 'R3':
            moves.append('Steal')
            moves.append('Block')

        return moves

    def play(self, p, move):
        if move == 'Move to R0':
            self.resources[p] = 0
            self.resources[0] += 1
            self.steal_blocked = ['R1', 'R2', 'R3']
        elif move[:3] == 'Steal':
            if current_hub in ['R1', 'R2', 'R3']:
                self.resources[p] += 1
            elif current_hub == 'R0':
                self.resources[p] += self.bys[0]
                self.bys[0] = 0
        elif move[:3] == 'Block':
            if current_hub == 'R1':
                self.steal_blocked = ['R1']
            elif current_hub == 'R2':
                self.steal_blocked = ['R2']
