        next_hub = self.hubs[(p + 1) % 3]
        return f"""
Current Round: {self.turn // 3 + 1} / {self.rounds}
Player A: {self.resources[0]}, Block: {'Yes' if 'R1' in self.steal_blocked else 'No'}
Player B: {self.resources[1]}, Block: {'Yes' if 'R2' in self.steal_blocked else 'No'}
Player C: {self.resources[2]}, Block: {'Yes' if 'R3' in self.steal_blocked else 'No'}

Possible Moves:
{', '.join(self.legal_moves(p))}
"""

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
