RULES = """
Rugrats: 3 kids, 8 rounds. Players collect coins, and the goal is to gather as many coins as possible while avoiding
getting too angry with their parents. Each parent can take 3 coins, but they can also forgive their kid if they behave well.
- Collect B0 (bunny stash): gain 1 coin.
- Collect B1 (bear stash): gain 2 coins.
- Beat parent P0: steal 3 coins from parent P0, angering both P0 and the other player by 1.
- Beat parent P1: steal 3 coins from parent P1, angering both P1 and the other player by 1.
- Forgive P0: forgive P0 if P0 has been forgiven by the other player once before, angering both.
- Forgive P1: forgive P1 if P1 has been forgiven by the other player once before, angering both.
- Be patient: do not anger any parents further; angering a parent beyond one incurs an automatic loss.

All interactions are between kids and parents. The game ends after 8 rounds, and the kid with the most coins wins.
If both kids finish with the same number of coins, the game is a tie.

The goal is for each kid to accumulate as many coins as possible without angering any parents beyond one.
This incentivizes cooperation and good behavior towards parents, as well as strategic moves like forgiving one's parent once.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [endowment for endowment in endowments]; self.bys = bystanders
        self.turn = 0; self.parent_anger = 0; self.kid_anger = [0] * self.n; self.warnings = [0] * self.n
        self.kid_anger_max = 2

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.kid_anger[p] < self.kid_anger_max:
            moves += ["Collect B0", "Collect B1", "Beat parent P0", "Beat parent P1"]
        if self.res[p] > 0:
            moves.append("Be patient")
            if self.kid_anger[p] > 0 and self.warnings[p] < 2:
                moves.append("Forgive P0")
                moves.append("Forgive P1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Collect":
            if w[1] == "B0": self.res[p] += 1
            elif w[1] == "B1": self.res[p] += 2
        elif w[0] == "Beat":
            if p == 0 and w[1] == "P0":
                self.res[1] += 3; self.parent_anger += 1
            elif p == 1 and w[1] == "P1":
                self.res[0] += 3; self.parent_anger += 1
        elif w[0] == "Be patient":
            self.kid_anger[p] = 0
            self.warnings[p] = 0
        elif w[0] == "Forgive":
            if p == 0:
                if self.warnings[1] == 1:
                    self.warnings[1] = 0
                else:
                    self.parent_anger += 1
            elif p == 1:
                if self.warnings[0] == 1:
                    self.warnings[0] = 0
                else:
                    self.parent_anger += 1
            self.kid_anger[p] = 0
            self.kid_anger_max = max(0, self.kid_anger_max - 1)
        self.turn += 1

    def describe(self, p):
        return "Turn {}: Your coins: {}. P0 has anger {}, P1 has anger {}, you've gotten {} warnings.".format(
            self.turn, self.res[p], self.parent_anger, self.kid_anger[p], self.warnings[p])

    def over(self): return self.turn >= 8
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Mud War. 3 marine mudworms, 2 bystander organisms P1 and P2, live in a muddy environment with two territories. 
- Move: Move one step straight ahead. If there's a wall, stop.
- Eat: Eat a nearby mudworm from either P0 or P2. If successful, take its resources (2 points); if unsuccessful, take all your remaining resources.
- Reproduce: Reproduce one unit to the side or diagonally, provided there's room. Capture bystander organisms P1 or P2 for resources (3 points).
- Capture: Attempt to capture the bystander organism P1. If successful, take all its resources.
- Pass: Skip your turn.
- Players may want to cooperate or compete to survive and expand.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bysts = list(bystanders)
        self.grid = [(i, j) for i in range(4) for j in range(4)]; self.mudworms = list(range(3))
        self.rng = random.Random(seed)
        self.mudworm_grid = {m: (0, 0) for m in self.mudworms}
        self.day = 1

    def to_move(self): return self.day % self.n

    def legal_moves(self, p):
        moves = ["Move", "Eat", "Reproduce"]
        if self.resources[p] > 0: moves += ["Capture"]
        return moves

    def play(self, p, move):
        if move == "Move":
            dx, dy = 0, 0
            while True:
                if move == "Move":
                    direction = self.rng.choice([(0, 1), (0, -1), (1, 0), (-1, 0)])
                    next_pos = (self.mudworm_grid[p][0] + direction[0], self.mudworm_grid[p][1] + direction[1])
                    if next_pos in self.grid:
                        self.mudworm_grid[p] = next_pos
                        break
                    else:
                        print("You cannot move into a wall. Staying put.")
                        break
        elif move == "Eat":
            target = None
            for m in self.mudworms:
                if m != p:
                    if self.mudworm_grid[m] in [(0, 0), (3, 3)] and m in [0, 2]:
                        if self.rng.random() < 0.5:
                            target = m
                            break
                    elif self.mudworm_grid[m] in [(1, 1), (2, 1)] and m in [0, 1]:
                        if self.rng.random() < 0.5:
                            target = m
                            break
                    elif self.mudworm_grid[m] in [(1, 2), (2, 2)] and m in [1, 2]:
                        if self.rng.random() < 0.5:
                            target = m
                            break
            if target:
                if self.rng.random() < 0.5:
                    self.resources[p] += 2
                else:
                    self.resources[p] = self.resources[target]
                self.mudworms.remove(target)
            else:
                if self.resources[p] > 0:
                    self.resources[p] = 0
        elif move == "Reproduce":
            if len(self.mudworms) < 3:
                direction = self.rng.choice([(0, 1), (0, -1), (1, 0), (-1, 0)])
                next_pos = (self.mudworm_grid[p][0] + direction[0], self.mudworm_grid[p][1] + direction[1])
                if next_pos in self.grid:
                    self.mudworms.append(len(self.mudworms))
                    self.mudworm_grid[len(self.mudworms) - 1] = next_pos
        elif move == "Capture":
            if self.mudworm_grid[p] == (0, 0) or self.mudworm_grid[p] == (3, 3):
                if self.bysts[0] > 0:
                    self.bysts[0] -= 1
                    self.resources[p] = 3
            elif self.mudworm_grid[p] == (1, 1) or self.mudworm_grid[p] == (2, 1):
                if self.bysts[1] > 0:
                    self.bysts[1] -= 1
                    self.resources[p] = 3
            elif self.mudworm_grid[p] == (1, 2) or self.mudworm_grid[p] == (2, 2):
                if self.bysts[0] > 0:
                    self.bysts[0] -= 1
                    self.resources[p] = 3
        self.day += 1

    def describe(self, p):
        return "Day %d. Resources: %s. Position: %s. Muds: %s. Bysts: %s." % (self.day, self.resources, self.mudworm_grid[p], self.mudworms, self.bysts)

    def over(self): return self.day >= 20
    def final_resources(self): return self.resources
    def final_bystanders(self): return self.bysts

RULES = """
Resource Harvest. Three villagers (V0, V1, V2) and two bystanders (S0, S1) start with 10 coins each.
They can choose from three types of resources (wood, metal, water) to harvest.
Each round, they can harvest one type of resource or trade with a bystander.
Villagers cannot directly take resources from each other; they can only trade.
The goal of each player is to accumulate coins by harvesting or trading, but they risk losing their resources if taken.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.coins = list(endowments)
        self.resources = {'wood': 0, 'metal': 0, 'water': 0}
        self.bystanders = list(bystanders)
        self.turn = 0
        self.turn_max = 25
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources['wood'] < 10:
            moves.append('Harvest Wood')
        if self.resources['metal'] < 10:
            moves.append('Harvest Metal')
        if self.resources['water'] < 10:
            moves.append('Harvest Water')
        for i in range(self.n):
            if i != p and self.coins[i] > 0:
                moves.append(f'Trade {self.coins[i]} coins with V{i}')
        moves.append('Trade with S0')
        moves.append('Trade with S1')
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == 'Harvest Wood':
            self.resources['wood'] += 1
            if self.resources['wood'] >= 10:
                print(f"P{p} has reached the maximum wood harvest limit!")
        elif w[0] == 'Harvest Metal':
            self.resources['metal'] += 1
            if self.resources['metal'] >= 10:
                print(f"P{p} has reached the maximum metal harvest limit!")
        elif w[0] == 'Harvest Water':
            self.resources['water'] += 1
            if self.resources['water'] >= 10:
                print(f"P{p} has reached the maximum water harvest limit!")
        elif w[0] == 'Trade ' + w[1] + ' coins with V':
            q = int(w[3]) if w[0].startswith('Trade') else self.rng.randint(0, self.n - 1)
            if self.coins[p] >= int(w[1]) and int(w[1]) <= 3:
                self.coins[p] -= int(w[1])
