# Note: The hunter never asks for help, and the player carrying the treasure is guaranteed to finish the game.


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.treasure = 100; self.hunter = -1; self.player_with_treasure = -1
        self.round = 0; self.rounds = 7; self.reserve = (sum(endowments) + sum(bystanders)) // 2

