        moves = []
        if self.hunter == p:
            return []
        if self.player_with_treasure == p:
            moves += ["defend P%d" % q for q in range(self.n) if q != self.hunter]
            moves += ["steal 4"]
        else:
            moves += ["collect"]
            if self.res[p] >= 2:
                moves += ["offer 2"]

        return moves

