        w = move.split(" ")
        if w[0] == "collect":
            self.res[p] += 1; self.reserve -= 1
        elif w[0] == "offer 2":
            self.res[p] -= 2; self.hunter += 2
            if self.hunter < self.treasure:
                self.hunter += 1; self.res[self.hunter % self.n] -= 1
        elif w[0] == "defend P%d" % p:
