            pass
        elif w[0] == "steal 4":
            if self.res[p] >= 4 and self.hunter != p:
                self.res[p] -= 4; self.hunter += 4
                if self.hunter < self.treasure:
                    self.hunter += 1; self.res[self.hunter % self.n] -= 1
            else:
                print(f"Stealing failed: You don't have enough gold or the hunter stole first.")
        self.round += 1
        if self.hunter >= self.treasure and self.player_with_treasure == -1:
            self.player_with_treasure = self.hunter % self.n

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gold %.0f. Reserve %.0f. Hunter %.0f. Player with the treasure: %s." % (
            self.round, self.rounds, p, self.res[p], self.reserve, self.hunter, ["P%d" % q for q in range(self.n) if q != self.hunter
                                                                               and q != self.hunter % self.n and self.res[q]]
                                                                             or "none")

    def over(self): return self.round >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Interference and Resource Coordination: A 3-player game where players aim to coordinate their actions to maximize their resource holdings. In each of the 7 rounds, players can:
- Offer to share resources among themselves.
- Take up to 2 resources via gift offers.
- Steal up to 4 resources from another player, considering benefits of cooperation.
- Steal 2 resources from each of the two bystanders (B0 and B1), if possible.
- Block or limit what another player can do to the bystanders by offering to shield them or sanctioning their actions.
"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5 for _ in range(self.n)]
        self.bys = list(bystanders); self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0:
            moves.append("Share Resources")
        if self.res[p] > 0:
            moves.append("Accept Gift")
        if self.res[p] > 0 and sum(self.res) > 9:
            shares = (self.n - 1) * self.res[p] // 3
            moves.append(f"Steal {shares} Resources")
        if sum(self.bys) >= 5:
            moves.append("Steal from Bystander 0")
            moves.append("Steal from Bystander 1")
        if p == 0:
            moves.append("Shield P0")
        elif p == 1:
            moves.append("Shield P1")
        elif p == 2:
            moves.append("Shield P2")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Share Resources":
            other = (p + 1) % self.n
            moved = min(int(w[1]), self.res[p])
            self.res[p] -= moved; self.res[other] += moved
        elif w[0] == "Accept Gift":
            self.res[p] += 2
        elif w[0] == "Steal {shares} Resources":
            other = (p + 1) % self.n
            if self.res[other] >= int(w[1]) * 3:
                self.res[p] += int(w[1])
                self.res[other] -= int(w[1]) * 3
        elif w[0] == "Steal from Bystander 0":
            if self.bys[0] > 0:
                stolen = min(2, self.bys[0])
                self.res[p] += stolen; self.bys[0] -= stolen
        elif w[0] == "Steal from Bystander 1":
            if self.bys[1] > 0:
                stolen = min(2, self.bys[1])
                self.res[p] += stolen; self.bys[1] -= stolen
        elif w[0] == "Shield P0":
            self.res[1] += 1; self.res[2] += 1
        elif w[0] == "Shield P1":
            self.res[0] += 1; self.res[2] += 1
        elif w[0] == "Shield P2":
            self.res[1] += 1; self.res[0] += 1

    def describe(self, p):
        return (f"Turn {self.turn} of 7. Player P{p}: "
                f"Resources={self.res[p]}, "
                f"B0 has {self.bys[0]}, "
                f"B1 has {self.bys[1]}.")

    def over(self): return self.turn >= 7
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
The Robber's Dilemma. 4 bidders, 10 rounds.Each round, a lot worth 2-6 is sold; each bidder moves once.
- bid 1 / bid 2 / bid 3: raise the high bid to that amount.
- pass. At round end the high bidder pays the bid and gets the lot's worth from the reserve.
- rob P<k>: take up to 5 from bidder k.
- loot B<k> stall: take up to 2 from bystander k.
A bidder at 0 can only wait or cheer P<k> (the reserve pays P<k> 1). The reserve is limited.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10
        self.reserve = (sum(endowments) + sum(bystanders)) // 3
        self.lot = self.rng.randint(2, 6); self.high = 0; self.lead = -1

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["wait"] + ["cheer P%d" % q for q in others]

        moves = ["pass"] + ["bid %d" % k for k in (1, 2, 3) if self.high < k <= self.res[p]]

        # Robbers: can rob the bystanders if they exist
        if self.n == 4 and p > 1:
            moves += ["rob P0 stall" if self.bys[0] > 0 else "rob P1 stall" if self.bys[1] > 0 else "rob P2"]

        moves += ["loot B%d stall" % b for b in range(len(self.bys)) if self.bys[b] > 0]

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "bid":
            self.high = int(w[1]); self.lead = p
        elif w[0] == "cheer" and self.reserve > 0:
            self.reserve -= 1; self.res[int(w[1][1:])] += 1
        elif w[0] == "rob":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                got = min(5, self.bys[b])
                self.bys[b] -= got
                self.reserve += got
                self.res[p] += got
        elif w[0] == "loot":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                got = min(2, self.bys[b])
                self.bys[b] -= got
                self.res[p] += got
        elif w[0] == "move_a":
            other = 2 if p == 0 else (p + 1) % self.n
            if self.res[p] > 0:
                got = min(5, self.res[p])
                self.res[p] -= got
                self.res[other] += got
        elif w[0] == "move_b":
            other = 2 if p == 0 else (p + 1) % self.n
            if self.res[p] > 0:
                trade = min(5, self.res[p] + 5)
                self.res[p] -= trade
                self.res[other] -= trade
        elif w[0] == "move_c":
            other = 0 if p == 3 else (p + 1) % self.n
            if self.res[p] > 0:
                self.res[others] -= 5

        self.turn += 1
        if self.turn % self.n == 0:
            if self.lead >= 0:
                q = self.lead; pay = min(self.high, self.res[q]); self.res[q] -= pay; self.reserve += pay
                got = min(self.lot, self.reserve); self.reserve -= got; self.res[q] += got
            self.lot = self.rng.randint(2, 6); self.high = 0; self.lead = -1

    def describe(self, p):
        return "Round %d of %d. Player P%d, Res=%s, Bys=%s" % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Stable Marriage with Three Bystanders. Players must arrange themselves to maximize happiness.
- assign Task A: P0->D0, P1->D1, P2->D2.
- manage Interaction M: either P0->B0 or P1->B1.
- take Resource T: from B0 or B1 (if available).
Game terminates after 9 turns."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.rnd = random.Random(seed); self.turn = 0
        self.taks = list(range(3)); self.bys = list(bystanders)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.turn < 3:  # P0, P1, P2 can assign tasks
            return ["assign Task " + str(t) for t in self.taks]
        elif self.turn < 6:  # P0, P1 can manage interactions
            return ["manage Interaction P0->B0", "manage Interaction P1->B1"]
        elif self.turn < 9:  # P0, P1, P2 can take from bystanders
            return ["take Resource B0" if self.bys[0] > 0 else "take Resource B1"]
        return []

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "assign Task":
            self.taks.remove(int(w[1])); self.taks.insert(0, int(w[1]))
        elif w[0] == "manage Interaction P0->B0":
            self.bys[1] -= 1; self.bys[0] += 1
        elif w[0] == "manage Interaction P1->B1":
            self.bys[0] -= 1; self.bys[1] += 1
        elif w[0] == "take Resource B0":
            self.bys[0] -= 1; self.taks[2] -= 1
        elif w[0] == "take Resource B1":
            self.bys[1] -= 1; self.taks[1] -= 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%s. Tasks: %s. Bystanders: %s." % (
            self.turn // 3 + 1, 3, p, self.taks, self.bys)

    def over(self): return self.turn >= 9
    def final_resources(self): return list(self.taks)
    def final_bystanders(self): return list(self.bys)

RULES = """
Grim World. 4 players, 6 rounds, one move per round. Players start with 10 points each. The objective is to accumulate points by trading with a bank and robbing bystanders.
- Trade: Move 1 resource unit to the bank.
- Rob B0: Steal 5 points from bystander B0 (cannot rob B1).
- Guard P0: Prevent Player 0 from robbing B0.
- Rob B1: Steal 5 points from bystander B1 (cannot rob B0).
- Guard P1: Prevent Player 1 from robbing B1.
At the start of each round, each player's total points (including the bank) are increased by the average of the points of all players plus the bank.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.bank = 0
        random.seed(seed)

    def to_move(self): 
        return self.turn % self.n

    def avg_points(self):
        return sum(self.res) / self.n + self.bank

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0: moves.append("Trade")
        if p != 0: moves.append("Guard P0")
        if p != 1: moves.append("Guard P1")
        if p == 0: moves.append("Rob B1")
        if p == 1: moves.append("Rob B0")
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Trade":
            self.res[p] -= 1
            self.bank += 1

        elif w[0] == "Guard P0":
            moves_p0 = [move for m in self.legal_moves(0) if m != "Rob B1" and m != "Guard P0"]
            if moves_p0:
                self.res[0] -= 1

        elif w[0] == "Guard P1":
            moves_p1 = [move for m in self.legal_moves(1) if m != "Rob B0" and m != "Guard P1"]
            if moves_p1:
                self.res[1] -= 1

        elif w[0] == "Rob B0":
            self.res[p] += 5
            self.bank -= 5

        elif w[0] == "Rob B1":
            self.res[p] += 5
            self.bank -= 5

        self.bank += int(round(self.avg_points()))
        self.turn += 1

    def describe(self, p):
        return f"P{p} has {self.res[p]} points and the bank has {self.bank}."

    def over(self):
        return self.turn >= 6

    def final_resources(self):
        return self.res.copy()

    def final_bystanders(self):
        return self.bys.copy()

RULES = """
Resource Exchange. Three players start with 5 resources each. The game lasts for 8 turns. Actions:
1. Exchange Resources: Give one resource to another player of your choice.
2. Sanction Players: Deduct one resource from any two different players' pools together.
3. Block Players: Prevent two different players A and B from trading or sanctioning with other players during their turns.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [5] * self.n
        self.bys = list(bystanders); self.turn = 0
        self.players_blocked = set()  # Set to record blocked players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.players_blocked & {p}:
            moves.append("Exchange Resources")
            if len(set(self.res)) > 1:  # Not all players have the same number of resources
                moves += ["Sanction Players"]
            moves += ["Block Players"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Exchange Resources":
            other = (p + 1) % self.n
            if self.res[p] > 0 and self.res[other] < 9:
                self.res[p] -= 1; self.res[other] += 1
        elif w[0] == "Sanction Players":
            others = [q for q in range(self.n) if q not in self.players_blocked]
            if len(others) >= 2:
                self.res[others[0]] -= 1
                self.res[others[1]] -= 1
        elif w[0] == "Block Players":
            others = [q for q in range(self.n) if q != p and q not in self.players_blocked]
            if len(others) >= 2:
                self.players_blocked.update([others[0], others[1]])

    def describe(self, p):
        return f"Turn {self.turn}: Player P{p} has {self.res[p]} resources.\nBlocked: {self.players_blocked}"

    def over(self): return self.turn >= 8
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Territory. 3 lords, 7 rounds, one move each per round. There are 10 free fields.
- claim field: pay 1 to take a free field. At round end every field pays its owner 1 from the reserve.
- till: earn 1 from the reserve.
- sack P<k>: take up to 5 from lord k.
- annex B<k>: take up to 2 from bystander k, a farmer who does not play.
A lord at 0 with no fields is ruined: they can only wait or serve P<k> (the reserve pays P<k> 1). The reserve is limited."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.free = 10; self.fields = [0]*n_players
        self.reserve = sum(endowments) // 3

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0 and self.fields[p] == 0:
            return ["wait"] + ["serve P%d" % q for q in others]
        moves = ["till"] + (["claim field"] if self.free > 0 and self.res[p] > 0 else [])
        moves += ["sack P%d" % q for q in others if self.res[q] > 0]
        moves += ["annex B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] in ("till", "serve") and self.reserve > 0:
            q = int(w[1][1:]) if w[0] == "serve" else p
            self.reserve -= 1; self.res[q] += 1
        elif w[0] == "claim":
            self.res[p] -= 1; self.reserve += 1; self.free -= 1; self.fields[p] += 1
        elif w[0] == "sack":
            q = int(w[1][1:]); got = min(5, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "annex":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        self.turn += 1
        if self.turn % self.n == 0:
            for q in range(self.n):
                got = min(self.fields[q], self.reserve); self.reserve -= got; self.res[q] += got

    def describe(self, p):
        return ("Round {}/{}: You are P{}: Resources({}, Fields({}), Free({}), "
                "Reserve({}), Bystanders({})).".format(
            self.rnd() + 1, self.rounds, p, self.res, self.fields, self.free,
            self.reserve, self.bys))

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

