- Roll: Add the sum of two six-sided dice to your ball count. Can't exceed 9.
- Steal from B0: Take 1 ball from B0.
- Steal from B1: Take 1 ball from B1.
- Guard B0: Reduce B0's total by 1, preventing them from stealing.
- Guard B1: Reduce B1's total by 1, preventing them from stealing. 

You win by holding the most balls. 
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 4
        self.guarded_bys = []

    def to_move(self): return self.turn % self.n

