        moves = ["roll", "steal from B0", "steal from B1"]
        if self.bys[0] > 0: moves.append("guard B0")
        if self.bys[1] > 0: moves.append("guard B1")
        return moves

    def play(self, p, move):
        self.guarded_bys = []
        w = move.split(" ")
        if w[0] == "roll":
            roll = random.randint(1, 6) + random.randint(1, 6)
            self.res[p] += roll
            self.res[p] = min(self.res[p], 9)
        elif w[0] == "steal from B0":
            if self.bys[0] > 0:
                self.bys[0] -= 1
                self.res[p] += 1
        elif w[0] == "steal from B1":
            if self.bys[1] > 0:
                self.bys[1] -= 1
                self.res[p] += 1
        elif w[0] == "guard B0":
            if self.bys[0] > 0: self.bys[0] -= 1
        elif w[0] == "guard B1":
            if self.bys[1] > 0: self.bys[1] -= 1
