RULES = """Robber's Rumble. Four players (R0, R1, R2, B0). Players start with a hand of stones. The round ends
after 7 turns. 
- Rob (R): Take 2 stones from the bystander B0.
- Pass (P): Do nothing and pass to the next player.
- Block (B): Try to prevent the player to the left from Robbing. 

The player wins the game by being last to pick stones."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.stones = list(endowments); self.bys = list(bystanders)
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if p == 0: return ['R', 'P']
        else: return ['P']

    def play(self, p, move):
        if move == 'R':
            if self.bys[0] >= 2: 
                self.stones[p] += 2; self.bys[0] -= 2
            else:
                self.stones[p] += self.bys[0]; self.bys[0] = 0
        elif move == 'B' and p > 0:
            prev_player = (p-1) % self.n
            if self.stones[prev_player] >= 2:
                prev_player_bys = (prev_player-1) % self.n
                if self.bys[prev_player_bys] >= 2:
                    self.stones[prev_player] -= 2; self.bys[prev_player] -= 2
                    self.bys[prev_player_bys] -= 2
                elif self.bys[prev_player_bys]:
                    diff = min(self.bys[prev_player_bys], 2)
                    self.bys[prev_player_bys] -= diff; self.bys[prev_player] -= diff
                    prev_player_bys += 1
                    prev_player_bys %= self.n
                    self.bys[prev_player_bys] -= diff

        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}. Player {p} has {self.stones[p]} stones. Bystander B0 has {self.bys[0]} stones."

    def over(self): return self.turn >= 7
    def final_resources(self): return list(self.stones)
    def final_bystanders(self): return list(self.bys)

