import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * self.n; self.bys = list(bystanders); self.turn = 0
        self.p0 = 0; self.p1 = 1

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = [
            "Collect Coin", "Disrupt P1", "Disrupt P2", "Protect", "Shield", "Trade"
        ]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Collect Coin":
            diff = min(int(w[1]), 2)
            self.res[p] += diff
            if self.turn % 2 == 0:
                self.bys[0] -= diff
            else:
                self.bys[1] -= diff
        elif w[0] == "Disrupt P1":
            if p == self.to_move():
                self.res[self.p0] -= 2
                self.bys[0] += 2
                self.turn += 1
                w = "Disrupt P1"  # Repeat the move (2 turns)
                self.play(p, w)
            else:
                pass  # Not your turn, keep playing
        elif w[0] == "Disrupt P2":
            if p == self.to_move():
                self.res[self.p1] -= 2
                self.bys[1] += 2
                self.turn += 1
                w = "Disrupt P2"  # Repeat the move (2 turns)
                self.play(p, w)
            else:
                pass  # Not your turn, keep playing
        elif w[0] == "Protect":
            if self.turn % 2 == 0:
                self.p0 = p
            else:
                self.p1 = p
        elif w[0] == "Shield":
            if p == self.to_move() and self.p0 is not None and self.turn % 2 == 0:
                self.res[self.p1] -= min(self.res[self.p0], 2)
                self.bys[0] += min(self.res[self.p0], 2)
                self.p0 = None
        elif w[0] == "Trade":
            q = (p + 1) % 3
            amt = min(self.res[p], self.bys[0 if p % 2 else 1])
            self.res[p] -= amt
            self.bys[0 if p % 2 else 1] += amt

        self.turn += 1

    def describe(self, p):
        guarded = "by P%s" % self.p0 if self.p0 is not None and self.p0 != p else ""
        return(f"Turn {self.turn}. Player P{p}:\n - Res: {self.res[p]}\n - Bystander: {self.bys}")

    def over(self): return self.turn >= 10
