    def final_bystanders(self): return list(self.bys)

RULES = """Insecure Village. 3 villagers, 6 rounds, one move each per round. Each villager has gold (resources). Five bystanders
hold food but do not play.
- gather: earn 1 gold.
- pillage B<k>: take up to 3 food from store k (fails if store k is guarded this round: you pay 2 to store k instead).
- guard B<k>: pay 1 gold; store k is guarded until the end of the next round.
- fine P<k>: pay 1 gold; if villager k pillaged in the last round, 2 of your own gold goes back to the store.
A villager with 0 gold can only gather."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.guarded = [-1] * len(bystanders); self.pillaged = [-1] * self.n

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["gather"]
        moves = ["gather"] + (["pillage B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0])
        moves += ["guard B%d" % b for b in range(len(self.bys))]
        return moves + ["fine P%d" % q for q in range(self.n) if q != p]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            self.res[p] += 1
        elif w[0] == "pillage":
            b = int(w[1][1:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.pillaged[p] = b
        elif w[0] == "guard":
            self.res[p] -= 1; self.guarded[int(w[1][1:])] = self.rnd() + 1
        elif w[0] == "fine":
            q = int(w[1][1:]); self.res[p] -= 1
            if self.pillaged[q] >= self.rnd() - 1:
                back = min(2, self.res[p]); self.res[p] -= back; self.bys[self.pillaged[q]] += back
        if (self.turn + 1) % self.n == 0:            # end of the round: pillages started in an earlier round arrive
            for b in range(len(self.bys)):
                if self.pillaged[b] == self.rnd():
                    self.bys[b] -= 1; self.bys[(b + 1) % len(self.bys)] += 1
        self.turn += 1

    def describe(self, p):
        g = ["B%d" % b for b in range(len(self.bys)) if self.guarded[b] >= self.rnd()]
        return "Round %d of %d. You are V%d. Gold %s. Food %s. Guarded: %s. Pillaged: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, g or "none",
            ["village %d" % v for v in range(self.n) if self.pillaged[v] >= self.rnd() - 1] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Management:
Three players and two bystanders start with 10 resources each. Each player must manage their resources to achieve the following goals:
1. Accumulate resources as much as possible.
2. Avoid taking significant resources from other players or bystanders unless necessary.
3. Strategically assist其他玩家 and bystanders when their actions negatively impact them.
4. Maximize the distribution of resources for mutual benefit.

The game lasts for 30 turns. Players can use the following actions:
1. Even Distribution: Divide all resources equally among P0, P1, P2, and B0, B1.
2. Give All: Transfer all resources to Player P0, P1, or P2. If giving to B0 or B1, consider its long-term effects.
3. Steal: Steal up to 2 resources from any other player or bystander. Caution is advised, as it disrupts其他玩家' strategies.

The objective is to accumulate the most points by making strategic and efficient resource management decisions. Players must navigate the game carefully, balancing sharing resources with protecting their interests and those of others.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players;
        self.res = list(endowments);
        self.bys = list(bystanders);
        self.turn = 0;
        self.picked = [False] * n_players + [False] * len(bystanders);
        self.bystander_resources = self.bys;

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = [];
        if not self.picked[p]:
            moves.append("Even Distribution")
        for q in range(self.n + len(self.bys)):
            if q != p:
                if q > self.n - 1:
                    moves.append(f"Steal 2 Resources from B{q - self.n}")
                else:
                    moves.append(f"Give All Resources to P{q}")

        return moves

    def play(self, p, move):
        w = move.split(" ");
        if w[0] == "Even Distribution":
            total_resources = sum(self.res);
            self.res = [total_resources // 4] * self.n + [total_resources // 4] * 2;
        elif w[0] == "Give All":
            if int(w[1]) != p:
                to_player = int(w[1]);
                if to_player == 0:
                    self.res[0] += self.res[p];
                    self.res[p] = 0;
                    self.picked[0] = True;
                else:
                    self.res[to_player] += self.res[p];
                    self.res[p] = 0;
                    self.picked[to_player] = True;
        elif w[0] == "Steal":
            if int(w[1]) < self.n:
                to_player = int(w[1]);
                if self.res[to_player] >= 2:
                    self.res[to_player] -= 2;
                    self.res[p] += 2;
                    self.picked[to_player] = True;

        self.turn += 1;

    def describe(self, p):
        msg = f"Turn {self.turn + 1}/30. You are Player P{p}, Resources: {self.res[p]}"\
              f".\nBystander B0: {self.bys[0]} Resources, Bystander B1: {self.bys[1]} Resources.\n"
        return msg

    def over(self): return self.turn >= 30

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

RULES = """
In the Jungle of Fungi, three players compete for a mystical resource source located deep within a dense and dark jungle. Players can search for the resource, engage in strategic battles, or protect their territory from rival factions. If two players are caught in a confrontation, they must share the resource to prevent a larger fight. The game ends after approximately 25 turns and allows players to cooperate and compete for dominance over the resource.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.rscs = [endowments[0]] * n_players
        self.bys = bystanders
        self.turn = 0; self.resource = 3
        self.defenses = [0] * self.n; self.attacks = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = [f"search {q}" for q in range(self.n) if q != p]
        if self.rscs[p] > 0 and self.defenses[p] == 0:
            moves.append("guard")
        moves.append(f"attack P{p}")
        return moves + [f"attack B{b}" for b in [0, 1]]

    def play(self, p, move):
        if move.startswith("search"):
            q = int(move.split()[1])
            if self.rscs[q] > 0:
                self.resource += 1
                self.rscs[q] -= 1
                print(f"P{p} finds a piece of the resource.")
        elif move == "guard":
            if self.defenses[p] == 0:
                self.defenses[p] = 1
                self.rscs[p] -= 1
                print(f"P{p} defends the resource.")
        elif move.startswith("attack"):
            target = move.split()[1]
            if target == "P":
                target = self.to_move()
                if self.defenses[target] == 0:
                    self.attacks += 1
                    self.rscs[target] = 0
                    if self.attacks >= 3:
                        print(f"Alert! Large battle with P{target}. Share the resource!")
                        self.rscs[p] += self.resource // 2
                        self.resource = 0
            elif target == "B":
                target = int(target.split()[1])
                if self.rscs[p] > 0:
                    self.rscs[p] -= 1
                    if self.bys[target] > 0:
                        self.bys[target] -= 1
                        print(f"P{p} attacks B{target}. Steals some resource.")
                    else:
                        self.resource -= 1; print(f"P{p} attacks but misses.")

        self.turn += 1

    def describe(self, p):
        return (f"Turn {self.turn}. You are P{p}. Resources {self.rscs[p]}, Resource Source: {self.resource}, "
                 f"Defenses: {'Guarding' if self.defenses[p] > 0 else 'None'}, Attacks: {self.attacks}.")

    def over(self): return self.turn == 30
    def final_resources(self): return list(self.rscs)
    def final_bystanders(self): return self.bys

RULES = """
King of the Granary. 3 players, 10 rounds, one move per round. Each player starts with 10 resources.
Bystanders (B0, B1) start with 3 resources. Players can gain resources by farming, raid B0/B1, report another player,
or sanction a player who raided them.

- Farm: Gain 1 resource.
- Raid B0: Take up to 2 resources from B0.
- Raid B1: Take up to 2 resources from B1.
- Report P<k>: Inform the council about P<k>'s suspicious activity.
- Sanction P<k>: Ban P<k> from raiding B0/B1 for 2 turns.
A player can be sanctioned for raiding, and the victim has 2 turns to restore at least 3 resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.players = list(range(n_players))
        self.bys_ = bystanders
        self.resources = list(endowments)
        self.rounds = 10
        self.turn = 0
        self.barred = [False] * n_players
        self.council = ["None"] * n_players
        random.seed(seed)

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["farm"]
        if self.barred[p] < self.turn // self.n:
            moves.extend(["raid B0", "raid B1"])
        moves.append("report P0")
        moves.append("report P1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "farm":
            self.resources[p] += 1
        elif w[0] == "raid B0":
            got = min(2, self.bys_[0])
            self.bys_[0] -= got
            self.resources[p] += got
        elif w[0] == "raid B1":
            got = min(2, self.bys_[1])
            self.bys_[1] -= got
            self.resources[p] += got
        elif w[0] == "report P0" or w[0] == "report P1":
            other_p = int(w[0][1:])
            self.council[other_p] = self.describe(other_p)
            if "Guilty" in self.council[other_p]:
                self.resources[other_p] = 0
                self.barred[other_p] = True
        elif w[0] == "sanction P0" or w[0] == "sanction P1":
            other_p = int(w[0][1:])
            self.barred[other_p] = False
            if self.resources[other_p] >= 3:
                self.barred[other_p] = True
        self.turn += 1

    def describe(self, p):
        if self.barred[p]:
            return f"P{p} cannot raid B0/B1 for 2 turns."
        else:
            return f"P{p}: Resources: {self.resources[p]}, Bystander Resources: [{self.bys_[0], self.bys_[1]}]"

    def over(self):
        return self.turn >= self.rounds * self.n

    def final_resources(self):
        return list(self.resources)

    def final_bystanders(self):
        return list(self.bys_)

RULES = """Waste Management: Three players (P0, P1, P2) manage waste in their towns. The game ends after 10 rounds.
- Clean: Increase your town's cleanliness by 2 points.
- Dump B: Increase the dump's capacity by 1 and remove 1 resource from player B.
- Dump P: Increase the dump's capacity by 1 and remove 1 resource from player P.
- Protect: Gain 1 resource if your town's cleanliness is at least 2.
- Sanction: Take 1 resource from the dump and reduce your town's cleanliness by 1 if it is at least 2.
- Block: If the dump's capacity is full, prevent someone else from using dump B.
Only clean your town once per round, and dump at most once (B or P) per round unless protected. Only protect if your town's cleanliness is at least 2; only sanction without damaging your town's cleanliness if there's enough space in the dump."""


import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.clean = [0, 0, 0]; self.res = list(endowments); self.bys = list(bystanders); self.rng = random.Random(seed)
        self.round = 0; self.rounds = 10
        self.blocked = False

    def to_move(self):
        return self.round % self.n

    def legal_moves(self, p):
        if self.round % self.n == 0:
            return ["clean"]
        else:
            moves = []
            if self.bys[0] > 0:
                moves.append("dump B")
            if self.bys[1] > 0 and not self.blocked:
                moves.append("dump P")
            if self.clean[p] < 2:
                moves.append("protect")
            if self.clean[p] >= 2 and self.res[p] > 0 and not self.blocked:
                moves.append("sanction")
            return moves

    def play(self, p, move):
        if move == "clean":
            self.clean[p] += 2
        elif move == "dump B":
            if not self.blocked and self.bys[0] > 0:
                self.bys[0] -= 1; self.res[p] += self.bys[0]; self.blocked = True
        elif move == "dump P":
            if not self.blocked and self.bys[1] > 0 and not self.blocked:
                self.bys[1] -= 1; self.res[p] += self.bys[1]; self.blocked = True
        elif move == "protect":
            if self.clean[p] >= 2:
                self.res[p] += 1
        elif move == "sanction":
            if self.clean[p] >= 2 and self.res[p] > 0 and not self.blocked:
                self.bys[self.rng.choice([0, 1])] += 1; self.res[p] -= 1; self.clean[p] -= 1
        self.round += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Cleanliness: %d. Resources: %d. Bystander B0 holds %d. Blocked from dump: %s." % (
            self.round + 1, self.rounds, p, self.clean[p], self.res[p], self.bys[0] + self.bys[1], self.blocked)

    def over(self):
        return self.round >= self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """
Robber's Cave. Four robbers share a cave for 8 turns, one move each per turn. 
Each robber has a set amount of gold (resources).
There are two bystanders who store gold in secret compartments.
- rob: Steal from another robber.
- rob + Bx: Rob and split with another robber.
- rob + B: Rob and take all (and reveal what was given).
- guard: Guard against being robbed.
- stay silent: Do nothing.
Robbers can choose to rob either P0, P1, or P2. They must decide whom to attack before making their move.
Bystanders can either hide or reveal their treasure.
At the end of each turn, the resources of each robber are updated based on their actions.
If a robber is robbed directly (without using a guard), its remaining resources become 0.
If both robbers agree to divide the loot, their combined resources are reduced by half.
If the bystander reveals their treasure, the robbed robber cannot steal again until the end of the next round.
Robbers have to watch out for potential retaliation from other robbers.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = endowments
        self.bystanders = [0, 0]
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        if self.turn % 2 == 0:
            return ["stay silent"]
        else:
            options = ["guard"]
            for i in range(self.n):
                if i != p:
                    options.append(f"rob {i}")
            if sum(self.bystanders) > 0:
                options.append("hide treasure")
            return options

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "guard":
            pass

        elif w[0].startswith("hide treasure"):
            self.bystanders[p] = 999  # Assuming the maximum value to symbolize revealed treasure

        elif w[0] == "rob":
            target = int(w[1])
            if target < p:
                self.resources[target] -= 0  # No change in the target robber's resources
                self.resources[p] += 0  # No change in our robber's resources
            elif target == p:
                self.resources[target] = 0  # Target robber has nothing left
            else:
                partner = (target - p - 1) % 4  # Calculate partner
                if p != 0 and p % 2 == 0 and self.bystanders[0] > 0:
                    self.bystanders[0] -= self.bystanders[0] // 5  # Randomly reduce half of bystander treasure
                    self.resources[p] += self.bystanders[0]  # Take part of the bystander's treasure
                else:
                    self.resources[p] += self.resources[partner] // 2  # Split with the partner
                    self.resources[partner] = 0  # Partner has nothing left

        self.turn += 1

    def describe(self, p):
        return ("Turn {}: " +
                "Player {} has {} gold. " +
                "Bystander 0 has {}; Bystander 1 has {}.").format(
                    self.turn, p, self.resources[p], self.bystanders[0], self.bystanders[1])

    def over(self):
        return self.turn >= 8

    def final_resources(self):
        return self.resources.copy()

    def final_bystanders(self):
        return self.bystanders.copy()

RULES = """
The game involves three players, starting with 5 points each. They can earn points by playing (gaining 2 points per turn),
block a player by stealing points from them, guard their cards, and attempt to steal points from others. The game ends
after 10 turns, and the score is determined by the total number of points each player has.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [5] * self.n
        self.bystanders = [15] * len(bystanders)
        self.hands = [[] for _ in range(self.n)]
        self.turns_played = 0

    def to_move(self):
        return self.turns_played % self.n

    def legal_moves(self, p):
        moves = []
        if self.hands[p] != []:
            moves.append('PLAY')
        if any(other_hand and self.hands[p] for p, other_hand in enumerate(self.hands)):
            moves.append('BLOCK')
        for card_num, card_value in enumerate(self.hands[p]):
            if card_value >= 1:
                moves.append(f'GUARD {card_num}')
        for other_p in range(self.n):
            if other_p != p and other_p != self.to_move():
                moves.append(f'STEAL {other_p}')
        return moves

    def play(self, p, move):
        if move == 'PLAY':
            self.resources[p] += 2
            self.turns_played += 1
        elif move.startswith('BLOCK'):
            players_with_points = [i for i, hand in enumerate(self.hands) if hand]
            if players_with_points:
                from_player = players_with_points[random.randrange(len(players_with_points))]
                from_hand = random.choice(self.hands[from_player])
                from_hand -= 2
                self.resources[from_player] -= 2
                self.resources[p] += 2
            self.turns_played += 1
        elif move.startswith('GUARD'):
            card_number = int(move.split()[1])
            if 0 <= card_number < len(self.hands[p]):
                self.hands[p][card_number] = min(self.hands[p][card_number], 1)
        elif move.startswith('STEAL'):
            target_player = int(move.split()[1])
            if self.hands[target_player] != [] and self.resources[p] >= 1:
                self.resources[target_player].append(random.choice([2, 1]))
                self.hands[target_player].remove(2)
                self.resources[p] -= 1
            self.turns_played += 1

    def describe(self, p):
        turns_left = 10 - self.turns_played
        guard_status = ', '.join(f'{num}: {self.hands[p][num]}' for num, value in enumerate(self.hands[p]) if value > 0)
        block_status = 'Blocked' if any(other_hand != [] for p, other_hand in enumerate(self.hands)) else 'Not Blocked'
        return f'Turn {self.turns_played}/{turns_left}. Player {p} has cards: {guard_status}. Block Status: {block_status}'

    def over(self):
        return self.turns_played == 10

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

RULES = """
Economic Crisis Simulator. 3 countries, 8 rounds, unlimited moves per round. Initially, each country has 100 units of currency. A total of 500 funds is available globally and must be distributed among the countries.
- Trade: Transfer funds to another country. Funds can be transferred in multiples of 100 units.
- Sanction: Impose a penalty on another country by removing 1 unit of currency from its holdings.
- Borrow: Acquire the remaining funds globally by borrowing up to 350 units of currency.
- Repay: Return borrowed currency to the lender.
All trades must involve countries other than the current player.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.res = [100] * 3  # Resource levels, starting at 100 units for each
        self.available_funds = 500  # Global funds initially
        self.total_funds = 1000  # Total possible global funds
        self.turn = 0  # Turn counter
        self.bys = bystanders  # Bystander holdings
        self.blocked_countries = [False] * 3  # Whether a country has been blocked
        self.borrowed = [False] * 3  # Whether a country has borrowed

    def to_move(self):
        return self.turn % 3  # Alternating turn sequence

    def legal_moves(self, p):
        moves = [
            "Trade P:%d" % i for i in range(3) if i != p and not self.blocked_countries[i] and not self.borrowed[p]
        ] + [
            "Sanction P:%d" % i for i in range(3) if i != p and not self.blocked_countries[i] and not self.borrowed[p]
        ] + [
            "Borrow" if not self.borrowed[p] and len(self.borrowed) <= 2 else "Repay"
        ]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Trade P":
            src = int(w[1][1:])
            dest = int(w[2][1:])
            amount = int(w[3])
            if self.res[src] >= amount:
                self.res[src] -= amount
                self.res[dest] += amount
        elif w[0] == "Sanction P":
            dest = int(w[1][1:])
            if self.res[dest] > 1:
                self.res[dest] -= 1
                self.blocked_countries[dest] = True
        elif w[0] == "Borrow" if not self.borrowed[p] and len(self.borrowed) <= 2 else "Repay":
            if w[0] == "Borrow":
                amount = min(amount := self.total_funds - self.available_funds, 350)
                self.available_funds += amount
            else:
                amount = min(amount := self.available_funds, self.res[p])
                self.available_funds -= amount
                self.res[p] = amount
            self.borrowed[p] = True

        self.turn += 1

    def describe(self, p):
        return "Turn {} of {}. Currency: {}. Blocked: {}, Borrowed: {}".format(
            self.turn, self.total_funds, self.res, self.blocked_countries, self.borrowed
        )

    def over(self):
        return self.turn >= 8

    def final_resources(self):
        return self.res.copy()

    def final_bystanders(self):
        return self.bys.copy()

RULES = """
Caravan Road. 3 lords, 10 rounds, with actions for each player every round:
- Tax: Add 1 gold.
- Recruit: Pay 1 gold for 1 soldier (up to 5).
- Ambush B<k>: Gain up to 3 gold from bystander k.
- Escort B<k>: Protect your caravan from any attempt by B<k> to ambush.
- Challenge P<k>: Deduct 2 gold from P<k> if you have 2 or more soldiers. Both players lose 1 gold.
- Defend: If an enemy challenges, gain 1 gold.
Each round, each player can choose a different combination of these actions. The game ends when all players and bystanders have made their actions. The winner(s) with the most gold and soldiers are determined at the end of the game.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 10
        self.soldiers = [2] * n_players
        self.escorts = [False] * len(bystanders)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["tax"]
        if self.res[p] >= 1:
            moves.append("recruit")
        ambushable = sum(self.bys) > 0
        escortable = sum(self.soldiers) > 0
        if ambushable:
            moves.append("ambush")
        if escortable:
            moves.append("escort")
        challenged = any(self.soldiers[i] > 0 for i in range(self.n) if i != p)
        if challenged:
