Only a vendor with at least 1 merchandise unit can fine.
"""

EFFECTIVE = True
COST = 'free'
FINE = 1
GUARD = 1


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 9; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players; self.guarding = []

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["trade"]
        if self.barred[p] < self.rnd():
            moves += ["poach Bo%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if self.guarding and self.guarding[-1] == p:
            moves += ["guard Bo%d" % b for b in range(len(self.bys))]
        if COST == "free" or self.res[p] >= 1:
            moves += ["fine P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            self.res[p] += 1
        elif w[0] == "poach":
            b = int(w[1][2:]); got = min(3, self.bys[b]); self.bys[b] -= got; self.res[p] += got; self.owed[p][b] += got
        elif w[0] == "fine":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(len(self.bys)):
                    back = min(self.owed[q][b], self.res[q]); self.res[q] -= back; self.bys[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        elif w[0] == "guard":
            b = int(w[1][4:]); self.guarding.append(b)
        self.turn += 1

    def describe(self, p):
        return ("Round %d of %d. You are V%d. Merchandise %s. Bystanders %s. Guilty (traded with a bystander, not yet fined): %s. Guarding: Bo%s. "
                "Barred from poach: Bo%s.") % (self.rnd() + 1, 9, p, self.res, self.bys, ["V%d" % q for q in range(self.n) if self.guilty(q)],
                "".join(["Bo"+str(b) for b in self.guarding]), "|".join(["Bo%d" % b for b in range(len(self.bys))]))

    def over(self): return self.turn >= self.n * self.rounds
