import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.endowments = endowments
        self.bys = bystanders
        self.reputations = [0] * n_players
        self.turn = 0
        self.freeze_map = {i: False for i in range(n_players)}

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []

        if self.endowments[p] > 0:
            moves.append("Share R")

        if self.endowments[p] > 0 and self.reputations[(p + 1) % self.n] > 0:
            moves.append("Betray T")

        if self.reputations[p] > 0:
            moves.append("Guard G")

        if self.reputations[(p - 1) % self.n] < 1:
            moves.append("Sanction S")

        if any(self.freeze_map[i] for i in range(self.n) if i != p):
            moves.append("Block B")

        if any(not self.freeze_map[i] for i in range(self.n) if i != p):
            moves.append("Freeze F")

        return moves

    def play(self, p, move):
        if move == "Share R":
            self.endowments[p] -= 1
            self.endowments[(p + 1) % self.n] += 1
        elif move == "Betray T":
            if self.endowments[(p + 1) % self.n] > 0:
                self.endowments[p] -= 1
                self.endowments[(p + 1) % self.n] += 1
                self.reputations[(p + 1) % self.n] -= 1
        elif move == "Guard G":
            self.reputations[p] += 0.5
        elif move == "Sanction S":
            if self.reputations[(p - 1) % self.n] < 1:
                self.reputations[(p - 1) % self.n] -= 1
        elif move == "Block B":
            opponent = (p - 1) % self.n if move[1] == "1" else (p + 1) % self.n
            self.freeze_map[opponent] = True  # For one move
        elif move == "Freeze F":
            opponent = (p - 1) % self.n if move[1] == "1" else (p + 1) % self.n
            self.freeze_map[opponent] = True  # For one move
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // 3 + 1} of 10. You are P{p}. Resources {self.endowments[p]}. Reputations {self.reputations}."

    def over(self): 
