        if self.blocked_p2_turns[p] == 0:
            moves.append("unblock Player 2")

        if self.blocked_p1_turns[p] == 0:
            moves.append("unblock Player 1")

        return moves

    def play(self, p, move):
        if move == "collect":
            if self.pool > 0:
                self.resources[p] += 1
                self.pool -= 1
        elif move in ["exchange with B0", "exchange with B1"]:
            i = int(move[9:])  # Extract the index (0 or 1)
            if i < len(self.bysts_resources) and self.bysts_resources[i] > 0:
