                f"You have {self.resources[p]} resources. "
                f"Pool has {self.pool} resources. "
                f"Guilty: {self.owed_resources[p]}. "
                f"Blocked Player 2 this turn: {blocked_p2}. "
                f"Blocked Player 1 this turn: {blocked_p1}")

    def over(self):
