        if self.res[p] >= 0 and (3, self.places[self.to_move()]) in self.routes:
            moves.append("Defend")
        if self.barred[p] < self.turn:
            moves.append("Sabotage")
        if self.res[p] > 1:
            moves.append("Repair")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Explore":
            self.res[p] -= 1
