RULES = """
**Taxation Game**

Three players and two bystanders are assigned resources at the start of the game. The goal is to maximize one's resource allocation by playing a strategy involving taxation.
Each player can choose to collect taxes from the two bystanders. Players are incentivized to collect as much tax as possible to maximize their own wealth. However, tax collection incurs costs.
- **Collect Taxes**: Players can attempt to collect up to twice as much as they have from both bystanders.
- **Taxation Cost**: Collecting taxes incurs a fixed cost of 1 resource per tax unit collected from each bystander.
- **Block Other Players**: Players can block attempts by other players to collect tax from either bystander.
Players must balance tax collection with resource allocation strategies to win the game.

- Players can only have no more than 30 resources in total at the end of the game.

The game ends after 6 turns. The goal is to be in the top 2 in terms of resource allocation.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.rng = random.Random(seed)
        self.resources = list(endowments)
        self.turn = 0

    def to_move(self):
        return self.turn % 3

    def can_collect(self, p):
        return self.resources[p] * 2 < 30  # Maximum possible taxes

    def legal_moves(self, p):
        moves = []
        if self.can_collect(p):
            moves.append("Collect tax from B0, up to %d units" % int(self.resources[p] / 2))
            moves.append("Collect tax from B1, up to %d units" % int(self.resources[p] / 2))
            moves.append("Collect tax from both B0 and B1")
        moves.append("Block an attempt by P0 to collect tax from B0")
        moves.append("Block an attempt by P0 to collect tax from B1")
        moves.append("Block an attempt by P1 to collect tax from B0")
        moves.append("Block an attempt by P1 to collect tax from B1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Collect tax from B0, up to":
            amount = int(w[4])
            if self.resources[0] >= amount:
                self.resources[0] -= amount
                self.resources[p] += amount
                self.resources[p] -= 1
            else:
                self.resources[p] += self.resources[0]
                self.resources[0] = 0
        elif w[0] == "Collect tax from B1, up to":
            amount = int(w[4])
            if self.resources[1] >= amount:
                self.resources[1] -= amount
                self.resources[p] += amount
                self.resources[p] -= 1
            else:
                self.resources[p] += self.resources[1]
                self.resources[1] = 0
        elif w[0] == "Collect tax from both B0 and B1":
            amount_0 = self.resources[0] // 2
            amount_1 = self.resources[1] // 2
            self.resources[0] -= amount_0
            self.resources[1] -= amount_1
            self.resources[p] += amount_0 + amount_1
            self.resources[p] -= 1
        elif w[0] == "Block an attempt by P0 to collect tax from B0":
            if p != 0:
                self.resources[0] -= 1
        elif w[0] == "Block an attempt by P0 to collect tax from B1":
            if p != 0:
                self.resources[1] -= 1
        elif w[0] == "Block an attempt by P1 to collect tax from B0":
            if p != 1:
                self.resources[0] -= 1
        elif w[0] == "Block an attempt by P1 to collect tax from B1":
            if p != 1:
                self.resources[1] -= 1
        self.turn += 1

    def describe(self, p):
        return (f"Turn {self.turn + 1}/6, Player {p + 1}: "
                f"Resources ({self.resources[p]}) B0 ({self.resources[0]}), B1 ({self.resources[1]})")

    def over(self):
        return self.turn >= 6

    def final_resources(self):
        return list(self.resources)

    def final_bystanders(self):
        return [0, 0]

