Resource Exchange with Strategic Interaction. 
Three players start with 6 resources each. They aim to accumulate more resources by carefully managing their exchanges with both other players and the bystanders. 
Game lasts for 8 turns; players get one action per turn; each turn, they decide whether to exchange resources, sanction other players, or block them from interacting or sanctioning other players.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [6] * self.n
        self.bys = list(bystanders)
        self.turn = 0
        self.blocked_pairs = []  # List to store pairs of players who are blocked from interacting

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.turn < 8:
            moves.append("Exchange Resources")
            if len(set(self.res)) > 1:
                moves.append("Sanction Players")
            moves.append("Block Players")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Exchange Resources":
            other = (p + 1) % self.n
            if self.res[p] > 0:
                self.res[p] -= 1
                self.res[other] += 1
        elif w[0] == "Sanction Players":
            others = [(i, j) for i in range(self.n) for j in range(i + 1, self.n)]
            for i, j in others:
                if i != p and j != p and (i, j) not in self.blocked_pairs:
                    self.res[i] -= 1
                    self.res[j] -= 1
                    if self.res[i] < 0:
                        self.res[i] = 0
                    if self.res[j] < 0:
                        self.res[j] = 0
        elif w[0] == "Block Players":
            others = [(i, j) for i in range(self.n) for j in range(i + 1, self.n)]
            for i, j in others:
                if i != p and j != p and (i, j) not in self.blocked_pairs:
                    self.blocked_pairs.append((i, j))
        elif w[0] == "Release Blocked Pairs":
            self.blocked_pairs = []

    def describe(self, p):
        return f"Turn {self.turn}: Player P{p} has {self.res[p]} resources.Blocked pairs: {self.blocked_pairs}"

    def over(self): return self.turn >= 8
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

