                 "Defend P0", "Defend P1", "Reform Bystanders"]
        return moves

    def play(self, p, move):
        moves = move.split(" ")
        if moves[0] == "Collect":
            collected = min(5, self.pool)
            self.pool -= collected; self.res[p] += collected
        elif moves[0] == "Send to Player P0":
