        moves = ["Move", "Collect", "Influence", "Guard", "Sanction", "Block"]
        if p >= 1:  # Only P1 can Influence
            moves.remove("Influence")
        return moves

    def play(self, p, move):
        if move == "Move":
            i, j = divmod(p, 3)
            i = (i + 1) % 3
            self.resources[i], self.resources[p] = self.resources[i] + 1, self.resources[p] - 1
        elif move == "Collect":
            if p > 0 and self.bys_turn and self.bys[p - 1] > 0:
                self.resources[p] += self.bys[p - 1]
                self.bys[p - 1] = 0
        elif move == "Influence":
            self.bys[0] = max(0, self.bys[0] + 3)
        elif move == "Guard":
            if p > 0:
                self.resources[p] -= 2
        elif move == "Sanction":
            if p > 0 and self.bys_turn:
