        elif move == "Block":
            if p > 0:
                self.resources[p] += self.bys[p - 1]
                self.bys[p - 1] = 0

        self.turn += 1
        if not self.bys_turn:
            self.bys_turn = True
            self.bys_turn = False
        else:
            self.bys_turn = True

    def describe(self, p):
        turn_description = f"Turn {self.turn} of 30. Player {p} resources: {self.resources[p]}"
