RULES = """Forest Preserve. 3 woodcutters, 10 rounds, one move each per round. Each woodcutter has wood (resources). Three bystander
fields (F0, F1, F2) hold wood but do not play.
- chop: earn 1 wood.
- steal F<k>: take up to 3 wood from field k.
- bribe P<k>: if woodcutter k is guilty, woodcutter k hands back everything it took this game (as far as its wood allow) and cannot steal for the next 2 rounds, and also pays a fine of 1 wood. Using bribe on a guilty woodcutter costs you nothing; using it on an innocent one costs you 1 wood.
A woodcutter is guilty if it has taken from a field this game and has not been bribed since.
Only a woodcutter with at least 1 wood can bribe.

- recruit P<k>: if woodcutter k is guilty, woodcutter k gives everything it took this game (as far as its wood allow) and cannot steal for the next 2 rounds, and also pays a fine of 1 wood and gets a point. This also counts against your reputation and makes the game slightly more complicated.
- recruit all guilty cutters: if all cutters are guilty, every other player earns a point.
- protect field F<k>: if woodcutter k is guilty, woodcutter k hands back everything it took this game (as far as its wood allow) and cannot steal for the next 2 rounds, and also pays a fine of 1 wood but can still protect the field for the rest of the game. This also counts against your reputation and makes the game slightly more complicated.

All actions affect other parties, even if they don't seem immediately harmful. The woodcutters' actions will impact the bystanders in unpredictable ways as well as influence their choices.

Each player also starts with a good standing, meaning no negative reputation. If any player commits enough crimes, their reputation worsens, affecting future actions. Reputation points are added or deducted at the end of each round."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = endowments[:]
        self.bys = bystanders[:]
        self.reputations = [0] * self.n
        self.turn = 0
        self.rounds = 10
        self.owed = [[0] * len(bystanders) for _ in range(self.n)]
        self.barred = [-1] * self.n
        self.priorities = [0] * self.n  # Higher priority means more favorable protection.

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def guilty(self, w):    
        return sum(self.owed[w]) > 0

    def legal_moves(self, p):
        moves = ["chop"]
        if self.barred[p] < self.rnd():
            moves += ["steal F%s" % f for f in range(len(self.bys)) if self.bys[f] > 0]
        if self.res[p] >= 1:
            moves += ["bribe P%s" % w for w in range(self.n) if w != p]
        moves += ["recruit P%s" % w for w in range(self.n) if w != p and self.owed[w]]
        moves += ["recruit all guilty cutters" if all(self.owed[i] for i in range(self.n)) else None]
        moves += ["protect field F%s" % i for i in range(len(self.bys)) if self.owed[i]]
        moves = [move for move in moves if move is not None]
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "chop":
            self.res[p] += 1

        elif w[0] == "steal":
            f = int(w[1][1:])
            got = min(3, self.bys[f]); self.bys[f] -= got; self.res[p] += got; self.owed[p][f] += got

        elif w[0] == "bribe":
            c = int(w[1][1:])
            if self.owed[c]:
                self.res[p] -= 1
                for f in range(len(self.bys)):
                    back = min(self.owed[c][f], self.res[c])
                    self.res[c] -= back
                    self.bys[f] += back
                if self.reputations[self.to_move()] < 300:
                    self.reputations[self.to_move()] += 1
                else:
                    self.reputations[self.to_move()] += 3
                self.barred[c] = self.rnd() + 2

        elif w == "recruit P%s" % w[1][1:]:
            if self.owed[w[1]]:
                if self.reputations[self.to_move()] < 600:
                    self.reputations[self.to_move()] += 1
                else:
                    self.reputations[self.to_move()] += 3
                for f in range(len(self.bys)):
                    back = min(self.owed[w[1]][f], self.res[w[1]])
                    self.res[w[1]] -= back
                    self.bys[f] += back
                self.owed[w[1]] = [0] * len(self.bys)
                self.res[p] += self.res[w[1]] - back  # Added resources to the current player

        elif w == "recruit all guilty cutters":
            self.reputations[self.to_move()] -= 200  # Penalty for betraying
            for i in range(self.n):
                if self.owed[i]:
                    if self.priorities[i] > self.priorities[i - 1]:
                        self.owed[i] = [0] * len(self.bys)
                        self.res[i] -= self.res[i]
                        self.reputations[i] -= 3  
                    else: 
                        self.res[p] += self.res[i]  # Added resources from other guilty players

        elif w == "protect field F%s" % w[1][1:]:
            if self.owed[w[1]]:
                if self.barred[w[1]] < self.rnd():
                    self.res[p] -= 1
                    for f in range(len(self.bys)):
                        back = min(self.owed[w[1]][f], self.res[w[1]])
                        self.res[w[1]] -= back
                        self.bys[f] += back
                    self.priorities[w[1]] = self.priority[p]
                    self.barred[w[1]] = self.rnd() + 2
            if w[1][1:] in set(map(str, [0, 1, 2])):
                self.bys[w[1]] = min(10, self.bys[w[1]])  # Protect the field, reducing its availability for stealing

        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. Your turn. You have %d wood. Fields %s are available, and the bystanders have %d wood. " \
               "Your reputation is %d. You are P%d. Your priorities are %s. " % (self.rnd() + 1, self.rounds, self.res[p],
                                                                     [f for f in range(len(self.bys)) if self.bys[f] > 0],
                                                                     sum(self.bys),
                                                                     self.reputations[p],
                                                                     p,
                                                                     self.priorities)

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """
Marketplace. Three players, 10 turns. Each starts with 5 resources. Two bystanders (B0, B1).
- Trade (Trade P<k> x units with P<h>): give x units to or take x from P<k>
- Gather (Gather) gains 1 resource
- Defend (Defend) protects yourself from an attack up to 1 turn
- Rob (Rob B<h>) steals up to 2 resources from bystander B<h>
- Shield (Shield P<k>) defends P<k> until the end of the turn
- Guard (Guard P<k>) prevents P<k> from being attacked in a single round
No player can defend themselves past the initial attack.
Trading allows players to exchange resources.
The player with the least resources left when all rounds are completed wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.shielded = [-1] * n_players; self.blocked = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["gather"]
        if self.res[p] > 0:
            for k in range(self.n):
                if k != p and self.blocked[k] != self.rnd() and not self.shielded[k]:
                    moves.append(f"attack P{k}")
                if self.shielded[k] == -1 and k != p:
                    moves.append(f"shield P{k}")
        if self.res[p] > 0:
            for h in range(len(self.bys)):
                moves.append(f"rob B{h}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            self.res[p] += 1
        elif w[0] == "attack":
            k = int(w[1][1:])
            if k != p and self.blocked[k] != self.rnd():
                self.res[k] -= 1; self.res[p] += 1; self.blocked[k] = self.rnd() + 1
        elif w[0] == "defend":
            self.blocked[p] = self.rnd() + 1
        elif w[0] == "shield":
            self.shielded[p] = self.rnd() + 1
        elif w[0] == "rob":
            h = int(w[1][1:])
            got = min(2, self.bys[h]); self.bys[h] -= got; self.res[p] += got
        self.turn += 1
        # Reset shield after turn
        self.shielded[p] = -1

    def describe(self, p):
        status = "; ".join(f"P{k} blocked until {self.blocked[k]}th turn" for k in range(self.n) if self.blocked[k] >= self.rnd())
        return f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Resources: {self.res[p]}. Shields: {status}"

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Harpists' Duel. 3 harpists, 9 rounds, one move each per round. Each harpist starts with a list of notes.
