            moves.extend(["Defend Resources P1", "Defend Resources P2", "Cooperate on Resources P1", "Cooperate on Resources P2"])
        else:
            moves.extend(["Claim Resources", "Defend Resources P1", "Defend Resources P2", "Cooperate on Resources P1", "Cooperate on Resources P2"])
