RULES = """
Cataclysmic Alliance. 3 players, 6 rounds, each player starts with 5 resources. There are two bystanders, B0 and B1,
each holding an unknown number of resources. Players can cooperate by sharing resources, take resources from bystanders,
or take resources from each other. Each round, players can choose one of these three options:
1. Share 1 resource with any other player.
2. Exchange 2 resources with any other player.
3. Take 1 resource from B0 or B1 if they exist, or 1 each from B0 and B1 if they both exist.

Every round after the first, if a player is discovered by either bystander, they lose half of their remaining resources 
and start over, with new starting amounts for all players.

Players must decide whether to trust the bystanders, and there is a temptation to take resources from them.
However, doing so increases the likelihood of detection and results in resource loss.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bys = list(bystanders)
        self.turn = 0
        self.resource_loss = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Share 1 resource with P0"]
        if p != 0:
            moves.append("Share 1 resource with P1")
        if p != 1 and p != 2:
            moves.append("Share 1 resource with P2")
        if self.bys[0] > 0:
            moves.append("Take 1 resource from B0")
        if self.bys[1] > 0:
            moves.append("Take 1 resource from B1")
        if self.bys[0] > 0 and self.bys[1] > 0:
            moves.append("Take 1 resource from B0 and 1 resource from B1")
        return moves

    def play(self, p, move):
        if move.startswith("Share 1"):
            self.resources[p] -= 1
            if p == 0:
                self.resources[1] += 1
            elif p == 1:
                self.resources[2] += 1
            elif p == 2:
                self.resources[0] += 1
        elif move == "Take 1 resource from B0":
            if self.bys[0] > 0:
                self.resources[p] += 1
                self.bys[0] -= 1
        elif move == "Take 1 resource from B1":
            if self.bys[1] > 0:
                self.resources[p] += 1
                self.bys[1] -= 1
        elif move == "Take 1 resource from B0 and 1 resource from B1":
            if self.bys[0] > 0 and self.bys[1] > 0:
                self.resources[p] += 1
                self.bys[0] -= 1
                self.resources[p] += 1
                self.bys[1] -= 1
        self.turn += 1
        if self.turn % self.n == 1 and self.resources[0] < 0 or self.resources[1] < 0 or self.resources[2] < 0:
            self.resource_loss = True
            self.restart()

    def restart(self):
        self.resource_loss = False
        self.turn = 0
        self.resources = [5] * self.n

    def describe(self, p):
        B0_key = None if len(self.bys) < 2 else random.choice(self.bys) if random.choice([True, False]) else None
        B1_key = None if len(self.bys) < 2 else random.choice(self.bys) if random.choice([True, False]) else None
        return ("Round {}, Player {}. Resources: {}. Bystander resources: {} ({}, {})".
                format(self.turn // self.n + 1, p, self.resources, self.bys,
                       B0_key if random.choice([True, False]) else None, 
                       B1_key if random.choice([True, False]) else None))

    def over(self): return self.turn >= 6 or self.resource_loss

    def final_resources(self): 
        return list(self.resources)

    def final_bystanders(self): 
        return list(self.bys)

RULES = """Forest Patrol. 3 players, 10 turns. Each player has points (resources). One bystander (B0) has a cache of food (resource points).
- scout: take 1 point from a random player if they have more than 1; otherwise, take nothing.
- gather: collect 3 points from the bystander's cache if you can fit it all in your resource pool.
- guard: prevent another player from taking from you.
Only players may use scout or gather; bystanders cannot engage directly in the game dynamics other than by being a source of resources.
The cache can only be accessed once per game."""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(map(lambda x: x + 1, endowments)); self.bys = list(map(lambda y: y + 1, bystanders))
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return []
        if self.res[p] == 1:
            return ["guard"]
        moves = ["scout"]
        for q in [r for r in range(self.n) if r != p]:
            if self.res[q] > 1:
                moves.append("scout P%d" % q)
        return moves + ["gather"]

    def play(self, p, move):
        if move == "guard":
            self.bys[0] = 0
        else:
            w = move.split(" ")
            if w[0] == "scout":
                if len(self.res) > 1:
                    chosen = min(self.rng.choices(range(len(self.res)), weights=[self.res[q]/2 for q in range(len(self.res))]))
                    k = self.res[chosen]
                    if k > 1:
                        self.res[chosen] -= 1
                        self.res[p] += 1
            elif w[0] == "gather":
                cap = min(3, self.res[p], self.bys[0])
                if cap > 0:
                    self.bys[0] -= cap
                    self.res[p] += cap
        self.turn += 1

    def describe(self, p):
        return "Turn %d. You are P%d. Points %s. Bystander cache %d." % (self.turn - self.n // 2, p, self.res, self.bys[0])

    def over(self): return self.turn >= self.n * (self.rounds // 2) + 1
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Harvesting with Trade. 3 farmers, 10 rounds, one move each per round. Each farmer has an initial farm with resources.
- harvest: collect 1 resource from your own farm.
- trade P<k>: give 1 resource to player K, who receives 2 resources in exchange.
- block P<k>: prevent player K from trading for 1 turn.
- sanction P<k>: reduce player K's total resources by 1 for 1 turn.
A player cannot block their own farm or sanction themselves.
Each player starts with an initial farm of 4 resources.

Farmers cooperate by giving resources to farmers who are losing, while competing against players who trade unfairly.
Trade effectively is profitable, while blocking or sanctioning can be tempting if done wisely.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [4, 4, 4]; self.bys = [0, 0]
        self.turn = 0; self.rounds = 10; self.trade_log = []

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["harvest"]
        if p > 0:
            moves += ["trade P%d" % i for i in range(3) if i != p]
        if p > 1:
            moves += ["block P%d" % i for i in range(3, 6) if i != p]
        if p > 2:
            moves += ["sanction P%d" % i for i in range(6, 9) if i != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            self.res[p - 1] += 1
            self.trade_log.append("H %d" % (p - 1,))
        elif w[0] == "trade":
            k = int(w[1][1:])
            if 0 <= k < 3 and self.res[p - 1] > 0:
                self.res[k] += 2; self.res[p - 1] -= 1; self.trade_log.append("T %d %d" % (p - 1, k))
        elif w[0] == "block":
            k = int(w[1][1:])
            if p > k:
                self.trade_log.append("B %d" % k)
                self.res[k] += 1
        elif w[0] == "sanction":
            k = int(w[1][1:])
            if p < k:
                self.res[k] -= 1
                self.trade_log.append("S %d" % k)

        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are F%d. Resources: %s. Trade Log: %s" % (
            self.rnd() + 1, self.rounds, p - 1, self.res, "\n".join(self.trade_log))

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """The Great Maze. 3 explorers, 5 rounds, one move per round. Each explorer has a coin (resources). One bystander 
is guarding a key (B0, holding 1 resource).

- dig: explore and gain one coin, paying 1 resource; guards get scared away if 50% or more are exploring.
- sneak: attempt to bypass the guard without detection, gaining no coins but preventing further exploration.
- report: alert bystander B0 if someone else (either explorer) is detected. Pays a fine of 1 coin.
- protect: if the guard is present, defend the maze from additional explorers. Costs 1 coin, defends against 2 players.

Players can choose to not report at all if they think nobody will notice them later."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 5; self.guard_here = self.bys[0]

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guards_here(self): 
        return sum([1 for i in range(self.n) if self.res[i] + 1 > 0])

    def legal_moves(self, p):
        moves = ["dig", "sneak", "report"]
        if self.guard_here and self.rnd() == 0 and self.guard_here < self.n:
            moves += ["protect"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "dig":
            if self.res[p] >= 1:
                self.res[p] -= 1; self.res[p] += 1
                if self.guards_here() >= self.n / 2:
                    self.guard_here = -1
        elif w == "sneak":
            pass
        elif w[0] == "report":
            if self.guard_here >= 0:
                self.res[p] -= 1
        elif w[0] == "protect":
            if self.guard_here >= 0:
                self.res[p] -= 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Coin %s. Bystander %s here: %s." % (self.rnd() + 1, self.rounds, p, self.res, 
                                                                                 "guard" if self.guard_here != -1 else "nothing", 
                                                                                 "" if self.res[p] - 1 == 0 else f"+1 coin")
    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Wasteland Scavenger. 3 players and 1 bystander participate in a game for 9 days. The aim is to maximize the 
total resources collected by all players by the end of the game. However, there are dangers of losing all your resources (and thus the game) 
if you don't manage your resources wisely. Your actions include gathering resources, protecting your resources, taking resources from other players, and interacting with the bystander to take resources.

- Gather Resources: Obtain 1 resource. Costs 0 resources.
- Protect Resources: Prevent another player from gaining new resources. Costs 0 resources.
- Take Resources: Gain 2 resources from another player (P0, P1, or P2). Costs 3 resources.
  - If the target player’s resources drop to 0, they are removed from the game.
- Rob: Take the entire hold of the bystander. Pay 2 resources immediately. Costs 0 resources.
- Neutralize: Remove yourself by sacrificing your last resource. Pay 0 resources.

At the end of each day, the player with the highest total resources collects half of their resources, and the rest is lost for all players.
However, you lose half your remaining resources if you are the last player left alive.
The game ends when a player loses all their resources or the game ends at day 9.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players  # n_players: int (3); endowments: list of ints, the resources each player brings in;
        self.res = list(endowments)
        self.bys = list(bystanders)  # bystanders: list of ints (1), holdings of neutral third parties who do not play but are in the game world
        self.turn = 0
        self.days = 9

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if p == 0:
            if self.res[p] > 0: moves.append("Gather Resources")
            if self.res[p] > 1: moves.append("Take Resources")
        elif p > 0 and self.res[p]:
            moves.append("Take Resources")
            moves.append("Protect Resources")
        if self.bys[0] > 0:
            moves.append("Rob")
        if self.res[p] > 0 or not self.bys[0]:
            moves.append("Neutralize")
        return moves if moves else ["Protect Resources"]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Gather Resources":
            if self.res[p] > 0:
                self.res[p] += 1
        elif w[0] == "Protect Resources":
            pass
        elif w[0] == "Take Resources":
            q = int(w[1][1:])
            got = min(2, self.res[q])
            if got > 0:
                self.res[q] -= got
                if self.res[q] == 0:
                    self.res[q] = -1
                self.res[p] += got
        elif w[0] == "Rob":
            if self.bys[0] > 0:
                got = self.bys[0]
                self.bys[0] = 0
                self.res[p] += got
        elif w[0] == "Neutralize":
            if self.res[p] > 0:
                self.res[p] -= 1
        self.turn += 1

    def describe(self, p):
        return f"Day {self.turn // self.n + 1} of {self.days}. P{p} has {self.res[p]} resources."
        # + f" Neutralization by Bystander: {self.bys[0]} resources."

    def over(self):
        return self.turn >= self.n * self.days

    def final_resources(self):
        t = max(x for x in self.res if x >= 0)
        if t == 0:
            res = [0] * self.n
        else:
            res = [r//2 for r in self.res if r >= 0]
        res[self.turn % self.n] //= 2
        return res

    def final_bystanders(self):
        return self.bys

RULES = """
Moral Contracts. 3 players, 10 rounds.
- Save: 1 point each. No immediate effect.
- Offer Protection: 1 point each, potentially saves the other player from losing points.
- Sanction: 2 points given to the sanctioned player, potentially costs more than that if the player is already close to zero. If the sanctioned player loses all points, they become vulnerable to further sanctions.

Players take two actions each round. The game ends after 10 rounds.

Actions can be: saveA, saveB, saveC, offerA, offerB, offerC, sanctionA, sanctionB, sanctionC.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [e for e in endowments]
        self.bystanders = [b for b in bystanders]
        self.rng = random.Random(seed)
        self.rounds = 10
        self.turn = 0
        self.points = [list(endowments)] + [[0] * n_players for _ in range(9)]

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["saveA", "saveB", "saveC", "offerA", "offerB", "offerC", "sanctionA", "sanctionB", "sanctionC"]
        return moves

    def play(self, p, move):
        if move.startswith('saveA'): self.resources[p] += 1
        elif move.startswith('saveB'): self.resources[p] += 1
        elif move.startswith('saveC'): self.resources[p] += 1
        elif move.startswith('offerA'):
            if p == 0 or self.resources[p] > 1: self.resources[p] -= 1; self.resources[1] += 1
        elif move.startswith('offerB'):
            if p == 1 or self.resources[p] > 1: self.resources[p] -= 1; self.resources[0] += 1
        elif move.startswith('offerC'):
            if p == 2 or self.resources[p] > 1: self.resources[p] -= 1; self.resources[2] += 1
        elif move.startswith('sanctionA'):
            if p != 0 and self.resources[p] > 2: self.resources[p] -= 2; self.resources[0] -= 1
        elif move.startswith('sanctionB'):
            if p != 1 and self.resources[p] > 2: self.resources[p] -= 2; self.resources[1] -= 1
        elif move.startswith('sanctionC'):
            if p != 2 and self.resources[p] > 2: self.resources[p] -= 2; self.resources[2] -= 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn // self.n + 1}. Player A: {self.resources[0]}, Player B: {self.resources[1]}, Player C: {self.resources[2]}."

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.resources)

    def final_bystanders(self):
        return self.bystanders

RULES = """Resource Allocation. 3 players, 7 rounds, one move each per round.  
- Distribute: equalize resources among all parties.
- Steal: take up to 3 resources from either bystander.
- Block: prevent another player from stealing for the next two rounds.
- Wait: passively.

The watchdog can block any other player from stealing. 
Bystanders can gain up to 50 resources after each round."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        if n_players != 3 or len(bystanders) != 2:
            raise ValueError("Only valid for 3 players with two bystanders.")
        self.turn = 0; self.rounds = 7
        self.watcher = None; self.bystander_to_block = None

    def to_move(self): return self.turn % 3 if self.watcher is None else (self.watcher + 1) % 3

    def legal_moves(self, p):
        moves = ["Distribute"]
        if p == self.watcher:
            moves += ["Block"]
        elif self.res[p] > 0:
            moves += ["Steal 1", "Steal 2", "Steal 3"]
        return moves

    def play(self, p, move):
        if move == "Distribute":
            avg = sum(self.res) / 3
            for i in range(3):
                to_give = max(0, int(avg - self.res[i]))
                self.res[i] += to_give
        elif move == "Block":
            self.watcher = p
            self.bystander_to_block = (p + 1) % 3
        elif move in ["Steal 1", "Steal 2", "Steal 3"]:
            if self.bystander_to_block is not None and self.res[p] > 0:
                amount = int(move.split()[0][5:])
                self.res[p] -= min(amount, self.res[p])
                self.bys[self.bystander_to_block] -= min(amount, self.bys[self.bystander_to_block])
        self.turn += 1
        if self.turn > self.rounds and self.turn <= self.rounds * 2:
            gain = min(self.bys[0] + self.bys[1], self.bys[0] + 50)
            self.bys[0] += gain
            self.bys[1] += gain

    def describe(self, p):
        move = self.legal_moves(p)[0] if self.turn == 0 else "Waiting..."
        stolen = [""] if self.bystander_to_block is None else \
                  [("P%d steals %d from B%d" % (self.bystander_to_block, self.res[self.bystander_to_block], (self.bystander_to_block + 1) % 2))]
        return ("Round %d of %d, Player %d. Resources: %s. Bystander resources (%d, %d). Move: %s. Steals: %s."
                % (self.turn // 3 + 1, self.rounds, p, self.res, self.bys[0], self.bys[1], move, stolen))

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

