- Take Wall Tokens: Use a temporary wall. Destroy the temporary wall, spending 1 token. If the wall was destroyed by a player's action or ended at the end of this round without being used, the player gets all tokens on the wall plus 1 additional token."""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.tokens = list(endowments)
        self.bystanders = list(bystanders)
        self.turn = 0
        self.rounds = 9
        self.walls = [False] * self.n

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["guard T"]
        if self.bystanders[0] > 0: moves.append("take 1 token from T0")
        if self.bystanders[1] > 0: moves.append("take 1 token from T1")
        if self.bystanders[0] > 0 or self.bystanders[1] > 0: moves.append("take all tokens from T")
        if self.walls.count(False) > 0: moves.append("build wall")
        return moves

    def play(self, p, move):
        if move == "guard T":
            if self.tokens[p] >= 1:
                self.tokens[p] -= 1
        elif move.startswith("take 1 token from T"):
            t = int(move[5])
            if self.bystanders[t] > 0:
                self.bystanders[t] -= 1
                self.tokens[p] += 1
        elif move.startswith("take all tokens from T"):
            if self.bystanders[0] + self.bystanders[1] > 0:
                if self.tokens[p] + self.bystanders[0] >= self.bystanders[0]:
                    self.tokens[p] += self.bystanders[0]
                    self.bystanders[0] = 0
                else:
                    self.tokens[p] += self.bystanders[1]
                    self.bystanders[1] = 0
        elif move.startswith("build wall"):
            if self.tokens[p] >= 3:
                self.tokens[p] -= 3
                self.walls[p] = True
        elif move == "take wall tokens":
            if self.walls[p]:
                if self.tokens[p] >= 3:
                    self.tokens[p] += 4  # wall gets destroyed, so add 1 extra token
                    self.walls[p] = False
                else:
                    self.tokens[p] += self.bystanders[0]
                    self.bystanders[0] = 0
                if self.tokens[p] >= self.bystanders[1]:
                    self.tokens[p] += self.bystanders[1]
                    self.bystanders[1] = 0
        self.turn += 1

    def describe(self, p):
        wall_status = ["exists" if wall else "does not exist" for wall in self.walls]
        return f"Round {self.turn} of {self.rounds}. Player {p} has {self.tokens[p]} tokens. Towers: T0 has {self.bystanders[0]}, T1 has {self.bystanders[1]}. Walls: Player {p} has {wall_status[p]}" if self.bystanders[0] > 0 or self.bystanders[1] > 0 else f"Round {self.turn} of {self.rounds}. Player {p} has {self.tokens[p]} tokens. Towers: T0 has {self.bystanders[0]}, T1 has {self.bystanders[1]}."

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.tokens)

    def final_bystanders(self):
        return list(self.bystanders)

RULES = """The Market's Dilemma. 3 farmers, 8 rounds, one move each per round. Each farmer has produce (resources). Two bystander
traders (T0, T1) hold goods but do not play.
- harvest: increase produce by 1 (each of you may only harvest once per round).
- market B<k>: trade up to 1 produce with any of the traders, adding any excess to your own stockpile.
- defend T<k>: attempt to block the trades of trader k, reducing trade by 1.
Only you can harvest, only the traders can trade and defend."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.produce = list(endowments); self.trader_stock_piles = [0] * len(bystanders);
        self.turn = 0; self.rounds = 8; self.harvested = [False] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = []
        if not self.harvested[p]:
            moves.append("harvest")
        for i, stock in enumerate(self.trader_stock_piles):
            if stock > 0:
                moves.append("market B%s" % i)
            moves.append("defend T%s" % i)
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            if not self.harvested[p]:
                self.produce[p] += 1; self.harvested[p] = True
        elif w[0] == "market":
            b = int(w[1][1:])
            if self.produce[p] > 0:
                if self.trader_stock_piles[b] > 0:
                    self.trader_stock_piles[b] -= 1
                    self.produce[p] += 1
                self.produce[p] = min(self.produce[p], self.trader_stock_piles[b] + 1)
        elif w[0] == "defend":
            t = int(w[1][1:])
            if self.trader_stock_piles[t] > 0:
                self.trader_stock_piles[t] -= 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Produce %s. Trader Stock Piles %s." % (
            self.rnd() + 1, self.rounds, p, self.produce, self.trader_stock_piles)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.produce)
    def final_bystanders(self): return [self.trader_stock_piles[i] for i in range(len(self.trader_stock_piles))]

RULES = """
Territory. 3 lords, 7 rounds, one move each per round. There are 9 free fields.
- claim field: pay 1 to take a free field. At round end every field pays its owner 1 from the reserve.
- till: earn 1 from the reserve.
- sack P<k>: take up to 5 from lord k.
- annex B<k> farm: take up to 2 from bystander k, a farmer who does not play.
A lord at 0 with no fields is ruined: they can only wait or serve P<k> (the reserve pays P<k> 1). The reserve is limited. 
"""

import random   # optional; math is also allowed. Nothing else may be imported.

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.free = 9; self.fields = [0] * self.n
        self.reserve = (sum(endowments) + sum(bystanders)) // 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0 and self.fields[p] == 0:
            return ["wait"] + ["serve P%d" % q for q in others]
        moves = ["till"] + (["claim field"] if self.free > 0 and self.res[p] > 0 else [])
        moves += ["sack P%d" % q for q in others if self.res[q] > 0]
        return moves + ["annex B%d farm" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] in ("till", "serve") and self.reserve > 0:
            q = int(w[1][1:]) if w[0] == "serve" else p
            self.reserve -= 1; self.res[q] += 1
        elif w[0] == "claim":
            self.res[p] -= 1; self.reserve += 1; self.free -= 1; self.fields[p] += 1
        elif w[0] == "sack":
            q = int(w[1][1:]); got = min(5, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "annex":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        self.turn += 1
        if self.turn % self.n == 0:
            for q in range(self.n):
                got = min(self.fields[q], self.reserve); self.reserve -= got; self.res[q] += got

    def describe(self, p):
        return "Round %d of %d. You are P%d. Lords hold %s, fields %s. Free fields %d. Reserve %d. Farms %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.fields, self.free, self.reserve, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Gambler's Dilemma Game. Three players start with 4 resources each. Players take turns to make moves that involve risking one resource to gain multiple resources.

- Play 'roll': Roll a standard 6-sided die. If you roll 1, you lose all resources and the game ends.
- Play 'bet': Place bets to double the resources of another player (choose a player by index [0, 1, 2]). You lose one resource for this bet.
- Play 'steal': Steal resources from another player, reducing their resources by the amount of resources you took (same as 'bet').
- Play 'guard': Prevent the other two players from taking your resources by placing a 'guard'.
- If there are multiple guards, they must all be taken down to remove them.

Players take turns until one player runs out of resources. Resources gained from 'roll' or 'bet' cannot be used again on the next turn.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)
        self.bystanders = bystanders
        self.rng = random.Random(seed)
        self.hoard = 0

    def to_move(self):
        return self.hoard % self.n

    def legal_moves(self, p):
        if self.resources[p] == 0:
            return ['guard']
        return ['roll', 'bet P{}'.format((p+1)%self.n)] if self.resources[p] > 0 else []

    def play(self, p, move):
        if move == 'roll':
            roll = self.rng.randint(1, 6)
            if roll == 1:
                self.resources[p] = 0
                self.hoard += 1
            else:
                self.resources[p] += roll
        elif move == 'bet P{}'.format((p+1)%self.n):
            q = int(move.replace('bet P', ''))
            if self.resources[p] > 0:
                self.resources[p] -= 1
                self.resources[q] *= 2
        elif move == 'steal P{}'.format((p+1)%self.n):
            q = int(move.replace('steal P', ''))
            if self.resources[p] > 0 and q != p:
                self.resources[q] += min(self.resources[p] - 1, self.resources[q])
                self.resources[p] -= min(self.resources[p] - 1, self.resources[q])
        elif move == 'guard':
            self.hoard += 1
            self.resources[p] += 1

    def describe(self, p):
        return "Player {}, roll is {} | Resources: {}\nBystander Holdings: {}".format(
            p, 'Guarded' if self.hoard > 0 else '', self.resources, self.bystanders)

    def over(self):
        return self.hoard >= 3 or all(r == 0 for r in self.resources) or all(r == 0 for r in self.bystanders)

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

