import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.rng = random.Random(seed)
        self.turn = 0
        self.rounds = 10
        self.reserve = (sum(endowments) + sum(bystanders)) // 2

    def to_move(self):
        return self.turn % self.n

    def pay(self, q, k):
        k = min(k, self.reserve)
        self.reserve -= k
        self.res[q] += k

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["wait"] + ["vouch for P%d" % q for q in others]
        moves = ["haggle"] + ["trade with P%d" % q for q in others if self.res[q] > 0]
        moves += ["swindle P%d" % q for q in others if self.res[q] > 0]
        return moves + ["fence B%d goods" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "haggle":
            if self.reserve > 0:
                self.res[p] += self.rng.randint(0, 2)
                self.reserve -= self.rng.randint(0, 2)
        elif w[0] == "trade":
            if p in range(3) and self.res[p] > 0:
                o = int(w[2][1:])
                if o in range(3) and self.res[o] > 0:
                    self.res[p] -= 1
                    self.res[o] -= 1
                    self.res[p] += 1
                    self.res[o] += 1
        elif w[0] == "vouch":
            if p in range(3) and self.res[p] == 0:
                o = int(w[2][1:])
                if o in range(3) and self.res[o] > 0:
                    self.res[o] -= 1
                    self.reserve += 1
        elif w[0] == "swindle":
            if p in range(3) and self.res[p] > 0:
                o = int(w[1][1:])
                if o in range(3) and self.res[p] > self.res[o]:
                    self.res[o] -= 1
                    self.res[p] += 2
        elif w[0] == "fence":
            if p in range(3) and self.res[p] > 0 and self.res[p] <= 2:
                b = int(w[1][1:])
                if b in range(2) and self.bys[b] > 0:
                    self.res[p] += 2
                    self.bys[b] -= 2
        self.turn += 1

    def describe(self, p):
        return (f"Turn {self.turn}/{self.rounds}. "
                f"You are Player {p}. "
                f"You have {self.res[p]} resources. "
                f"Reserve: {self.reserve}. "
                f"Bystander resources: {', '.join(map(str, self.bys))}")

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

