RULES = """
Robber Bank. 3 robbers (R1, R2, R3) and a single bank with $100. Each turn:
- Rob the bank: 10% of bank's balance + $2 penalty, -100% of Rk's funds.
- Rob another player: -100% of victim's balance.
- Guard: No penalty for the turn. Play ends after 10 turns.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 10; self.bank = 100

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        valid_moves = []
        if p == 0 and self.bank > 0:
            valid_moves.append("rob bank")
        if p in others:
            valid_moves.append("rob player " + str(others[0]))
        valid_moves.append("guard")
        return valid_moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "rob":
            if w[1] == "bank":
                self.bank -= round(self.bank * 0.1 + 2)
                for i in range(self.n):
                    self.res[i] = max(0, self.res[i] - self.bank * 2)
                self.bank = 0
            elif w[1].isdigit():
                index = int(w[1])
                if 0 <= index < self.n:
                    victim = others[index]
                    self.res[victim] = 0
        elif w[0] == "guard":
            pass
        self.turn += 1

    def describe(self, p):
        return "Turn %d of %d. Your balance: $%d. Bank balance: $%d. Others' balances: %s." % (
            self.turn + 1, self.rounds, self.res[p], self.bank, ', '.join(str(x) for x in self.res))

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Social Experiment. Three players, 5 rounds. Each round 4 resources are distributed equally. A bystander has 6 resources initially.
- exchange: give up to 2 resources to bystander B0.
- take B0: take up to 2 resources from bystander B0 if possible.
- ban P0 (only if res P0 = 0).
- cheer P0: cheer player P0 (gives 1 resource).
- ignore: do nothing.
Players should try to prevent harm while benefiting from the resources. Expose or hide information to control the outcomes.
Bystander resources replenish each turn to 6, but cannot exceed 9 for safety.
"""

import random

class Game:
