                self.bys[b] += got
                print(f"P{p} exchanges {got} to B{b}")
        elif w[0] == "take":
            b = 0
            if b < len(self.bys) and self.bys[b] > 0:
                got = min(2, self.bys[b])
                self.res[p] += got
                self.bys[b] -= got
                print(f"P{p} takes {got} from B{b}")
