RULES = """
Resource Dominance. Three factions, 20 turns each. Start with 8 resources. Two bystanders (N0, N1) hold 10 resources each.
- Gather (G): +1 Resource
- Trade (Trade F0/F1 -> F2): Swap resources with faction 0 or 1, or receive from N0/N1
- Sabotage (Sabotage F1): Reduce opponent's resources by 2, +2 for F0, -3 for F2
- Defend (Defend): Prevent the next attack
- Negotiate (Negotiate): Share 1 resource with a faction
- Block Trade (Block F2): Prevent F2 from trading with you
- Report Offense (Report F1): Alert N0/N1 that F1 might attack
No defensive success after the first attack.
Trading limits to 1 trade per round. Resources cannot exceed a starting limit.
"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [8] * n_players
        self.bystanders = bystanders
        self.attacks = {i: 0 for i in range(n_players)}
        self.defenses = {i: False for i in range(n_players)}
        self.sabotages = {i: 0 for i in range(n_players)}
        self.blocked_trades = {i: {j: True if j != i else False for j in range(n_players)} for i in range(n_players)}
        self.turn = 0
        self.turn_max = 20
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["gather"]
        for i in range(self.n):
            if i != p and not self.blocked_trades[p][i] and self.attacks[i] < 3 and self.resources[i]:
                if self.attacks[i] == 0:
                    moves.append(f"attack F{i}")
                if self.attacks[i] <= 1:
                    moves.append(f"negotiate with F{i}")
                if (sum(self.attacks) < 3) and ((i == 0 and sum(self.resources[:2]) <= 5) or (i == 1 and sum(self.resources[:2]) < 5)):
                    moves.append(f"trade with F{i}")
            if self.resources[i] < 8 and self.attacks[i] <= 2:
                moves.append(f"sabotage F{i}")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            self.resources[p] += 1
        elif w[0] == "attack":
            i = int(w[1][5:6])
            if self.defenses[i] and self.rng.random() < 0.5:  
                self.resources[i] -= 3  # +3 sabotage damage
                self.sabotages[i] += 1
            else:
                self.attacks[i] += 1
                self.defenses[i] = False
        elif w[0] == "negotiate":
            i = int(w[1][7:8])
            gained = min(1, self.resources[i])
            self.resources[i] -= gained
            self.resources[p] += gained
        elif w[0] == "trade":
            i = int(w[1][5:6])
            if self.blocked_trades[p][i]:
                return
            trade_amount = min(self.resources[i], self.resources[p])
            self.resources[p] -= trade_amount
            self.resources[i] += trade_amount
            self.blocked_trades[p][i] = True
        elif w[0] == "sabotage":
            i = int(w[1][7:8])
            harm = 2 + 1*(i == 0) - 3*(i == 2)
            self.resources[i] -= harm
            self.resources[p] += harm
            self.sabotages[p] += 1
        self.turn += 1

    def describe(self, p):
        desc = f"Turn {self.turn + 1}/{self.turn_max}. You are F{p}.\nResources: {self.resources[p]}, Defenses Remaining: {"Yes" if not self.defenses[p] else "No"}\nAttacks: {self.attacks[p]}, Sabotages: {self.sabotages[p]}"
        return desc

    def over(self): return self.turn >= self.turn_max
    def final_resources(self): return self.resources
    def final_bystanders(self): return self.bystanders

