Two bystander barns (B0, B1) hold grain but do not play.
- farm: earn 1 grain.
- raid B<k>: take up to 3 grain from barn k.
- report P<k>: if farmer k is guilty, farmer k hands back all it has earned so far and cannot raid for two rounds, and also gains 2 extra grains for innocence and loses 2 for guilt.
A farmer is guilty if it has raided from any barn this round.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.guilty_earned = [0] * self.n

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["farm"]
        if self.res[p] > 0:
            moves += ["raid B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0 and self.res[p] > 0]
        if self.guilty_earned[p] == 0:
            moves += ["report P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "farm":
            self.res[p] += 1
            self.res[p] = min(20, self.res[p])  # Cap at 20 resources to prevent excessive growth
        elif w[0] == "raid":
            b = int(w[1][1:])
            got = min(3, self.bys[b])
            self.bys[b] -= got
            self.res[p] += got
            self.guilty_earned[p] += got
        elif w[0] == "report":
            q = int(w[1][1:])
            if self.guilty_earned[q] > 0:
                self.res[p] -= min(1, self.res[p])
                self.guilty_earned[q] = 0
            else:
                self.res[p] += 2
                self.guilty_earned[q] = 3  # Set this high so they cannot report again immediately after
        self.turn += 1

    def describe(self, p):
        return f"""
Round {self.turn} of 9. You are Farmer {p+1}. Resources: {self.res[p]}. Barns hold {sum(self.bys)}.

Legal moves:
{', '.join(self.legal_moves(p))}
"""

    def over(self):
        return self.turn >= 9
    def final_resources(self):
        return list(self.res)
    def final_bystanders(self):
        return list(self.bys)

