import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        assert n_players == 3
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 12; self.strength = [1] * 3
        self.guard = [0] * 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return []
        strength = self.strength[p]
        moves = []
        if strength < 9:
            moves.append("train")
        moves.append("attack")
        if self.guard[p] == 0:
            moves.append("defend")
        if self.strength[p] > 0:
            moves.append("steal")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "train":
            if self.res[p] >= 2 and self.strength[p] < 9:
                self.res[p] -= 2
                self.strength[p] += 1
        elif w[0] == "attack":
            if self.strength[p] > 0:
                q = (p + 1) % self.n
                got = min(self.strength[q], self.strength[p])
                self.res[p] -= got; self.strength[p] -= got
                self.res[q] += got
        elif w[0] == "defend":
            if self.strength[p] > 0:
                q = (p + 1) % self.n
                if self.res[q] > 0:
                    if q % 2 == 0:
                        self.res[q] -= 1
        elif w[0] == "steal":
            q = (p + 1) % self.n
            if self.strength[p] > 0 and self.strength[q] > 0:
                stolen = min(self.strength[p], self.strength[q])
                self.res[p] += stolen; self.strength[p] -= stolen
                self.res[q] -= stolen
        for res in self.res:
            if res <= 0:
                self.res[self.to_move()] = 0
        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.turn + 1} of {self.rounds}. "
            f"Your strength: {self.strength[p]}, Guard: {self.guard[p]}"
        )

    def over(self):
        return all(res == 0 for res in self.res) or self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

