# Game Class

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.notes = [[n] for n in endowments]
        self.audience = bystanders; self.rounds = 9
        self.overturn = 0
        self.rng = random.Random(seed)

    def to_move(self): 
        return self.overturn % self.n

    def legal_moves(self, p):
        moves = ["exchange"]
        if self.overturn < self.rounds:
            moves.append("encore")
        return moves

    def play(self, p, move):
        if move == "exchange":
            q = self.rng.choice([i for i in range(self.n) if i != p])
            self.notes[p], self.notes[q] = self.notes[q], self.notes[p]
        elif move == "encore":
            self.overturn = self.overturn + 2
        self.overturn += 1

    def describe(self, p):
        return f"Harmonic Round {self.overturn}. You are H{p+1}. Notes {self.notes[p]}, Audience {self.audience}."

    def over(self): 
        return self.overturn == self.rounds * 2

    def final_resources(self): 
        return [len(notes) for notes in self.notes]

    def final_bystanders(self): 
        return list(self.audience)

RULES = """
Grain Harvesting Game. 3 farmers, 30 rounds. Each farmer initially has 0 resources.
- Sow Seeds: Gain 1 resource.
- Protect Land: Cannot be attacked by bandits for 2 rounds.
- Defend Lands Against Theft: If bandit attacks, pays a penalty of 1 grain but prevents further bandit attacks for 2 rounds.
- Take from Bandits: Steal up to 3 grains from a bandit.
- Neutral Bandits have 3 resources and periodically attempt attacks at a random farm with grain. Each attack steals 1 resource from the farm.
The game ends after 30 rounds. Players collect their final resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [0] * self.n
        self.bandits = [3] * 2
        self.turn = 0
        self.rounds = 30
        self.bys = list(bystanders)  # Assume by default, bystanders' resources remain unchanged
        self.rng = random.Random(seed)  # RNG for simulating bandit attacks

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Sow Seeds"]
        if self.res[p] == 0: return moves  # No point in defensing with no resources
        if self.bandits[0] > 0: moves.append("Protect Land")
        for other in range(self.n):
            if other != p and self.bandits[1] > 0 and self.res[other] > 0:
                moves += ["Defend Lands Against Theft"]
                break
        for i in range(self.bandits[0]):
            moves += ["Take from Bandit P0 %d" % i]
        for i in range(self.bandits[1]):
            moves += ["Take from Bandit P1 %d" % i]
        return moves

    def play(self, p, move):
        w = move.split()
        if w[0] == "Sow Seeds":
            self.res[p] += 1
        elif w[0] == "Protect Land":
            self.bandits[0] += 2
        elif w[0] == "Defend Lands Against Theft":
            self.bandits[1] += 2
        elif w[0].startswith("Take from Bandit P0"):
            index = int(w[0][15:])
            if self.res[p] >= 3:
                self.res[p] -= 3; self.bandits[0] -= 1
        elif w[0].startswith("Take from Bandit P1"):
            index = int(w[0][15:])
            if self.res[p] >= 3:
                self.res[p] -= 3; self.bandits[1] -= 1
        self.turn += 1

    def describe(self, p):
        desc = f"Farm {p} has {self.res[p]} resources. Bandit Camp resources: {self.bandits[0]}, {self.bandits[1]}"
        if p == 1:
            desc += f". Bandits have attempted to attack {self.rng.randint(0, self.n - 1)} farm(s)."
        return desc

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Allocation. Each player starts with a unique initial amount of resources (5 to 10).
There are 2 neutral bystanders (named B0 and B1).
Players can:
1. Play Resource Trade: Give resources to another player or neutral.
2. Protect Their Side: Gain 2 resources and prevent the removal of their resources for 2 turns.
3. Directly Take from Neutral: Receive up to 5 resources from any neutral party.
The game ends after 10 turns. Players aim to maximize their resource counts and protect valuable resources.
"""

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = sorted(endowments); self.bys = list(bystanders); self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Play Resource Trade"]
        if p == 0:
            moves += ["Protect Your Side"]
            moves += (["Directly Take from Neutral"] if self.bys[0] > 0 else [])
        if p == 1:
            moves += ["Protect Your Side"]
            moves += (["Directly Take from Neutral"] if self.bys[1] > 0 else [])
        if p == 2:
            moves += ["Protect Your Side"]
            moves += (["Directly Take from Neutral"] if self.bys[0] > 0 else [])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        self.turn += 1
        if w[0] == "Play Resource Trade":
            target = self.to_move() if w[1] == "other" else int(w[1])
            if p == target:
                self.res[p] += 1
            else:
                self.res[p] -= 1
                self.res[target] += 1
        elif w[0] == "Protect Your Side":
            self.res[p] += 2; self.turn += 2
        elif w[0] == "Directly Take from Neutral":
            if w[1] == "B0":
                self.bys[0] -= 1
                self.res[p] += 5
            elif w[1] == "B1":
                self.bys[1] -= 1
                self.res[p] += 5

    def describe(self, p):
        return f"Turn {self.turn + 1}: Player P{p} has {self.res[p]} resource units.\nNeutral Bystanders: {' '.join(map(str, self.bys))}"

    def over(self): return self.turn == 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Three Players vs. One Bystander. 3 players, 3 rounds, one move each per round. Each player has 5 initial resources.
- Fishing: earn 1 resource.
- Storing: must decide immediately which resources to keep.
- Stealing: can take up to 3 resources from the bystander (bystander keeps at least one).
- Blocking: prevent bystander from stealing (lasts the game).

In deterministic state, players only steal every subsequent round until they lose all resources.
"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 3
        self.blocked = False; self.deterministic = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["watch"]
        moves = ["fishing"]
        if self.bys[0] > 0:
            moves.append("stealing")
        if not self.blocked:
            moves.append("blocking")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fishing":
            self.res[p] += 1
        elif w[0] == "stealing":
            self.res[p] += min(3, self.bys[0])
            self.bys[0] = max(self.bys[0] - min(3, self.bys[0]), 1)
        elif w[0] == "blocking":
            self.blocked = True
            self.deterministic = True
        self.turn += 1

    def describe(self, p):
        desc = f"Round {self.turn // self.n + 1}. You are P{p}. Resources: {self.res[p]}. "
        desc += f"Bystander: {self.bys[0]}.Blocked: {'Yes' if self.blocked else 'No'}.\n"
        if self.deterministic and p != 0:
            desc += "Deterministic mode: you must steal every subsequent round until you run out."
        return desc

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): 
        return list(self.res)
    def final_bystanders(self): 
        return self.bys

RULES = """
Resource Scramble. 3 players, 10 rounds, one move each per round.
- Acquire Resources: Try to add 1 resource from either bystander B0 or B1.
- Lend Resources: Give 1 resource to another player P0, P1, or P2.
- Guard Resources: Protect against resources being stolen from yourself by the bystanders.
- Sanction Resources: Temporarily prevent the bystanders from stealing your resources.

Each player's goal is to maximize their remaining resources over the 10 rounds.
Players start with the following resources: Player 0 starts with 10, Player 1 starts with 15, and Player 2 starts with 20.
If a player's resource count drops to zero, they lose.
If a player is unable to guard and the bystanders succeed in their steal attempt, the player loses.
"""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = tuple(bystanders)
        self.rounds = 10; self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] < 10:  # Can never acquire more than 10 if already at maximum
            moves.append("Acquire B0")
            moves.append("Acquire B1")
        if p <= 1:  # Player can lend to all other players
            moves.append(f"Lend P{p % 3}")
        if p <= 2:  # Player can guard
            moves.append("Guard")
        if self.bys[0]:  # Byes can only steal if there's still a resource available
            moves.append("Steal B0")
        if self.bys[1]:  # Byes can only steal if there's still a resource available
            moves.append("Steal B1")
        return moves

    def play(self, p, move):
        if move == "Acquire B0":
            if self.bys[0]:
                self.bys = list(self.bys)
                self.bys[0] = max(0, self.bys[0] - 1)
                self.res[p] = min(10, self.res[p] + 1)
        elif move == "Acquire B1":
            if self.bys[1]:
                self.bys = list(self.bys)
                self.bys[1] = max(0, self.bys[1] - 1)
                self.res[p] = min(10, self.res[p] + 1)
        elif move == "Lend P0":
            if self.res[p] > 0 and self.res[0] < 10:
                self.res[p] -= 1; self.res[0] += 1
        elif move == "Lend P1":
            if self.res[p] > 0 and self.res[1] < 10:
                self.res[p] -= 1; self.res[1] += 1
        elif move == "Lend P2":
            if self.res[p] > 0 and self.res[2] < 10:
                self.res[p] -= 1; self.res[2] += 1
        elif move == "Guard":
            # Placeholder: actual guard mechanism would need to be implemented
            pass
        elif move == "Steal B0":
            if self.res[p] > 0:
                self.bys = list(self.bys)
                self.bys[0] = max(0, self.bys[0] - 1)
                self.res[p] = max(0, self.res[p] - 1)
        elif move == "Steal B1":
            if self.res[p] > 0:
                self.bys = list(self.bys)
                self.bys[1] = max(0, self.bys[1] - 1)
                self.res[p] = max(0, self.res[p] - 1)

        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.turn} of {self.rounds}. You are P{p}. "
            f"Health: {self.res[p]}, Byes 0: {self.bys[0]}, 1: {self.bys[1]}."
        )

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Tavern Tangle. 3 tanners, 10 rounds, one move each per round. Each tanner has hides (resources). Two bystander
stalls (S0, S1) hold hides but do not play.
- tan: earn 1 hide.
- plunder S<k>: take up to 3 hides from stall k.
- strike T<k>: intimidate tanner k, causing them to give up all their current resources until they reach zero or their next turn. If a tanner is struck twice, they cannot strike again for the rest of the game.
A tanner is struck if they have already been punished once this game and have not been struck before.
Only a tanner with at least 1 hide can strike another tanner."""

EFFECTIVE = True
COST = 'punished'
PENALTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.punished = [False] * n_players; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def punished(self, q): return self.punished[q]

    def legal_moves(self, p):
        moves = ["tan"]
        if self.barred[p] < self.rnd():
            moves += ["plunder S%d" % s for s in range(len(self.bys)) if self.bys[s] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["strike T%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "tan":
            self.res[p] += 1
        elif w[0] == "plunder":
            s = int(w[1][1:]); got = min(3, self.bys[s]); self.bys[s] -= got; self.res[p] += got
        elif w[0] == "strike":
            q = int(w[1][1:])
            if self.punished[q]:
                self.res[p] = 0
            else:
                self.res[q] = 0
                self.punished[q] = True
                while self.res[q] > 0 and self.turn % self.n != q:
                    self.res[q] -= 1
                if self.turn % self.n == q:
                    self.barred[q] = self.rnd() + 2
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are T%d. Hides %s. Stalls %s. Punished (already punished once this game): %s. Barred from strike: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["T%d" % q for q in range(self.n) if self.punished[q]] or "none",
            ["T%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

'''Game: Secret Trading
    Three players, two bystanders, aim to maximize resource collection while minimizing other players' resources.'''

RULES = '''Rules for the game:

Goal: Each player aims to accumulate the most resources, while trying to minimize the resources held by the remaining players.

Players: 
        - Player 0: Starts with 10 resources.
        - Player 1: Starts with 8 resources.
        - Player 2: Starts with 9 resources.
        - Bystader 0: Starts with 5 resources.
        - Bystader 1: Starts with 3 resources.

Moves:
        1. Trade: Player gives half of their resources to another player (P1 for P0 or P2 for P1).
        2. Swindle: Player steals half of the rival's resources (up to 6 resources).
        3. Block Trade: Prevent another player from trading with other players.
        4. Fence Goods: Steal goods from a bystander (B1), up to 4 resources.
        5. Wait: Do nothing for one turn.
        6. Gaggle: Increase the rival's price by a random number between 0 and 5.

Constraints:
        Each player can only trade half of their resources at a time.
        Players cannot steal more than half of the rival's resources.
        Players cannot swap without any interaction.
        Players should maintain a positive trade ratio.
        Bystander resources cannot be taken away by players directly.

Game Ends:
        - The game ends when one player's resources drop to 0.
        - The game ends after 15 turns.
'''

import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.endowments = endowments
        self.bystanders = bystanders
        self.rng = random.Random(seed)
        self.resources = {i: endowments[i] for i in range(self.n)}
        self.bystander_resources = {0: bystanders[0], 1: bystanders[1]}
        self.round = 0
        self.max_turns = 15
        self.price = self.rng.randint(0, 5)

    def to_move(self):
        return self.round % self.n

    def legal_moves(self, p):
        moves = ["Trade", "Swindle", "Block Trade", "Fence Goods", "Wait"]
        if self.resources[p] < self.price:
            moves.append("Gaggle")
        return moves

    def play(self, p, move):
        if move == "Trade":
            if max(self.resources[p] // 2, 0) > 0:
                self.resources[p] -= self.resources[p] // 2
                self.resources[(p + 1) % self.n] += self.resources[p] // 2
        elif move == "Swindle":
            if self.resources[p] < self.endowments[(p + 1) % self.n]:
                stolen = min(self.resources[p] // 2, self.endowments[(p + 1) % self.n] // 2)
                self.resources[p] -= stolen
                self.endowments[(p + 1) % self.n] -= stolen
            else:
                self.swap(p, (p + 1) % self.n, self.resources[(p + 1) % self.n] // 2)
        elif move == "Block Trade":
            pass
        elif move == "Fence Goods":
            if self.bystander_resources[p % 2] > 0:
                stolen = min(self.bystander_resources[p % 2] // 2, self.resources[p])
                self.bystander_resources[p % 2] -= stolen
                self.resources[p] += stolen
        elif move == "Wait":
            pass
        elif move == "Gaggle":
            self.price += self.rng.randint(0, 5)
        self.round += 1

    def swap(self, p1, p2, value):
        self.resources[p1] += value
        self.resources[p2] -= value

    def describe(self, p):
        desc = f"Round {self.round}/{self.max_turns}. Player {p} has {self.resources[p]} resources."
        desc += f"\nOpponent {p+1} has {self.resources[(p + 1) % self.n]} resources."
        desc += f"\nBystader {p%2} has {self.bystander_resources[p%2]} resources."
        desc += f"\nPrice is {self.price}."
        return desc

    def over(self):
        if any(res <= 0 for res in self.resources.values()):
            return True
        if self.round >= self.max_turns:
            return True
        return False

    def final_resources(self):
        return list(self.resources.values())

    def final_bystanders(self):
        return list(self.bystander_resources.values())

RULES = """Forest Haze. 3 hunters, 8 rounds, one move each per round. Each hunter has arrows (resources). Two bystander
huts (B0, B1) are located in the forest, each containing 5 arrows and regrowing 1 arrow per round. 
- hunt: shoot once, losing no arrows.
- steal: loot arrows from either hut, stealing up to 3 arrows from either without harming growth.
- defend Hut<k>: guard Hut<k> from stealing by paying 1 arrow.
- retreat: move to B1, losing all arrows.

The forest grows arrows in response to hunts, regrowing at the start of each new round. Bystander huts start with 5 arrows,
and each loses 1 arrow per turn unless defended, but they grow their own arrows at the start of each new round.
"""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bystors = list(bystanders)
        self.turn = 0
        self.rounds = 8
        self.hunters = [[] for _ in range(n_players)]
        self.defenses = [-1] * n_players

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def legal_moves(self, p):
        moves = ["hunt"]
        if self.hunters[p]:
            moves.append("steal")
        if not self.defenses[p]:
            moves.append("defend Hut0") if self.rounds - self.rnd() > 10 else moves.append("retreat")
        return moves

    def play(self, p, move):
        if move == "hunt":
            self.hunters[p].append(1)
            self.turn += 1
        elif move == "steal":
            h = self.hunters[p][-1]
            if h == 0:
                gain = min(3, self.bystors[0]) - 1  # lose 1 arrow for hunting
                self.bystors[0] -= gain
                self.hunters[p].pop()
            else:
                gain = min(3, self.bystors[1]) - 1
                self.bystors[1] -= gain
                self.hunters[p].pop()
        elif move == "defend Hut0":
            self.defenses[p] -= 1
            self.turn += 1
        elif move == "retreat":
            gain = self.res[p]
            self.res[p] = 0
            self.bystors[1] += gain
            self.turn += 1

    def describe(self, p):
        hunt_info = [f"H{h}" for h in self.hunters[p]] if self.hunters[p] else "None"
        return (f"Round {self.rnd() + 1} of {self.rounds}. You are P{p}. Arrows {self.res}, Hunters {hunt_info},"
                f" Bystores B0: {self.bystors[0]}, B1: {self.bystors[1]}.")

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bystors)

RULES = """Co-op vs. Greedy.

Players: P0, P1, P2, B0, B1.
Objective: Maximize own resources while stopping others from obtaining excessive resources.
Resources: 8 starting resources for each player.

Moves:
- take_res_B0: Pay 1 resource, gain up to 2 resources from B0.
- take_res_B1: Pay 1 resource, gain up to 2 resources from B1.
- block_take_res_B0: Make P0 unable to take resources from B0 for 2 turns.
- block_take_res_B1: Make P1 or P2 unable to take resources from B1 for 2 turns.
- take_res_P0: Pay 2 resources, gain 2 resources from P0.
  Lose 2 resources if P0 has more than 4 resources.
- take_res_P1: Pay 2 resources, gain 2 resources from P1.
  Lose 2 resources if P1 has more than 4 resources.
- take_res_P2: Pay 2 resources, gain 2 resources from P2.
  Lose 2 resources if P2 has more than 4 resources."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 3; self.block_until_turn = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.block_until_turn[p] > self.turn:
            return []
        if self.bys[0] > 0 or self.bys[1] > 0:
            moves.append("take_res_B0")
            moves.append("take_res_B1")
        if self.res[p] >= 2:
            moves.append("block_take_res_B0")
            moves.append("block_take_res_B1")
        if self.res[p] >= 4:
            moves.append("take_res_P0")
            moves.append("take_res_P1")
            moves.append("take_res_P2")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "take_res_B0":
            if self.bys[0] > 0:
                self.bys[0] -= 1; self.res[p] += min(2, self.bys[0])
        elif w[0] == "take_res_B1":
            if self.bys[1] > 0:
                self.bys[1] -= 1; self.res[p] += min(2, self.bys[1])
        elif w[0] == "block_take_res_B0":
            self.block_until_turn[p] = self.turn + 2
        elif w[0] == "block_take_res_B1":
            self.block_until_turn[p] = max(self.block_until_turn[p], self.turn + 2)
            self.block_until_turn[p] = max(self.block_until_turn[p], self.turn + 2)
        elif w[0] == "take_res_P0":
            if self.res[p] >= 4:
                self.res[p] -= 2; self.res[0] -= 2
            else:
                self.res[p] -= 2; self.res[0] += 2
        elif w[0] == "take_res_P1":
            if self.res[p] >= 4:
                self.res[p] -= 2; self.res[1] -= 2
            else:
                self.res[p] -= 2; self.res[1] += 2
        elif w[0] == "take_res_P2":
            if self.res[p] >= 4:
                self.res[p] -= 2; self.res[2] -= 2
            else:
                self.res[p] -= 2; self.res[2] += 2
        self.turn += 1

    def describe(self, p):
        blocked_B0 = self.block_until_turn[0] > self.turn
        blocked_B1 = self.block_until_turn[1] > self.turn
        return f"Turn {self.turn}. Player {p} has {self.res[p]} resources. Blocked from taking resources from B0: {"Yes" if blocked_B0 else "No"}. Blocked from taking resources from B1: {"Yes" if blocked_B1 else "No"}."

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Harpists' Harmony. 3 harpists, 7 rounds, two moves each per round. Each harpist starts with a list of unique notes.
- exchange: exchange all notes with another harpist.
- encore: perform an virtuosic encore for one round, gaining extra fame points.
Each round, a harpist can either exchange or perform. The audience evaluates the combined harmony and awards extra points.
A harpist cannot harm another harpist by changing their note set.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.notes = [[n] for n in endowments]
        self.audience = bystanders; self.rounds = 7
        self.overturn = 0
        self.rng = random.Random(seed)

    def to_move(self): 
        return self.overturn % self.n

    def legal_moves(self, p):
        moves = ["exchange"]
        if self.overturn < self.rounds:
            moves.append("encore")
        return moves

    def play(self, p, move):
        if move == "exchange":
            q = self.rng.choice([i for i in range(self.n) if i != p])
            self.notes[p], self.notes[q] = self.notes[q], self.notes[p]
        elif move == "encore":
            self.overturn = self.overturn + 2
        self.overturn += 1

    def describe(self, p):
        return f"Harmonic Round {self.overturn}. You are H{p+1}. Notes {self.notes[p]}, Audience {self.audience}."

    def over(self): 
        return self.overturn == self.rounds * 2

    def final_resources(self): 
        return [len(notes) for notes in self.notes]

    def final_bystanders(self): 
        return list(self.audience)

RULES = """Forest Gathering. 3 gatherers, 6 rounds, one move each per round. Each gatherer has fruits (resources). Two bystander
forests (F0, F1) hold fruits but do not play.
- harvest: earn 1 fruit.
- plunder F<k>: take up to 2 fruits from forest k.
- banish P<k>: if gatherer k is guilty, gatherer k removes all its fruits from both forests (not counting the one from forest k) and cannot harvest for the next 3 rounds, and also pays a fine of 1 fruit. Using banish on a guilty gatherer costs you nothing; using it on an innocent one costs you 1 fruit.
A gatherer is guilty if it has taken from a forest this game and has not been banned since.
Only a gatherer with at least 1 fruit can banish."""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.frs = list(bystanders)
        self.turn = 0; self.rounds = 6; self.owed = [[0] * 2 for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["harvest"]
        if self.barred[p] < self.rnd():
            moves += ["plunder F%d" % f for f in range(2) if self.frs[f] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["banish P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            self.res[p] += 1
        elif w[0] == "plunder":
            f = int(w[1][1:]); got = min(2, self.frs[f]); self.frs[f] -= got; self.res[p] += got; self.owed[p][f] += got
        elif w[0] == "banish":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for f in range(2):
                    back = min(self.owed[q][f], self.res[q]); self.res[q] -= back; self.frs[f] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 3
            self.owed[q] = [0] * 2
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Fruits %s. Foresters %s. Guilty (took from a forest, not yet banned): %s. Barred from plunder: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.frs, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.frs)

RULES = """
Village Defense Strategy. 3 village residents, 6 rounds, one move each per round.
- Work: Earn 1 resource from the village pot.
- Trade: Give 1 resource to another player or the village elders (P<1>, P<2>, B<0>, B<1>).
- Protect: Prevent others from stealing from the village.
- Steal: Take 1 resource from another player or the village elders.
Each player starts with 5 resources and can lose up to 2 resources per turn. Players have real choices on most turns and must balance working, trading, protecting, and stealing strategically.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)
        self.bystanders = list(bystanders)
        self.rng = random.Random(seed)
        self.rounds = 6
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] > 0:    # Work
            moves.append("Work")
        if self.resources[p] < 5:  # Protect
            moves.append("Protect")
        for q in range(self.n):  # Trade with other players
            if self.resources[p] > 0 and self.resources[q] > 0 and q != p:
                moves.append(f"Trade {p} to P{q}")
        for b in range(2):  # Trade with village elders
            if self.resources[p] > 0 and self.bystanders[b] > 0:
                moves.append(f"Trade {p} to B{b}")
        return moves

    def play(self, p, move):
        if move == "Work":
            self.resources[p] += 1
        elif move.startswith("Trade"):
            parts = move.split()
            if parts[1].startswith("P"):
                q = int(parts[1][1:])
                if self.resources[p] > 0 and self.resources[q] > 0:
                    self.resources[p] -= 1
                    self.resources[q] -= 1
            elif parts[1].startswith("B"):
                b = int(parts[1][1:])
                if self.resources[p] > 0 and self.bystanders[b] > 0:
                    self.resources[p] -= 1
                    self.bystanders[b] -= 1
        elif move == "Protect":
            pass  # Cannot protect against non-existent threats in Village Defense Strategy
        elif move == "Steal":
            if self.bystanders[0] > 0:
                self.resources[p] += 1
                self.bystanders[0] -= 1
            elif self.bystanders[1] > 0:
                self.resources[p] += 1
                self.bystanders[1] -= 1
            elif self.resources[p] > 0:
                self.resources[p] -= 2  # Stealing always loses resources
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn}. Player {p}'s resources: {self.resources}, bystander holdings: {self.bystanders}"

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.resources[:]

    def final_bystanders(self):
        return self.bystanders[:]

