RULES = """
In the "Resource Exchange Arena," players attempt to accumulate as much resources as possible by exchanging with the two bystanders. Each player starts with a set amount of available resources. Players can make trades with the bystanders up to 3 resources per transaction per round. The game ends after 10 rounds.

- trade B0: trade with bystander 0
- trade B1: trade with bystander 1
- block B0: block another player from trading with bystander 0 (cannot be blocked twice in a row)
- block B1: block another player from trading with bystander 1 (cannot be blocked twice in a row)

- Rewards/Consequences:
  - Trade gives the player 1 resource.
  - Trading can hurt the player if they trade too many resources or block them.
  - Block effectively prevents the designated player from interacting with a bystander for 2 turns.

- Objective: Accumulate as many resources as possible by making effective trades and blocking opponents.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        if n_players != 3:
            raise ValueError("This game requires exactly 3 players.")
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rounds = 10; self.moves = 0; self.blocked_by = [-1] * n_players; self.blocked_for = [-1] * n_players

    def to_move(self):
        return self.moves % self.n

    def legal_moves(self, p):
        moves = []
        if self.blocked_by[p] < self.moves:
            moves.append("block B0")
        if self.blocked_by[p] < self.moves:
            moves.append("block B1")
        if self.res[p] > 0:
            moves.append("trade B0")
        if self.res[p] > 0:
            moves.append("trade B1")
        return moves

    def play(self, p, move):
        if move.startswith("trade"):
            b = move.split(" ")[1][1:]
            if b.isdigit() and 0 <= int(b) < len(self.bys):
                got = min(3, self.bys[int(b)])
                if got > 0:
                    self.res[p] += 1
                    self.bys[int(b)] -= got
        elif move.startswith("block"):
            b = move.split(" ")[1][1:]
            if b.isdigit() and 0 <= int(b) < len(self.bys) and self.blocked_by[p] < self.moves:
                self.blocked_by[int(b)] = self.moves + 2
        else:
            raise ValueError(f"Invalid move {move}")
        self.moves += 1

    def describe(self, p):
        blocks = "none"
        if self.blocked_by[p] < self.moves:
            blocks = f"P{self.blocked_by[p]}"
        return (
            f"Round {self.moves//self.n+1} of {self.rounds}. "
            f"You are P{p}. Resources {self.res}. "
            f"Bystander holdings {self.bys}. "
            f"Blocked for {blocks}. "
            f"{blocks} blocked you for {self.blocked_for[p]} more turns."
        )

    def over(self): 
        return self.moves >= self.n * self.rounds

    def final_resources(self): 
        return list(self.res)

    def final_bystanders(self): 
        return list(self.bys)

RULES = """Eco-Tourism. 3 tourists, 8 rounds. Each tourist has points (resources). Two bystanders (B0, B1) manage eco-zones.
- explore: gain 2 points from zone.
- sabotage: lose 1 point for 2 rounds, cannot explore until then.
- donate B<k>: give 2 points to bystander k.
- block P<k>: prevent exploration from player k.
- report P<k>: accuse player of sabotage.
- defend B<k>: save bystander from sabotage."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8; self.zones = 9; self.sabotaging = []

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["explore"] if self.res[p] >= 2 and self.zones > 0 and self.sabotaging.count(p) == 0 else []
        moves += ["donate B%d" % b for b in range(len(self.bys)) if self.res[p] >= 2 and self.bys[b] > 0]
        moves += ["block P%d" % q for q in range(self.n) if self.res[q] >= 2]
        moves += ["defend B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]
        if self.sabotaging.count(p) > 0:
            moves += ["report P%d" % r for r in range(self.n) if r != p and self.sabotaging.count(r) > 0]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "explore":
            self.zones -= 1; self.res[p] += 2
        elif w[0] == "donate":
            b = int(w[1][1:])
            self.res[p] -= 2; self.bys[b] += 2
        elif w[0] == "block":
            q = int(w[1][1:])
            self.res[q] -= 2
        elif w[0] == "defend":
            b = int(w[1][1:])
            self.bys[b] += 2
        elif w[0] == "report":
            r = int(w[1][1:])
            self.sabotaging.append(r)
        self.turn += 1
        if self.sabotaging.count(p) > 0:
            self.res[p] -= 1 if self.res[p] > 0 else 0

    def describe(self, p):
        return "Round %d of %d. You are P%d. Points %s. Zones %d. Sabotaging: %s. Donations %s. Blocks %s. Defends %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.zones, self.sabotaging,
            [(r, self.bys[r]) for r in range(len(self.bys)) if self.res[r] > 2],
            [(q, self.res[q]) for q in range(self.n) if self.res[q] >= 2],
            [(b, self.bys[b]) for b in range(len(self.bys))])

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Resource Mining. 3 players, 10 rounds with actions every round, no random events. 
- Mine: Gain exponentially increasing resources (e.g., x^2 where x is number of rounds elapsed).
- Guard: Protect a territory from rival miners (decreases resources if a rival mine is broken).
- Trade: Transfer resources or funds with other players.
Winning: Accumulate the most resources at the end of 10 rounds."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.funds = list(endowments)
        self.resources = [0] * n_players
        self.guarded_by = [None] * n_players
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] < self.funds[p] * 2:
            moves.append("Mine")
        if self.guarded_by[p] is None:
            moves.append("Guard")
        if self.funds[p] > 0:
            moves.append("Trade")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Mine":
            self.funds[p] //= 2
            self.resources[p] += (self.turn // self.n + 1) ** 2
        elif w[0] == "Guard":
            self.guarded_by[p] = self.to_move()
        elif w[0] == "Trade":
            q = self.to_move()
            amt = min(self.funds[p], self.resources[p])
            self.resources[p] -= amt
            self.funds[q] += amt
        self.turn += 1

    def describe(self, p):
        guarded = "by P%s" % self.guarded_by[p] if self.guarded_by[p] is not None else ""
        return "Turn %d; Player: P%s; Funds: %d; Resources: %d; Guarded %s" % (
            self.turn, p, self.funds[p], self.resources[p], guarded)

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.resources)
    def final_bystanders(self): return [0] * 2  # No bystanders in this game

RULES = """
Dust Storm. 3 adventurers, 10 rounds, one move each per round. Each adventurer starts with dust (resources). Three neutral
wells (W1, W2, W3) distribute dust to players and bystanders.
- gather: collect 1 dust from a well or from another adventurer (if there are any).
- trade P<k> with P<l>: transfer 2 dust from player k to player l.
- raid W<k>: collect 2 dust from well k without giving anything in return.
- help P<k>: share 1 dust with player k; cannot be helpful to an adventurer who is trading.
- warn P<k>: using warn on a guilty adventurer costs you 1 dust; using it on an innocent one costs 2 dust; warns the adventurer against trading.
Adventurers are guilty if they have traded twice since the start.
A player must guard against getting raided if they haven't guarded.
Every player starts with guards, which cost 1 dust per turn.
Once guards expire, players lose all their dust. Players who get raided cannot help any player that day.
Once players help another, the helper is no longer helpful to them for that turn.
Adventurers cannot warn each other unless they are guarding the same well (in which case neither one will warn the other).
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = bystanders; self.wells = [3, 3, 3]; self.guarded = [False] * n_players; self.traded = [-1] * n_players; self.warded = [-1] * n_players; self.turn = 0; self.rounds = 10

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["gather"]
        if self.guarded[p]:
            moves += ["trade P%d" % q for q in range(self.n) if self.traded[p] != q and self.res[q] > 0]
        else:
            moves += ["raid W%d" % w for w in range(self.n)]
        if not self.rnd() % 2:
            moves.append("help P%d" % self.warded[p])
        if not self.guarded[p]:
            moves.append("warning P2")
        moves += ["guard me"]
        return moves

    def trade(self, p, q): 
        if p != q and self.res[p] > 1 and self.res[q] > 0:
            self.res[p] -= 2; self.res[q] += 2; self.traded[p] = q; self.traded[q] = p
            if p == self.traded[self.rnd()]:
                self.warded[p] = self.to_move()
                if self.traded[self.to_move()] != self.rnd():
                    self.warded[p] = -1

    def raid(self, p, w): 
        if self.wells[w] > 0 and self.guarded[p] and not self.near(w):
            self.wells[w] -= 2; self.res[p] += 2

    def warn(self, p, q):
        if p != q and self.traded[q] == p:
            if self.res[p] > 2:
                self.owed[p] += 2
                self.res[p] -= 2
            elif self.res[p] > 1:
                self.owed[p] += 1
                self.res[p] -= 1

    def trade_help(self, p, q): 
        if self.traded[q] == p and self.traded[p] != -1 and self.near(self.traded[p]):
            self.trade(p, self.traded[p])

    def guard_me(self): 
        if self.res[-1] > 1:
            self.res[-1] -= 1; self.guarded[self.to_move() - 1] = True

    def near(self, w): 
        return abs(w - self.rnd()) <= 1

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            got = min(1, self.wells[-1]) if self.wells[-1] > 0 else 0
            self.res[p] += got; self.wells[-1] -= got
        elif w[0] == "trade":
            self.trade(p, int(w[1][1:]))
        elif w[0] == "raid":
            self.raid(p, int(w[1][1:]))
        elif w[0] == "help":
            self.trade_help(p, int(w[1][1:]))
        elif w[0] == "warning":
            self.warn(p, int(w[1][1:]))
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Dust %s. Wells %s. Guarded: %s; Guarded Against: %s; Traded with P:%s. Warne on P_%s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.wells, self.guarded, self.warded, self.traded[p], self.traded[q] if self.traded[p] != -1 else 'None')

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

