Resource Control. 3 players (P0, P1, P2) and 1 bystander (B0) start with 5 resources each.
- Steal: P0, P1, or P2 can steal resources from B0 (B0 starts with 10 resources).
- Use Power: P2 can temporarily control P0 or P1, causing them to lose all stolen resources from B0.
- Guard: P2 can prevent anyone from stealing from B0 by either P0 or P1.
- The game ends after 10 turns. Players maximize their resources, and P2 tries to limit their control.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.turn_limit = 10; self.power_controlled = None; self.guard = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.guard:
            moves.append("guard")
