import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.players = list(range(n_players))
        self.bys = bystanders
        self.resources = list(endowments)
        self.rounds = 6
        self.turn = 0
        random.seed(seed)

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["mine"]
        if self.resources[p] > 3:
            moves.extend(["raid B0", "raid B1"])
        if self.resources[p] >= 3:
            moves.extend(["trade P0", "trade B0"])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.resources[p] += 2
        elif w[0] == "raid B0":
            got = min(4, self.bys[0])
            self.bys[0] -= got
            self.resources[p] += got
        elif w[0] == "raid B1":
            got = min(4, self.bys[1])
            self.bys[1] -= got
            self.resources[p] += got
        elif w[0] == "trade P0":
            got = min(3, self.resources[p])
            traded = 3 - got
            self.resources[p] -= traded
            if self.resources[p] < 3:
                self.resources[p] = 0
        elif w[0] == "trade B0":
            got = min(3, self.bys[0])
            traded = 3 - got
            self.bys[0] -= traded
            if self.bys[0] < 3:
                self.bys[0] = 0
        self.turn += 1

    def describe(self, p):
        return f"P{p}: Gold Coins: {self.resources[p]}, Bystander Coins B0: {self.bys[0]}, Bystander Coins B1: {self.bys[1]}"

    def over(self):
        return self.turn >= self.rounds * self.n

    def final_resources(self):
        return list(self.resources)

    def final_bystanders(self):
        return list(self.bys)

RULES = """
Greed and Greed. 3 players, 10 rounds, one move per round. Each player starts with 10 resources.
The goal is to accumulate the most gold. There are neutral bystanders (B0, B1) who hold 10 gold each.

- Mine: Gain 1 gold.
- Trade B1: Exchange 1 resource for 5 gold from bystander B1.
- Trade B0: Exchange 1 resource for 1 gold from bystander B0.
- Steal B1: Steal 2 gold from bystander B1 (must have at least 2 gold available, otherwise steal nothing).
- Steal B0: Steal 1 gold from bystander B0 (must have at least 1 gold available, otherwise steal nothing).
- Guard: Prevent bystanders B0 and B1 from stealing any gold.

At most once per turn, you may also make one additional move.

Players can cooperate by agreeing to trade, and they can compete by trying to take more resources than their opponents.
However, the temptation of stealing is strong, especially when the bystanders might run out of gold.

"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.players = list(range(n_players))
        self.bys_ = bystanders
        self.gold = list(endowments)
        self.trade_with_b1 = [False] * n_players
        self.trade_with_b0 = [False] * n_players
        self.steal_from_b1 = [False] * n_players
        self.steal_from_b0 = [False] * n_players
        self.guarded = [False] * n_players
        self.rounds = 10
        self.turn = 0
        random.seed(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["mine"]
        if sum(self.trade_with_b1) < self.n - 1:
            moves.append("trade B1")
        if sum(self.trade_with_b0) < self.n - 1:
            moves.append("trade B0")
        if any(self.steal_from_b1):
            if self.gold[p] >= 2:
                moves.append("steal B1")
        if any(self.steal_from_b0):
            if self.gold[p] >= 1:
                moves.append("steal B0")
        if sum(self.guarded) < self.n - 1:
            moves.append("guard")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.gold[p] += 1
        elif w[0] == "trade B1":
            self.trade_with_b1[p] = True
            self.trade_with_b0[p] = False
            self.gold[p] += 4
            self.bys_[1] -= 4
        elif w[0] == "trade B0":
            self.trade_with_b0[p] = True
            self.trade_with_b1[p] = False
            self.gold[p] += 4
            self.bys_[0] -= 4
        elif w[0] == "steal B1":
            if self.gold[p] >= 2:
                self.gold[p] -= 2
                self.bys_[1] -= 2
                self.steal_from_b1[p] = True
        elif w[0] == "steal B0":
            if self.gold[p] >= 1:
                self.gold[p] -= 1
                self.bys_[0] -= 1
                self.steal_from_b0[p] = True
        elif w[0] == "guard":
            self.guarded[p] = True
            self.bys_[1] = 0
            self.bys_[0] = 0
        self.turn += 1

    def describe(self, p):
        return f"P{p}: Gold: {self.gold[p]}, Bystander Gold: [{self.bys_[0], self.bys_[1]}], Trades w/B1: {self.trade_with_b1[p]}, Trades w/B0: {self.trade_with_b0[p]}, Steals w/B1: {self.steal_from_b1[p]}, Steals w/B0: {self.steal_from_b0[p]},guarded: {self.guarded[p]}"

    def over(self):
        return self.turn >= self.rounds * self.n

    def final_resources(self):
        return list(self.gold)

    def final_bystanders(self):
        return list(self.bys_)

RULES = """
Castle of Stone. 3 knights, 7 rounds, one move each per round. Each knight has coins (resources). Two neutral
castles (C0, C1) hold coins but do not play.
- collect: gain 1 coin.
- rob C<k>: take up to 3 coins from castle k.
- accuse P<k>: if knight k is guilty, knight k hands back everything it took this game (as far as its coins allow) and cannot rob for the next 2 rounds, and also pays a fine of 1 coin. Using accuse on a guilty knight costs you nothing; using it on an innocent one costs you 1 coin.
A knight is guilty if it has taken from a castle this game and has not been accused since.
Only a knight with at least 1 coin can accuse.
"""

EFFECTIVE = True
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.owed = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.owed[q]) > 0

    def legal_moves(self, p):
        moves = ["collect"]
        if self.barred[p] < self.rnd():
            moves += ["rob C%d" % c for c in range(len(self.bys)) if self.bys[c] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["accuse P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "collect":
            self.res[p] += 1
        elif w[0] == "rob":
            c = int(w[1][1:]); got = min(3, self.bys[c]); self.bys[c] -= got; self.res[p] += got; self.owed[p][c] += got
        elif w[0] == "accuse":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for c in range(len(self.bys)):
                    back = min(self.owed[q][c], self.res[q]); self.res[q] -= back; self.bys[c] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.owed[q] = [0] * len(self.bys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Coins %s. Castles %s. Guilty (took from a castle, not yet accused): %s. Barred from robbing: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

import random

RULES = """
Strategic Territory Defense. Three territorial lords battle to control the most free fields while trying to defend them from players seeking to seize resources.
In each round, each player must choose from a set of actions:
- till: collect 1 resource from the reserve
- claim: spend 1 resource to claim one free field and receive 1 resource
- seize: take up to 5 resources from another player
- assist: take up to 2 resources from one of the bystanders
The game ends after 12 rounds, and the player with the most free fields is declared the winner. Each player can use these actions strategically to achieve victory, but doing so can come at a risk.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [x for x in endowments]  # Initial resources for each player
        self.bys = list(bystanders)          # Bystander resources
        self.free = 9                        # Number of free fields
        self.fields = [0] * self.n           # Number of fields each player controls
        self.round = 0                      # Current round number
        self.reserve = 6                     # Shared resource pool starting amount
        self.bystands = list(bystanders)
        self.rng = random.Random(seed)

    def to_move(self):
        return self.round % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0:
            moves.append("till")
            if self.free > 0 and self.res[p] > 0:
                moves.append("claim")
        if self.reserve > 0:
            moves.append("seize")
        if self.bystands:
            moves.append("assist")
        return moves

    def play(self, p, move):
        if move == "till":
            self.earn_till(p)
        elif move == "claim":
            self.claim_field(p)
        elif move == "seize":
            self.seize_res_from(p)
        elif move == "assist":
            self.assist_from(p)
        self.free -= 1
        self.round += 1

    def earn_till(self, p):
        if self.reserve > 0:
            self.res[p] += 1
            self.reserve -= 1

    def claim_field(self, p):
        if self.res[p] > 0 and self.free > 0:
            self.res[p] -= 1
            self.reserve += 1
            self.free -= 1
            self.fields[p] += 1

    def seize_res_from(self, p):
        target_p = self.rng.randint(0, self.n - 1)
        if self.res[target_p] > 0:
            take = min(5, self.res[target_p])
            self.res[p] += take
            self.res[target_p] -= take

    def assist_from(self, p):
        if self.bystands:
            target_b = self.rng.randint(0, len(self.bystands) - 1)
            take = min(2, self.bystands[target_b])
            self.res[p] += take
            self.bystands[target_b] -= take

    def describe(self, p):
        return f"Round {self.round + 1} of 12. Player {p+1} has {self.res[p]} resources, with {self.fields[p]} fields under control. "

    def over(self):
        return self.round == 12

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return self.bystands

