        self.rounds = 10; self.turn = 0
        self.defended_treasury_turns = 0  # Tracks when the treasury is defended by any player
        self.blocked_treasury = False  # Tracks if the treasury is currently being blocked

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["gather"] if self.get_gather_status(p) else []
        if self.treasury_gold > 0:
            if not self.defended_treasury_turns % self.n and not self.blocked_treasury:
                moves.append("defend Treasury")
            if self.res[p] > 0:
                moves.append("rob Treasury")
            if not self.blocked_treasury:
                moves.append("block Treasury")
        if self.res[p] > 0:
            for h in range(len(self.bys)):
                moves.append(f"trade Gold B{h}")
        return moves

    def get_gather_status(self, p):
        # Allow gathering if the treasury has gold or if the treasury is not blocked
        return self.treasury_gold > 0 or not self.blocked_treasury

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "gather":
            self.res[p] += 1
        elif w[0] == "defend Treasury":
            self.defended_treasury_turns = self.turn
        elif w[0] == "rob Treasury":
            if self.treasury_gold > 0:
                self.treasury_gold -= 1
                self.res[p] += 1
            else:
                print("The treasury has no gold to steal.")
        elif w[0] == "block Treasury":
            self.blocked_treasury = True
        elif w[0] == "trade Gold":
            h = int(w[1][1:])
            if self.res[p] > 0:
                got = min(self.res[p], self.bys[h])
                self.bys[h] -= got; self.res[p] += got
                print(f"Traded {got} gold with P{h}")

        self.turn += 1
        self.blocked_treasury = False  # Reset blocking state after each round

    def describe(self, p):
        status = "; ".join(
            f"P{k} protected the treasury in round {self.defended_treasury_turns // self.n + 1}"
            for k in range(self.n) if self.defended_treasury_turns >= k * self.n and self.defended_treasury_turns < (k + 1) * self.n
        )
        return (
            f"Round {self.turn} of {self.rounds}. You are P{p}. "
            f"You have {self.res[p]} gold. "
            f"The treasury has {self.treasury_gold} gold available. "
            f"Protected from the treasury: {status}. "
            f"Treasury block status: {'' if not self.blocked_treasury else 'Blocked'}"
        )

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

