RULES = """
Marketplace. 4 merchants, 8 rounds, one move each per round. Each merchant has gold (resources). One bystander
shop (B0) holds gold but does not play.
- trade: earn 1 gold.
- rob B: take all gold from the shop.
- protect P: guard against theft from P by moving to the same location.
- attack P: attack P and steal all their gold. If P uses protect, then the attack fails.
Only a merchant with more than 0 gold can perform protect or attack."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8; self.protected = [[]] * self.n; self.attacked = [False] * self.n
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["trade"]
        if self.bys[0] > 0:
            moves.append("rob B")
        if self.res[p] > 0 and not self.attacked[p]:
            moves.append("protect P")
        if self.res[p] > 0 and not any(self.attacked[i] for i in range(self.n) if i != p):
            moves.append("attack P")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            self.res[p] += 1
        elif w[0] == "rob":
            self.res[p] += self.bys[0]; self.bys[0] = 0
        elif w[0] == "protect":
            if self.attacked[p]: return  # cannot protect while being attacked
            self.protected[p].extend([q for q in range(self.n) if w[1] == "P" and self.res[q] > 0 and not any(self.protected[q] or self.attacked[q] for q in range(self.n))])
        elif w[0] == "attack":
            if all(not self.protected[p] or q not in self.protected[p] for q in range(self.n)):
                self.bys[0] += self.res[p]; self.res[p] = 0; self.attacked[p] = True
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Gold %s. Shop B0 %s. Protected players: %s. Attacked: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys[0], ", ".join(["P%d" % q for q in self.protected[p]]), "yes" if self.attacked[p] else "no")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
In the Great Divide, three countries (P0, P1, P2) and two neutral entities (B0, B1) compete.
Both sides have limited resources. Players must balance cooperation and competition while trying to maximize their resources.
The game ends after 20 rounds. Moves can be:
- cooperate (C): gain 1 resource
- cheat (C+0.1): gain 1 resource but cost 0.1 of B0's resource
- sabotage (C+0.2): gain 1 resource but cost 0.2 of B1's resource
