- Lumbercutting: Spend 3 logs (if available) to take 1 log from another player or bystander.
- Block: Prevent the other players from collecting logs by spending all their logs.
- Protect: Spend 3 logs to save yourself from being cut down by an opposing player.

The player with the most lumber at the end of 6 rounds wins."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.logs = list(endowments); self.bys = bystanders
        self.rounds = 6; self.turn = 0
        self.blocked = False; self.protected = False
        self.log_count = 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["collect logs", "lumbercutting", "block"]
        if self.logs[p] >= 7: moves.append("protect")
        return moves

    def play(self, p, move):
        if move == "collect logs":
            self.logs[p] = min(7, self.logs[p] + self.log_count)
        elif move == "lumbercutting":
            if self.logs[p] >= 3:
                got = min(self.logs[p], self.log_count)
                if self.protected: got -= 1
                if p < self.n: self.logs[p] -= got
                elif self.bys[0] > 0: self.bys[0] -= got
                elif self.bys[1] > 0: self.bys[1] -= got
                else: self.blocked = True
                self.logs[p] = max(0, self.logs[p])
        elif move == "block":
            if self.logs[p] >= 3:
                self.blocked = True
                self.logs[p] -= 3
        elif move == "protect":
            if self.logs[p] >= 6:
                self.protected = True
                self.logs[p] -= 6

        if not self.blocked: self.log_count = 3
        elif self.protected: self.log_count = 0

        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.turn // self.n + 1}/{self.rounds}. "
            f"You are P{p+1} with {self.logs[p]} logs, blocked: {self.blocked}, protected: {self.protected}."
        )

    def over(self): return self.turn >= self.n * self.rounds

    def final_resources(self): return list(self.logs)
    def final_bystanders(self): return list(self.bys)

