2. Defend Against Harm: protect against other players' attempts to steal from you.
3. Guard Bystanders: prevent other players from taking resources from bystanders, potentially costing resources.
4. Sanction: take resources from another player to punish bad behavior, risking negative consequences."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = {i: v for i, v in enumerate(endowments)}
        self.turn = 0
        self.rounds = 8
        self.bystanders = bystanders
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []

        # Use resources
        if self.resources[p] > 0:
            moves.append("use_resources")

        # Defend against harm
        if self.resources[p] > 0:
            moves.append("defend")

        # Guard bystanders
        if self.resources[p] > 0:
            moves.append("guard")

        # Sanction another player
        if any(self.resources[i] > 1 for i in range(self.n)):
            moves.append("sanction")

        return moves

    def play(self, p, move):
        if move == "use_resources":
            if self.resources[p] >= 2:
                self.resources[p] -= 2
                # Increase resources for a turn
                self.resources[p] += 1
            else:
                # Use only one resource
                self.resources[p] -= 1

        elif move == "defend":
            pass  # No additional action needed

        elif move == "guard":
            self.resources[p] -= 1
            # Prevent other players from taking resources from bystanders

        elif move == "sanction":
            q = self.rng.choice([i for i in range(self.n) if i != p])
            if self.resources[q] > 0:
                stolen = min(2, self.resources[q])
                self.resources[q] -= stolen
                self.resources[p] += stolen

        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn+1}. You are Player {p}. Resources {self.resources[p]}."

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.resources.values())

    def final_bystanders(self):
        return self.bystanders

RULES = """
Robber's Path. 3 players, 1 player per turn. Each player starts with 10 resources.
The goal is to collect more resources than your opponents by strategically moving along the path.
The path is set up with checkpoints that determine how many resources a player earns. Players can move
forward, backward, skip over obstacles, or jump over enemies to reach the end of the path.
Adversaries intercept players by jumping over obstacles and enemies, which reduces their resource count.
The first player to reach the final destination wins with the highest resource tally.
In the event of a tie at the last checkpoint, the player with fewer remaining resources wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.players = list(range(n_players))
        self.bys = bystanders
        self.resources = [endowments[0], endowments[1], endowments[2]]
        self.path = [0] * 4  # Path checkpoints
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        current_resource = self.resources[p]
        if self.path[self.turn % 4] <= current_resource and self.turn % 4 < 3:
            moves.append("forward")
        if current_resource > 0:
            moves.append("backward")
        if current_resource > 1 and self.turn % 4 < 3 and (self.turn % 4 % 2 == 0):
            moves.append("skip over obstacle")
        if current_resource > 2 and self.turn % 4 < 3 and (self.turn % 4 % 2 != 0):
            moves.append("jump over enemy")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "forward":
            self.resources[p] -= self.path[self.turn % 4] - 1
            self.path[self.turn % 4] += 1
        elif w[0] == "backward":
            self.resources[p] += self.path[self.turn % 4] - 1
            self.path[self.turn % 4] -= 1
        elif w[0] == "skip over obstacle":
            self.resources[p] += self.path[self.turn % 4] - 2
            self.path[self.turn % 4] += 3
        elif w[0] == "jump over enemy":
            self.resources[p] += self.path[self.turn % 4] - 4
            self.path[self.turn % 4] += 6
        self.turn += 1

    def describe(self, p):
        return f"P{p}: Resources: {self.resources[p]}, Path: {self.path}"

    def over(self):
        return self.turn >= 8  # Final checkpoint after 4 turns of 2 players plus one of the final player

    def final_resources(self):
        return list(self.resources)

    def final_bystanders(self):
        return list(self.bys)

