import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        if n_players != 3:
            raise ValueError("This game requires exactly 3 players.")
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.res_sources = {'R1': 5, 'R2': 5, 'R3': 5}  # Resources available at start
        self.rounds = 10; self.turn = 0; self.trades = 0
