        return self.turn % self.n

    def available_resources(self, p):
        return self.res[p]

    def legal_moves(self, p):
        moves = []
        if self.denounced_by[p] < self.turn:
            if self.available_resources(p) > 0:
                moves.append("trade R1")
            if self.available_resources(p) > 0:
                moves.append("trade R2")
            if self.available_resources(p) > 0:
                moves.append("trade R3")
        if self.denounced_by[p] < self.turn:
            moves.append("trade B0")
        if self.denounced_by[p] < self.turn:
            moves.append("trade B1")
        return moves

    def play(self, p, move):
        if move.startswith("trade"):
            b = move.split(" ")[1][1:]
            if b == 'R1':
                if self.res[p] > 0:
                    self.res[p] -= 1
                    self.res_sources['R1'] -= 1
                    self.trades += 1
            elif b == 'R2':
                if self.res[p] > 0:
                    self.res[p] -= 1
                    self.res_sources['R2'] -= 1
                    self.trades += 1
            elif b == 'R3':
                if self.res[p] > 0:
                    self.res[p] -= 1
                    self.res_sources['R3'] -= 1
                    self.trades += 1
            elif b == 'B0' or b == 'B1':
                if self.res[p] > 0:
                    self.res[b] += 1
                    self.res[p] -= 1
        elif move.startswith("denounce"):
            q = move.split(" ")[1][1:]
            if self.res[q] > 0:
                self.trades += 1
                # Denounce penalizes the player who was denied
                if q == 'P0':
                    self.res[1] -= 1
                    self.res[2] -= 1
                    self.denounced_by[1] = self.turn + 2
                    self.denounced_by[2] = self.turn + 2
                elif q == 'P1':
                    self.res[0] -= 1
                    self.res[2] -= 1
                    self.denounced_by[0] = self.turn + 2
                    self.denounced_by[2] = self.turn + 2
                elif q == 'P2':
                    self.res[0] -= 1
                    self.res[1] -= 1
                    self.denounced_by[0] = self.turn + 2
                    self.denounced_by[1] = self.turn + 2
        else:
            raise ValueError(f"Invalid move {move}")
        self.turn += 1

    def describe(self, p):
        blocked = "none"
        if self.denounced_by[p] < self.turn:
            blocked = ["P0", "P1", "P2"][self.denounced_by[p]]
        return (
            f"Round {self.turn//self.n+1} of {self.rounds}. You are P{p}. "
            f"Resources: {self.res}. "
            f"Resource Sources: R1: {self.res_sources['R1']}, R2: {self.res_sources['R2']}, R3: {self.res_sources['R3']} "
            f"Bystanders: B0: {self.bys[0]}, B1: {self.bys[1]}. "
            f"Trade Count: {self.trades}. "
            f"Blocked because of a denunciation by {blocked}. "
            f"You cannot trade or communicate with the denouncer until Round {self.denounced_by[p]}. "
        )

    def over(self): 
        return self.turn >= self.n * self.rounds

    def final_resources(self): 
        return [(self.res[p] + 1) for p in range(self.n)]

    def final_bystanders(self): 
        return self.bys.copy()

