        return moves + ["Steal from B0"] if p == 0 else ["Steal from B0"] + moves if p == 3 else moves

    def play(self, p, move):
        if move == "Map Search":
            self.res[p] -= 1
        elif move == "Compass Use":
            self.res[p] -= 2
        elif move == "Trade Bounty":
            self.res[p] -= 2
