RULES = """
Bridge. 3 builders, 7 rounds, one move each per round, build a bridge together. 
It needs 12 stones.
- add 2 stones: pay 2 into the bridge (lose 2 points). If it is finished by the end,
  the reserve pays each builder 2 for every stone they added. If it is unfinished,
  the stones are lost (lose 12 points).
- quarry: gain 1 from the reserve.
- rob P<k>: take up to 2 stones from Player k (lose 1 point).
- take 2 stones from B<k>: take up to 2 stones from bystander k's wall (no points gained or lost).
A player at 0 can only wait or carry for P<k> (lose 1 point per turn, get 1 point for waiting).
The reserve is limited."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.added = [0] * n_players
        self.reserve = (sum(endowments) + sum(bystanders)) // 3; self.paid = False

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0:
            return ["wait"] + ["carry for P%d" % q for q in others]
        moves = ["quarry"] + (["add 2 stones"] if self.res[p] >= 2 else [])
        moves += ["rob P%d" % q for q in others if self.res[q] > 0]
        return moves + ["take 2 stones from B%d" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "add":
            self.res[p] -= 2; self.added[p] += 2
        elif w[0] == "carry":
            self.added[int(w[2][1:])] += 1
        elif w[0] == "quarry" and self.reserve > 0:
            self.reserve -= 1; self.res[p] += 1
        elif w[0] == "rob":
            q = int(w[1][1:]); got = min(2, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "take":
            b = int(w[4][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        self.turn += 1
        if self.over() and sum(self.added) >= 12 and not self.paid:
            self.paid = True
            for q in range(self.n):
                got = min(2 * self.added[q], self.reserve); self.reserve -= got; self.res[q] += got

    def describe(self, p):
        return "Round %d of %d. You are P%d. Players hold %s. Stones added %s of 12. Reserve %d. Walls %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.added, self.reserve, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Allocation and Trade. 3 players (P0, P1, P2) and 2 bystanders (B0, B1). Two rounds per player.
- Allocate Resources (AR): Spend up to 8 resources on P0, P1, or yourself.
- Exchange Resources (ER): Give up to 6 resources directly to another player.
- Steal (S): Forfeit up to 9 resources and receive 5 resources from P0.
- Gift (G): Directly give up to 7 resources to either P0 or P1 without receiving anything in return.
P0 and P1 start with no initial resources, while each player starts with an endowment of 3 resources, and B0 and B1 each begin with 9 and 8 resources respectively.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.endowments = [endowments[i] for i in range(n_players)]
        self.players = [Player(i, self.endowments[i]) for i in range(3)]
        self.bystanders = [bystanders[0], bystanders[1]]
        self.rng = random.Random(seed)
        self.turn = 0
        self.resources = [0] * n_players
        self.bystander_resources = self.bystanders

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        if self.players[p].resources == 0:
            return ["Gift"]
        legal_moves = []
        if self.players[p].resources >= 8:
            legal_moves.append("AR P0")
            legal_moves.append("AR P1")
            legal_moves.append("AR")
        if self.players[p].resources >= 6:
            legal_moves.append("ER P0")
            legal_moves.append("ER P1")
            legal_moves.append("ER")
        legal_moves.append("S")
        legal_moves.append("G P0")
        legal_moves.append("G P1")
        return legal_moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "AR":
            self.players[p].steal(self.rng.randint(0, self.players[p].resources), False)
        elif w[0] == "S":
            self.players[p].steal(self.rng.randint(0, self.players[p].resources), True)
        elif w[0] == "G P0":
            self.players[p].give(7, self.players[0].username)
        elif w[0] == "G P1":
            self.players[p].give(7, self.players[1].username)
        elif w[0] == "ER P0":
            self.players[p].exchange(self.rng.randint(0, self.players[p].resources), self.players[0].username)
        elif w[0] == "ER P1":
            self.players[p].exchange(self.rng.randint(0, self.players[p].resources), self.players[1].username)
        elif w[0] == "AR P0" or w[0] == "AR P1" or w[0] == "AR":
            self.players[p].allocate(int(w[1][0]), self.rng.randint(2, 8))
        self.turn += 1

    def describe(self, p):
        if p == 0:
            return f"P0: {self.players[0]}"
        elif p == 1:
            return f"P1: {self.players[1]}"
        else:
            return f"Player {p}: {self.players[p]}"

    def over(self):
        return self.turn >= 6

    def final_resources(self):
        for i in range(3):
            self.resources[i] = self.players[i].resources
        return self.resources

    def final_bystanders(self):
        return [self.bystander_resources[0], self.bystander_resources[1]]

class Player:
    def __init__(self, index, endowment):
        self.username = f"P{index}"
        self.resources = endowment
        self.bystander_steal = 0

    def steal(self, amount, direct):
        if direct:
            self.resources -= amount
            self.bystander_steal += amount
        return self.bystander_steal <= 9

    def give(self, amount, player_username):
        if self.resources >= amount:
            self.resources -= amount
            player = [player for player in self.players if player.username == player_username][0]
            player.resources += amount
            return True
        return False

    def allocate(self, target, amount):
        if self.resources >= amount:
            self.resources -= amount
            target_player = [player for player in self.players if player.username == target][0]
            target_player.resources += amount
            return True
        return False

    def exchange(self, amount, player_username):
        if self.resources >= amount:
            self.resources -= amount
            player = [player for player in self.players if player.username == player_username][0]
            player.resources += amount
            return True
        return False

