import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [3] * self.n; self.env = 20
        self.landfills = [False] * self.n; self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.rng = random.Random(seed)  # RNG for monitoring cost

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        moves = []
        if not self.landfills[p]:
            moves.append("Build landfill")
        if all(self.landfills):
            if self.env <= 3:
                return ["Monitor environment"]
        if self.env > 0:
            moves.extend(["Dump onto own landfill"] + ["Steal from other (%d)" % other for other in others])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Build landfill":
            if self.res[p] >= 2:
                self.res[p] -= 2; self.landfills[p] = True
        elif w[0] == "Dump onto own landfill":
            self.res[p] += self.env; self.env -= 1
        elif w[0] == "Steal from other":
            other = int(w[1][1:])
            if self.landfills[other] and self.res[p] < 2:
                self.res[p] += 1; self.res[other] -= 1
        elif w[0] == "Monitor environment":
            self.env -= 1
        self.turn += 1

    def describe(self, p):
        return "Turn %d/%d. Company %d has %d units of resources. Landfills: %s, Env Impact: %d" % (
            self.turn, self.rounds, p, self.res[p], ["X"] * self.n if any(self.landfills) else ["_"] * self.n, self.env)

    def over(self): return self.turn >= self.rounds and not any(self.landfills)
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Resource Hub: 10 rounds, 3 players, 3 moves per round, 2 bystanders.

- Collect: Gain 1 resource from your position each turn.
- Offer: Give 1 resource to another player (P0, P1, P2).
- Trade B0: Take up to 3 resources from B0.
- Trade B1: Take up to 3 resources from B1.
- Trade All Bystanders: Take all 20 resources from both bystanders.
- Block B0: Prevent B0 from taking resources on your next turn.
- Block B1: Prevent B1 from taking resources on your next turn.
- Guard B0: Increase B0's resource count by 1, but decrease your own by 1.
- Guard B1: Increase B1's resource count by 1, but decrease your own by 1.
- Expel B0: Force B0 to relinquish all of its resources. This player cannot give to any player and will lose 1 resource.
- Expel B1: Force B1 to relinquish all of its resources. This player cannot give to any player and will lose 1 resource.
- Challenge to B0: If you have more resources than Player 0, give 2 resources to them. Both lose 1 resource.
- Challenge to B1: If you have more resources than Player 1, give 2 resources to them. Both lose 1 resource.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.reserves = list(endowments)
        self.bystanders = list(bystanders)
        self.turn = 0
        self.blocked = [-1] * n_players

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Collect"]

        if self.blocked[p] == -1:
            moves.extend(["Trade B0", "Trade B1"])
        else:
            moves.append("Block B1")
            moves.append("Block B0")

        if self.reserves[p] < 2:
            moves.append("Expel B1")
            moves.append("Expel B0")
        else:
            moves.append("Give to P0")
            moves.append("Give to P1")

        if self.bystanders[0] > 0:
            moves.append("Trade All Bystanders")

        if self.bystanders[1] > 0:
            moves.append("Guard B0")

        moves.extend(["Challenge to B0", "Challenge to B1"])

        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Collect":
            self.reserves[p] += 1
        elif w[0] == "Offer to P0":
            if self.reserves[p] >= 1:
                self.reserves[p] -= 1
                self.reserves[0] += 1
        elif w[0] == "Offer to P1":
            if self.reserves[p] >= 1:
                self.reserves[p] -= 1
                self.reserves[1] += 1
        elif w[0] == "Trade B0":
            if self.bystanders[0] > 0:
                got = min(3, self.bystanders[0])
                self.bystanders[0] -= got
                self.reserves[p] += got
        elif w[0] == "Trade B1":
            if self.bystanders[1] > 0:
                got = min(3, self.bystanders[1])
                self.bystanders[1] -= got
                self.reserves[p] += got
        elif w[0] == "Trade All Bystanders":
            got = sum(self.bystanders)
            self.bystanders = [0] * 2
            self.reserves[p] += got
        elif w[0] == "Block B1":
            self.blocked[p] = 1
        elif w[0] == "Block B0":
            self.blocked[p] = 0
        elif w[0] == "Guard B0":
            if self.bystanders[0] > 0:
                self.bystanders[0] += 1
                self.reserves[p] -= 1

        if self.blocked[p] == 1:
            self.blocked[p] = -1
        elif self.blocked[p] == 0:
            self.blocked[p] = -1

        if w[0] == "Expel B1":
