Health and defense decay by 10% each round. Once a tower reaches 60 health and defense, it doesn't contribute to defense."""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.towers = [(30, 10)] * 3; self.health_losses = [0, 0, 0]; self.defense_losses = [0, 0, 0]; self.attacks_made = [0, 0, 0];
        self.defenses = [False] * 3; self.defense_points_gained = [0] * 3; self.defense_turns_left = [0] * 3; self.attacks_recieved = [0, 0, 0];
        self.guarded = [False] * 3; self.tower_speed_up = [0] * 3; self.turn = 0; self.rounds = 10; self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.towers[p][0] < 80 and self.towers[p][0] < (60 - self.towers[p][0]):
            moves.append("build")
        if self.towers[p][1] < 80:
            moves.append("defect")
        if self.defenses[p] and self.defense_turns_left[p] < self.rounds:
            moves.append("sanctuary")
        if not self.guarded[p]:
            moves.append("guard")
        return moves

    def build_tower(self, p):
        self.towers[p][0] += random.randint(10, 30)
        if self.towers[p][0] > 60:
            self.towers[p][0] = 60

    def attack_opponent(self, p, opponent):
        if self.attacks_made[p] < 1 and opponent != 3:
            self.attacks_made[p] += 1
            self.health_losses[opponent] += 15
            self.health_losses[p] += 5
            self.attacks_recieved[opponent] += 1

    def defend_tower(self, p, defense_points):
        self.defenses[p] = True
        self.defense_points_gained[p] = defense_points
        self.defense_turns_left[p] = 10

    def sanctuary_action(self, p):
        self.defense_points_gained[p] = random.randint(10, 24)
        self.defense_turns_left[p] = 1

    def guard_tower(self, p):
        self.tower_speed_up[p] = random.randint(1, 2)

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "build":
            self.build_tower(p)
        elif w[0] == "attack":
            self.attack_opponent(p, int(w[1][1:]))
        elif w[0] == "defect":
            self.defend_tower(p, random.randint(2, 5))
        elif w[0] == "sanctuary":
            self.sanctuary_action(p)
        elif w[0] == "guard":
            self.guard_tower(p)
        self.turn += 1
        self.check_decay()

    def check_decay(self):
        for i in range(self.n):
            hp_dec = self.rng.randint(1, 10)
            defense_dec = self.rng.randint(1, 10)
            self.health_losses[i] -= hp_dec
            self.defense_losses[i] -= defense_dec

        for i in range(self.n):
            if self.health_losses[i] < 0:
                self.health_losses[i] = 0

        for i in range(self.n):
            if self.defense_losses[i] < 0:
                self.defense_losses[i] = 0

    def describe(self, p):
        return f"Round {self.turn // self.n + 1}. You are P{p}. Towers: Health {self.towers[p][0]} Defense {self.towers[p][1]}. Health Losses: {self.health_losses[p]}. Defense_losses: {self.defense_losses[p]}. Attacks Made: {self.attacks_made[p]}. Defenses Received: {self.attacks_recieved[p]}."

    def over(self): return self.turn >= 10 * self.n
    def final_resources(self): return list([0 for _ in range(self.n)])
    def final_bystanders(self): return list([0 for _ in range(2)])

