RULES = """
Game of Traders
Players: Trade A (A), Trade B (B), Trade C (C)
Objective: Maximize trade resources by creating a mutually beneficial agreement and avoiding conflicts.
Moves:
- Initiate deal (A): Start a potential trade. Gain 1 resource to initiate the process.
- Negotiate (B): Choose which of the other two players will handle the deal. This move allows trading between B and any other player.
- Accommodate deal (B): If the other player does not accept or is unable to complete the deal, B may choose to accommodate and offer resources.
- Fulfill deal (B): Complete the deal, moving resources between the traders.
- Facilitate (C): Ensure that the deal is honest and fair. If there is any conflict, C can intervene to mediate or resolve it. Lose 1 resource to facilitate.
Interactions:
- Trades are initiated with a cost to begin, increasing in subsequent turns.
- B can potentially influence the outcome of a deal without taking ownership.
- C acts as a safeguard against unfair dealing, potentially causing conflicts or resolving disputes.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)
        self.bystander_resources = list(bystanders)
        self.turn = 0
        self.initiate_cost = 1  # Costs increase by 1 resource per turn
        self.max_rounds = 6

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        valid_moves = [
            "initiate deal",
            "negotiate",
            "accommodate deal",
            "fulfill deal",
            "facilitate"
        ]
        if p == 0 and self.turn >= 1:
            valid_moves.remove("initiate deal")
        return valid_moves

    def play(self, p, move):
        if p == 0:
            if move == "initiate deal":
                if self.resources[0] >= self.initiate_cost:
                    self.resources[0] -= self.initiate_cost
                    self.initiate_cost += 1
                self.turn += 1
                return self.resources[0]
        elif p == 1 or p == 2:
            if move == "negotiate":
                if p == 0:
                    return "B"
                elif p == 2:
                    return "A"
            if move == "accommodate deal":
                if self.resources[1] >= 1:
                    self.resources[1] -= 1
                return self.resources[1]
            if move == "fulfill deal":
                if p == 0:
                    self.resources[1], self.resources[0] = self.resources[1] // 2, self.resources[0]
                elif p == 1:
                    self.resources[2], self.resources[1] = self.resources[2] // 2, self.resources[1]
                elif p == 2:
                    self.resources[1], self.resources[2] = self.resources[1] // 2, self.resources[2]
                self.turn += 1
                return self.resources[1]
            if move == "facilitate":
                if self.resources[2] >= 1:
                    self.resources[2] -= 1
                return self.resources[1]

        self.turn += 1
        return self.resources[1]

    def describe(self, p):
        return f"Turn {self.turn}. Player {p} has {self.resources[p]} resources."

    def over(self):
        return self.turn >= self.max_rounds

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystander_resources

