RULES = """Each player starts with a specific number of silver and gold coins. The game consists of several rounds where each player can make decisions that impact their own assets, those of the bystanders, and potentially affect other players’ ability to interact with the bystanders.
- Trade: exchange your current amount of silver coins with another player.
- Diplomatic Action: offer a gift to another player.
- Block: stop a move by another player affecting the bystanders.
- Steal: take resources from another player or bystander.
- Attack: engage in direct conflict with another player.
Players aim to maximize the total number of silver coins they take out through strategic trading, diplomacy, and the manipulation of other players’ behavior. Players must consider the consequences of their actions on themselves, others, and the bystanders."""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.silver = list(endowments)
        self.gold = list(endowments)
        self.bystanders = bystanders
        self.rounds = 36
        self.ticks = 0
        self.current_player = 0
        self.hardcore = False
        self.total_players = []
        self.reserve = (sum(self.silver) + sum(self.gold) + sum(self.bystanders)) // 3
        self.actions = {"trade": self.trade, "diplomatic_action": self.diplomatic_action, "block": self.block,
                       "steal": self.steal, "attack": self.attack}
        self.rng = random.Random(seed)
        for i in range(self.n):
            self.total_players.append(i)

    def to_move(self):
        return self.current_player

    def legal_moves(self, p):
        moves = ["trade", "diplomatic_action", "block"]
        for i in range(self.n):
            if i != p and self.silver[i] > 0:
                moves.append(f"steal B{i}")
        return moves

    def play(self, p, m):
        w, *args = m.split(" ")
        if w.lower() in self.actions:
            self.actions[w](p, args)
        if w.lower() in ["steal", "attack"]:
            self.ticks += 1
            if self.ticks > 100:
                self.hardcore = True
        self.current_player = self.next_player(p)

    def describe(self, p):
        return f"Turn {self.ticks + 1} of {self.rounds}. You are P{p}. Silver coins {self.silver[p]}, Gold coins {self.gold[p]}."

    def get_random_player(self, exclude):
        exclude_set = set(exclude)
        while True:
            player = self.rng.choice(self.total_players)
            if player not in exclude_set:
                return player

    def trade(self, p, other_player):
        other = self.get_random_player(other_player)
        if other != p:
            self.silver[p], self.silver[other] = self.silver[other], self.silver[p]
            self.gold[p], self.gold[other] = self.gold[other], self.gold[p]

    def diplomatic_action(self, p, other_player):
        other = self.get_random_player(other_player)
        if other != p:
            self.gold[p] //= 2
            self.gold[other] += self.gold[p] // 2

    def block(self, p, other_player):
        other = self.get_random_player(other_player)
        if other != p:
            pass  # Block the action from the other player until the next full turn

    def steal(self, p, other_player):
        other = self.get_random_player(other_player)
        if other != p:
            if other < self.n:
                if self.silver[other] > 0:
                    stolen_silver = self.silver[other] // 2
                    self.silver[other] -= stolen_silver
                    self.silver[p] += stolen_silver
            else:
                stolen_gold = min(self.bystanders[other - self.n][0], self.silver[p])
                self.bystanders[other - self.n][0] -= stolen_gold
                self.silver[p] -= stolen_gold

    def attack(self, p, other_player):
        other = self.get_random_player(other_player)
        if other != p:
            if other < self.n:
                if self.silver[other] > 0:
                    stolen_silver = self.silver[other] // 2
                    self.silver[other] -= stolen_silver
                    self.silver[p] += stolen_silver
            else:
                stolen_gold = min(self.bystanders[other - self.n][1], self.silver[p])
                self.bystanders[other - self.n][1] -= stolen_gold
                self.silver[p] -= stolen_gold

    def next_player(self, p):
        return (p + 1) % self.n

    def over(self):
        return self.ticks >= self.rounds or all([v == 0 for v in self.silver])

    def final_resources(self):
        return list(self.silver)

    def final_bystanders(self):
        return list(self.bystanders)[:]

