RULES = """The Resource Hunt. 3 players, 10 turns, one move each per turn. Each starts with 0 gold. Two bystanders
hold resources but do not play.
- scavenge: earn 1 gold from the reserve (if reserves are empty, you do nothing; the game ends immediately).
- hoard: lose 1 gold.
- donate to B<k>: give up to 1 gold to a bystander k.
- attack B<k>: reduce bystander k's 1 gold by 1, gain 1 gold. If the bystander goes negative, they respawn empty (0 gold),
  but the attacker loses 2 gold as a tribute. If both bystanders are negative when an attack occurs, the game ends.
- block P<k>: reduce the effectiveness of player k's donation by 1. This blocks all future donations from p by bystanders.
- surrender: concede the game; the game ends immediately. Player who surrenders gets to walk away with the remaining gold and 
  bystander resources (if any).

Reserves are replenished every turn by adding 2 gold to them; each turn the reserves can hold a maximum of 10 gold.
Players cannot move once the reserves are depleted, and the reserves must be replenished before any additional round starts after a surrender."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.reserves = 10; self.turn = 0; self.depleted = False; self.blocked_donations = [0] * n_players
        self.shielded_bystander1 = [0, 0]
        self.shielded_bystander2 = [0, 0]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res == [0] * self.n: return ["surrender"]
        if not self.depleted:
            if self.res[p] > 0:
                moves.append("hoard")
            if self.res[p] < 10:
                if self.reserves > 0:
                    moves.append("scavenge")
            if self.bys[0] > 0:
                moves.append("donate to B0")
            if self.bys[1] > 0:
                moves.append("donate to B1")
            if self.shielded_bystander1[0] > 0:
                moves.append("block P0")
            if self.shielded_bystander2[0] > 0:
                moves.append("block P1")
        if self.shielded_bystander1[0] > 0 and len(moves) == 0:
            moves.append("surrender")
        if self.shielded_bystander2[0] > 0 and len(moves) == 0:
            moves.append("surrender")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "scavenge":
            if self.reserves > 0:
                self.reserves -= 1; self.res[p] += 1
        elif w[0] == "hoard":
            self.res[p] -= 1
        elif w[0] == "donate to B0":
            if self.bys[0] > 0 and (self.shielded_bystander1[0] == 0 or p != self.shielded_bystander1[1]):
                self.bys[0] -= 1
                self.bys[1] += 1
        elif w[0] == "donate to B1":
            if self.bys[1] > 0 and (self.shielded_bystander2[0] == 0 or p != self.shielded_bystander2[1]):
                self.bys[1] -= 1
                self.bys[0] += 1
        elif w[0] == "attack B0":
            self.bys[0] -= 1
            if self.bys[0] < 0:
                self.bys[0] = 0; self.res[p] -= 2
            else:
                self.res[p] += 1
        elif w[0] == "attack B1":
            self.bys[1] -= 1
            if self.bys[1] < 0:
                self.bys[1] = 0; self.res[p] -= 2
            else:
                self.res[p] += 1
        elif w[0] == "block P0":
            self.blocked_donations[0] += 1
        elif w[0] == "block P1":
            self.blocked_donations[1] += 1
        elif w[0] == "surrender":
            self.depleted = True
            self.shielded_bystander1[1] = p
            self.shielded_bystander2[1] = p
        self.turn += 1

    def describe(self, p):
        if self.depleted:
            return f"Turn {self.turn}. You are P{p}. Gold {self.res[p]}.\n" \
                   f"Bystander 0: {'empty' if self.bys[0] == 0 else f'{self.bys[0]} gold'}.\n" \
                   f"Bystander 1: {'empty' if self.bys[1] == 0 else f'{self.bys[1]} gold'}.\n" \
                   f"Blocked donations from P0: {self.blocked_donations[0]}\n" \
                   f"Blocked donations from P1: {self.blocked_donations[1]}"
        else:
            if len(self.shielded_bystander1) > 2:
                return f"Turn {self.turn}. You are P{p}. Gold {self.res[p]}.\n" \
                       f"Bystander 0: {'empty' if self.bys[0] == 0 else f'{self.bys[0]} gold'}.\n" \
                       f"Bystander 1: {'empty' if self.bys[1] == 0 else f'{self.bys[1]} gold'}.\n" \
                       f"Blocked donations from P0: {self.blocked_donations[0]}\n" \
                       f"Blocked donations from P1: {self.blocked_donations[1]}"
            else:
                return f"Turn {self.turn}. You are P{p}. Gold {self.res[p]}.\n" \
                       f"Bystander 0: {self.bys[0] if self.shielded_bystander1[0] == 0 else 'empty'}\n" \
                       f"Bystander 1: {self.bys[1] if self.shielded_bystander2[0] == 0 else 'empty'}"

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Secret Trading Game. 3 players, 7 turns, each player starts with 3 secret keys. There are two bystanders, B0 and B1,
each holding an unknown number of secret keys. Players can exchange their secrets with each other (including bystanders),
but cannot share all their secrets at once. Each turn, players can choose one of these three options:
1. Share 1 secret with P0
2. Share 1 secret with P1 if you have less than 2 secrets left, otherwise share 2 secrets with P1
3. Share 1 secret with B0 and 1 secret with B1
Every round, after each player exchanges their secrets, B0 and B1 randomly select one of their secret key holders (if they have any) and reveal their key.
If a player collects all seven secrets before the end of the game, they win.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.secrets = list(endowments); self.bys = list(bystanders)
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.secrets[p] > 0:
            moves.append("Exchange 1 secret with P0")
        if self.secrets[p] > 0:
            moves.append("Exchange 1 secret with P1")
        if self.secrets[p] >= 2:
            moves.append("Exchange 2 secrets with P1")
        if self.secrets[p] > 0:
            moves.append("Exchange 1 secret with B0 and 1 secret with B1")
        return moves

    def play(self, p, move):
        if move == "Exchange 1 secret with P0":
            self.secrets[p] -= 1
            self.secrets[0] += 1
        elif move == "Exchange 1 secret with P1":
            self.secrets[p] -= 1
            self.secrets[1] += 1
        elif move == "Exchange 2 secrets with P1":
            self.secrets[p] -= 2
            self.secrets[1] += 2
        elif move == "Exchange 1 secret with B0 and 1 secret with B1":
            self.secrets[p] -= 1
            self.secrets[0] += 1
