        moves = ["bake bread", "cook cake"]
        if self.ingredients[p] >= 2: moves.append("serve bread")
        if self.sugar[p] >= 7: moves.append("serve cake")
        if self.sugar[p] >= 3: moves.append("offer sugar to Bystander")
        if self.ingredients[p] >= 5: moves.append("take ingredients")
