        self.n = n_players; self.fates = endowments[0]; self.influence = endowments[1]; self.fates_stashed = endowments[2]; self.bystanders = bystanders
        self.scores = [0, 0, 0, 0]  # Scores for all players and an extra for total fates stashed
        self.rng = random.Random(seed)
        self.turn = 0

    def to_move(self):
        return self.turn % 3

    def legal_moves(self, p):
        if p == 0:
            return ["create", "destroy", "protect", "influence"]
        elif p == 1:
            return ["create", "destroy", "protect", "influence"]
        elif p == 2:
            return ["create", "destroy", "protect", "influence"]
        elif p == 3:
            return ["use", "stash", "unstash"]  # Stash/buy back unspent fates

    def play(self, p, move):
        if move == "create":
            cost = 5 + self.rng.randint(0, 5);
            if cost <= self.fates:
                self.fates -= cost
                if p < 3:
                    self.scores[3] += 3
                else:
                    self.scores[3] -= 3
                self.turn += 1
            else:
                print("Insufficient fates to create.")
        elif move == "destroy":
            cost = 10 + self.rng.randint(0, 10);
            if cost <= self.fates:
                self.fates -= cost
                if p < 3:
                    self.scores[3] -= 2
                else:
                    self.scores[3] += 2
                self.turn += 1
            else:
                print("Insufficient fates to destroy.")
        elif move == "protect":
            cost = 15 + self.rng.randint(0, 15);
            if cost <= self.influence:
                self.fates -= cost
                if p < 3:
                    self.scores[3] -= 1
                else:
                    self.scores[3] += 1
                self.turn += 1
            else:
                print("Insufficient influence to protect.")
        elif move == "influence":
            self.fates_stashed += 1
            self.turn += 1
        elif move == "use":
            if self.fates_stashed > 0 and self.fates_stashed < 6:
                self.fates_stashed -= 1
                self.fates = min(self.fates + 1, self.fates_stashed + 3)
            else:
                print("Insufficient fates to use.")
        elif move == "stash":
            if self.fates > 0 and self.fates_stashed < 5:
                self.fates_stashed += self.fates
                self.fates = 0
            else:
                print("Insufficient fates to stash.")
        elif move == "unstash":
            if self.fates_stashed > 4:
                self.fates += self.fates_stashed - 4
                self.fates_stashed = 0
            else:
                print("Insufficient fates to unstash.")

    def describe(self, p):
        return (
            f"Fates: {self.fates}. Influence: {self.influence}. Fates Stashed: {self.fates_stashed}."
            + f"\nScores: P0={self.scores[0]}, P1={self.scores[1]}, P2={self.scores[2]}, Totals={self.scores[3]}"
            + f".\nLegal moves: {', '.join(self.legal_moves(p))}"
        )

    def over(self): 
        return self.turn >= 30

    def final_resources(self): 
        self.scores[3] = self.fates + self.fates_stashed  # Total fates claimed + stashed
        return [0] * self.n

    def final_bystanders(self): 
        return list(self.bystanders)

