    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["guard"]
        moves = ["guard"] + (["protect S%s" % s for s in range(len(self.sby)) if s not in self.protected] + 
                           ["rob S%s" % s for s in range(len(self.sby)) if s not in self.fortified] +
                           ["fortify S%s" % s for s in range(len(self.sby)) if s not in self.protected])
        return moves + ["surrender P%s" % q for q in range(self.n) if q != p]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "guard":
            self.res[p] += 1
        elif w[0] == "protect":
            s = int(w[1][1:])
            self.protected.add(s); self.res[p] -= 1
        elif w[0] == "rob":
