        elif w[0] == "surrender":
            s = int(w[1][1:])
            if s in self.protected:
                self.res[p] -= 1; self.protected.remove(s)
        self.turn += 1

    def describe(self, p):
        prot = ["S%s" % s for s in self.protected]
        fort = ["S%s" % s for s in self.fortified]
        return "Round %d of %d. You are G%d. Gold %s. Strongholds %s. Fortified: %s. Protected: %s." % (
