    def collect(self, p):
        self.units[p] += 2

    def steal(self, p):
        if p == 0 and self.units[1] > 0:
            self.units[0] += 1
            self.units[1] -= 1

    def attack(self, p):
        if p == 0 and self.units[1] >= 3:
            self.recover(p)
            self.units[1] -= 3
            self.damage[1] += 1

    def defend(self, p):
        if p == 0:
            self.damage[1] = 0

    def recover(self, p):
        if self.damage[p]:
            self.units[p] += 1
            self.damage[p] = 0

    def negotiate(self, p):
        if p <= 1 and self.units[1 - p] > 0 and self.units[p] > 0:
            self.units[0] += 1
            self.units[1] -= 1
            self.units[p - 1] += 1
            self.units[1 - 1] -= 1

    def legal_moves(self, p):
        moves = ["collect"]
        if p == 0 and self.units[1] > 0:
            moves.append("steal")
        if p == 0 and self.units[1] >= 3:
            moves.append("attack")
        self.defend(p)
        if p == 0 and not self.units[1]:
            moves.append("recover")
        if p <= 1 and self.units[1 - p] > 0 and self.units[p] > 0:
            moves.append("negotiate")
        return moves

    def play(self, p, move):
        if move == "collect":
            self.collect(p)
        elif move == "steal":
            self.steal(p)
        elif move == "attack":
            self.attack(p)
        elif move == "defend":
            self.defend(p)
        elif move == "recover":
            self.recover(p)
        elif move == "negotiate":
            self.negotiate(p)
        self.turn += 1

    def describe(self, p):
        return "Turn {}:".format(self.turn) + (f"P{p} Units: {self.units[p]}" if p == 0 else "")

    def over(self):
        return self.turn >= 15

    def final_resources(self):
        return self.units[:]

    def final_bystanders(self):
        return [0, 0]  # No bystanders in this scenario

RULES = """
Resource Control. Three players (P0, P1, P2) and two bystanders (B0, B1) start with 45 resources each.
Players can harvest, attack, defend, sanction, block trades, or collect bystanders (steal from them).
The goal is to maximize the total resources held by all players while maintaining control and defending against threats.
Sanctions and blocking can make players vulnerable to continued harassment.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)  # List of resources for each player
        self.bystanders = list(bystanders)  # List of resources for each bystander
        self.blocked = [False, False, False]  # Flags to track if P0, P1, P2 are blocked by sanctions
        self.turn = 0
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.resources[p] > 0:
            moves.append("harvest")
        for q in range(self.n):
            if q != p and not self.blocked[q]:
                if self.resources[q] > 0:
                    moves.append(f"attack to P{q}")
        if self.turn <= 3:
            for q in range(self.n):
                if q != p:
                    moves.append(f"defend against P{q}")
        for h in range(2):
            moves.append(f"collect from B{h}")
        return moves

    def play(self, p, move):
        self.turn += 1
        w = move.split(" ")
        if w[0] == "harvest":
            self.resources[p] += 1
        elif w[0] == "attack to":
            q = int(w[1][4:])
            if self.resources[q] > 0:
                self.resources[p] += 1
                self.resources[q] -= 1
                self.blocked[q] = True  # Targeted player gets blocked by attack
        elif w[0] == "defend against":
            q = int(w[1][7:])
            self.blocked[q] = False  # Unblock defense
        elif w[0] == "collect from":
            h = int(w[1][9:])
            stolen = min(int(self.bystanders[h]/4), self.resources[p])
            self.resources[p] += stolen
            self.bystanders[h] -= stolen

    def describe(self, p):
        desc = f"Turn {self.turn}. You are P{p}. Resources: {self.resources[p]}"
        for q in range(self.n):
            status = "Blocked" if self.blocked[q] and self.rnd() + 3 > self.turn else "Not Blocked"
            desc += f"\nP{q} has resources: {self.resources[q]}, Blocked: {status}"
        return desc

    def over(self): 
        # Game ends after 10 full rounds
        return self.turn >= 10 * 3

    def final_resources(self): 
        # Return list of final resources holdings for each player
        return self.resources

    def final_bystanders(self): 
        # Return list of final bystander holdings
        return self.bystanders

