        self.was_stealed = False
        self.defending_p = -1
        self.round = 0

    def to_move(self): return self.round % 3

    def legal_moves(self, p):
        if self.round % 3 == p and self.endowments[p] >= 5:
            return ["take 1", "share 5", "try 3"]
        if self.round % 3 == p and self.endowments[p] < 5:
            return ["try 3"]
        if self.defending_p == -1 and self.endowments[p] >= 5:
            return ["defend j"]
        return []

    def play(self, p, move):
        split_move = move.split()
        if split_move[0] == "take 1" and self.endowments[p] < 5:
            print("Not enough coins. Cannot take 1.")
            return
        elif split_move[0] == "take 1":
            self.endowments[p] -= 5; self.c_reserve -= 1
            self.c_held[p] += 1
        elif split_move[0] == "share 5":
            if self.endowments[p] < 5:
                print("Not enough coins. Cannot share 5.")
                return
            self.endowments[p] -= 5; self.c_held[p] += 5
            self.bys[int(split_move[1])] += 5
        elif split_move[0] == "try 3":
            if p != 0 and self.endowments[p] < 5:
                print("Not enough coins. Cannot take 3.")
                return
            if p == 0 and self.was_stealed: 
                print("Already tried to steal. Cannot steal again.")
                return
            if self.endowments[p] < 5:
                print("Not enough coins. Cannot take 3.")
                return
            elif self.defending_p == 0:
                self.defending_p = -1
            self.was_stealed = True
            self.endowments[p] -= 3; self.endowments[1] += 3
        elif split_move[0] == "defend j":
            if p != -1:
                self.defending_p = p
        self.round += 1

    def describe(self, p):
        return f"Round {self.round} of 20. You are P{p+1}. Gold Held: {self.c_held[p]}, Reserve: {self.c_reserve}."

