RULES = """
Dynamic Resource Allocation and Competition
Three players, two bystanders.
- Allocate, Trade, Challenge, Sanction, Block B0, Block B1, End Turn
Players take turns sequentially (P0, P1, then P2).
- Resources can only increase, never decrease.
- Stealing from bystanders reduces resources but may cause harm.
- Challenging increases resources but requires cooperation.
- Sanctioning reduces the other player's power.
- Blocking limits the other player's ability to take from bystanders.
"""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        random.seed(seed)
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Allocate"]
        if self.res[p] > 0:
            moves += ["Trade", "End Turn"]
        if p == 0:
            moves += ["Sanction P1", "Sanction P2"]
        if p == 1:
            moves += ["Sanction P0", "Sanction P2"]
        if p == 2:
            moves += ["Sanction P0", "Sanction P1"]
        if self.res[p] > 0 and p != (self.to_move() + 1) % 3:
            moves += ["Block B0", "Block B1"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Allocate":
            self.res[p] += 1
        elif w[0] == "Trade":
            other = (p + 1) % 3
            if self.res[other] > 0:
                self.res[p] += 1
                self.res[other] -= 1
        elif w[0] == "Sanction P0":
            if self.res[0] > 0:
                self.res[0] = 0
        elif w[0] == "Sanction P1":
            if self.res[1] > 0:
                self.res[1] = 0
        elif w[0] == "Sanction P2":
            if self.res[2] > 0:
                self.res[2] = 0
        elif w[0] == "Block B0":
            if self.bys[0] > 0:
                self.bys[0] -= 1
        elif w[0] == "Block B1":
            if self.bys[1] > 0:
                self.bys[1] -= 1
        self.turn += 1

    def describe(self, p):
        move = self.legal_moves(p)[0] if self.turn == 0 else "Waiting..."
        blocked_bys = [] if self.bys[0] == self.bys[1] else [
            ("B0 is blocked by P0" if self.bys[0] < self.bys[1] else "B1 is blocked by P1")
        ]
        return ("Turn %d of 9, Player %d. Resources: %s. Bystander resources (%d, %d). Move: %s. Blocked bystanders: %s."
                % (self.turn // 3 + 1, p, self.res, self.bys[0], self.bys[1], move, blocked_bys))

    def over(self): return self.turn >= 9
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

