        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0:
            moves += ["Move 1 A" if self.res[p] > max(1, self.n // 2) else "Skip Move 1"]
            moves += ["Move 2 B" if self.res[p] > max(2, self.n // 3) else "Skip Move 2"]
