    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["produce"]
        if self.turn < self.n:
            moves.append("harvest B0")
            moves.append("harvest B1")
        if self.turn < 9:  # Can only attempt duel once in the first 9 rounds
            moves.append("duel P1")
