        if w[0] == "produce":
            self.res[p] += 2
        elif w == "harvest B0":
            if self.bys[0] > 0:
                self.bys[0] -= 1; self.res[p] += 1
        elif w == "harvest B1":
            if self.bys[1] > 0:
                self.bys[1] -= 1; self.res[p] += 1
        elif w == "duel P1":
            if self.res[p] >= 2:
                self.res[p] -= 2
                if random.random() < 0.1:
                    self.res[1] -= 2
                self.duels.append((p, 1))
        elif w == "duel P2":
            if self.res[p] >= 2:
                self.res[p] -= 2
                if random.random() < 0.1:
                    self.res[2] -= 2
                self.duels.append((p, 2))
        elif w == "dissuade P0":
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.duels.remove((1, 0))
        elif w == "dissuade P1":
            if self.res[p] >= 1:
                self.res[p] -= 1
                self.duels.remove((2, 1))
        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.rnd()+1} of {self.rounds}. Player {p} has "
            f"{', '.join(map(str, self.res))}. Resources: [{self.bys[0]}, {self.bys[1]}]"
