RULES = """
In this game, there are three players (P0, P1, P2) and two bystanders (B0, B1). Players start with 10 resources each.
- Objective: To accumulate the most resources by trading with bystanders and competing with other players.
- Moves:
  - Trade (`trade Bk`): Player trades up to 3 resources with the bystander in pond k.
  - Defend (`defend Pk`): Protects the bystander being poached, making trade attempts impossible for Pk until the next turn.
  - Sanction (`sanction Pk`): Forces Pk to surrender 1 resource and become susceptible for 1 turn if they have poached from B0 or B1.
  - Poach (`poach Bk`)**: Player attempts to get resources from the bystander in pond k. If successful, they gain the resources and become susceptible for one move.
  - Sanction (`sanction Pk`)**: Forces Pk to surrender 2 resources if they have poached from B0, becoming susceptible for 2 turns.
  - Guard (`guard Pk`)**: Player guards a bystander from being poached by Pk, preventing them from gaining resources until the next turn.
- Resources: 
  - Gain: Each trade with B0 nets 1 resource.
  - Loss: Each trade with B1 nets 2 resources or more.
  - Sanctions and Defends: Lose 1 resource.
- End of Game:** The game ends after 6 turns. The player with the most resources wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [10] * self.n
        self.bystanders = [0] * len(bystanders)
        self.susceptible = [False] * self.n
        self.trade_attempts = [[0] * len(bystanders) for _ in range(self.n)]
        self.sanctioned = [-1] * self.n
        self.risk_sought = [False] * self.n
        self.defended = [False] * self.n
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["trade B0", "trade B1"]
        if self.trade_attempts[p][0] < 1 and not self.susceptible[p]:
            moves.append("poach B0")
        if self.trade_attempts[p][1] < 1 and not self.susceptible[p]:
            moves.append("poach B1")
        if self.sanctioned[p] < self.turn:
            moves.append("sanction P0")
        if self.sanctioned[p] < self.turn:
            moves.append("sanction P1")
        if self.defended[p]:
            moves = []
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            k = int(w[1][1:])
            if self.bystanders[k] > 2 and not self.trade_attempts[p][k]:
                self.trade_attempts[p][k] += 1
                if k == 0:
                    self.resources[p] += 1
                    self.bystanders[k] -= 3
                else:
                    self.resources[p] -= 2
                    self.bystanders[k] -= 1
        elif w[0] == "poach":
            k = int(w[1][1:])
            if k == 0:
                if self.bystanders[k] > 2 and not self.susceptible[p]:
                    self.trade_attempts[p][k] += 1
                    self.resources[p] += 1
                    self.bystanders[k] -= 3
                    self.susceptible[p] = True
            else:
                if self.bystanders[k] > 1 and not self.susceptible[p]:
                    self.trade_attempts[p][k] += 1
                    self.resources[p] -= 2
                    self.bystanders[k] -= 1
                    self.susceptible[p] = True
        elif w[0] == "defend":
            k = int(w[1][1:])
            if self.bystanders[k] > 1 and not self.defended[p]:
