        elif w[0] == "sanction":
            k = int(w[1][1:])
            if k == 0:
                self.resources[p] -= 1
                self.sanctioned[p] = self.turn + 1
                self.sick_sought = True
            else:
                self.sick_sought = True

        self.turn += 1

    def describe(self, p):
        turns_left = 6 - self.turn
        defend_status = "Defended" if self.defended[p] else "Not Defended"
        sanctions = ["P0"] if self.sanctioned[p] == self.turn + 1 else []
        return f"Turn {self.turn}/{turns_left}. Player {p} has resources: {self.resources[p]}. Bystanders B0: {self.bystanders[0]}, B1: {self.bystanders[1]}. Defended: {defend_status}. Sanctioned: {'Yes' if sanctions else 'No'}."

    def over(self):
        return self.turn == 6

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

