        elif move == "attack R0": self.gold[p] -= 1; self.gold[0] = max(0, self.gold[0] - 1)
        elif move == "attack R1": self.gold[p] -= 1; self.gold[1] = max(0, self.gold[1] - 1)
        elif move == "attack R2": self.gold[p] -= 1; self.gold[2] = max(0, self.gold[2] - 1)
        self.turn += 1

