Each move pays off by giving resources or gaining power. However, there are also threats or dangers. Players must be careful not to 
lose everything due to attacks or bad decisions.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.resource_scores = [0] * self.n
        self.land = list(range(n_players))
        self.village_lives = [3] * self.n
        self.village_strength = 2  # Village can withstand up to this number of attacks from other players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.land[p] > 0:
            moves.append(f"Build Wall P{p}")
        if self.bys[0] > 0:
            moves.append(f"Build Wall B0")
        lands = set(self.land)
        if len(lands) > 1:
            moves.append(f"Trade Land P{p} -> to P1")
            moves.append(f"Trade Land P{p} -> to P2")
        moves.append("Sell Land P{p} for Gold Coins")
        moves.append("Buy Land for Gold Coins")
        if self.village_lives[p] > 0:
            moves.append("Protect The Village from Attacks")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Build Wall":
            if w[3].startswith("P"):
                self.land[int(w[3][1:])] -= 1
                if int(w[3][1:]) != self.to_move():
                    self.land[int(w[3][1:])] -= 1
            else:
                self.bys[0] -= 1
        elif w[0] == "Buy Land" and self.bys[1] > 0:
            self.bys[1] -= 1
            self.land[self.rng.randint(0, 3)] += 1
        elif w[0] == "Sell Land":
            land_index = int(move[6:])
            if land_index == self.to_move():
                self.res[p] += 9
                self.rng.shuffle(self.land)
        elif w[0] == "Trade Land":
            p1, p2 = int(move[11:3]), int(move[39:6])
            self.land[int(p1)] -= 1
            self.land[int(p2)] += 1
        elif w[0] == "Protect The Village":
            self.village_lives[p] = 3
        self.turn += 1
        self.perform_events()

    def perform_events(self):
        for _ in range(self.n):
            if self.rng.random() < 0.08:  # 8% chance each turn
                player = self.rng.randint(0, 2)  # Random player who suffers damage
                self.res[player] += 0  # No action for now
            if self.rng.random() < 0.15:  # 15% chance each turn
                if self.bys[1] > 0:
                    self.bys[1] -= 1
                    self.village_lives[self.to_move()] -= 1
        self.end_game_check()

    def end_game_check(self):
        if self.turn >= 50:  # Example: Game ends after 50 turns
            for i in range(3):
                if self.bys[0] > 0:
                    self.res[i] += self.bys[0]
                    self.bys[0] = 0
                for j in range(2):
                    if self.land[j] > 0:
                        self.res[i] += self.land[j]
                        self.land[j] = 0
                    if self.village_lives[j] > 0:
                        self.res[i] += self.village_strength
                        self.village_lives[j] = 0
        self.resource_scores[self.to_move()] += random.randint(-2, 2)

    def describe(self, p):
        return (f"Turn {self.turn}. You are P{p}. Resources: G={self.res[p]}, Land: L=[0,1,2], Village Lives: V={[i for i in range(3) if self.village_lives[i] > 0]}")

    def over(self):
        if self.turn >= 50 or all(life == 0 for life in self.village_lives):
            return True
        return False

    def final_resources(self): return list(self.res)

    def final_bystanders(self): return list(self.bys)

