        self.blocked_turns = [0] * n_players  # Turn during which B0 is blocked

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        other_players = [q for q in range(self.n) if q != p]
        moves = []
        if self.res[p] == 0:
            moves.append("guard")
        elif self.cnt[p] < 2:
