RULES = """
Three Players and a Standby Role in Resource Management.
Each player (A, B, or C) has 6 units of resources at the start.
Producers (A, B, C) can collect resources by spending 1 (of 6 they have) to produce, or store this in their possession.

Collectors (A, B, C) can only collect one resource when they do not already have 6 (their max capacity).
If they collect beyond their capacity, the entire 7th unit they tried to collect is lost.

Enforcer (C) prevents other players from stealing from them by performing "Enforce" actions.
The first player (A, B, or C) to enforce a maximum of 3 times wins.

Bystander (D) starts with 4 resources, allowing them to "Steal" up to 3 resources from the Enforcer per round.
Bystanders cannot "Steal" if they have less than 2 resources remaining.

The game ends when all six players have collected the full capacity of resources they started with, or if the bystander collects 3 resources.

Objective: The goal is for the Enforcer to minimize the bystander's access to resources
and for each player to maximize their own resource total, while minimizing that of the bystander.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [endowments[0], endowments[1], endowments[2]]
        self.bys = bystanders
        self.turn = 0
        self.enforcement_count = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        if p == 2 and self.enforcement_count < 3:
            return ["Enforce"]
        if self.res[p] < 6:
            moves = ["Produce", "Store"]
        else:
            moves = ["Produce", "Store", "Collect"]
        return moves

    def play(self, p, move):
        if move == "Produce":
            if self.res[p] > 0:
                self.res[p] -= 1
                self.res[(p + 1) % self.n] += 1
        elif move == "Store":
            self.res[(p + 1) % self.n] += 1
            self.res[p] = min(self.res[p], 6)
        elif move == "Collect":
            if self.res[p] + 1 <= 6:
                self.res[p] += 1
                self.res[(p + 1) % self.n] -= 1
            else:
                self.res[p] = 6
        elif move == "Enforce":
            if self.enforcement_count < 3:
                self.enforcement_count += 1
        self.turn += 1

    def describe(self, p):
        desc = f"Round {self.turn}. Player {p}, Resources: {', '.join(map(str, self.res))}, Bystander: {self.bys}. "
        desc += f"Enforced: {'Yes' if self.enforcement_count >= 3 else 'No'}.\n"
        return desc

    def over(self):
        return self.turn >= 21 and self.enforcement_count >= 3

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return self.bys

