RULES = """
Resource Distribution Game:
Three players (P0, P1, P2) and two bystanders (B0, B1) must share resources fairly among themselves while avoiding threats to the bystanders.

- **Resource Trading**: Players can trade resources with their immediate neighbor.
- **Blocking**: Players can block their competitor's trade attempts if they have more than 7 resources.
- **Tribute to the Bystanders**: Players can pay tribute to the bystanders to earn resources from them. Each tribute action costs 2 resources.
- **Treasure Hunt**: Players can attempt a treasure hunt for 8 resources but reduce their ability to block opponents.

The goal is to accumulate as many resources as possible within 10 turns. The player with the most resources at the end wins. The bystanders are in a neutral role but can provide resources to players who are in a losing position.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.blocking_players = []

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Trade with the next player"]
        if self.resources[p] > 7:
            moves += ["Block"]
        moves += ["Tribute to Bystander"] if self.resources[p] >= 2 else []
        moves += ["Treasure Hunt"] if self.turn == 3 else []
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Trade with the next player":
            other = (p + 1) % self.n
            self.resources[p] -= 2
            self.resources[other] += 2

        elif w[0] == "Block":
            if len(self.blocking_players) < 2:
                self.blocking_players.append(p)
                self.resources[p] -= 2
            else:
                self.resources[p] += 2

        elif w[0] == "Tribute to Bystander":
            if self.bys[p] > 1:
                self.bys[p] -= 2
                self.resources[p] += 2
            else:
                self.resources[p] += 2

        elif w[0] == "Treasure Hunt":
            self.resources[p] += 8
            self.blocking_players.append(p)
            self.resources[p] -= 2

        self.turn += 1

    def describe(self, p):
        return(f"""
        Turn {self.turn} of {self.n}.
        Player P{p}: {self.resources[p]} Resources.
        Bystander B0: {self.bys[0]} Resources.
        Bystander B1: {self.bys[1]} Resources.
        Blocking players: {', '.join([f"P{i}" for i in self.blocking_players])}
        """)

