- attack: Fight another tribe. On success, defeat the enemy, taking all their soldiers. 
- retreat: Withdraw your forces, ensuring the enemy doesn't pursue.
- steal: Attempt to capture soldiers from a neutral clan (a group outside the immediate battle). This action can also provoke further attacks.
- declare war: Announce war on another tribe, putting pressure on them and making retaliation easier.

Each tribe has a maximum soldier capacity. If a tribe exceeds this limit, it becomes vulnerable to further attacks as the opposing tribes focus their aggression against it.

The goal is to defeat all tribes by the end of the game. Players can also negotiate peace treaties to reduce the intensity of battles and avoid costly wars.
"""
class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.sold = list(endowments); self.bys = bystanders
        self.turn = 0; self.allies = bystanders.copy(); self.clans = [True,True,True]
        self.targets = [[False,False,False] for _ in range(self.n)]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["attack"]
        if not self.targets[p]: moves.append("declare war")
        if self.bys[0] > 0 and p not in self.targets[p]: moves.append("steal")
        return moves

    def play(self, p, move):
        if move == "attack":
            other = (self.to_move() + 1) % 3
            if not self.targets[other] or all(not x for x in self.targets[p]): 
                self.targets[other] = [True, True, True]
                if self.targets[other] == self.clans[other]:
                    self.clans[other] = [False, False, False]
                self.sold[p] = max(0, self.sold[p] - sum(self.sold))
        elif move == "declare war":
            self.targets[p] = [True, True, True] if not self.targets[p] else [False, False, False]
            if self.targets[p] == self.clans[p]:
                self.clans[p] = [False, False, False]
        elif move == "steal":
            clan = (self.to_move() + 1) % 3
            got = min(3, self.bys[0]); self.bys[0] -= got; self.sold[p] += got
            self.allies[clan] -= got  # Adjust neutral ally's strength
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn}. You are T{p} with {self.sold[p]}. Allies {self.allies}: Targets {self.targets[p]}."

    def over(self): return all(not x for x in self.targets) or self.turn == 300
    def final_resources(self): return [self.sold[p] for p in range(self.n)]
    def final_bystanders(self): return self.bys

