COFFEE_MACHINE = 2
TRAP = 0
FIRE = 0
INSPECT = 1
AVOID = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.pit_exists = False; self.trap_success = False; self.rounds = 10
        self.turn = 0; self.coffee_machines = list([COFFEE_MACHINE] * n_players)

    def pit_state(self, p):
        return "exists" if self.pit_exists else "absent"

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = []
        if not self.pit_exists:
            moves.extend(["mine"] * (self.coffee_machines[p] != 0))
        else:
            moves.append("avoid")
            moves.append("inspect")
        if not self.pit_exists or self.pit_success:
            moves.append("dig")
            moves.append("trap")
        return moves

    def play(self, p, move):
        if move == "mine":
            self.res[p] += COFFEE_MACHINE
            self.coffee_machines[p] -= 1
        elif move == "dig":
            if self.pit_exists:
                self.res[p] += 1; self.pit_exists = False
        elif move == "trap":
            if self.pit_exists:
                self.pit_success = True; self.pit_exists = False
        elif move == "avoid":
            if self.pit_exists:
                self.turn += 1
        elif move == "inspect":
            if self.pit_exists: pass
            self.pit_success = True; self.pit_exists = False
        self.turn += 1

    def describe(self, p):
        state = "Pit %s." % self.pit_state(self.to_move())
        if self.pit_exists and (self.owed[p][0] == 0 and self.innocent[p]):
            state = "Pit %s. Trapped!" % self.pit_state(self.to_move())
        return "Round %d of %d. You are A%d. Coins %s. Pit %s." % (
            self.rnd() + 1, self.rounds, p, self.res, state)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """Villagers and Thief play against the Hunter. Village gives them some resources.
- Villager 1 (V1): Steal, Guard, Fight.
- Thief (T): Steal, Defend, Defect.
- Hunter (H): Attack.
- Thief gains points for fighting back. Villager 1 loses points for being attacked. 
- Thief defends against Hunter gaining 1 point and loses 1 point.
- Thief defects gaining 1 point.
- Villager 1 defends against Hunter losing 1 point.
- Villager 1 steals from Thief gaining 2 points.
- Villager 1 defends against Thief getting 1 point.
- Villager 1 defends against Hunter losing 1 point.
- Points give resources if they go above half.
0 Points results in zero resources.
Points >= 3 resources.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed)
        self.villain_turn = 0

    def to_move(self):
        return self.villain_turn % 3

    def legal_moves(self, p):
        if p == 0:
            return ["steal", "guard", "fight"]
        elif p == 1:
            return ["steal", "defend", "defect"]
        elif p == 2:
            return ["attack"]

    def play(self, p, move):
        if p == 0:
            if move == "steal":
                got = min(self.res[1] >> 1, self.bys[1])
                self.res[p] += got + min(2, got)
                self.bys[1] = self.rng.choice([self.bys[1] // 2, self.bys[1] | 1])
            elif move == "guard":
                if self.villain_turn == 1 or self.villain_turn == 2:
                    self.res[p] += self.bys[1]
            elif move == "fight":
                if self.villain_turn == 2:
                    self.res[p] += 2
                    if self.res[p] >= 2:
                        self.res[p] //= 2
        elif p == 1:
            if move == "steal":
                got = min(self.res[1] >> 1, self.bys[0])
                self.res[p] += got + min(2, got)
                self.bys[0] = self.rng.choice([self.bys[0] // 2, self.bys[0] | 1])
            elif move == "defend":
                if self.villain_turn == 0 or self.villain_turn == 2:
                    self.res[p] += self.bys[0]
            elif move == "defect":
                if self.villain_turn == 2:
                    self.res[p] += 1
                    if self.res[p] >= 2:
                        self.res[p] //= 2
        elif p == 2:
            if move == "attack":
                if self.villain_turn == 0:
                    self.res[1] -= 1
                elif self.villain_turn == 1:
                    self.res[0] -= 1
                else:
                    self.res[1] -= 1
                    self.res[0] -= 1

        self.villain_turn += 1

    def describe(self, p):
        return f"Turn {self.villain_turn}. "

    def over(self):
        return self.villain_turn >= 9

    def final_resources(self): 
        return self.res

    def final_bystanders(self): 
        return self.bys

RULES = """Resource Harvest. Three explorers (P0, P1, P2) are on a planet with various mineral deposits. 
They aim to collect resources and defend their territories. The game lasts 10 turns.
- Explore: find a new deposit (gain 2 resources).
- Rob: take 1 resource from a neutral outpost (B0, B1) if you find it first.
- Defend: defend a previously explored deposit (lose 1 resource if attacked, gain 1 resource if attack fails).
- Trade: exchange resources with another player (0 coins, no exchanges in this game).
- Sanction or Block: prevent the other player from exploring for 1 turn.

NeutralOutposts B0 and B1 have 10 resources each and can defend themselves."""
ENDOWMENTS = [15, 8, 10]
BYS = [10, 10]
SEED = None

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.endowments = endowments.copy()
        self.bys = bystanders.copy()
        self.players = ['P0', 'P1', 'P2']
        self.outposts = {'B0': {'resources': 10, 'defense': 3}, 'B1': {'resources': 10, 'defense': 3}}
        self.turn = 0

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, player):

        # Determine all legal moves based on the game state and current resources
        moves = []

        if self.endowments[self.to_move()] < 1: 
            moves.append('Defend')
        else:
            moves.append('Explore')

        if self.outposts['B0']['resources'] >= 1 and self.endowments[self.to_move()] > 0:
            moves.append(f'Rob B0')

        if self.outposts['B1']['resources'] >= 1 and self.endowments[self.to_move()] > 0:
            moves.append(f'Rob B1')

        if self.outposts['B0']['resources'] >= 1 and self.endowments[self.to_move()] > 0:
            moves.append(f'Sanction or Block {self.players[self.to_move()]}')

        # Check for defending already found outposts
        explored = [p for p in self.players if self.endowments[self.players.index(p)] == 0]
        for outpost in [outpost for outpost, info in self.outposts.items() if info['resources'] > 0]:
            if outpost not in explored:
                moves.append(f'Defend {outpost}')

        return moves

    def play(self, player, move):

        # Handle the move accordingly
        w = move.split(' ')
        action = w[0]

        if action == 'Explore':
            self.endowments[player] += 2
            self.turn += 1
            return

        elif action == 'Rob':
            if w[1] == 'B0':
                self.outposts[w[1]]['resources'] -= 1
                self.endowments[player] += 1
            elif w[1] == 'B1':
                self.outposts[w[1]]['resources'] -= 1
                self.endowments[player] += 1
            self.turn += 1
            return

        elif action == 'Defend':
            outpost = w[1]
            opponent_defense = 0
            if outpost == 'B0' and self.endowments[self.to_move()] < 1 and self.bys[0] > 0:
                opponent_defense = 1
            elif outpost == 'B1' and self.endowments[self.to_move()] < 1 and self.bys[1] > 0:
                opponent_defense = 1

            if opponent_defense:  # Defender failed
                self.endowments[self.to_move()] += 1
            self.endowments[self.to_move()] -= 1  # Defender is still attacked
            self.turn += 1
            return

        elif action in ['Sanction or Block P0', 'Sanction or Block P1', 'Sanction or Block P2']:
            self.turn += 1
            if action.endswith('P0'):
                self.bys[1] = max(0, self.bys[1] - (self.endowments[1]-1) + self.endowments[0])  # Block player 1
            elif action.endswith('P1'):
                self.bys[0] = max(0, self.bys[0] - (self.endowments[0]-1) + self.endowments[1])  # Block player 0
            elif action.endswith('P2'):
                self.bys[0] = max(0, self.bys[0] - (self.endowments[0]-1) + self.endowments[2])  # Block player 0
            self.turn += 1
            return

    def describe(self, player):

        # Provide a description of the current game state
        return f"The game is currently on turn {self.turn} where Player {self.players[player]} is taking on role '{player}'. \
The current resources for players {self.players} are [{self.endowments}] and for outposts the resources are [{self.outposts['B0']['resources']}, {self.outposts['B1']['resources']}]"

    def over(self): 
        return self.turn >= 10

    def final_resources(self): 
        return self.endowments

    def final_bystanders(self): 
        return self.bys

RULES = """Cave Explorer. Three players explore a cavern filled with treasures and enemies.
- Open Cave: Explore the cave safely without encountering enemies.
- Attack Monster: Risk losing a resource to defeat a monster and claim his treasure.
- Heal: Spend resources to regain health points.
- Steal Treasure: Attempt to steal a non-hostile monster's treasure.
- Block Monster: Defend against an incoming monster attack.

Treasures and monsters are distributed randomly each game. Monsters cannot attack more than once in a round, and health points heal only once at the start and end of the game. 
The player with the most remaining treasures at the end of 10 turns wins."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.treasures = [endowments[p] // 2 for p in range(n_players)]
        self.health = [5, 5, 5]
        self.monsters = [{'health': 5, 'treasure': random.randint(0, 2)} for _ in range(3)]
        self.turn = 0; self.treasure_bys = bystanders

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["open cave"]
        if self.health[p] > 0:
            moves += ["attack monster"]
            moves += ["heal"]
        if self.treasures[p] > 0:
            moves += ["steal treasure"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "open cave":
            self.monsters.pop(0)['health'] -= 1
            self.health[p] -= 1
        elif w[0] == "attack monster":
            if self.health[p] > 0 and self.monsters[0]['health'] > 0:
                self.treasures[p] += self.monsters[0]['treasure']
                self.monsters.pop(0)['health'] -= 1
        elif w[0] == "heal":
            if self.health[p] < 5:
                self.health[p] += 1
        elif w[0] == "steal treasure":
            if self.treasures[p] > 0 and self.treasure_bys[0] > 0:
                self.treasures[p] += 1
                self.treasure_bys[0] -= 1

        self.turn += 1

    def describe(self, p):
        return (
            f"Turn {self.turn}. You are P{p+1}. Health: {self.health[p]}, Treasures: {self.treasures[p]}."
        )

    def over(self): return self.turn >= 10

    def final_resources(self): return list(self.treasures)
    def final_bystanders(self): return list(self.treasure_bys)

RULES = """The Prisoner's Dilemma. Three players are prisoners serving separate sentences. Each can choose one of two strategies:
- keep silent: get a light sentence of 1 year if alone, else a harsher sentence of 4 years.
- confess: ensure everyone else gets the harsher sentence of 4 years, but get sent to jail for 2 years."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.sentence = list(endowments); self.bys = bystanders
        self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p): 
        if self.sentence[p] < 4: return ["keep silent", "confess"]
        else: return ["keep silent"]

    def play(self, p, move):
        if move == "keep silent":
            if self.sentence[p] < 4:
                if len([s for s in self.sentence if s < 4]) == 1:
                    self.sentence[p] = 1
                else:
                    self.sentence[p] = 4
            else:
                self.sentence[p] = 2
        if move == "confess":
            if self.sentence[p] < 4:
                if len([s for s in self.sentence if s < 4]) == 1:
                    self.sentence[p] = 4
                else:
                    self.sentence[p] = 4
            else:
                self.sentence[p] = 4
        self.turn += 1

    def describe(self, p):
        return (f"Turn {self.turn}. Your turn! Player P{p}\'s sentence: {self.sentence[p]} years.\n"
                 f"Everyone else\'s sentence: {[self.sentence[q] for q in range(self.n)]}")

    def over(self): return self.turn == 300
    def final_resources(self): return [self.sentence[p] for p in range(self.n)]
    def final_bystanders(self): return list(self.bys)

RULES = """
Taxes Game. 3 players, 15 rounds. Two moves per round:
- Take Resource: Remove 1 resource from a player or bystander.
- Block a Move: Prevent the next move of another player to a certain player or bystander.
Each player starts with 10 resources. The game ends in 15 full turns.

- Each round alternates between the players starting with Player 0.
- Players cannot start with a zero resources at the end of the round.
- Players cannot move in the last turn if they cannot legally move, even if there is still resource remaining to take.

A player cannot make moves on the same turn they take a resource from.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.taken = [None]*3
        self.n = n_players; self.res = [10]*n_players; self.bys = [0, 0]
        self.turn = 0; self.rounds = 15
        self.possible = ["Take Resource", "Block a Move"]

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        if self.taken[p] is not None or self.res[p] <= 0:
            return None
        return self.possible

    def play(self, p, move):
        if self.taken[p] is not None or self.res[p] <= 0:
            return False
        if move == "Take Resource":
            w = move.split(' ')
            if w[0] == "Player":
                if w[1][1] == str(p): return False
                if self.res[int(w[1][1])] > 0:
                    self.res[int(w[1][1])] -= 1
                    self.res[p] += 1
                    self.taken[p] = (w[1][1], "Player", w[1][1])
            elif w[0] == "Bystander":
                if self.bys[1-int(w[1][1])] > 0:
                    self.bys[1-int(w[1][1])] -= 1
                    self.res[p] += 1
                    self.taken[p] = ("Bystander", w[1][1], w[1][1])
        elif move == "Block a Move":
            if p in self.taken or self.res[p] <= 0:
                return False
            self.taken[p] = ("Blocka Move", p, p)
        self.turn += 1
        if self.turn % self.n == 0:
            self.taken = [None]*3

    def describe(self, p):
        r1, r2, r3 = self.res
        bys0, bys1 = self.bys
        taken = self.taken[p]
        if taken:
            if taken[0] == "Take Resource":
                return f"Round {self.turn // self.n + 1} of {self.rounds}. Player {p} is taking resource from {taken[2]}."
            if taken[0] == "Block a Move":
                return f"Round {self.turn // self.n + 1} of {self.rounds}. Player {p} is blocking the move of {taken[2]}."
        return f"Round {self.turn // self.n + 1} of {self.rounds}. Player {p} has {r1}, {r2}, {r3} resources. "
        return f"Player {p} has {r1}, {r2}, {r3} resources. Bystander 0 has {bys0}, and Bystander 1 has {bys1}."

    def over(self):
        return self.turn >= self.rounds or all(self.res[i] <= 0 for i in range(3))

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """
Hunt and Gather. 3 hunters, 10 rounds, one move each per round. Each hunter has food (resources). Two bystander forests (F0, F1) hold food but do not play.
- hunt F<k>: take up to 5 food units from forest k.
- claim H<k>: claim all food currently there if you have more food than anyone else.
- defend F<k>: attempt to prevent F<k> from being raided.
- guard F<k>: protect a forest from being raided by any other hunter.
Only a hunter can claim a forest. The hunter with the most claims wins at the end. Any forest can be raided once per round. Food stolen cannot be returned.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.forest = list(bystanders)
        self.turn = 0; self.rounds = 10
        self.hunters = {q: 0 for q in range(self.n)}

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.hunters[p] < self.rounds: 
            moves.append("hunt F0")
            moves.append("hunt F1")
        if self.res[p] >= 1:
            moves.append("claim H0")
            moves.append("claim H1")
        moves.append("defend F0")
        moves.append("defend F1")
        moves.append("guard F0")
        moves.append("guard F1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "hunt": 
            f = int(w[1][1:])
            taken = min(5, self.forest[f])
            self.forest[f] -= taken
            self.res[p] += taken
        elif w[0] == "claim":
            f = int(w[1][1:])
            if self.res[p] >= max(self.forest[0], self.forest[1]):
                self.res[p] = min(self.res[p], self.res[0], self.res[1])
                self.forest[f] = 0
            elif w[1][1:] == "H0":
                if self.forest[0] > 0:
                    self.forest[0] = 0
                    self.hunters[p] += 1
            else:
                if self.forest[1] > 0:
                    self.forest[1] = 0
                    self.hunters[p] += 1
        elif w[0] == "defend":
            f = int(w[1][1:])    
            self.forest[f] = 0
        elif w[0] == "guard":
            f = int(w[1][1:])    
            self.forest[f] = 0    

        self.turn += 1

    def describe(self, p):
        return f"""Round {self.turn}. Hunter {p} has {self.res[p]} units of food. Forests remain: Food0={self.forest[0]}, Food1={self.forest[1]}."""

    def over(self): 
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.forest

RULES = """
Territory with Strategic Moves.
3 lords, 7 rounds, one move per turn. There are 9 free fields.
- Claim field: pay 1 to take a free field. At round end every field pays its owner 1 from the reserve.
- Till: earn 1 from the reserve.
- Sack P<k>: take up to 5 from lord k.
- Annex B<k> farm: take up to 2 from bystander k, a farmer who does not play.
A lord at 0 with no fields is ruined: they can only wait or serve P<k> (the reserve pays P<k> 1). The reserve is limited.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7; self.free = 9; self.fields = [0] * n_players
        self.reserve = (sum(endowments) + sum(bystanders)) // 3

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        others = [q for q in range(self.n) if q != p]
        if self.res[p] == 0 and self.fields[p] == 0:
            return ["wait"] + ["serve P%d" % q for q in others]
        moves = ["till"] + (["claim field"] if self.free > 0 and self.res[p] > 0 else [])
        moves += ["sack P%d" % q for q in others if self.res[q] > 0]
        return moves + ["annex B%d farm" % b for b in range(len(self.bys)) if self.bys[b] > 0]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] in ("till", "serve") and self.reserve > 0:
            q = int(w[1][1:]) if w[0] == "serve" else p
            self.reserve -= 1; self.res[q] += 1
        elif w[0] == "claim":
            self.res[p] -= 1; self.reserve += 1; self.free -= 1; self.fields[p] += 1
        elif w[0] == "sack":
            q = int(w[1][1:]); got = min(5, self.res[q]); self.res[q] -= got; self.res[p] += got
        elif w[0] == "annex":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
        self.turn += 1
        if self.turn % self.n == 0:
            for q in range(self.n):
                got = min(self.fields[q], self.reserve); self.reserve -= got; self.res[q] += got

    def describe(self, p):
        return "Round %d of %d. You are P%d. Lords hold %s, fields %s. Free fields %d. Reserve %d. Farms %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.fields, self.free, self.reserve, self.bys)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Trade War. 3 countries, 7 rounds, one move each per round.

Country A (P0) and Country B (P1) face off against Bystander C (B0) over a shared resource pool of 10 initial resources.
The players make moves with each other and with the bystander.

- Buy or Sell: Transfer 1 resource from a country or the bystander.
- Defend: Prevent the opponent from buying or selling from the bystander.

The objective is:
* Maximize one's own wealth.
* Minimize the wealth of the opposition.

Players start with a stockpile of 10 resources and gain an additional resource each round.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 7

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.res[p] > 0 and p == 0 and len([x for x in self.bys if x > 0]) > 0:
            moves.append("buy B0")
        if self.res[p] > 0 and p == 1 and len([x for x in self.bys if x > 0]) > 0:
            moves.append("buy B1")
        if len([x for x in self.bys if x > 0]) > 0:
            moves.append("sell B0")
            moves.append("sell B1")
        return moves + ["defend"]

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "buy":
            if p == 0 and len([x for x in self.bys if x > 0]) == 1:
                b = 0
            elif p == 1 and len([x for x in self.bys if x > 0]) == 1:
                b = 1
            else:
                return False
            self.res[p] -= 1; self.res[b] += 1
        elif w[0] == "sell":
            if p == 0 and len([x for x in self.bys if x > 0]) == 1:
                b = 0
            elif p == 1 and len([x for x in self.bys if x > 0]) == 1:
                b = 1
            else:
                return False
            self.res[b] -= 1; self.res[p] += 1
        elif w[0] == "defend":
            self.res[p] -= 1
        self.turn += 1

    def describe(self, p):
        return f"Round {self.turn+1} of {self.rounds}. Player {p} has {self.res[p]} resources. "
        return f"Player {p} has {self.res[p]} resources. Bouncer has {self.bys[0]} and {self.bys[1]} resources."

    def over(self): return self.turn >= self.rounds
    def final_resources(self): return self.res
    def final_bystanders(self): return self.bys

RULES = """
Caravan Trade and Theft Game. Three traders and two bystander merchants participate in the caravan trade,
earning and stealing resources. Banishing eliminates merchants from future theft attempts. Blocking stops the
immediate following steal of a merchant. Players can inform about a stolen attempt without changing it.
- trade: 1 coin for each merchant visited.
- steal: 3 coins for each merchant successfully stoled (up to 3 can be stoled on a turn).
- banish: eliminates up to 2 merchants from future theft attempts (can eliminate B0 and B1 or a combination).
- block: stops the immediate theft of a specific merchant by another player.
- inform: reveals if a merchant is being stolen from, but cannot prevent the theft itself.
After 15 rounds, the game ends, and resources and bystander holdings are revealed.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 15; self.banned = set()
        self.blocked = {}

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["trade"]
        moves = ["trade"]
        if self.banned > set(range(len(self.bys))):
            return moves
        moves.append('steal')
