            moves.append('banish')
        if self.turn > 0:
            moves.append('block')
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "trade":
            self.res[p] += len([b for b in range(len(self.bys)) if not self.banned or self.bans[b]])
        elif w[0] == "steal":
            if len(self.banned) < len(self.bys):
                got = min(3, len([b for b in range(len(self.bys)) if not self.banned]))
                if got > 0:
