                for i in range(len(self.bys)):
                    if len(self.banned) >= len(self.bys) - 1:
                        banned.add(i)
                banned = set([i for i in banned if i not in self.banned])
                self.banned.update(banned)
        elif w[0] == "block":
            otherp = (p + 1) % self.n
            self.blocked[otherp] = self.turn + 1
        self.turn += 1

    def describe(self, p):
        bals = ", ".join(["B%d" % i for i in range(self.n) if i not in self.banned])
        b = self.blocked.get(p)
        return f"Round {self.turn} of {self.rounds}. You are P{p}. Resources: {self.res}. Bystander Merchants: {self.bys}. Banned: {' '.join(bals)}"

