RULES = """Treasure Hunters. 3 players, 10 rounds, one move each per round. Players collect gold by hunting hidden treasures while avoiding ghost attacks. Goal is to amass the most gold."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        assert n_players == 3
        self.n = n_players
        self.endowments = list(endowments[:]) # Initial gold for each player
        self.resources = list(endowments[:]) # Current gold for each player
        self.bystanders = bystanders          # Health points of the two ghost hunters
        self.seed = seed                      # Seed for random number generation
        self.rng = random.Random(seed)

        self.treasures = [4, 6]              # Amounts of gold in hidden treasures
        self.ghost_states = [True, True]    # Whether each ghost hunter is active
        self.round_num = 0                    # Current round
        self.game_over = False                # Flag to indicate if the game has ended

    def to_move(self):
        return self.round_num % self.n

    def legal_moves(self, p):
        moves = ["H%d" % t for t in range(len(self.treasures))]
        moves.append("S")
        moves.extend(["G%d" % g for g in range(len(self.ghost_states))])
        moves.append("E")
        return moves

    def play(self, p, move):
        self.round_num += 1
        if move.startswith("H"):
            treasure_id = int(move[1:])
            assert treasure_id < len(self.treasures)
            amount = self.rng.randint(1, self.treasures[treasure_id])
            self.resources[p] += amount

            # Encounter with ghosts?
            ghost_encountered = False
            for i, ghost_state in enumerate(self.ghost_states):
                if ghost_state and self.rng.random() < 0.5:
                    ghost_encountered = True
                    self.bystanders[i] -= 1
                    if self.bystanders[i] < 0:
                        self.bystanders[i] = 0

            if ghost_encountered:
                self.resources[p] = max(self.resources[p] - 1*(len([g for g in self.ghost_states if g])), 0) 

        elif move == "S":
            pass

        elif move.startswith("G"):
            ghost_id = int(move[1:])
            assert ghost_id < len(self.ghost_states)

        elif move == "E":
            self.game_over = True

    def describe(self, p):
        desc = f'''
Round {self.round_num+1}/{10}. You are Player {p}.
Current Gold: {self.resources[p]}
Health of Ghost Hunter B0: {self.bystanders[0]}
Health of Ghost Hunter B1: {self.bystanders[1]}'''
        if not self.ghost_states[0]:
            desc += "\nGhost Hunter B0 is inactive."
        if not self.ghost_states[1]:
            desc += "\nGhost Hunter B1 is inactive."

        return desc

    def over(self):
        return self.round_num >= 10 or all([self.resources[p]==0 for p in range(3)])

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

