        moves = []

        # Take resources from bystanders
        if True:
            moves += ["Take B0"]
            moves += ["Take B1"]

        # Sanction a player
        if self.resources[p] > 0:
            moves += ["Sanction P0"]
            moves += ["Sanction P1"]
            moves += ["Sanction P2"]

        # Guard your resources
        if True:
            moves += ["Guard Your Resources"]

        # Skip
        if True:
            moves += ["Skip"]

        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Take B0":
            if self.bys[0] > 0:
                res = min(1, self.bys[0])
                self.bys[0] -= res
                self.resources[p] += res
                self.resources[(p + 1) % self.n] += res
                self.resource_diff = [self.resources[(p + 2) % self.n] - self.resources[p], self.resources[(p + 2) % self.n] - self.resources[(p + 1) % self.n]]

        elif w[0] == "Take B1":
            if self.bys[1] > 0:
                res = min(1, self.bys[1])
                self.bys[1] -= res
                self.resources[p] += res
                self.resources[(p + 1) % self.n] += res
                self.resource_diff = [self.resources[(p + 2) % self.n] - self.resources[p], self.resources[(p + 2) % self.n] - self.resources[(p + 1) % self.n]]

        elif w[0] == "Sanction P0":
            if self.resources > 0:
                self.resources[p] -= 1
                self.resources[0] -= 1

        elif w[0] == "Sanction P1":
            if self.resources > 0:
                self.resources[p] -= 1
                self.resources[1] -= 1

        elif w[0] == "Sanction P2":
            if self.resources > 0:
                self.resources[p] -= 1
                self.resources[2] -= 1

        elif w[0] == "Guard Your Resources":
