            if self.rnd() >= 4 and self.res[p] == 0:
                return ["steal"]
        if p == 1:
            if self.res[p] > 0:
                return ["mine"]
            if self.rnd() >= 7 and self.res[p] == 0:
                return ["steal"]
        if p == 2:
            if self.res[p] > 0:
                return ["mine"]
            if self.rnd() >= 10 and self.res[p] == 0:
                return ["steal"]
        return ["protect"]

    def play(self, p, move):
        self.res[p] += 1
        self.period += 1

        if move == "steal":
            r = self.rnd()
            if r < 7:
                got = random.randint(min(self.bys[r], 3), self.bys[r])
                self.bys[r] -= got
                self.res[p] += got
        elif move == "sanction":
            self.sanction[p] = self.to_move()

        if self.period == 10:
            self.sanction[p] = -1

    def describe(self, p):
        if self.res[p] == 0:
            return f"{self.rnd()+1}th Period: Not enough resources to mine, consider stealing."
        return f"{self.rnd()+1}th Period: Extracted 1 unit. Resources: {self.res}, Byess: {self.bys}."

    def over(self):
        return self.period >= 10

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """  
