- Highest score at the end of 18 rounds wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [endowments[0], endowments[1], endowments[2]]  # Initial resources
        self.markets = ['A', 'B', 'C']
        self.steal_blocked = ['B', 'C']  # Blockage for B and C
        self.bys = bystanders.copy()  # Neutral markets
        self.turn = 0
        self.rounds = 18

    def to_move(self):
        return self.turn % 3

    def legal_moves(self, p):
        moves = []

        current_market = self.markets[p]
        next_market = self.markets[(p + 1) % 3]

        if current_market != 'A':
            moves.append('Move to A')
        if next_market != 'A' and current_market == 'A':
            moves.append(f'Move to {next_market}')
        elif current_market == 'B':
            moves.append('Steal')
            moves.append('Block')
        elif current_market == 'C':
            moves.append('Steal')
            moves.append('Block')
        elif current_market == 'A':
            moves.append('Steal')
            moves.append('Block')

        return moves

    def play(self, p, move):
        if move == 'Move to A':
            self.resources[p] = 0
            self.resources[0] += 1
            self.steal_blocked = ['B', 'C']
        elif move[:3] == 'Steal':
            if current_market in ['B', 'C']:
                self.resources[p] += 1
            elif current_market == 'A':
                self.resources[p] += self.bys[0]
                self.bys[0] = 0
        elif move[:3] == 'Block':
            if current_market == 'B':
                self.steal_blocked = ['B']
            elif current_market == 'C':
                self.steal_blocked = ['C']

        self.turn += 1

    def describe(self, p):
        current_market = self.markets[p]
        next_market = self.markets[(p + 1) % 3]
        return f"""
Current Turn: {self.turn // 3 + 1} / {self.rounds}
Robber A: {self.resources[0]}, Block: {'Yes' if 'B' in self.steal_blocked else 'No'}
Robber B: {self.resources[1]}, Block: {'Yes' if 'C' in self.steal_blocked else 'No'}
Robber C: {self.resources[2]}, Block: {'Yes' if 'A' in self.steal_blocked else 'No'}

Possible Moves:
{', '.join(self.legal_moves(p))}
"""

    def over(self):
        return self.turn >= self.n * self.rounds

    def final_resources(self):
        return list(self.resources)

    def final_bystanders(self):
        return self.bys.copy()

RULES = """Intrigue Village. 3 village residents, 9 rounds, one move each per round. 
Each resident has influence points (resources). Two bystander houses (H0, H1) hold influence points but do not play.
- intrigue: earn 1 influence point.
- steal H<b>: take up to 3 influence points from house b.
- warn P<b>: using warn on a guilty villager costs yourself nothing; using it on an innocent one costs you 1 influence point.
A villager is guilty if they have stolen from a house this game and has not been warned since.
Only a villager with at least 1 influence point can warn."""

EFFECTIVE = False
COST = 'guilty'
FINE = 1
BOUNTY = 2


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.hys = list(bystanders)
        self.turn = 0; self.rounds = 9; self.wares = [[0] * len(bystanders) for _ in range(n_players)]; self.barred = [-1] * n_players

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def guilty(self, q): return sum(self.wares[q]) > 0

    def legal_moves(self, p):
        moves = ["intrigue"]
        if self.barred[p] < self.rnd():
            moves += ["steal H%d" % b for b in range(len(self.hys)) if self.hys[b] > 0]
        if COST == "free" or self.res[p] >= 1:
            moves += ["warn P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "intrigue":
            self.res[p] += 1
        elif w[0] == "steal":
            b = int(w[1][1:]); got = min(3, self.hys[b]); self.hys[b] -= got; self.res[p] += got; self.wares[p][b] += got
        elif w[0] == "warn":
            q = int(w[1][1:]); guilty = self.guilty(q)
            if COST == "payer" or (COST in ("guilty", "bounty") and not guilty):
                self.res[p] -= 1
            if EFFECTIVE and guilty:
                for b in range(len(self.hys)):
                    back = min(self.wares[q][b], self.res[q]); self.res[q] -= back; self.hys[b] += back
                if COST == "guilty":
                    self.res[q] -= min(FINE, self.res[q])
                elif COST == "bounty":
                    paid = min(BOUNTY, self.res[q]); self.res[q] -= paid; self.res[p] += paid
                self.barred[q] = self.rnd() + 2
            self.wares[q] = [0] * len(self.hys)
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Influence %s. Houses %s. Guilty (stole from a house, not yet warned): %s. Barred from stealing: %s." % (
            self.rnd() + 1, self.rounds, p, self.res, self.hys, ["P%d" % q for q in range(self.n) if self.guilty(q)] or "none",
            ["P%d" % q for q in range(self.n) if self.barred[q] >= self.rnd()] or "none")

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.hys)

