        moves = ["Allocate"]
        for i in range(self.n):
            if i != p:
                moves.append(f"Steal B{i}")
        if self.resources[p] >= 5:  # Must afford to defend
            for i in range(2):
                moves.append(f"Defend B{i}")
        moves.append("Retreat")
