            defender = int(w[2])
            self.resources[p] = max(self.resources[p] - stolen, 0)
            self.resources[defender] = max(self.resources[defender] - self.rng.randint(1, 2), 0)

        elif w[0] == "Defend B":
            self.resources[p] = max(self.resources[p] - 2, 0)

