RULES = """Tavern Hold. 3 Tavern Masters, 6 rounds, one move each per round. Each Tavern Master has money (resources) and a
number of patrons (also resources). Two bystander taverns (B0, B1) serve drinks, but do not play.
- collect: get 1 patron and 1 payment.
- serve B<k>: give 1 patron to another tavern k (cannot overserve a tavern).
- ban P<k>: remove patron p from this tavern.
- charge B<k>: charge another tavern k for any number of patrons (the amount charged is deducted from the target tavern's resources).
- protect P<k>: prevent patron p from being given to another tavern for a turn."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.money = list(endowments); self.patrons = list(endowments[:])
        self.bys = list(bystanders)
        self.turn = 0; self.rounds = 6; self.protected = [[] for _ in range(self.n)]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["collect"] 
        for b in range(len(self.bys)):
            moves.append("serve B%d" % b)
        moves += ["ban P%d" % p for p in range(self.n)]
        moves += ["charge B%d" % b for b in range(len(self.bys))]
        moves += ["protect P%d" % p for p in range(self.n)]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "collect":
            if p <= 2:
                got_patron, got_money = 1, 1
            elif p == 3:
                got_patron, got_money = 2, 2
            elif p == 4:
                got_patron, got_money = 3, 3
            self.patrons[p] += got_patron; self.money[p] += got_money; self.turn += 1
        elif w[0] == "serve":
            b = int(w[1][1:])
            target = (p + 1) % 3 if p < 3 else (p + 2) % 3
            if self.patrons[target] > 0:
                self.patrons[target] -= 1; self.patrons[p] += 1; self.turn += 1
            else:
                print("Cannot serve: no patrons")
        elif w[0] == "ban":
            p_to_ban = int(w[1][1:])
            if p_to_ban in self.protected[p]:
                print("Cannot ban: already protected")
            else:
                self.protected[p].append(p_to_ban); self.turn += 1
        elif w[0] == "charge":
            b = int(w[1][1:])
            got_patrons = min(self.bys[b], self.patrons[p])
            self.bys[b] -= got_patrons; self.patrons[p] -= got_patrons; self.turn += 1
            print("Charged %d patrons from B%d" % (got_patrons, b))
        elif w[0] == "protect":
            p_to_protect = int(w[1][1:])
            if p_to_protect in self.protected[p]:
                print("Already protecting P%d" % p_to_protect)
            else:
                self.protected[p].append(p_to_protect); self.turn += 1

    def describe(self, p):
        return "Turn %d, Player P%d. Money %d. Patrons %d. Bystander Taverns %s. Protected from receiving patrons: %s." % (
            self.turn // self.n + 1, p, self.money[p], self.patrons[p], self.bys, self.protected[p])

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.money)
    def final_bystanders(self): return [by for by in self.bys]  # Copy since the game instance may mutate it.

