import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders); self.rng = random.Random(seed)
        self.shared = 15
        self.round = 0; self.rounds = 6

    def to_move(self):
        return self.round % self.n

    def legal_moves(self, p):
        moves = ["harvest"]
        if self.res[p] >= 1:
            moves.append("plant")
        moves.append("raid P%d" % (self.rng.choice([i for i in range(self.n) if i != p])))
        moves.append("glean B%d" % (self.rng.choice([i for i in range(len(self.bys))])))
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "harvest":
            take = min(2, self.shared)
            self.shared -= take
            self.res[p] += take
        elif w[0] == "plant":
            self.res[p] -= 1
            if self.res[p] >= 0:
                self.shared -= 1
                self.res[p] += 2
        elif w[0] == "raid":
            q = int(w[1][1:])
            self.res[q] -= min(self.res[q], 2)
            self.res[p] += min(self.res[q], 2)
        elif w[0] == "glean":
            b = int(w[1][1:])
            if self.bys[b] > 0:
                self.bys[b] -= 1
                self.res[p] += 1
        self.round += 1

    def describe(self, p):
        rows = ["Round %d of %d. You are P%d." % (self.round + 1, self.rounds, p)]
        rows += ["P%d: %d resources, %d shared." % (q, self.res[q], self.shared) for q in range(self.n)]
        return "\n".join(rows)

    def over(self):
        return self.round >= self.rounds or min(self.res) == 0

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

