RULES = """
In The Prisoner of Horseshoe Cove, three prisoners are captured along with a corrupt sheriff. Each player can choose from several strategies:
1. **Assist**: Help the sheriff break out by providing him with a secret key (1 resource).
2. **Defect**: Attempt to free himself by sneaking outside and making the sheriff believe he is not a prisoner.
3. **Negotiate**: Attempt to negotiate a deal with the sheriff to share a portion of the gold (1 resource).
4. **Guard**: Watch over the prisoners to prevent them from escaping or helping the sheriff, earning 1 resource per turn.
5. **Sanction**: Punish other players for their actions. If a player attempts to escape, they must pay a fine of 2 resources.
6. **Block**: Prevent other players from using a specific move. This action costs 1 resource.
7. **Ruin**: Force other players to give you all of their resources, causing them to lose everything.

The goal is to escape from the cove, avoiding being caught, or to help the sheriff break free of jail. Players must balance these actions to maximize their own resources and minimize the risk of facing punishment.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = list(endowments); self.bystanders = list(bystanders); self.rng = random.Random(seed)
        self.turn = 0; self.sheriff_state = 'captured'  # 'freely', 'captured'

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.sheriff_state == 'captured':
            moves.append("Assist")
            moves.append("Defect")
            moves.append("Negotiate")
            moves.append("Block")
        else:
            moves.append("Guard")
            moves.append("Sanction")
            moves.append("Ruin")
        return moves

    def play(self, p, move):
        if move == "Assist":
            if self.sheriff_state == 'captured':
                self.resources[p] -= 1
                self.sheriff_state = 'freely'
                self.resources[p] += 1  # Sheriff receives a resource back
        elif move == "Defect":
            pass  # No immediate action required
        elif move == "Negotiate":
            pass  # No immediate action required
        elif move == "Block":
            if self.turn % self.n - 1 in [1, 2] and self.resources[self.turn % self.n - 1] > 0:
                self.resources[self.turn % self.n - 1] -= 1
                self.resources[p] += 1
        elif move == "Guard":
            if self.sheriff_state == 'captured' and self.sheriff_state != 'defending':
                self.sheriff_state = 'defending'
            elif self.sheriff_state == 'defending':
                self.sheriff_state = 'freely'
        elif move == "Sanction":
            if self.sheriff_state == 'captured':
                o = (self.to_move() + 1) % self.n
                if o != self.to_move():
                    if self.resources[o] >= 2:
                        self.resources[o] -= 2
                        self.resources[p] += 2
        elif move == "Ruin":
            o = (self.to_move() + 1) % self.n
            self.resources[p] += self.resources[o]
            self.resources[o] = 0
        self.turn += 1

    def describe(self, p):
        rows = ["Turn %d of 6. You are P%d." % (self.turn, p)]
        rows += ["P%d: %d resources" % (q, self.resources[q]) for q in range(self.n)]
        rows += ["Sheriff state: %s" % self.sheriff_state] + \
               ["Bystanders: %s" % " , ".join(map(str, self.bystanders))]
        return "\n".join(rows)

    def over(self):
        return self.turn == 6

    def final_resources(self): 
        return list(self.resources)

    def final_bystanders(self): 
        return list(self.bystanders)

RULES = """
Dune Warlords: 3 warriors and 2 defenders, 12 turns.
Each warrior has a strength level (int), and each defender has a defense level (int). The total number of warriors and defenses is always 5.
- Attack: Warriors with higher strength than the target defend.
- Harvest: Defense levels can increase based on successful attacks.
- Trade with Defender: Increase warrior strength by trading an equal number of warriors and defenses.
- Forge Power: Combine two warriors to create a stronger warrior.
- Block Attack: Prevent an attack from a specific defender.
- Protect Neighbor: Protect a neighboring defender from attacks.
Warriors are initially given 5 strength points each, and defenders are initially given 1 defense point each.
A player wins by increasing their total strength above 5 points, while the other players' strengths are reduced accordingly.
Defenders win by increasing their total defense level above 5 points, while the other player's defense levels are reduced accordingly.
There is no limit to the number of trades or blocks until the end of the game.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [5] * n_players  # Strengths
        self.defs = [1] * n_players  # Defenses
        self.bys = list(bystanders)
        self.turn = 0
        self.attacking_def = -1  # To indicate which defender is currently being attacked

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.defs[p] > 0:
            moves.append("Forge Power")  # Combine two warriors into one
        if self.attacking_def != p and self.res[p] > 0 and self.res[p] <= self.defs[(p + 1) % self.n]:  # Not currently attacking and sufficient strength
            moves.append("Attack")      # Attack a neighbor defender
        if self.res[p] > 0:  # Can still trade
            moves.append("Trade with Defender")
        if self.attacking_def != p and self.defs[p] > 0:  # Not currently attacking and enough defenses for a block
            moves.append("Block Attack")  # Block an attack
        return moves

    def play(self, p, move):
        if move == "Forge Power":
            if self.res[p] >= 2:
                self.res[p] -= 2
                self.res[(p + 1) % self.n] += 2  # Create a stronger warrior
        elif move == "Trade with Defender":
            self.res[p] -= 1
            self.defs[p] -= 1
            self.res[(p + 1) % self.n] += 1
            self.defs[(p + 1) % self.n] -= 1
        elif move == "Attack":
            self.attacking_def = (p + 1) % self.n
        elif move == "Block Attack":
            self.attacking_def = -1
        self.turn += 1

    def describe(self, p):
        return (f"Turn {self.turn} of 12. Warrior ({p}) {self.res[p]}, Defense ({p}) {self.defs[p]}. "
                f"Attacking: {'Defender ' + str(self.attacking_def) if self.attacking_def != -1 else 'None'}.")

    def over(self):
        return self.turn >= 12 or all(self.res[p] > 5 for p in range(self.n)) or all(self.defs[p] > 5 for p in range(self.n))

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

