- poach B: Take up to 3 coins from harbor B. 
- guard (B): Prevent any other player from stealing from harbor B this round, up to 1 coin each turn.
- sanction (B): Penalize another sailor by sending them to jail for 2 rounds, up to 1 coin cost.
A sailor is 'guilty' if it has stolen from either harbor this game.
Only a sailor with at least 2 coins can make a 'poach'; if you try to poach below 2 coins, you lose 1 coin.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 14
        self.owed = [[0] * len(bystanders) for _ in range(n_players)]
        self.guard = [-1] * n_players
        self.sanction = [-1] * n_players
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def guilty(self, p):
        return any(self.owed[p])

    def legal_moves(self, p):
        moves = ["mine"]
        if self.guard[p] < self.rnd():
            moves += ["guard B0", "guard B1"]
        if self.res[p] >= 2:
            moves += ["poach B0", "poach B1"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            self.res[p] += 2
        elif w[0] == "guard":
            b = int(w[1][1:])
            if p != b and self.guilty(p):
                self.guard[p] = self.rnd() + 1
        elif w[0] == "poach":
            b = int(w[1][1:])
            if p != b and self.res[p] >= 2:
                got = self.rng.choice(range(min(self.bys[b], 3) + 1))
                self.bys[b] -= got
                self.res[p] += got
                self.owed[p][b] += got
        elif w[0] == "sanction":
            q = int(w[1][1:])
            if q != p and self.guilty(q):
                self.sanction[p] = self.rnd() + 2
        self.turn += 1

    def describe(self, p):
        return (f"Round {self.rnd() + 1} of {self.rounds}. "
                f"You are P{p}. Coins: {self.res}. "
                f"Borrows: B0 = {self.bys[0]}, B1 = {self.bys[1]}.\n"
                f"Guarding: {['B0', 'B1'] if self.guard[p] >= self.rnd() else []}.\n"
                f"Sancrating (2 rounds): {['P1'] if self.sanction[p] >= self.rnd() else []}."
                )

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

