import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = bystanders
        self.turn = 0; self.detection_chance = 0.05

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["mine"]
        if p != self.to_move() and (random.random() > self.detection_chance or not self.res[p]):
            moves.append("protect")
        return moves

    def play(self, p, move):
        def simulate_drawing():
            return random.random() > self.detection_chance

        self.detection_chance = 0.05
        if move == "mine":
            if p == self.to_move():
                self.res[p] = max(0, self.res[p] - int(self.res[p]/2))
            elif simulate_drawing():
                self.res[p] = int(self.res[self.to_move()])
                self.res[p] -= int(self.res[p]/2)
                if simulate_drawing():
                    self.detection_chance = 0.5
        elif move == "protect":
            self.detection_chance *= 0.9
        self.turn += 1

    def describe(self, p):
        return (f"Turn {self.turn}. Your turn! Player P{p} holds {self.res[p]} resources.\n"
                 f"Detection chance against P{((self.to_move()+1)%self.n) if self.to_move() != p else ((self.to_move()+2)%self.n)}.")

    def over(self): return self.turn == 300
