                self.res[p] += 1

        elif w[0] == "Block":
            if not self.blocked[p] and p < self.n - 1:
                self.blocked[p] = True
                self.res[p] -= 1
            else:
                self.res[p] += 1

        elif w[0] == "Tribute to Bystander":
            if self.bys[p] > 19 and not self.blocked[p]:
