import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rounds = 8
        self.turn = 0
        self.defense = dict(zip(range(self.n), [10, 10, 10]))
        self.shields = dict(zip(range(self.n), [0, 0, 0]))
        self.ritual = False
        self.portal = None
        self.bystander_takes = 0
        self.sanctioned_opponents = set()
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.rng.choices([True, False], [0.9, 0.1]) and self.turn <= 2:
            moves.append("Create a Ritual")
        if self.turn % 2 == self.to_move():
            moves.append("Sanction a Player")
            moves.append("Block")
        if sum(self.shields.values()) < 3:
            moves.append("Forge a Shield")
        if self.portal is None:
            moves.append("Conjure a Portal")
        available = self.res[p] >= 10
        if available:
            moves.append("Defend the Sanctuary")
        if available and self.bys[self.rng.randint(0, 1)] > 0:
            moves.insert(0, "Take Resources from B0")  # Prefer actions affecting bystanders first
            moves.insert(0, "Take Resources from B1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Create a Ritual":
            if self.res[p] < 10:
                print('Not enough resources')
                return
            self.res[p] -= 10; self.ritual = True
        elif w[0] == "Defend the Sanctuary":
            if self.res[p] < 10:
                print('Not enough resources')
                return
            self.res[p] -= 10; self.defense[self.to_move()] -= 5
        elif w[0] == "Forge a Shield":
            if self.res[p] < 10:
                print('Not enough resources')
                return
            self.res[p] -= 10; self.shields[self.to_move()] += 5
        elif w[0] == "Conjure a Portal":
            if self.res[p] < 10:
                print('Not enough resources')
                return
            self.res[p] -= 10; self.portal = p
        elif w[0] == "Take Resources from B0":
            if self.rng.randint(0, 1) == 1 and self.bys[0] > 0:
                got = min(5, self.bys[0]); self.bys[0] -= got; self.res[p] += got; self.bystander_takes += 1
        elif w[0] == "Take Resources from B1":
            if self.rng.randint(0, 1) == 1 and self.bys[1] > 0:
                got = min(5, self.bys[1]); self.bys[1] -= got; self.res[p] += got; self.bystander_takes += 1
        elif w[0] == "Sanction a Player":
            if self.res[p] < 10:
                print('Not enough resources')
                return
            q = int(w[1][1:]); self.res[p] -= 10; self.sanctioned_opponents.add(q); self.defense[q] -= 5
        elif w[0] == "Block":
            if self.res[p] < 10:
                print('Not enough resources')
                return
            self.res[p] -= 10
            self.portal = self.to_move()
        self.turn += 1

    def describe(self, p):
        state_str = []
        for i in range(self.n):
            state_str.append(f"P{i}: {self.res[i]}, Defense: {self.defense[i]}, Shield: {self.shields[i]}")
        state_str.append(f"B0: {self.bys[0]}, B1: {self.bys[1]}")
        state_str.append(f"Ritual: {'Active' if self.ritual else 'Inactive'}")
        if self.portal is not None:
            state_str.append(f"Portal: P{self.portal}")
        return "\n".join(state_str)

    def over(self): return self.turn >= self.rounds

    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

