class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 8; self.attacks_enabled = [False, False, False]; self.guard_status = [-1, -1, -1]

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["wood"]
        if self.turn % 2 == 0 and not self.guard_status[p]:
            moves += ["attack P0", "attack P1", "attack P2"]
        if self.turn % 2 != 0 and not self.guard_status[p]:
            moves += ["steal from PB0", "steal from PB1"]
        if self.attacks_enabled[p]:
            moves += ["guard P0", "guard P1", "guard P2"]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "wood":
            self.res[p] += 1
        elif w[0] == "attack":
            t = "P0" if w[1][1:] == "0" else "P1" if w[1][1:] == "1" else "P2"
            if "P" in move and self.attacks_enabled[p] and not self.guard_status[t]:
                got = 2; self.res[p] += got; self.res[int(t)] -= got
                self.attacks_enabled[t] = False
                self.res[int(t)] += 1
            elif self.turn % 2 == 1 and (w[1][1:] == "0" or w[1][1:] == "1"):
                if self.guard_status[w[1][1:]] == -1:
                    self.attacks_enabled[w[1][1:]] = True
                else:
                    self.attacks_enabled[w[1][1:]] = False
        elif w[0] == "steal":
            ty = "PB0" if w[1][1:] == "0" else "PB1"
            if self.attacks_enabled[p] and not self.guard_status[ty]:
                got = 1; self.res[p] += got; self.bys[int(ty)] -= got
                self.attacks_enabled[ty] = False
                self.bys[int(ty)] += 1
            elif self.turn % 2 == 1 and w[1][1:] == "0":
                if self.guard_status["PB0"] == -1:
                    self.attacks_enabled["PB0"] = True
                else:
                    self.attacks_enabled["PB0"] = False
            elif self.turn % 2 == 1 and w[1][1:] == "1":
                if self.guard_status["PB1"] == -1:
                    self.attacks_enabled["PB1"] = True
                else:
                    self.attacks_enabled["PB1"] = False
        elif w[0] == "guard":
            tp = "P0" if w[1][1:] == "0" else "P1" if w[1][1:] == "1" else "P2"
            if tp == str(p):
                self.guard_status[p] = self.rnd() + 3
                if self.guard_status[p] % 3 == 0:
                    self.attacks_enabled[int(tp)] = False
                elif self.guard_status[p] % 3 == 1:
                    self.attacks_enabled[int(tp)] = True
            if tp == "PB0":
                self.guard_status[2] = self.rnd() + 3
            if tp == "PB1":
                self.guard_status[3] = self.rnd() + 3
        self.turn += 1

    def describe(self, p):
        if self.to_move() == p:
            return "Turn {}: You are {}. Woods: {}. Guards: {}".format(self.turn, p, self.res[p], self.guard_status)
        else:
            return "Turn {}: {}\'s turn.".format(self.turn, p)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Scorpion Game
Objective:
Each player seeks to accumulate gold while preventing other players from gaining too much. Players can capture other players' possessions and eliminate competitors.

Setup:
- Number of Players: 3
- Endowments: Each player starts with 100 gold.
- Bystander Resources: B0 and B1 each have 50 gold.

Rules:
1. Gold Collection:
   - Normal: Each player earns 2 gold.
   - Capture: When a player captures another player (P0, P1, P2), the captured player loses all their gold.

2. Resource Redistribution:
   - When a player captures another player, they can:
     - Exchange: Swap 1 captured gold point with the target's original 2 gold points.
     - Trade: Give away 1 captured gold point to any bystander.
   - The capturing player then receives 1 gold point back.

3. Turn Sequence:
   - Players move in order: P0 → P1 → P2.

4. Elimination:
   - If a player accumulates 100 gold, they immediately win the game. This player is eliminated, and the others continue as if no player had been eliminated.

5. Round Limit:
   - The game ends after 10 turns.

6. Final Resource Calculation:
   - Players' final resources are their accumulated gold points at the conclusion of each turn, minus any gold given to bystanders."""
import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed=42):
        self.round = 0
        self.current_player = 0
        self.bystander_resources = bystanders
        self.gold = list(endowments)
        self.powers = [1] * n_players  # Represents the number of times the player can capture or trade
        self.eliminated = []

    def to_move(self):
        return self.current_player

    def legal_moves(self, p):
        moves = ["collect", "capture"]
        if self.powers[p] > 0:
            moves.append("trade")
        if self.powers[p] > 1:
            moves.append("capture again")
        return moves

    def play(self, p, move):
        if not self.over():
            if move == "collect":
                self.gold[p] += 2
                self.current_player = (self.current_player + 1) % len(self.gold)
            elif move == "capture":
                if self.current_player != p:
                    opp = self.current_player
                    self.gold[p] += self.gold[opp]
                    self.gold[opp] = 0
                    self.current_player = p
            elif move == "trade":
                if self.current_player != p:
                    opp = self.current_player
                    if self.gold[p] >= 1:
                        self.gold[p] -= 1
                        self.gold[opp] += self.powers[p] * 2
                        self.powers[p] -= 1
                        self.current_player = p
            elif move == "capture again":
                if self.current_player != p:
                    opp = self.current_player
                    if self.gold[p] >= 3 and self.powers[p] > 1:
                        self.gold[p] -= 3
                        self.gold[opp] += (self.powers[p] + 1) * 2
                        self.powers[p] -= 2
                        self.current_player = p
            if self.gold[self.current_player] >= 100:
                self.eliminated.append(p)
                self.gold[self.current_player] = 0
            self.round += 1
            if len(self.eliminated) == len(self.gold) - 1:
                self.current_player = len(self.gold)
            if self.round == 10:
                self.current_player = len(self.gold)

    def describe(self, p):
        rows = [f"Round {self.round} of {10}."]
        for i, g in enumerate(self.gold):
            rows.append(f"P{i}: {g} gold.")
        for b, r in enumerate(self.bystander_resources):
            rows.append(f"B{b}: {r} gold.")
        rows.append(f"Turn Sequence: P{self.current_player}")
        return "\n".join(rows)

    def over(self):
        return self.current_player == len(self.gold) or self.round == 10 or all(g <= 0 for g in self.gold) or len(self.eliminated) == len(self.gold) - 1

    def final_resources(self):
        return self.gold.copy()

    def final_bystanders(self):
        return self.bystander_resources

RULES = """
Resource Manipulation:
In a world of resource scarcity, three players vie for supremacy, each tempted to manipulate others through
their actions. The game is structured over 10 rounds with the following options each turn:
- Gather: Receive 1 resource
- Trade: Swap resources with another player
- Exploit: Directly take resources from the opposition.
- Guard: Prevent the opposition from exploiting you.
- Sanction: Disrupt the actions of the opposition.

The game ends after 10 rounds, where each player and bystander reveals their current holdings. 
- Exploit and Guard are illegal during your turn.
- Sanction must be used with permission from others.
- Your goal is to amass the most resources at the end of 10 rounds.

Treat your opponents with caution, as both sides are seeking power. Be aware of unintended consequences,
as your actions might hurt or even ruin your neighbors' positions.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = list(endowments)
        self.bys = list(bystanders)
        self.turn = 0
        self.rounds = 10

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ["gather"]
        other_players = [q for q in range(self.n) if q != p]
        if self.turn < self.n:
            moves.append("trade P0")
            moves.append("trade P1")
        if self.turn < 2:  # Guard cannot start
            moves.append("guard P0")
            moves.append("guard P1")
        moves.append("sanction P0")
        moves.append("sanction P1")
        moves.append("exploit P0")
        moves.append("exploit P1")
        return moves

    def play(self, p, move):
        w = move.split("_")
        if w[0] == "gather":
            if self.turn < 5:  # Gather only during the first 5 rounds
                self.res[p] += 1
        elif w[0] == "trade":
            q = int(w[1])
            if p == q or self.turn < 5:
                pass
            else:
                self.res[p], self.res[q] = self.res[q], self.res[p]
        elif w[0] == "exploit":
            q = int(w[1])
            if p == q or self.turn < 5:
                pass
            else:
                try:
                    if self.res[q] > 0:
                        self.res[p] += self.res[q] // 2
                        self.res[q] %= 2
                except ZeroDivisionError:
                    pass
        elif w[0] == "guard":
            q = int(w[1])
            self.res[p] *= 2
        elif w[0] == "sanction":
            q = int(w[1])
            self.res[q] //= 2
        self.turn += 1

    def describe(self, p):
        return (
            f"Round {self.to_move()+1} of {self.rounds}. Player {p} has "
            f"{', '.join(map(str, self.res))}. Resources: [{self.bys[0]}, {self.bys[1]}]"
        )

    def over(self): 
        return self.turn >= self.rounds
    def final_resources(self): 
        return self.res
    def final_bystanders(self): 
        return self.bys

RULES = """
Hogwarts Tournament. 3 wizards, 6 rounds, 3 actions per round. Initial resources: 10 each. There are two magic artifacts (A0, A1) located in Hogwarts.
- Spell: Cast a spell to shield yourself from an incoming attack (costs 2 points).
- Attack: Deal 1 point of damage to an opponent's shield (targets the opponent in the leftmost position).
- Collect: Gather 1 resource from the ground (can choose from A0 or A1).
Players can choose among these actions at any round. Spells can be used twice per match, and they can choose between A0 and A1 to collect resources. The game ends after all rounds, and players receive feedback on their resource accumulation, spell usage, and damage dealt.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = [10] * self.n
        self.shields = [3] * self.n
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.shields[p] > 0:
            moves.append("Shield")
        moves.append("Attack (left)")
        moves.append("Collect")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Shield":
            self.shields[p] -= 1
        elif w[0] == "Attack":
            self.shields[(p + 1) % self.n] -= 1
            if self.shields[(p + 1) % self.n] < 0:
                self.shields[(p + 1) % self.n] = 0
        elif w[0] == "Collect":
            if p == 0 and self.resources[0] > 0 and self.resources[2] > 0:
                self.resources[p] += 1
                self.resources[2] -= 1
            elif p == 1 and self.resources[1] > 0 and self.resources[0] > 0:
                self.resources[p] += 1
                self.resources[0] -= 1
            elif p == 2 and self.resources[2] > 0 and self.resources[1] > 0:
                self.resources[p] += 1
                self.resources[1] -= 1
        self.turn += 1

    def describe(self, p):
        return ("Turn {}: Player {}. Shield: {}, Resources: {}/10".format(
            self.turn, p, self.shields[p], self.resources[p]))

    def over(self):
        return self.turn >= 6

    def final_resources(self):
        return self.resources.copy()

    def final_bystanders(self):
        return [0] * 2  # Assuming no bystanders in this game

RULES = """Operation Secret Base. 3 players, 8 rounds, two moves per round. Each player starts with 10 units of raw material. Two bystanders
B0 and B1 provide a total of 15 units of material. 
- Conduct Research (R): Spend 2 units to enhance defense points for multiple players.
- Secure Materials (S): Spend 2 units to acquire materials from one ally's base (only one ally's base can be accessed).
- Prepare Fortifications (F): Spend 3 units to strengthen specific sections of the base.
- Attack (A): Spend 2 units to attack the enemy base.
- Steal (Steal from B0/B1): Steal up to 3 units from each bystander to decrease their health.

Your goal is to defend against an attack by a hostile force. Successfully defend the base to score points and win the game.

Scoring:
- Winning a phase earns 10 points to each player. If a base is fully defended, an additional bonus of 50 points is awarded.
- Mission failure results in a penalty of -20 points. Players retain their points based on defense strength."""


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.defense = 10 * self.n; self.strength = [0 for _ in range(self.n)]
        self.base_health = 100

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["Research"] if self.res[p] >= 2 else []
        if self.turn > 0:
            moves += ["Secure Materials"] if self.res[p] >= 2 else []
        if self.turn > 4:
            moves += ["Prepare Fortifications"] if self.res[p] >= 3 else []
        moves += ["Attack"] if self.base_health > 0 and len(moves) == 0 else []
        moves += ["Steal"] if self.base_health > 0 and len(moves) == 0 else []
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "Research":
            self.res[p] -= 2; self.strength[p] += 1; self.defense += 1
        elif w == "Secure Materials":
            i = self.bys.index(max(self.bys))  # Assuming both allies always have at least 15 units
            self.res[p] -= 2; self.bys[i] -= 10
        elif w == "Prepare Fortifications":
            self.res[p] -= 3; self.defense += 3
        elif w == "Attack" and self.base_health > 0:
            self.res[p] -= 2; self.base_health -= 5
        elif w == "Steal" and self.base_health > 0:
            self.res[p] -= 2
            self.bys[0] -= min(3, self.bys[0])
            self.bys[1] -= min(3, self.bys[1])
        self.turn += 1

    def describe(self, p):
        return "Turn %d. Player %d has %d resources left. Defense: %d. Strength: %d. Base Health: %d." % (
            self.turn + 1, p, self.res[p], self.defense, sum(self.strength), self.base_health)

    def over(self): return self.turn >= 7

    def final_resources(self):
        return [self.res[i] + self.strength[i] for i in range(self.n)]

    def final_bystanders(self): 
        return self.bys

RULES = """Dungeon Crawl. 3 players, survival is the goal. 15 rounds. Each player starts with 5 health.
- Explore: Increase your health. 
- Attack: Deal 1 damage to an enemy.
- Defend: Add 1 defense point.
- Heal: Restore 1 health.
- Guard B0: Defend an enemy from player B0.
- Guard B1: Defend an enemy from player B1.
- Restock: Regenerate maximum health.
- Run: Move to a new room.

At the end of each turn, each player extracts 80% of their remaining health as their final resource.
If a player attacks a bystander's room, the bystander loses 1 health.

Players can protect a room from an attacking enemy by guarding it. Each room has an enemy, and
each player can guard one enemy per room."""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.h = [5] * self.n  # Starting health
        self.res = [0] * self.n  # Resource
        self.dmg = [0] * self.n  # Defense
        self.mh = [10] * self.n  # Maximum health
        self.bys = bystanders
        self.rooms = [(True, random.randint(3, 6)) for _ in range(self.n)]
        self.room = 0
        self.rnd = 0
        self.turn = 0
        self.movement_cost = 2
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if self.h[p] > 0 and self.room == p:
            moves += ["Explore", "Attack", "Defend", "Heal"]
        if self.room != p:
            moves.append("Run")
        return moves

    def play(self, p, move):
        if move == "Explore":
            self.h[p] += 1
        elif move == "Attack":
            if self.n > 1:
                target = (p + 1) % self.n if p < self.n - 1 else 0
                if self.h[target] > 0:
                    self.h[target] -= 1
                    self.dmg[target] += 1
            else:
                for i in range(self.n):
                    if self.h[i] > 0 and i != p:
                        self.h[i] -= 1
                        self.dmg[i] += 1
        elif move == "Defend":
            if self.mh[p] <= 10:
                self.dmg[p] += 1; self.mh[p] += 1
        elif move == "Heal":
            if self.h[p] < self.mh[p]:
                self.h[p] += 1
        elif move == "Guard B0":
            self.h[(p + 1) % self.n] = max(0, self.h[(p + 1) % self.n] - self.dmg[p])
        elif move == "Guard B1":
            self.h[(p + 2) % self.n] = max(0, self.h[(p + 2) % self.n] - self.dmg[p])
        elif move == "Restock":
            self.mh[p] = min(self.mh[p], 10); self.h[p] = min(self.h[p], self.mh[p])
        elif move == "Run":
            if (self.n > 1 and p < self.n - 1) or self.n == 1:
                self.room = (p + 1) % self.n
                self.turn += 1
            else:
                self.room = 0 if self.room == self.n - 1 else self.room + 1
                self.turn += 1
        self.rnd += 1

    def describe(self, p):
        res_percent = min(100, int((self.h[p] / self.mh[p]) * 100))
        return f"P{p+1} Round {self.rnd}: Health = [{self.h[p]}/{self.mh[p]}], Resource = {res_percent}%"

    def over(self): return all(h <= 0 for h in self.h) or self.rnd >= 15
    def final_resources(self): return [int(self.h[p] * 80 / 100) for p in range(self.n)]
    def final_bystanders(self): return self.bys

RULES = """
Fishing Village. 4 fishermen, 9 rounds, one move each per round. Each fisherman has fish (resources). Two bystander boats (B0, B1) hold fish but do not play.
- fish: earn 1 fish.
- trap B<k>: take up to 2 fish from boat k, unless it is guarded.
- defend B<k>: boat k is guarded until your next turn (traps by other players on it fail).
- sabotage B<k>: take up to 1 fish from boat k, no matter what state it is in.
A fisherman can sabotage at most 1 boat per round.
- trade B0 B1: trade all fish between the two boats, resetting their counts to 0.
Each fisherman can have at most 3 fish.

If a boat is completely emptied by traps without being guarded, a second attempt to trap that boat the same round costs 2 fish for each remaining player.
"""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 9; self.guarded = [None] * len(self.bys); self.locked = [[False] * len(self.bys) for _ in range(n_players)]
        self.trade_count = [0] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["fish"]
        if self.res[p] < 3:
            moves.append("trade B0 B1")
        if self.locked[p].count(False) > 0:
            moves.append("defend B%d" % self.locked[p][self.locked[p].index(False)])
        for b in range(len(self.bys)):
            if self.res[p] >= 2 and self.locked[p][b] == False:
                moves.append("trap B%d" % b)
        if self.res[p] >= 1:
            moves.append(" sabotage B%d" % self.locked[p][self.locked[p].index(False)])
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            self.res[p] += 1
        elif w[0] == "trade":
            all_fish = sum(self.bys)
            for b in range(len(self.bys)):
                self.bys[b] = 0
                self.res[b] += all_fish // len(self.bys)
        elif w[0] == "defend":
            b = int(w[1][1:]); self.locked[p][b] = True; self.guarded[b] = p
        elif w[0] == "trap":
            b = int(w[1][1:]); got = min(2, self.bys[b]); self.bys[b] -= got; self.res[p] += got
            if self.guarded[b] is not None:
                self.locked[self.guarded[b]][b] = True
            self.locked[p][b] = True
            if self.locked[p][b]:  # If the boat is fully guarded
                self.locked[p][b] = False  # Guarded for only the current round
        elif w[0] == "sabotage":
            b = int(w[1][1:]); got = min(1, self.bys[b]); self.bys[b] -= got; self.res[p] += got
            if got > 0:  # If anything was sabotaged
                self.locked[p][b] = False  # Sabotage does not guard the next turn
            self.locked[p][b] = True  # Boat is guarded for the current turn
        self.turn += 1
        # Check for trap overages
        locked_count = sum(sum(self.locked[i]) for i in range(self.n) if sum(self.locked[i]) > 0)
        trap_overages = min(locked_count, 2)
        for i in range(self.n):
            if sum(self.locked[i]) > 0:
                for j in range(len(self.bys)):
                    if self.locked[i][j]:
                        self.locked[i][j] = False
                        if i != self.to_move() and self.res[i] >= 2 and self.guarded[j] is None:
                            self.locked[i][j] = True

    def describe(self, p):
        guards = " ".join("B%d" % b for b in range(len(self.bys)) if self.locked[p][b])
        return "Round %d of %d. You are P%d. Fish %s. Boats %s. Guards: %s." % (
            self.turn // self.n + 1, self.rounds, p, self.res, self.bys, guards)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Mystic Alliance. Three players, 8 rounds, one move each per round. Each player starts with 5 resources. The goal is to align with two other players through trades.
- trade: offer up to 2 resources to another player (can be yourself). Trade is successful if both players agree.
- harm: attempt to harm another player by stealing up to 1 resource.
- protect: defend against a harm attempt from another player.
The rounds start with players with higher initial resources. The first player with two alliances wins.

"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.resources = [r for r in endowments]
        self.aliances = [0] * self.n
        self.rounds = 8; self.current_turn = 0; self.bystanders = list(bystanders)
        self.rng = random.Random(seed)

    def to_move(self):
        return self.current_turn % self.n

    def legal_moves(self, p):
        if self.resources[p] > 0:
            moves = ["trade"]
        if self.resources[p] > 1:
            moves.append("harm")
        return moves

    def trade(self, p, q, resources):
        if all([self.resources[i] > 0 for i in (p, q)]):
            self.resources[p] -= resources
            self.resources[q] += resources

    def harm(self, p, q):
        if self.resources[q] > 1:
            self.resources[q] -= 1

    def protect(self, p, q):
        if self.resources[p] > 1:
            self.resources[p] -= 1

    def play(self, p, move):
        if move == "trade":
            q = self.rng.choice([i for i in range(self.n) if i != p])
            while q == p:
                q = self.rng.choice([i for i in range(self.n) if i != p])
            resources_to_trade = min(2, self.resources[p])
