            self.protect(p, q)
        self.current_turn += 1

    def describe(self, p):
        return f"Round {self.current_turn+1}. You are Player {p+1}. Resources {self.resources[p]}, Current Aliances {self.aliances[p]}."

    def over(self):
        return max(self.aliances) >= 2 and self.current_turn >= self.rounds

    def final_resources(self):
        return sorted(self.resources)

    def final_bystanders(self):
        return self.bystanders

