        if self.res[p] == 0: return moves

        moves += ["rob_P0"] if self.res[p] >= 1 else []
        moves += ["rob_P1"] if self.res[p] >= 1 else []
        moves += ["attack_B0"] if self.res[p] >= 1 else []

        moves += ["sanction"] if self.res[p] >= 1 else []

