import random


class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.rng = random.Random(seed); self.turn = 0; self.rounds = 8
        self.reserve = sum(endowments) // 3
        self.blocked = [False] * n_players

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        if self.res[p] == 0:
            return ["watch"]
        moves = ["fish"]
        if not self.blocked[p] and self.res[p] > 0:
            moves.extend(["watch", "sanitize P0", "sanitize P1/P2", "eliminate P1", "eliminate P2", "eliminate B0"])
        if self.res[p] > 0 and not self.blocked[p]:
            moves.append("defend (P0/P2) (B0)")
        if self.bys[0] > 0:
            moves.append("steal (B0)")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            self.res[p] += 1
        elif w[0] == "watch":
            if not self.blocked[p] and p < 2:
                self.blocked[p] = True
        elif w[0] == "sanitize P0":
            if self.bys[0] > 0:
                self.res[0] -= 2; self.res[p] += 2
        elif w[0] == "sanitize P1/P2":
            if w[1] == "P1" or w[1] == "P2":
                self.res[int(w[1])] -= 2; self.res[p] += 2
        elif w[0] == "eliminate P1":
            if not self.blocked[p] and p == 0:
                self.blocked[p] = True; self.res[1] = 0
        elif w[0] == "eliminate P2":
            if not self.blocked[p] and p == 0:
                self.blocked[p] = True; self.res[2] = 0
        elif w[0] == "eliminate B0":
            if self.blocked[0] and self.bys[0] > 0:
                self.bys[0] = 0
        elif w[0] == "defend (P0/P2) (B0)":
            if w[0] == "P0":
                if self.bys[0] > 4:
                    self.bys[0] -= min(5, self.res[0]); self.res[0] -= 1
            elif w[0] == "P2":
                if self.bys[0] > 4:
                    self.bys[0] -= min(5, self.res[2]); self.res[2] -= 1
        elif w[0] == "steal (B0)":
            if w[0] == "P0":
                self.res[0] += min(5, self.bys[0]);
            elif w[0] == "P2":
                self.res[2] += min(5, self.bys[0]);
            self.bys[0] -= min(5, self.bys[0])
        self.turn += 1
        if self.turn % self.n == 0 and self.bys[0] >= 4:
            grow = min(self.rng.randint(1, 3), self.reserve); self.reserve -= grow; self.bys[0] += grow

    def describe(self, p):
        return "Round %d: %s. You are P%d. Fish: %d. Pond: %d. Blocked: %s." % (
            self.turn // self.n + 1, ["Watch", "Sanitize P0", "Sanitize P1/P2", "Eliminate P1", "Eliminate P2", "Eliminate B0"][
                p], p, self.res[p], self.bys[0], ["yes" if b else "no" for b in self.blocked])

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): 
        return list(self.res)
    def final_bystanders(self): 
        return list(self.bys)

