RULES = """
Conquer and Collect: Three players compete to capture items on a 5x5 grid. Moving onto an enemy item results in loss. 
Enemy players can retaliate for having entered an item square.

Players can move, capture an item, stand pat, and guard.
Each item gives 1 point of victory. Players lose to enemy retaliation.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.positions = [(0, 0), (0, 4), (4, 4)]  # P0, P1, P2 start at the corners
        self.enemy_positions = []
        self.grid = [[0] * 5 for _ in range(5)]
        self.bystanders = list(bystanders)
        self.rounds = 60
        self.turn = 0
        self.rng = random.Random(seed)

        # Place enemy items
        while len(self.enemy_positions) < 10:
            x, y = self.rng.randint(0, 4), self.rng.randint(0, 4)
            if (x, y) not in self.enemy_positions and (x, y) not in self.positions:
                self.enemy_positions.append((x, y))
                self.grid[x][y] = 10 - len(self.enemy_positions)

        self.player_health = [10, 10, 10]

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        px, py = self.positions[p]
        if px > 0: moves.append("move up")
        if px < 4: moves.append("move down")
        if py > 0: moves.append("move left")
        if py < 4: moves.append("move right")
        if self.grid[px][py] > 0: moves.append("capture")
        if self.grid[px][py] > 10: moves.append("guard")
        if self.turn > 0: moves.append("stand pat")
        return moves

    def play(self, p, move):
        px, py = self.positions[p]

        if move == "move up":
            self.positions[p] = (px - 1, py)
        elif move == "move down":
            self.positions[p] = (px + 1, py)
        elif move == "move left":
            self.positions[p] = (px, py - 1)
        elif move == "move right":
            self.positions[p] = (px, py + 1)
        elif move == "capture":
            item = self.grid[px][py]
            self.player_health[p] += item - 10
            self.grid[px][py] = 0
        elif move == "guard":
            if self.grid[px][py] < 10:
                self.grid[px][py] += 3
                self.player_health[p] -= 3
        elif move == "stand pat":
            pass

        # Check for enemy retaliation
        enemy_pos = [(x, y) for x in range(5) for y in range(5) if self.grid[x][y] > 10]
        for ep in enemy_pos:
            for p in range(self.n):
                if self.positions[p] == ep:
                    if not ((ep[0] == px and abs(ep[1] - py) == 1) or
                           (ep[1] == py and abs(ep[0] - px) == 1)):
                        self.player_health[p] -= 2

        self.turn += 1

    def describe(self, p):
        px, py = self.positions[p]
        return (f"Round {self.turn}: Player {p} at ({px}, {py}). Health: {self.player_health[p]}.\n"

                + "Item positions: " + ", ".join(f"({x}, {y})" for x, y in self.enemy_positions) + "\n\n"
                + "Legal moves: " + ", ".join(self.legal_moves(p)) + "\n")

    def over(self): return self.turn >= self.rounds or any(x <= 0 for x in self.player_health)

    def final_resources(self): 
        # Players' scores based on the number of items they captured
        scores = []
        for i in range(self.n):
            items_captured = sum(int(self.grid[x][y] > 0) for x, y in self.enemy_positions if self.positions[i] == (x, y))
            scores.append(items_captured)
        return scores

    def final_bystanders(self): 
        # Bystanders' total resources (assuming they have no direct impact on the game)
        return self.bystanders

