The game ends when all turns are completed, and the score is determined by the difference between the remaining resources of each player and their starting amounts.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [7] * self.n
        self.bys = list(bystanders); self.turn = 0

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = []
        if not self.bys:
            moves.extend(['Defend Reserves: Player', 'Share Resources'])
        else:
            moves.extend(['Trade Resources', 'Defend Reserves: Player', 'Share Resources'])
        return moves

    def play(self, p, move):
        w = move.split(" "); r = w[1] if len(w) > 1 else ""
        self.turn += 1
        if w[0] == "Trade Resources":
            q = int(r); self.res[q] += min(self.res[p], 4); self.res[p] -= min(self.res[p], 4)
        elif w[0] == "Defend Reserves: Player":
            if self.res[r]: self.res[r] += min(self.res[p], 2); self.res[p] -= min(self.res[p], 2)
        elif w[0] == "Share Resources":
            if p != r:
                d = min(2, self.res[p]); self.res[p] -= d; self.res[r] += d

    def describe(self, p):
        return ("Turn {}/{} of 10\nPlayer {} has {} resources."
                .format(self.turn, 10, p, sum(self.res)))

    def over(self): return self.turn >= 10
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)

RULES = """
Game of Resource Management:
- Three players start with 10 coins each.
- Two neutral bystanders each start with 10 coins.
- Players can:
  1. Collect Coin (1-2): Take coins from a neutral bystander.
  2. Disrupt (Steal): Attempt to take coins from another player directly.
  3. Protect: Prevent being directly disrupted by one player.
  4. Shield: Steal up to one coin from a protected player.
  5. Trade with Bystander: Transfer coins to/from a neutral bystander.
  6. Bait: Redirect an opponent to take coins from a neutral bystander.
- Neutral bystanders can:
  1. Divert coins away from targeted opponents.
  2. Randomly take coins from the game board.
- Players have 12 turns to maximize their resource hold.
- The game ends, and the scores are determined by remaining resources.

Game over after 12 turns.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = [10] * self.n; self.bys = list(bystanders); self.turn = 0
        self.baited = False  # Tracks if an opponent has been baited
        self.player_to_bait = -1  # Tracks which opponent should be baited
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = [
            "Collect Coin P0", "Collect Coin P1",  # Collect coins from bystanders
            "Disrupt P0", "Disrupt P1",           # Direct disruptions
            "Protect",                            # Self-protection
            "Shield P0", "Shield P1",                # Shielding against disruptions
            "Trade with B0", "Trade with B1",       # Trade with bystanders
            "Bait"                                # Redirect opponent to target
        ]
        return moves

    def play(self, p, move):
        w = move.split(" ")

        if w[0] == "Collect Coin P0":
            if self.bys[0] > 0:
                diff = min(int(w[1]), 2)
                self.res[p] += diff; self.bys[0] -= diff
        elif w[0] == "Collect Coin P1":
            if self.bys[1] > 0:
                diff = min(int(w[1]), 2)
                self.res[p] += diff; self.bys[1] -= diff
        elif w[0] == "Disrupt P0":
            if p != 0:
                self.res[0] -= 1
        elif w[0] == "Disrupt P1":
            if p != 1:
                self.res[1] -= 1
        elif w[0] == "Protect":
            if self.rng.random() < 0.5:
                self.res[p] -= 1
        elif w[0] == "Shield P0" and p != 0:
            if self.res[p] > 0:
                self.res[0] -= 1
                self.res[p] -= 1 if self.rng.random() < 0.5 else 0
        elif w[0] == "Shield P1" and p != 1:
            if self.res[p] > 0:
                self.res[1] -= 1
                self.res[p] -= 1 if self.rng.random() < 0.5 else 0
        elif w[0] == "Trade with B0":
            if p != 0 and self.bys[0] > 0:
                diff = min(int(w[1]), 2)
                self.res[p] += diff; self.bys[0] -= diff
        elif w[0] == "Trade with B1":
            if p != 1 and self.bys[1] > 0:
                diff = min(int(w[1]), 2)
                self.res[p] += diff; self.bys[1] -= diff
        elif w[0] == "Bait":
            if self.turn % 2 == 0:  # Target P1
                if self.player_to_bait == -1:
                    self.player_to_bait = 1
            else:  # Target P0
                if self.player_to_bait == -1:
                    self.player_to_bait = 0

            # Redistribute resources towards the targeted opponent
            if self.player_to_bait != -1:
                self.res[self.player_to_bait] += 3
                self.res[p] -= 3
                self.player_to_bait = -1  # Clear target after using

        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn} of 12. Player P{p}:\nRes: {self.res[p]}\nBys: B0={self.bys[0]}, B1={self.bys[1]}"

    def over(self): return self.turn >= 12
    def final_resources(self): return self.res
    def final_bystanders(self): return self.bys

RULES = """
Rock-Paper-Scissors. 3 players, 6 rounds.
Each turn, each player chooses Rock, Paper, or Scissors. 
- Rock beats Scissors, loses to Paper.
- Scissors beats Paper, loses to Rock.
- Paper beats Rock, loses to Scissors.
A player who goes 6-0 wins, receiving a score of +12 from the other players, and -6 points from the players who lose.

Each player receives one point for each turn (not counted towards the score).
Players are given two initial points (total 4).
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [4] * n_players
        self.bys = list(bystanders)  # No change since it doesn't participate in the game
        self.turn = 0
        self.rounds = 6

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        return ["Rock", "Paper", "Scissors"]

    def play(self, p, move):
        win = False
        for q in range(self.n):
            if q != p:
                if move == "Rock":
                    if self.res[q] == "Scissors":
                        self.res[p] += 2
                        self.res[q] -= 2
                        win = True
                        break
                elif move == "Paper":
                    if self.res[q] == "Rock":
                        self.res[p] += 2
                        self.res[q] -= 2
                        win = True
                        break
                elif move == "Scissors":
                    if self.res[q] == "Paper":
                        self.res[p] += 2
                        self.res[q] -= 2
                        win = True
                        break
        if not win:
            self.res[p] -= 2
        self.res[p] += 1
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn} of {self.rounds}. Player {p} has {self.res[p]} points."

    def over(self):
        return self.turn >= self.rounds

    def final_resources(self):
        return list(self.res)

    def final_bystanders(self):
        return list(self.bys)

RULES = """
Fishing Village's Festival. 3 fishermen, 7 rounds, one move each per round. Each fisherman has fish (resources).
Two bystander villages (B0, B1) keep fish ponds by the lake; they do not play. The lake starts with 12 fish and regrows 2 per round.
- Fish: take 2 fish from the lake (1 if it has less).
- Restock: refill your fish stocks to 10.
- Poach B<k>: attempt to capture up to 3 fish from village k's pond.
- Guard P<k>: prevent your neighbor from fishing for 1 round.
- Sanction P<k>: force your opponent to discard all their fish for 1 round.
A player's fish stocks become exhausted if they do not catch their first fish within the first three rounds.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.res = [min(end, 10) for end in endowments]
        self.bys = bystanders
        self.turn = 0
        self.rounds = 7
        self.exhausted = [False] * n_players
        self.guarded = [-1] * n_players
        self.sanctioned = [-1] * n_players
        self.rng = random.Random(seed)

    def to_move(self):
        return self.turn % self.n

    def rnd(self):
        return self.turn // self.n

    def legal_moves(self, p):
        moves = ["fish"] if not self.exhausted[p] else []
        if self.guarded[p] < self.rnd():
            moves.append("guard P%d" % (p + 1))
        if self.sanctioned[p] < self.rnd():
            moves.append("sanction P%d" % (p + 1))
        if self.res[p] < 10:
            moves.append("restock")
        if self.guarded[(p - 1) % self.n] < self.rnd():
            moves.append("guard P%d" % ((p - 1) % self.n + 1))
        if self.guarded[(p + 1) % self.n] < self.rnd():
            moves.append("guard P%d" % ((p + 1) % self.n + 1))
        if self.res[(p + 1) % self.n] > 0 and self.guarded[p] >= self.rnd() and self.guarded[(p + 1) % self.n] >= self.rnd():
            moves.append("poach B0")
        if self.res[(p + 2) % self.n] > 0 and self.guarded[p] >= self.rnd() and self.guarded[(p + 2) % self.n] >= self.rnd():
            moves.append("poach B1")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "fish":
            if self.res[p] < 10:
                self.exhausted[p] = True
                self.res[p] += 1
            else:
                self.res[p] += 1
        elif w[0] == "restock":
            self.res[p] = 10
        elif w[0] == "poach":
            b = int(w[1][1:])
            if b == 0 and self.bys[0] > 0:
                got = min(3, self.bys[0])
                self.bys[0] -= got
                self.res[p] += got
            elif b == 1 and self.bys[1] > 0:
                got = min(3, self.bys[1])
                self.bys[1] -= got
                self.res[p] += got
        elif w[0] == "guard":
            self.guarded[p] = self.rnd() + 1
        elif w[0] == "sanction":
            self.sanctioned[p] = self.rnd() + 1
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Fish %s. Stock %s. Guarded: %s. Sanctioned: %s." % (
            self.rnd() + 1, self.rounds, p + 1, self.res[p], self.res[p] + self.bys[0] + self.bys[1], "Yes" if self.guarded[p] > self.rnd() else "No",
            "Yes" if self.sanctioned[p] > self.rnd() else "No")

    def over(self): 
        return self.turn >= self.n * self.rounds or all([self.exhausted[p] for p in range(self.n)])

    def final_resources(self): 
        return self.res.copy()

    def final_bystanders(self): 
        return self.bys.copy()

RULES = """
The Resource Allocation and Conflict Game. Three players compete strategically to extract, allocate, and defend resources. External subsidies and conflicts add an element of tension.
- extract: Move to extract resources without alerting potential enemies.
- allocate: Spend resources to increase your resource pool.
- claim subsidy: Take up to 10 coins from a bystander. 
- defend: Defend yourself from enemies by shifting resources away to distract them.
- attack: Attempt to force a confrontation with another player.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.rscs = list(endowments); self.bys = bystanders
        self.turn = 0; self.conflicts = set()
        self.rscs_left = [max(0, endowments[p] - 10) for p in range(n_players)]

    def to_move(self): 
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ['extract']
        if self.rscs_left[p] > 0: moves.append('allocate')
        if p in self.conflicts: moves.append('defend')
        elif self.bys[0] > 0: moves.append('claim subsidy')
        else: moves.extend(['attack'])
        return moves

    def play(self, p, move):
        if self.over(): raise ValueError("Game over!")
        if move == 'extract': 
            self.rscs[p] = max(0, self.rscs[p] - 3)
            self.rscs_left[p] -= 1
        elif move == 'allocate':
            amt = min(self.rscs[p], 4)
            self.rscs[p] -= amt
            self.rscs[self.to_move()] += amt
        elif move == 'claim subsidy':
            self.bys[0] -= min(10, self.bys[0])
            self.rscs[p] += min(10, self.bys[0])
        elif move == 'defend':
            self.rscs[p] = max(0, self.rscs[p] - self.rscs[self.to_move()])
        elif move == 'attack':
            other = self.to_move()
            if random.random() > 0.8 or p == other: 
                self.rscs[self.to_move()] = 0
            else:
                self.rscs[p] = 0
        self.turn += 1

    def describe(self, p):
        info = [f"P{p} has {self.rscs[p]} resources"]
        if self.turn < 15: 
            info.append(f"Withstanding attack risk: {'Yes' if self.bys[0] > 0 else 'No'}")
        else:
            info.append(f"Conflict resolution: {'In progress' if self.to_move() in self.conflicts else 'None'}")
        return '\n'.join(info)

    def over(self): 
        return self.turn == 256 or len(self.conflicts) >= 3
    def final_resources(self): return list(self.rscs)
    def final_bystanders(self): return self.bys

RULES = """
Resource Distribution Challenge. 3 players, 10 rounds. Each player starts with 25 resources. Two bystanders, B0 and B1, each have 10 resources.

- Collect Resources (C): Spend no resources and gain 3 resources.
- Donate (D): Spend 5 resources and give 2 resources to a bystander.
- Exchange (E): Spend 5 resources and exchange 1 resource with a bystander (probability 25%).
- Guard Resources (G): Spend 3 resources to prevent another player from receiving resources from a bystander.
- Sanction (S): Spend 5 resources to punish another player by deducting 3 resources from it and giving those 3 resources to a bystander.
- Block (B): Spend 3 resources to temporarily prevent a specific bystander from exchanging or donating resources from them.
- End Turn (T): End your turn without making any move.

Winning the game is determined by the number of resources each player has: the player with the most resources wins. In case of a tie, the player who received the most resources from bystanders wins.
"""

import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 10; self.blocked = [-1] * n_players
        self.rng = random.Random(seed)

    def to_move(self): return self.turn % self.n

    def legal_moves(self, p):
        moves = ["C"]
        if self.res[p] < 5:
            moves.extend(["D", "E", "S", "B"])
        if self.turn % 2 == self.to_move():
            moves.append("G")
        moves.append("T")
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "C":
            if self.res[p] < 3:
                print('Not enough resources')
                return
            self.res[p] -= 3
        elif w[0] == "D":
            if self.res[p] < 5:
                print('Not enough resources')
                return
            self.res[p] -= 5; self.bys[self.rng.randint(0, 1)] += 2
        elif w[0] == "E":
            if self.res[p] < 5:
                print('Not enough resources')
                return
            if self.rng.randint(1, 4) == 1:
                self.res[p] -= 5; self.bys[self.rng.randint(0, 1)] += 1
        elif w[0] == "S":
            if self.res[p] < 5:
                print('Not enough resources')
                return
            q = self.rng.randint(0, self.n - 1)
            if self.res[q] < 3:
                print('Player P%d is not guilty' % q)
                return
            self.res[p] -= 5; self.res[q] -= 3; self.bys[self.rng.randint(0, 1)] += 3
        elif w[0] == "B":
            if self.res[p] < 3:
                print('Not enough resources')
                return
            self.res[p] -= 3
            self.blocked[p] = self.turn + 3
        elif w[0] == "T":
            pass
        self.turn += 1

    def describe(self, p):
        return f"Turn {self.turn+1}. Player {p+1} has {self.res[p]} resources. Blocked until {self.blocked[p]}. Round {self.turn//self.n+1}/{self.rounds}."

    def over(self): return self.turn >= self.rounds

    def final_resources(self):
        return self.res

    def final_bystanders(self):
        return self.bys

RULES = """The Great Treasure Hunt
Three players (Player 0, Player 1, Player 2) and two bystanders (Bystander 0, Bystander 1). Each starts with 5 resources. There are 8 rounds, one move per turn. Players can:
- 'STEAL_B0': Steal 1 from Bystander 0.
- 'STEAL_B1': Steal 1 from Bystander 1.
- 'ATTACK_PP': Attack Player 2, attempting to defeat them and take their resources.
- 'DEFEND_BB': Defend Player 0, preventing Player 1 from attacking them.
- 'SKIP': Pass without moving.
Winners: The player with the most resources after 8 turns. If there is a tie, the player who defended better (i.e., prevented an attack) wins."""


import random

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players
        self.resources = endowments[:]
        self.bystanders = bystanders[:]
        self.defense_count = 0  # Count of successful defense attempts
        self.attack_count = 0   # Count of successful attack attempts
        self.turn = 0

    def to_move(self):
        return self.turn % self.n

    def legal_moves(self, p):
        moves = ['STEAL_B0', 'STEAL_B1', 'ATTACK_PP', 'DEFEND_BB', 'SKIP']
        if p == 0:
            moves.remove('DEFEND_BB')  # Can't defend if attacking
        if p == 1:
            moves.remove('DEFEND_BB')  # Can't defend if defending
        return moves

    def play(self, p, move):
        if move == 'STEAL_B0' and self.bystanders[0] > 0:
            self.bystanders[0] -= 1
            self.resources[p] += 1
        elif move == 'STEAL_B1' and self.bystanders[1] > 0:
            self.bystanders[1] -= 1
            self.resources[p] += 1
        elif move == 'ATTACK_PP' and self.resources[2] > 0:
            if self.resources[2] >= 3:
                self.resources[2] -= 3
                self.resources[p] += 3
                self.attack_count += 1
        elif move == 'DEFEND_BB':
            if self.defense_count == 0:
                self.defense_count += 1

        self.turn += 1

    def describe(self, p):
        return "\n".join(
            f"Player {p} has {self.resources[p]} resources, Bystander 0: {self.bystanders[0]}, Bystander 1: {self.bystanders[1]}"
        )

    def over(self):
        return self.turn >= 8

    def final_resources(self):
        return self.resources

    def final_bystanders(self):
        return self.bystanders

RULES = """Dueling Factions. 3 factions, 16 rounds, two moves per round. Each faction has silver (resources). Two bystander cities
(C0, C1) sit below the river and hold silver; they do not play.

- mine: gain 2 silver.
- steal C<K>: take 4 silver from city K's holdings (the river floods city K).
- guard B<K>: pay 1 silver; city K cannot be stolen for the rest of this round.
- defend B<K>: pay 2 silver; city K cannot be protected again this round.
- donate P<K>: give 4 silver to faction K.
The river holds a reserve; mining stops paying when it is empty."""

class Game:
    def __init__(self, n_players, endowments, bystanders, seed):
        self.n = n_players; self.res = list(endowments); self.bys = list(bystanders)
        self.turn = 0; self.rounds = 16; self.shored = [-1] * len(bystanders); self.guarded = [-1] * len(bystanders)
        self.reserve = sum(endowments) // 3 + 3

    def to_move(self): return self.turn % self.n

    def rnd(self): return self.turn // self.n

    def legal_moves(self, p):
        moves = ["mine"] 
        moves += ["steal C%d" % c for c in range(len(self.bys)) if self.bys[c] > 0 and self.guarded[c] < self.rnd()]
        if self.res[p] >= 1:
            moves += ["guard B%d" % b for b in range(len(self.bys)) if self.shored[b] < self.rnd()]
        if self.res[p] >= 2:
            moves += ["defend B%d" % b for b in range(len(self.bys))]
        moves += ["donate P%d" % q for q in range(self.n) if q != p]
        return moves

    def play(self, p, move):
        w = move.split(" ")
        if w[0] == "mine":
            got = min(2, self.reserve); self.reserve -= got; self.res[p] += got
        elif w[0] == "steal":
            c = int(w[1][1:]); got = min(4, self.bys[c]); self.bys[c] -= got; self.res[p] += got
        elif w[0] == "guard":
            self.res[p] -= 1; self.shored[int(w[1][1:])] = self.rnd() + 1
        elif w[0] == "defend":
            self.res[p] -= 2; self.guarded[int(w[1][1:])] = self.rnd() + 1
        elif w[0] == "donate":
            q = int(w[1][1:]); got = min(4, self.res[q]); self.res[q] -= got; self.res[p] += got
        self.turn += 1

    def describe(self, p):
        return "Round %d of %d. You are P%d. Silver %s. Cities %s. Guarded: %s. Defended: %s. Reserve %d." % (
            self.rnd() + 1, self.rounds, p, self.res, self.bys,
            ["C%d" % c for c in range(len(self.bys)) if self.shored[c] >= self.rnd()] or "none",
            ["C%d" % c for c in range(len(self.bys)) if self.guarded[c] >= self.rnd()] or "none", self.reserve)

    def over(self): return self.turn >= self.n * self.rounds
    def final_resources(self): return list(self.res)
    def final_bystanders(self): return list(self.bys)
